# ═══════════════════════════════════════════════════════════════════════════
#  ENH-01  Structured Error Handling — classifier, retry decorator, logging
# ═══════════════════════════════════════════════════════════════════════════

class ErrorClassifier:
    """Classify exceptions into actionable categories."""

    RETRIABLE = (
        TimeoutError, asyncio.TimeoutError, ConnectionResetError,
        ConnectionRefusedError, BrokenPipeError, OSError,
    )
    FATAL = (KeyboardInterrupt, SystemExit, MemoryError)

    _TRANSIENT_MSGS = frozenset([
        "reset by peer", "broken pipe", "connection refused",
        "too many open files", "temporary failure", "eof occurred",
        "ssl handshake", "timed out", "connection timed",
    ])

    @classmethod
    def is_retriable(cls, exc: Exception) -> bool:
        if isinstance(exc, cls.FATAL):
            return False
        if isinstance(exc, cls.RETRIABLE):
            return True
        msg = str(exc).lower()
        return any(m in msg for m in cls._TRANSIENT_MSGS)

    @classmethod
    def classify(cls, exc: Exception) -> str:
        if isinstance(exc, cls.FATAL):
            return "FATAL"
        if isinstance(exc, asyncio.CancelledError):
            return "CANCELLED"
        if isinstance(exc, asyncio.TimeoutError):
            return "TIMEOUT"
        if cls.is_retriable(exc):
            return "TRANSIENT"
        return "PERMANENT"

    @classmethod
    def format_tb(cls, exc: Exception, limit: int = 5) -> str:
        """Return compact traceback string."""
        lines = traceback.format_exception(type(exc), exc, exc.__traceback__, limit=limit)
        return "".join(lines).strip()


def with_retry(
    max_attempts: int = 3,
    base_delay: float = 1.0,
    max_delay: float = 30.0,
    retryable_exc: tuple = (Exception,),
    label: str = "",
):
    """Async retry decorator with exponential back-off and structured logging."""

    def decorator(fn: Callable) -> Callable:
        import functools

        @functools.wraps(fn)
        async def wrapper(*args, **kwargs):
            _label = label or fn.__qualname__
            for attempt in range(1, max_attempts + 1):
                try:
                    return await fn(*args, **kwargs)
                except asyncio.CancelledError:
                    raise
                except retryable_exc as exc:
                    cls = ErrorClassifier.classify(exc)
                    if cls == "FATAL" or attempt >= max_attempts:
                        _tb = ErrorClassifier.format_tb(exc, limit=3)
                        logging.getLogger("webscout").warning(
                            "[%s] attempt %d/%d failed (%s): %s\n%s",
                            _label, attempt, max_attempts, cls, exc, _tb,
                        )
                        return None  # graceful degradation instead of crash
                    delay = min(base_delay * (2 ** (attempt - 1)) + random.uniform(0, 0.5), max_delay)
                    logging.getLogger("webscout").debug(
                        "[%s] attempt %d/%d — %s, retry in %.1fs",
                        _label, attempt, max_attempts, exc, delay,
                    )
                    await asyncio.sleep(delay)
            return None

        return wrapper

    return decorator


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-02  Async Worker Pool — bounded queue, back-pressure, cancellation
# ═══════════════════════════════════════════════════════════════════════════

class BoundedWorkerPool:
    """
    Bounded async worker pool with:
    - Hard concurrency cap via Semaphore
    - Back-pressure via bounded asyncio.Queue
    - Graceful cancellation / drain
    - Per-task timeout enforcement
    - Aggregated result collection
    """

    def __init__(
        self,
        max_workers: int = 20,
        queue_capacity: int = 200,
        task_timeout: float = 60.0,
    ):
        self.max_workers = max_workers
        self.queue_capacity = queue_capacity
        self.task_timeout = task_timeout
        self._sem = asyncio.Semaphore(max_workers)
        self._queue: asyncio.Queue = asyncio.Queue(maxsize=queue_capacity)
        self._results: List[Any] = []
        self._errors: List[str] = []
        self._active: int = 0
        self._done = asyncio.Event()
        self._shutdown = False

    async def submit(self, coro_factory: Callable, label: str = "") -> bool:
        """Submit a coroutine factory. Returns False if pool is shutting down."""
        if self._shutdown:
            return False
        try:
            await asyncio.wait_for(
                self._queue.put((coro_factory, label)),
                timeout=5.0,
            )
            return True
        except asyncio.TimeoutError:
            logging.getLogger("webscout").warning(
                "[WorkerPool] Queue full (%d cap) — dropping task '%s' (back-pressure)",
                self.queue_capacity, label,
            )
            return False

    async def _worker(self):
        while True:
            try:
                item = self._queue.get_nowait()
            except asyncio.QueueEmpty:
                break
            except Exception as _qe:
                logging.getLogger("webscout").debug("[WorkerPool] queue get error: %s", _qe)
                break
            coro_factory, label = item
            self._active += 1
            try:
                async with self._sem:
                    try:
                        result = await asyncio.wait_for(
                            coro_factory(), timeout=self.task_timeout
                        )
                        if result is not None:
                            if isinstance(result, list):
                                self._results.extend(result)
                            else:
                                self._results.append(result)
                    except asyncio.TimeoutError:
                        self._errors.append(f"{label}: timed out after {self.task_timeout}s")
                        logging.getLogger("webscout").warning(
                            "[WorkerPool] '%s' timed out after %.0fs", label, self.task_timeout
                        )
                    except asyncio.CancelledError:
                        self._errors.append(f"{label}: cancelled")
                        raise
                    except Exception as exc:
                        cat = ErrorClassifier.classify(exc)
                        tb = ErrorClassifier.format_tb(exc, limit=3)
                        self._errors.append(f"{label}: {cat} — {exc}")
                        logging.getLogger("webscout").warning(
                            "[WorkerPool] '%s' failed (%s): %s\n%s", label, cat, exc, tb
                        )
            finally:
                self._active -= 1
                self._queue.task_done()

    async def run_all(self, num_workers: Optional[int] = None) -> List[Any]:
        """Drain the queue with `num_workers` concurrent workers."""
        n = num_workers or self.max_workers
        workers = [asyncio.create_task(self._worker()) for _ in range(n)]
        try:
            await self._queue.join()
        except asyncio.CancelledError:
            for w in workers:
                w.cancel()
            raise
        finally:
            for w in workers:
                if not w.done():
                    w.cancel()
            await asyncio.gather(*workers, return_exceptions=True)
        return list(self._results)

    async def map(
        self,
        coro_factories: List[Tuple[Callable, str]],
    ) -> List[Any]:
        """Submit all and run; convenience method."""
        for factory, label in coro_factories:
            await self.submit(factory, label)
        return await self.run_all()

    @property
    def error_summary(self) -> List[str]:
        return list(self._errors)


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-03  Memory Watchdog — RSS monitoring, streaming cap, GC trigger
# ═══════════════════════════════════════════════════════════════════════════

class MemoryWatchdog:
    """
    Monitors RSS memory usage and applies safeguards:
    - Warns at soft limit, forces GC + response truncation at hard limit
    - Streaming read cap per HTTP response body
    - Background task that polls every N seconds
    """

    SOFT_LIMIT_MB: int = 800   # warn
    HARD_LIMIT_MB: int = 1400  # force GC + truncate
    RESPONSE_CAP_BYTES: int = 2 * 1024 * 1024   # 2 MB per response body
    POLL_INTERVAL: float = 15.0

    def __init__(self):
        self._task: Optional[asyncio.Task] = None
        self._triggered_gc = False
        self._logger = logging.getLogger("webscout.memory")

    @staticmethod
    def _rss_mb() -> float:
        try:
            import resource
            return resource.getrusage(resource.RUSAGE_SELF).ru_maxrss / 1024
        except ImportError:
            pass
        try:
            with open("/proc/self/status") as f:
                for line in f:
                    if line.startswith("VmRSS:"):
                        return int(line.split()[1]) / 1024
        except OSError:
            pass
        return 0.0

    @classmethod
    def truncate_response(cls, text: str) -> str:
        """Cap a response body at RESPONSE_CAP_BYTES to avoid OOM."""
        cap = cls.RESPONSE_CAP_BYTES
        if len(text.encode("utf-8", errors="replace")) > cap:
            truncated = text.encode("utf-8", errors="replace")[:cap].decode("utf-8", errors="replace")
            return truncated + "\n[... response truncated by MemoryWatchdog ...]"
        return text

    async def _monitor(self):
        while True:
            try:
                await asyncio.sleep(self.POLL_INTERVAL)
                rss = self._rss_mb()
                if rss >= self.HARD_LIMIT_MB:
                    self._logger.warning(
                        "[MemoryWatchdog] RSS %.0f MB >= hard limit %d MB — forcing GC + truncation",
                        rss, self.HARD_LIMIT_MB,
                    )
                    gc.collect(2)
                    self._triggered_gc = True
                elif rss >= self.SOFT_LIMIT_MB:
                    self._logger.info(
                        "[MemoryWatchdog] RSS %.0f MB approaching soft limit %d MB",
                        rss, self.SOFT_LIMIT_MB,
                    )
            except asyncio.CancelledError:
                break
            except Exception as exc:
                self._logger.debug("[MemoryWatchdog] poll error: %s", exc)

    def start(self) -> None:
        if self._task and not self._task.done():
            return  # already running — avoid duplicate monitors
        try:
            self._task = asyncio.ensure_future(self._monitor())
        except RuntimeError as _mw_err:
            self._logger.debug("[MemoryWatchdog] Cannot start outside event loop: %s", _mw_err)

    def stop(self) -> None:
        if self._task and not self._task.done():
            self._task.cancel()

    @property
    def pressure(self) -> bool:
        """True when memory is under heavy pressure."""
        return self._rss_mb() >= self.HARD_LIMIT_MB


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-04  Playwright Browser Engine — real Chromium for SPA/JS targets
# ═══════════════════════════════════════════════════════════════════════════

class PlaywrightBrowserEngine:
    """
    Full Chromium browser via Playwright for:
    - SPA rendering (React, Next.js, Vue, Nuxt)
    - Network request interception
    - JS console log capture
    - DOM snapshot after hydration
    - Cookie / localStorage extraction
    """

    DEFAULT_ARGS = [
        "--no-sandbox",
        "--disable-setuid-sandbox",
        "--disable-dev-shm-usage",
        "--disable-extensions",
        "--disable-gpu",
        "--no-first-run",
        "--no-default-browser-check",
        "--disable-background-networking",
        "--disable-sync",
        "--disable-translate",
        "--hide-scrollbars",
        "--metrics-recording-only",
        "--mute-audio",
        "--safebrowsing-disable-auto-update",
    ]

    def __init__(self, headless: bool = True, timeout_ms: int = 30_000):
        self.headless = headless
        self.timeout_ms = timeout_ms
        self._browser = None
        self._playwright = None
        self._ready = False

    async def start(self) -> bool:
        """Initialise Playwright + Chromium. Returns True on success."""
        try:
            from playwright.async_api import async_playwright
            self._playwright = await async_playwright().start()
            self._browser = await self._playwright.chromium.launch(
                headless=self.headless,
                args=self.DEFAULT_ARGS,
            )
            self._ready = True
            logging.getLogger("webscout").info("[Playwright] Chromium browser started")
            return True
        except Exception as exc:
            logging.getLogger("webscout").warning(
                "[Playwright] Failed to start: %s — falling back to HTTP client", exc
            )
            self._ready = False
            return False

    async def stop(self) -> None:
        try:
            if self._browser:
                await self._browser.close()
            if self._playwright:
                await self._playwright.stop()
        except Exception as _stop_exc:
            logging.getLogger("webscout").debug("[Playwright] stop error: %s", _stop_exc)
        self._ready = False

    async def get_page_snapshot(
        self,
        url: str,
        wait_for: str = "networkidle",
        extra_headers: Optional[Dict[str, str]] = None,
    ) -> Dict[str, Any]:
        """
        Navigate to URL and return:
        {html, title, requests, console_msgs, cookies, local_storage, screenshot_b64}
        """
        if not self._ready:
            return {}
        result: Dict[str, Any] = {
            "html": "", "title": "", "requests": [],
            "console_msgs": [], "cookies": {}, "local_storage": {},
            "screenshot_b64": "",
        }
        try:
            ctx = await self._browser.new_context(
                user_agent=(
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                    "AppleWebKit/537.36 (KHTML, like Gecko) "
                    "Chrome/124.0.0.0 Safari/537.36"
                ),
                extra_http_headers=extra_headers or {},
                ignore_https_errors=True,
            )
            page = await ctx.new_page()

            # Intercept network requests
            intercepted: List[Dict] = []

            async def _on_request(req):
                intercepted.append({
                    "url": req.url,
                    "method": req.method,
                    "resource_type": req.resource_type,
                    "post_data": req.post_data or "",
                })

            page.on("request", lambda r: asyncio.ensure_future(_on_request(r)))

            # Capture console messages
            console_msgs: List[str] = []
            page.on("console", lambda m: console_msgs.append(f"[{m.type}] {m.text}"))

            try:
                await page.goto(url, wait_until=wait_for, timeout=self.timeout_ms)
            except Exception as nav_exc:
                logging.getLogger("webscout").debug(
                    "[Playwright] Navigation partial (%s) — capturing snapshot anyway", nav_exc
                )

            result["html"] = await page.content()
            result["title"] = await page.title()
            result["requests"] = intercepted
            result["console_msgs"] = console_msgs

            # Cookies
            cookies = await ctx.cookies()
            result["cookies"] = {c["name"]: c["value"] for c in cookies}

            # Local storage
            try:
                ls = await page.evaluate("() => Object.entries(localStorage)")
                result["local_storage"] = dict(ls)
            except Exception as _ls_exc:
                logging.getLogger("webscout").debug("[Playwright] localStorage unavailable: %s", _ls_exc)

            # Screenshot (base64, for evidence)
            try:
                png = await page.screenshot(full_page=False)
                result["screenshot_b64"] = base64.b64encode(png).decode()
            except Exception as _ss_exc:
                logging.getLogger("webscout").debug("[Playwright] screenshot failed: %s", _ss_exc)

            await ctx.close()
        except Exception as exc:
            logging.getLogger("webscout").warning("[Playwright] snapshot error: %s", exc)
        return result

    async def inject_js_and_capture(self, url: str, js_snippet: str) -> Any:
        """Navigate, inject JS, return its return value."""
        if not self._ready:
            return None
        try:
            ctx = await self._browser.new_context(ignore_https_errors=True)
            page = await ctx.new_page()
            await page.goto(url, wait_until="domcontentloaded", timeout=self.timeout_ms)
            result = await page.evaluate(js_snippet)
            await ctx.close()
            return result
        except Exception as exc:
            logging.getLogger("webscout").debug("[Playwright] JS inject error: %s", exc)
            return None


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-05  Browser DOM Intelligence — form/link/API endpoint discovery
# ═══════════════════════════════════════════════════════════════════════════

class BrowserDOMIntelligence:
    """
    Extracts security-relevant DOM features from a rendered page snapshot:
    - HTML forms (action, method, inputs, hidden fields)
    - Anchor links (internal / external / javascript:)
    - API calls observed in network requests
    - Cookie attribute analysis
    - localStorage secrets scanning
    - Input auto-complete hints
    """

    _SECRET_RE = re.compile(
        r'(?i)(api[_-]?key|secret|token|password|passwd|auth|bearer|private)["\s]*[:=]["\s]*([A-Za-z0-9+/=._-]{8,})',
        re.MULTILINE,
    )

    def analyse(self, snapshot: Dict[str, Any], base_url: str) -> Dict[str, Any]:
        html = snapshot.get("html", "")
        requests = snapshot.get("requests", [])
        cookies = snapshot.get("cookies", {})
        local_storage = snapshot.get("local_storage", {})

        parsed = urlparse(base_url)
        host = parsed.netloc

        report: Dict[str, Any] = {
            "forms": [],
            "internal_links": [],
            "external_links": [],
            "js_hrefs": [],
            "api_calls": [],
            "insecure_cookies": [],
            "ls_secrets": [],
            "html_secrets": [],
            "autocomplete_on": [],
        }

        # ── Forms ─────────────────────────────────────────────────────────
        for form_m in re.finditer(r'<form([^>]*)>(.*?)</form>', html, re.DOTALL | re.IGNORECASE):
            attrs_str, form_body = form_m.group(1), form_m.group(2)
            action_m = re.search(r'action=["\']([^"\']*)["\']', attrs_str, re.I)
            method_m = re.search(r'method=["\']([^"\']*)["\']', attrs_str, re.I)
            action = action_m.group(1) if action_m else ""
            method = method_m.group(1).upper() if method_m else "GET"
            inputs = re.findall(r'<input([^>]*)>', form_body, re.I)
            fields = []
            has_csrf = False
            for inp in inputs:
                n_m = re.search(r'name=["\']([^"\']+)["\']', inp, re.I)
                t_m = re.search(r'type=["\']([^"\']+)["\']', inp, re.I)
                ac_m = re.search(r'autocomplete=["\']([^"\']*)["\']', inp, re.I)
                n = n_m.group(1) if n_m else ""
                t = t_m.group(1).lower() if t_m else "text"
                if n:
                    fields.append({"name": n, "type": t})
                if re.search(r'csrf|_token|authenticity', n, re.I):
                    has_csrf = True
                if ac_m and ac_m.group(1).lower() not in ("off", "new-password"):
                    if t in ("password", "email", "username"):
                        report["autocomplete_on"].append({"form_action": action, "field": n, "type": t})
            report["forms"].append({
                "action": action,
                "method": method,
                "fields": fields,
                "has_csrf_token": has_csrf,
            })

        # ── Links ──────────────────────────────────────────────────────────
        for href_m in re.finditer(r'href=["\']([^"\']+)["\']', html, re.I):
            href = href_m.group(1).strip()
            if href.startswith("javascript:"):
                report["js_hrefs"].append(href)
            elif href.startswith(("http://", "https://")):
                ph = urlparse(href).netloc
                if ph == host:
                    report["internal_links"].append(href)
                else:
                    report["external_links"].append(href)
            elif href.startswith("/"):
                report["internal_links"].append(urljoin(base_url, href))

        # ── API calls from network intercept ───────────────────────────────
        api_re = re.compile(r'/api/|/graphql|/gql|/v\d+/|/rest/', re.I)
        for req in requests:
            if api_re.search(req.get("url", "")):
                report["api_calls"].append({
                    "url": req["url"],
                    "method": req["method"],
                    "body": (req.get("post_data") or "")[:200],
                })

        # ── Cookie security ────────────────────────────────────────────────
        for name, value in cookies.items():
            issues = []
            if not value:
                continue
            report["insecure_cookies"].append({"name": name, "issues": issues})

        # ── LocalStorage secrets ───────────────────────────────────────────
        for key, val in local_storage.items():
            for m in self._SECRET_RE.finditer(f"{key}={val}"):
                report["ls_secrets"].append({
                    "key": key,
                    "pattern": m.group(1),
                    "sample": m.group(2)[:20] + "...",
                })

        # ── HTML secrets ───────────────────────────────────────────────────
        for m in self._SECRET_RE.finditer(html):
            val = m.group(2)
            if len(val) >= 12 and not val.startswith("{{"):
                report["html_secrets"].append({
                    "pattern": m.group(1),
                    "sample": val[:20] + "...",
                })

        # De-duplicate lists
        report["internal_links"] = list(dict.fromkeys(report["internal_links"]))[:50]
        report["external_links"] = list(dict.fromkeys(report["external_links"]))[:30]
        return report


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-06  Modern Frontend Detector — React / Next.js / Vue / Nuxt / Remix
# ═══════════════════════════════════════════════════════════════════════════

@dataclass
class FrontendFramework:
    name: str
    confidence: float
    version_hint: str = ""
    routes: List[str] = field(default_factory=list)
    api_patterns: List[str] = field(default_factory=list)
    ssr: bool = False
    notes: List[str] = field(default_factory=list)


class ModernFrontendDetector:
    """
    Detect SPA/SSR frameworks and derive security-relevant scan targets:
    - Next.js: /_next/static, /api/* routes, __NEXT_DATA__
    - Nuxt:    /__nuxt/, __NUXT__ global
    - React:   react-root, ReactDOM, _reactFiber
    - Vue:     __vue__, Vue.config, v-bind markers
    - Remix:   __remixContext, /routes/ manifest
    - Angular: ng-version, angular.json
    - Gatsby:  __gatsby, /page-data/
    - Vite:    /@vite/client, /__vite_hmr
    """

    SIGNATURES: List[Tuple[str, str, str]] = [
        # (pattern, framework, note)
        (r'__NEXT_DATA__', "Next.js", "SSR data blob detected"),
        (r'/_next/static/', "Next.js", "Static chunk URL"),
        (r'__NEXT_ROUTER_BASEPATH', "Next.js", "Router base-path"),
        (r'__nuxt', "Nuxt.js", "Nuxt global detected"),
        (r'/_nuxt/', "Nuxt.js", "Nuxt static chunk"),
        (r'__vue_ssr_context', "Nuxt.js/Vue SSR", "SSR context"),
        (r'__vue__', "Vue.js", "Vue instance"),
        (r'vue-router', "Vue.js", "Vue Router"),
        (r'__remixContext', "Remix", "Remix context"),
        (r'/__remix_hmr', "Remix", "Remix HMR"),
        (r'window\.__gatsby', "Gatsby", "Gatsby global"),
        (r'/page-data/', "Gatsby", "Gatsby page-data API"),
        (r'ng-version=', "Angular", "Angular version attr"),
        (r'/@angular/', "Angular", "Angular package"),
        (r'/@vite/client', "Vite", "Vite HMR client"),
        (r'/__vite_hmr', "Vite", "Vite HMR endpoint"),
        (r'react-dom', "React", "ReactDOM bundle"),
        (r'_reactFiber', "React", "React Fiber internals"),
        (r'data-reactroot', "React", "SSR root marker"),
        (r'svelte', "Svelte", "Svelte bundle"),
        (r'SvelteKit', "SvelteKit", "SvelteKit framework"),
    ]

    # Framework-specific security-relevant paths to probe
    FRAMEWORK_PATHS: Dict[str, List[str]] = {
        "Next.js": [
            "/api/auth/[...nextauth]",
            "/api/graphql",
            "/_next/data",
            "/__nextjs_original-stack-frame",
            "/api/trpc",
        ],
        "Nuxt.js": [
            "/_nuxt/",
            "/api/",
            "/__nuxt_error",
        ],
        "Remix": [
            "/__remix_hmr",
            "/api/",
            "/_data",
        ],
        "Gatsby": [
            "/page-data/index/page-data.json",
            "/page-data/app-data.json",
            "/static/",
        ],
        "Angular": [
            "/assets/",
            "/api/",
        ],
        "Vite": [
            "/@vite/client",
            "/@id/",
        ],
    }

    def detect(self, html: str, headers: Dict[str, str], base_url: str) -> List[FrontendFramework]:
        detected: Dict[str, FrontendFramework] = {}
        text_lower = html.lower()

        for pattern, framework, note in self.SIGNATURES:
            if re.search(pattern, html, re.I):
                if framework not in detected:
                    detected[framework] = FrontendFramework(
                        name=framework,
                        confidence=0.0,
                        ssr=False,
                    )
                fw = detected[framework]
                fw.confidence = min(fw.confidence + 25.0, 99.0)
                fw.notes.append(note)

        # SSR detection
        for fw in detected.values():
            if any(s in fw.notes for s in ["SSR data blob detected", "SSR context", "SSR root marker"]):
                fw.ssr = True

        # Version hints from meta / headers
        x_powered = headers.get("x-powered-by", "") or headers.get("X-Powered-By", "")
        if "next.js" in x_powered.lower():
            if "Next.js" not in detected:
                detected["Next.js"] = FrontendFramework("Next.js", 80.0, ssr=True)
            m = re.search(r'Next\.js[\s/]+([\d.]+)', x_powered, re.I)
            if m:
                detected["Next.js"].version_hint = m.group(1)

        # Attach probe paths
        for name, fw in detected.items():
            fw.routes = [urljoin(base_url, p) for p in self.FRAMEWORK_PATHS.get(name, [])]
            fw.api_patterns = ["/api/", "/graphql", "/trpc"] if name in ("Next.js", "Nuxt.js", "Remix") else ["/api/"]

        return list(detected.values())

    def to_findings(self, frameworks: List[FrontendFramework], base_url: str) -> List[Dict]:
        """Convert framework detections to lightweight Finding dicts."""
        results = []
        for fw in frameworks:
            results.append({
                "plugin": "frontend_detect",
                "title": f"Modern Frontend Detected: {fw.name}",
                "severity": "INFO",
                "confidence": fw.confidence,
                "description": (
                    f"{fw.name} SPA/SSR framework detected. "
                    f"{'Server-side rendered. ' if fw.ssr else ''}"
                    f"Probe paths: {', '.join(fw.routes[:3])}"
                ),
                "evidence": " | ".join(fw.notes[:4]),
                "url": base_url,
                "tags": ["frontend", fw.name.lower().replace(".", "").replace("/", ""), "spa"],
                "_probe_routes": fw.routes,
            })
        return results


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-07  JS Runtime Instrumentation — fetch/XHR/WS intercept via Playwright
# ═══════════════════════════════════════════════════════════════════════════

class JSRuntimeInstrument:
    """
    Injects instrumentation JS into a live Playwright page to intercept:
    - window.fetch() — capture URL, method, headers, body
    - XMLHttpRequest.open/send — legacy AJAX
    - WebSocket constructor — WS endpoint discovery
    - postMessage() — cross-origin message analysis
    - eval() / Function() — dynamic code execution tracking
    """

    _INJECT_SCRIPT = r"""
() => {
    window.__wsIntelCapture = {
        fetch_calls: [],
        xhr_calls: [],
        ws_endpoints: [],
        post_messages: [],
        eval_calls: [],
    };
    const cap = window.__wsIntelCapture;

    // ── fetch intercept ─────────────────────────────────────────────────
    const _origFetch = window.fetch;
    window.fetch = function(input, init) {
        const entry = {
            url: typeof input === 'string' ? input : (input.url || String(input)),
            method: (init && init.method) || 'GET',
            body: (init && typeof init.body === 'string' ? init.body.slice(0, 500) : ''),
            headers: (init && init.headers) ? JSON.stringify(init.headers) : '',
        };
        cap.fetch_calls.push(entry);
        return _origFetch.apply(this, arguments);
    };

    // ── XHR intercept ────────────────────────────────────────────────────
    const _origOpen = XMLHttpRequest.prototype.open;
    const _origSend = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.open = function(method, url) {
        this.__url = url; this.__method = method;
        return _origOpen.apply(this, arguments);
    };
    XMLHttpRequest.prototype.send = function(body) {
        cap.xhr_calls.push({
            url: this.__url || '',
            method: this.__method || 'GET',
            body: typeof body === 'string' ? body.slice(0, 500) : '',
        });
        return _origSend.apply(this, arguments);
    };

    // ── WebSocket constructor ────────────────────────────────────────────
    const _origWS = window.WebSocket;
    window.WebSocket = function(url, protocols) {
        cap.ws_endpoints.push(url);
        return new _origWS(url, protocols);
    };
    window.WebSocket.prototype = _origWS.prototype;

    // ── postMessage ──────────────────────────────────────────────────────
    const _origPM = window.postMessage;
    window.postMessage = function(data, targetOrigin) {
        cap.post_messages.push({
            data: JSON.stringify(data).slice(0, 200),
            targetOrigin: targetOrigin,
        });
        return _origPM.apply(this, arguments);
    };

    // ── eval intercept ───────────────────────────────────────────────────
    const _origEval = window.eval;
    window.eval = function(code) {
        cap.eval_calls.push(typeof code === 'string' ? code.slice(0, 200) : '[non-string]');
        return _origEval.apply(this, arguments);
    };

    return 'instrumentation_installed';
}
"""

    _COLLECT_SCRIPT = "() => window.__wsIntelCapture || {}"

    async def instrument_page(
        self,
        browser_engine: "PlaywrightBrowserEngine",
        url: str,
        wait_ms: int = 3000,
    ) -> Dict[str, Any]:
        """Instrument a page and collect runtime call data after `wait_ms` ms."""
        if not browser_engine._ready:
            return {}
        try:
            from playwright.async_api import async_playwright
            ctx = await browser_engine._browser.new_context(ignore_https_errors=True)
            page = await ctx.new_page()
            await page.add_init_script(script=self._INJECT_SCRIPT)
            await page.goto(url, wait_until="domcontentloaded", timeout=browser_engine.timeout_ms)
            await page.wait_for_timeout(wait_ms)
            data = await page.evaluate(self._COLLECT_SCRIPT)
            await ctx.close()
            return data or {}
        except Exception as exc:
            logging.getLogger("webscout").debug("[JSInstrument] error: %s", exc)
            return {}

    def analyse_calls(self, data: Dict[str, Any], base_url: str) -> List[Dict]:
        """Convert runtime call data into security findings."""
        findings = []
        host = urlparse(base_url).netloc

        # API endpoints from fetch/XHR
        seen_apis: Set[str] = set()
        for call in (data.get("fetch_calls") or []) + (data.get("xhr_calls") or []):
            url = call.get("url", "")
            if url and url not in seen_apis:
                seen_apis.add(url)
                if re.search(r'/api/|/graphql|/gql|/v\d+/', url, re.I):
                    findings.append({
                        "plugin": "js_instrument",
                        "title": f"JS Runtime API Call: {call.get('method','GET')} {url[:80]}",
                        "severity": "INFO",
                        "confidence": 95.0,
                        "description": "API endpoint discovered via JS runtime fetch/XHR instrumentation.",
                        "evidence": f"method={call.get('method')} body={call.get('body','')[:80]}",
                        "url": url,
                        "tags": ["js-instrumentation", "api-discovery"],
                    })

        # WebSocket endpoints
        for ws_url in (data.get("ws_endpoints") or []):
            findings.append({
                "plugin": "js_instrument",
                "title": f"WebSocket Endpoint Discovered via JS: {ws_url[:80]}",
                "severity": "INFO",
                "confidence": 98.0,
                "description": "WebSocket URL intercepted from the page's JS runtime.",
                "evidence": ws_url,
                "url": ws_url,
                "tags": ["js-instrumentation", "websocket", "discovery"],
            })

        # Eval calls — dynamic code execution
        if data.get("eval_calls"):
            findings.append({
                "plugin": "js_instrument",
                "title": "Dynamic eval() Usage Detected",
                "severity": "LOW",
                "confidence": 85.0,
                "description": "The page uses eval() or dynamic code execution, increasing XSS impact.",
                "evidence": (data["eval_calls"][0] or "")[:120],
                "url": base_url,
                "tags": ["js-instrumentation", "eval", "xss"],
            })

        # postMessage to wildcard
        for pm in (data.get("post_messages") or []):
            if pm.get("targetOrigin") in ("*", None, ""):
                findings.append({
                    "plugin": "js_instrument",
                    "title": "postMessage with Wildcard targetOrigin",
                    "severity": "MEDIUM",
                    "confidence": 80.0,
                    "description": "postMessage called with '*' origin — data may leak to malicious iframes.",
                    "evidence": pm.get("data", "")[:120],
                    "url": base_url,
                    "tags": ["js-instrumentation", "postmessage", "xss"],
                })
        return findings


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-08  Client-Side Security Analyzer — JS bundle / secrets / deps
# ═══════════════════════════════════════════════════════════════════════════

class ClientSideAnalyzer:
    """
    Analyse JS bundle content for:
    - Hardcoded secrets / API keys
    - Vulnerable dependency version strings
    - Source-map exposure (.map files)
    - Dangerous sinks (eval, innerHTML, document.write)
    - Exposed internal endpoints / IP addresses
    """

    _SECRET_PATTERNS: List[Tuple[str, str, str]] = [
        (r'(?i)(aws_access_key_id|aws_secret)["\s]*[:=]["\s]*([A-Z0-9/+]{20,40})', "AWS Key", "CRITICAL"),
        (r'(?i)(github_token|gh_token|ghp_)["\s]*[:=]?["\s]*([a-zA-Z0-9_-]{35,})', "GitHub Token", "CRITICAL"),
        (r'(?i)AIza[0-9A-Za-z_-]{35}', "Google API Key", "HIGH"),
        (r'(?i)sk-[a-zA-Z0-9]{48}', "OpenAI Key", "CRITICAL"),
        (r'(?i)(stripe_secret|sk_live_)[a-zA-Z0-9]{24,}', "Stripe Secret", "CRITICAL"),
        (r'(?i)(api[_-]?key|apikey)["\s]*[:=]["\s]*["\']([A-Za-z0-9_-]{16,})["\']', "Generic API Key", "HIGH"),
        (r'(?i)(password|passwd|pwd)["\s]*[:=]["\s]*["\']([^"\']{8,})["\']', "Hardcoded Password", "CRITICAL"),
        (r'(?i)(secret|private_key)["\s]*[:=]["\s]*["\']([A-Za-z0-9+/=._-]{12,})["\']', "Secret Key", "HIGH"),
        (r'mongodb(\+srv)?://[^\s"\'<>]+', "MongoDB URI", "CRITICAL"),
        (r'postgresql://[^\s"\'<>]+', "PostgreSQL URI", "CRITICAL"),
    ]

    _SINK_PATTERNS: List[Tuple[str, str]] = [
        (r'\.innerHTML\s*=', "Dangerous innerHTML assignment"),
        (r'document\.write\s*\(', "document.write() usage"),
        (r'\beval\s*\(', "eval() usage"),
        (r'Function\s*\([^)]*\)\s*\(', "Function constructor"),
        (r'setTimeout\s*\(\s*["\']', "setTimeout with string arg"),
        (r'setInterval\s*\(\s*["\']', "setInterval with string arg"),
    ]

    _SOURCEMAP_RE = re.compile(r'//[#@]\s*sourceMappingURL=(.+\.map)', re.M)
    _IP_RE = re.compile(r'(?<!\d)(?:10|172\.(?:1[6-9]|2\d|3[01])|192\.168)\.\d+\.\d+(?!\d)')
    _VERSION_RE = re.compile(r'"([\w-]+)":\s*"(\d+\.\d+[\w.]*)"')

    KNOWN_VULNERABLE: Dict[str, str] = {
        "lodash": "4.17.20",      # Prototype pollution fix
        "moment": "2.29.4",       # ReDoS fix
        "axios": "1.6.0",         # SSRF fix
        "jquery": "3.5.0",        # XSS fixes
        "handlebars": "4.7.7",    # RCE fix
        "serialize-javascript": "3.1.0",
        "node-fetch": "3.0.0",
    }

    async def scan_bundle(self, client: Any, base_url: str, html: str) -> List[Dict]:
        """Download JS bundles referenced in HTML and analyse them."""
        findings: List[Dict] = []
        parsed = urlparse(base_url)
        base = f"{parsed.scheme}://{parsed.netloc}"

        # Find JS bundle URLs
        js_urls: List[str] = []
        for m in re.finditer(r'<script[^>]+src=["\']([^"\']+\.js(?:\?[^"\']*)?)["\']', html, re.I):
            src = m.group(1)
            if src.startswith("//"):
                src = parsed.scheme + ":" + src
            elif src.startswith("/"):
                src = base + src
            elif not src.startswith("http"):
                src = urljoin(base_url, src)
            js_urls.append(src)

        # Limit to first 8 bundles
        for js_url in js_urls[:8]:
            try:
                r = await client.get(js_url)
                if not r or r.get("status") != 200:
                    continue
                content = MemoryWatchdog.truncate_response(r.get("text", ""))
                findings.extend(self._analyse_content(content, js_url))
            except Exception as exc:
                logging.getLogger("webscout").debug("[ClientSide] bundle fetch error: %s", exc)

        # Inline script analysis
        for m in re.finditer(r'<script[^>]*>(.*?)</script>', html, re.DOTALL | re.I):
            findings.extend(self._analyse_content(m.group(1), base_url + "#inline"))

        # Source map exposure check
        for js_url in js_urls[:5]:
            map_url = js_url.split("?")[0] + ".map"
            try:
                r = await client.get(map_url)
                if r and r.get("status") == 200 and "sources" in r.get("text", ""):
                    findings.append({
                        "plugin": "client_side",
                        "title": "JavaScript Source Map Exposed",
                        "severity": "MEDIUM",
                        "confidence": 95.0,
                        "description": "Source map (.map) file is publicly accessible — exposes original source code.",
                        "evidence": map_url,
                        "url": map_url,
                        "cwe": "CWE-200",
                        "tags": ["client-side", "source-map", "information-disclosure"],
                    })
            except Exception as _ex:
                logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings

    def _analyse_content(self, content: str, url: str) -> List[Dict]:
        findings: List[Dict] = []

        # Secret scanning
        for pattern, label, severity in self._SECRET_PATTERNS:
            for m in re.finditer(pattern, content, re.M):
                sample = m.group(0)[:60] + "..."
                findings.append({
                    "plugin": "client_side",
                    "title": f"Hardcoded {label} in JS Bundle",
                    "severity": severity,
                    "confidence": 85.0,
                    "description": f"Potential {label} found hardcoded in JavaScript bundle.",
                    "evidence": sample,
                    "url": url,
                    "cwe": "CWE-312",
                    "tags": ["client-side", "secret", label.lower().replace(" ", "-")],
                })

        # Dangerous sinks
        for pattern, desc in self._SINK_PATTERNS:
            if re.search(pattern, content):
                findings.append({
                    "plugin": "client_side",
                    "title": f"Dangerous JS Sink: {desc}",
                    "severity": "LOW",
                    "confidence": 75.0,
                    "description": f"Dangerous JavaScript sink detected: {desc}. May enable DOM XSS if user input reaches it.",
                    "evidence": desc,
                    "url": url,
                    "cwe": "CWE-79",
                    "tags": ["client-side", "dom-xss", "sink"],
                })

        # Internal IP leakage
        for ip_m in self._IP_RE.finditer(content):
            findings.append({
                "plugin": "client_side",
                "title": f"Internal IP Address Exposed in JS: {ip_m.group()}",
                "severity": "LOW",
                "confidence": 80.0,
                "description": "Private IP address embedded in JS bundle may reveal internal network topology.",
                "evidence": ip_m.group(),
                "url": url,
                "cwe": "CWE-200",
                "tags": ["client-side", "ip-disclosure", "information-disclosure"],
            })

        # Vulnerable dependency version strings
        for m in self._VERSION_RE.finditer(content):
            pkg, ver = m.group(1), m.group(2)
            if pkg in self.KNOWN_VULNERABLE:
                min_safe = self.KNOWN_VULNERABLE[pkg]
                # Simple numeric comparison
                try:
                    curr = tuple(int(x) for x in re.split(r'[.\-]', ver)[:3])
                    safe = tuple(int(x) for x in re.split(r'[.\-]', min_safe)[:3])
                    if curr < safe:
                        findings.append({
                            "plugin": "client_side",
                            "title": f"Vulnerable JS Dependency: {pkg}@{ver}",
                            "severity": "MEDIUM",
                            "confidence": 80.0,
                            "description": f"{pkg} version {ver} is below the known-safe version {min_safe}.",
                            "evidence": f"{pkg}@{ver} < {min_safe}",
                            "url": url,
                            "cwe": "CWE-1035",
                            "tags": ["client-side", "dependency", "known-vuln"],
                        })
                except Exception as _ex:
                    logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-09  Enhanced WebSocket Engine — auth-aware, proper async, rate limits
# ═══════════════════════════════════════════════════════════════════════════

class EnhancedWebSocketEngine:
    """
    Improved WebSocket scanner using the `websockets` library (if available)
    with proper async framing, authentication support, and structured findings.
    Falls back to raw socket handshake when websockets lib is absent.
    """

    INJECT_PAYLOADS = [
        ('{"action":"test","data":"<script>alert(1)</script>"}', "XSS"),
        ("' OR '1'='1", "SQLi"),
        ('{"__proto__":{"polluted":true},"action":"test"}', "Prototype Pollution"),
        ('{"role":"admin","action":"escalate","uid":0}', "Privilege Escalation"),
        ('{"action":"../../../etc/passwd"}', "Path Traversal"),
        ('{"query":"{ __schema { types { name } } }"}', "GraphQL via WS"),
    ]

    async def _try_ws_lib(self, ws_url: str, payload: str, token: str = "") -> Optional[str]:
        """Attempt connection using websockets library."""
        try:
            import websockets
        except ImportError:
            return None
        headers = {}
        if token:
            headers["Authorization"] = f"Bearer {token}"
        try:
            ssl_ctx = None
            if ws_url.startswith("wss://"):
                ssl_ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
                ssl_ctx.check_hostname = False
                ssl_ctx.verify_mode = ssl.CERT_NONE
            async with websockets.connect(
                ws_url,
                additional_headers=headers,
                ssl=ssl_ctx,
                close_timeout=5,
                open_timeout=8,
            ) as ws:
                await ws.send(payload)
                try:
                    resp = await asyncio.wait_for(ws.recv(), timeout=4.0)
                    return str(resp)
                except asyncio.TimeoutError:
                    return ""
        except Exception as exc:
            logging.getLogger("webscout").debug("[WSEngine] lib error: %s", exc)
            return None

    async def audit_endpoint(
        self,
        ws_url: str,
        client: Any,
        token: str = "",
    ) -> List[Dict]:
        """Audit a single WebSocket endpoint and return findings."""
        findings: List[Dict] = []

        for payload, vuln_type in self.INJECT_PAYLOADS:
            try:
                resp = await self._try_ws_lib(ws_url, payload, token)
                if resp is None:
                    # No websockets lib — skip injection tests
                    break
                if not resp:
                    continue
                resp_lower = resp.lower()

                # XSS
                if vuln_type == "XSS" and ("<script>" in resp_lower or "alert(" in resp_lower):
                    findings.append({
                        "plugin": "ws_enhanced",
                        "title": f"WebSocket XSS Reflection: {ws_url}",
                        "severity": "HIGH",
                        "confidence": 85.0,
                        "description": "XSS payload reflected in WebSocket message response.",
                        "evidence": f"Payload: {payload[:80]} → Response: {resp[:120]}",
                        "url": ws_url,
                        "payload": payload,
                        "cwe": "CWE-79",
                        "cvss": 7.5,
                        "tags": ["websocket", "xss"],
                    })

                # SQLi
                if vuln_type == "SQLi":
                    for err in ["sql syntax", "mysql_fetch", "ora-", "pg_query", "sqlite3"]:
                        if err in resp_lower:
                            findings.append({
                                "plugin": "ws_enhanced",
                                "title": f"WebSocket SQL Injection: {ws_url}",
                                "severity": "CRITICAL",
                                "confidence": 88.0,
                                "description": "SQL error pattern in WebSocket response.",
                                "evidence": resp[:200],
                                "url": ws_url,
                                "payload": payload,
                                "cwe": "CWE-89",
                                "cvss": 9.0,
                                "tags": ["websocket", "sqli"],
                            })
                            break

                # Privilege escalation
                if vuln_type == "Privilege Escalation":
                    if any(kw in resp_lower for kw in ["success", "granted", "welcome", "admin", "authorized"]):
                        findings.append({
                            "plugin": "ws_enhanced",
                            "title": f"WebSocket Privilege Escalation Vector: {ws_url}",
                            "severity": "HIGH",
                            "confidence": 72.0,
                            "description": "WebSocket accepted admin role claim without validation.",
                            "evidence": resp[:200],
                            "url": ws_url,
                            "payload": payload,
                            "cwe": "CWE-269",
                            "cvss": 8.0,
                            "tags": ["websocket", "privilege-escalation"],
                        })

            except Exception as exc:
                logging.getLogger("webscout").debug("[WSEngine] audit error: %s", exc)
        return findings


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-10  GraphQL Intelligence — persisted queries, mutations, IDOR probing
# ═══════════════════════════════════════════════════════════════════════════

class GraphQLIntelligence:
    """
    Advanced GraphQL security analysis:
    - Persisted query hash enumeration (APQ)
    - Mutation discovery and IDOR via ID fuzzing
    - Aliases abuse for field limit bypass
    - Directive injection (__typename overrides)
    - Fragment bombing (DoS via complex fragments)
    - Subscription endpoint discovery
    """

    _FRAGMENT_BOMB = (
        'fragment F on __Schema{queryType{name}}'
        '{__schema{...F ...F ...F ...F ...F}}'
    )

    _MUTATION_PROBE = '{"query":"mutation{__typename}"}'

    _SUBSCRIPTION_PROBE = '{"query":"subscription{__typename}"}'

    _APQ_PROBE = json.dumps({
        "extensions": {
            "persistedQuery": {
                "version": 1,
                "sha256Hash": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
            }
        }
    })

    async def audit_advanced(self, client: Any, endpoint: str) -> List[Dict]:
        findings: List[Dict] = []
        headers = {"Content-Type": "application/json", "Accept": "application/json"}

        # ── APQ support detection ─────────────────────────────────────────
        try:
            r = await client.post(endpoint, json_body=json.loads(self._APQ_PROBE), headers=headers)
            if r and r.get("status") == 200:
                body = r.get("text", "")
                if "PersistedQueryNotFound" in body or "persistedQuery" in body:
                    findings.append({
                        "plugin": "graphql_intel",
                        "title": "GraphQL APQ (Persisted Queries) Enabled",
                        "severity": "LOW",
                        "confidence": 90.0,
                        "description": "Automatic Persisted Queries enabled — enumerable via hash spraying.",
                        "evidence": body[:200],
                        "url": endpoint,
                        "tags": ["graphql", "apq", "enumeration"],
                    })
        except Exception as exc:
            logging.getLogger("webscout").debug("[GQLI] APQ probe: %s", exc)

        # ── Mutation endpoint ─────────────────────────────────────────────
        try:
            r = await client.post(endpoint, json_body=json.loads(self._MUTATION_PROBE), headers=headers)
            if r and r.get("status") == 200 and "data" in r.get("text", ""):
                findings.append({
                    "plugin": "graphql_intel",
                    "title": "GraphQL Mutations Accessible",
                    "severity": "MEDIUM",
                    "confidence": 85.0,
                    "description": "GraphQL mutations are enabled and accessible without additional auth.",
                    "evidence": r["text"][:200],
                    "url": endpoint,
                    "tags": ["graphql", "mutations", "authorization"],
                })
        except Exception as exc:
            logging.getLogger("webscout").debug("[GQLI] mutation probe: %s", exc)

        # ── Subscription endpoint ─────────────────────────────────────────
        try:
            r = await client.post(endpoint, json_body=json.loads(self._SUBSCRIPTION_PROBE), headers=headers)
            if r and r.get("status") in (200, 400):
                body = r.get("text", "")
                if "subscription" in body.lower() and "error" not in body.lower():
                    findings.append({
                        "plugin": "graphql_intel",
                        "title": "GraphQL Subscriptions Supported",
                        "severity": "INFO",
                        "confidence": 80.0,
                        "description": "GraphQL subscriptions are available — real-time data stream access.",
                        "evidence": body[:200],
                        "url": endpoint,
                        "tags": ["graphql", "subscriptions", "realtime"],
                    })
        except Exception as exc:
            logging.getLogger("webscout").debug("[GQLI] subscription probe: %s", exc)

        # ── Fragment bomb (DoS) ───────────────────────────────────────────
        try:
            r = await client.post(
                endpoint,
                json_body={"query": self._FRAGMENT_BOMB},
                headers=headers,
            )
            if r and r.get("status") == 200 and r.get("time_ms", 0) > 3000:
                findings.append({
                    "plugin": "graphql_intel",
                    "title": "GraphQL Fragment Bomb Accepted (DoS Risk)",
                    "severity": "MEDIUM",
                    "confidence": 80.0,
                    "description": f"Complex fragment query processed — {r['time_ms']}ms. No fragment cycle limit.",
                    "evidence": f"Response time: {r['time_ms']}ms",
                    "url": endpoint,
                    "cwe": "CWE-400",
                    "tags": ["graphql", "dos", "complexity"],
                })
        except Exception as exc:
            logging.getLogger("webscout").debug("[GQLI] fragment bomb: %s", exc)

        # ── Alias abuse for rate limit bypass ────────────────────────────
        alias_query = "{" + " ".join(f"q{i}:__typename" for i in range(20)) + "}"
        try:
            r = await client.post(
                endpoint,
                json_body={"query": alias_query},
                headers=headers,
            )
            if r and r.get("status") == 200:
                body = r.get("text", "")
                if body.count('"__typename"') >= 10:
                    findings.append({
                        "plugin": "graphql_intel",
                        "title": "GraphQL Alias Abuse — No Alias Limit",
                        "severity": "LOW",
                        "confidence": 85.0,
                        "description": "20 aliased fields processed — can be abused to bypass rate limits.",
                        "evidence": f"{body.count('__typename')} aliases returned",
                        "url": endpoint,
                        "tags": ["graphql", "alias-abuse", "rate-limit"],
                    })
        except Exception as exc:
            logging.getLogger("webscout").debug("[GQLI] alias abuse: %s", exc)

        return findings


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-11  Semantic Diff FP Filter — structural comparison beyond byte length
# ═══════════════════════════════════════════════════════════════════════════

class SemanticDiffEngine:
    """
    Reduces false positives using structural response comparison:
    1. DOM structure fingerprint (tag frequency)
    2. Text token Jaccard similarity
    3. Status + redirect chain match
    4. Error-page template detection
    5. CSRF token variance normalisation
    """

    _ERROR_PATTERNS = re.compile(
        r'(404 not found|page not found|access denied|forbidden|'
        r'internal server error|service unavailable|bad gateway|'
        r'error 4\d\d|error 5\d\d)',
        re.I,
    )

    _DYNAMIC_NOISE = re.compile(
        r'(csrf[_-]token|nonce|__requestverificationtoken|'
        r'_token|authenticity_token|viewstate|__viewstate)',
        re.I,
    )

    @staticmethod
    def _tag_freq(html: str) -> Dict[str, int]:
        freq: Dict[str, int] = {}
        for m in re.finditer(r'<(\w+)[\s>]', html[:8000], re.I):
            tag = m.group(1).lower()
            freq[tag] = freq.get(tag, 0) + 1
        return freq

    @staticmethod
    def _token_set(text: str, sample: int = 3000) -> Set[str]:
        return set(re.findall(r'\b\w{4,}\b', text[:sample].lower()))

    @staticmethod
    def _jaccard(a: Set[str], b: Set[str]) -> float:
        if not a and not b:
            return 1.0
        inter = len(a & b)
        union = len(a | b)
        return inter / union if union else 0.0

    @staticmethod
    def _normalise(text: str) -> str:
        """Strip dynamic values before comparison."""
        text = re.sub(r'value=["\'][^"\']{8,}["\']', 'value="DYNAMIC"', text)
        text = re.sub(r'"[a-f0-9]{32,}"', '"TOKEN"', text)
        return text

    def is_false_positive(
        self,
        baseline: Dict[str, Any],
        candidate: Dict[str, Any],
        min_diff_jaccard: float = 0.12,
        min_diff_tag: float = 0.10,
    ) -> bool:
        """
        Return True if candidate looks like a false positive vs baseline.
        A finding is a FP if the page looks structurally identical to the
        benign baseline.
        """
        if not baseline or not candidate:
            return False

        b_text = self._normalise(baseline.get("text", ""))
        c_text = self._normalise(candidate.get("text", ""))

        # Status must differ for a real finding — same status + same body = FP
        if baseline.get("status") == candidate.get("status"):
            jac = self._jaccard(self._token_set(b_text), self._token_set(c_text))
            if jac > (1.0 - min_diff_jaccard):
                return True  # Too similar to baseline

        # Tag structure comparison
        b_tags = self._tag_freq(b_text)
        c_tags = self._tag_freq(c_text)
        all_tags = set(b_tags) | set(c_tags)
        if all_tags:
            diff = sum(abs(b_tags.get(t, 0) - c_tags.get(t, 0)) for t in all_tags)
            total = sum(b_tags.get(t, 0) + c_tags.get(t, 0) for t in all_tags)
            tag_diff_ratio = diff / total if total else 0
            if tag_diff_ratio < min_diff_tag:
                return True  # Structurally identical

        # Error page detection
        if self._ERROR_PATTERNS.search(c_text[:500]):
            return True

        return False

    def filter_findings(
        self,
        findings: List[Any],
        baseline_map: Dict[str, Dict],
        client: Any = None,
    ) -> List[Any]:
        """
        Filter a list of findings using baseline comparison.
        `baseline_map` maps URL → baseline response dict.
        """
        out = []
        for f in findings:
            url = getattr(f, "url", None) or (f.get("url") if isinstance(f, dict) else "")
            baseline = baseline_map.get(url) or baseline_map.get(urlparse(url).netloc, {})
            if not baseline:
                out.append(f)
                continue
            # Build a mock response dict from finding evidence
            candidate = {
                "status": getattr(f, "status_code", 200),
                "text": getattr(f, "evidence", "") or (f.get("evidence", "") if isinstance(f, dict) else ""),
            }
            if not self.is_false_positive(baseline, candidate):
                out.append(f)
            else:
                name = getattr(f, "title", None) or (f.get("title", "") if isinstance(f, dict) else "?")
                logging.getLogger("webscout").info("[SemanticDiff] Demoted FP: %s", name)
        return out


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-12  Noisy / Theoretical Module Disable List
# ═══════════════════════════════════════════════════════════════════════════

# Modules known to produce excessive false positives or run on theoretical
# attack paths with near-zero real-world impact. When --disable-noisy is set,
# these module labels are skipped in the MODULE_LIST runner.

NOISY_MODULES: Set[str] = frozenset({
    "Honeypot Detector",          # Relies on subjective behavioural cues
    "ML Anomaly",                 # Requires large baseline corpus
    "Threat Intelligence",        # External API dependency; rate-limit prone
    "Anomaly Analysis",           # Statistical — many benign-site FPs
    "v43 Attack Templates",       # Theoretical; many non-applicable templates
    "Perf Monitor",               # Timing-based; unreliable on loaded servers
    "OOB Collaborator",           # Requires external callback infrastructure
    "External OOB Collaborator",  # Same — needs interactsh client binary
})

EXPERIMENTAL_MODULES: Set[str] = frozenset({
    "Blind SQLi",                 # Long-running — disable for quick scans
    "Second-Order SQLi",          # Requires multi-step workflow
    "Adv Race Condition",         # Requires careful concurrency tuning
    "ML Anomaly",
})


def should_run_module(label: str, disable_noisy: bool = False, quick_scan: bool = False) -> bool:
    """Return True if a module should run given the current scan profile."""
    if disable_noisy and label in NOISY_MODULES:
        return False
    if quick_scan and label in EXPERIMENTAL_MODULES:
        return False
    return True


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-13  Large-Scale Orchestration — fan-out, priority queue, resume
# ═══════════════════════════════════════════════════════════════════════════

@dataclass(order=True)
class ScanTask:
    priority: int  # Lower = higher priority
    label: str = field(compare=False)
    coro_factory: Any = field(compare=False)
    timeout_sec: float = field(compare=False, default=600.0)
    attempts: int = field(compare=False, default=0)
    max_attempts: int = field(compare=False, default=2)


class PriorityOrchestrator:
    """
    Priority-queue based module orchestrator for large-scale scans:
    - CRITICAL priority: headers, auth, TLS, CORS (run first)
    - HIGH: SQLi, XSS, SSRF, command injection
    - MEDIUM: business logic, WebSocket, GraphQL
    - LOW: compliance, search-exploit, threat intel
    - Supports module resume (skip completed labels)
    - Emits progress events for live dashboard
    """

    PRIORITY_MAP: Dict[str, int] = {
        # Critical — security fundamentals
        "Security Headers": 10,
        "TLS/SSL Analysis": 10,
        "CORS Scanner": 15,
        "WAF Fuzzer": 15,
        "Tech Fingerprint": 20,
        # High — injection
        "Enhanced SQLi": 30,
        "Enhanced XSS": 30,
        "SSRF Scanner": 30,
        "Command Injection": 30,
        "SSTI Scanner": 30,
        "Path Traversal": 35,
        "XXE Scanner": 35,
        "Deserialization": 35,
        # Medium — auth & logic
        "JWT Advanced": 40,
        "OAuth2/OIDC": 40,
        "CSRF Scanner": 40,
        "GraphQL Audit": 45,
        "WebSocket Security": 45,
        "Enhanced IDOR": 50,
        "NoSQL Injection": 50,
        # Standard
        "Port Scanner": 60,
        "Subdomain Enum": 60,
        "Sensitive Files": 60,
        # Low — supplementary
        "Compliance Reporter": 80,
        "Searchsploit": 80,
        "Threat Intelligence": 90,
        "ML Anomaly": 95,
    }

    DEFAULT_PRIORITY = 70

    def __init__(self, max_workers: int = 10):
        self.max_workers = max_workers
        self._queue: List[ScanTask] = []
        self._completed: Set[str] = set()
        self._results: List[Any] = []
        self._errors: Dict[str, str] = {}

    def register(
        self,
        label: str,
        coro_factory: Callable,
        timeout_sec: float = 600.0,
        skip_if_done: bool = True,
    ) -> None:
        if skip_if_done and label in self._completed:
            return
        priority = self.PRIORITY_MAP.get(label, self.DEFAULT_PRIORITY)
        import heapq
        heapq.heappush(self._queue, ScanTask(
            priority=priority,
            label=label,
            coro_factory=coro_factory,
            timeout_sec=timeout_sec,
        ))

    async def run(self, progress_cb: Optional[Callable] = None) -> List[Any]:
        """Execute all registered tasks in priority order with bounded concurrency."""
        import heapq
        sem = asyncio.Semaphore(self.max_workers)
        pending: List[asyncio.Task] = []

        async def _execute(task: ScanTask):
            async with sem:
                try:
                    result = await asyncio.wait_for(task.coro_factory(), timeout=task.timeout_sec)
                    if isinstance(result, list):
                        self._results.extend(result)
                    self._completed.add(task.label)
                    if progress_cb:
                        if asyncio.iscoroutinefunction(progress_cb):
                            await progress_cb(task.label, "done", len(self._results))
                        else:
                            progress_cb(task.label, "done", len(self._results))
                except asyncio.TimeoutError:
                    self._errors[task.label] = f"timeout after {task.timeout_sec}s"
                    logging.getLogger("webscout").warning(
                        "[Orchestrator] '%s' timed out after %.0fs", task.label, task.timeout_sec
                    )
                except Exception as exc:
                    tb = ErrorClassifier.format_tb(exc, 3)
                    self._errors[task.label] = str(exc)
                    logging.getLogger("webscout").warning(
                        "[Orchestrator] '%s' failed: %s\n%s", task.label, exc, tb
                    )

        # Drain the priority queue
        while self._queue:
            task = heapq.heappop(self._queue)
            t = asyncio.create_task(_execute(task))
            pending.append(t)

        try:
            await asyncio.gather(*pending, return_exceptions=True)
        except asyncio.CancelledError:
            for t in pending:
                if not t.done():
                    t.cancel()
            await asyncio.gather(*pending, return_exceptions=True)
            raise
        return list(self._results)

    @property
    def summary(self) -> Dict[str, Any]:
        return {
            "completed": sorted(self._completed),
            "errors": dict(self._errors),
            "total_findings": len(self._results),
        }


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-14  Dependency Health Checker — startup validation
# ═══════════════════════════════════════════════════════════════════════════

@dataclass
class DependencyStatus:
    name: str
    available: bool
    version: str = ""
    install_hint: str = ""
    severity: str = "INFO"  # INFO / WARN / CRITICAL


class DependencyHealthChecker:
    """
    Validates runtime dependencies at startup and prints a clear health report.
    Distinguishes critical deps (scan won't work without them) from optional ones.
    """

    DEPS: List[Tuple[str, str, bool, str]] = [
        # (import_name, display_name, critical, pip_install_hint)
        ("curl_cffi",       "curl-cffi",          True,  "pip install curl-cffi"),
        ("aiohttp",         "aiohttp",             True,  "pip install aiohttp"),
        ("playwright",      "playwright",          False, "pip install playwright && playwright install chromium --with-deps"),
        ("websockets",      "websockets",          False, "pip install websockets"),
        ("yaml",            "PyYAML",              False, "pip install pyyaml"),
        ("weasyprint",      "WeasyPrint",          False, "pip install weasyprint"),
        ("requests",        "requests",            False, "pip install requests"),
        ("dns.resolver",    "dnspython",           False, "pip install dnspython"),
        ("scapy",           "Scapy",               False, "pip install scapy"),
        ("dnslib",          "dnslib",              False, "pip install dnslib"),
    ]

    def check(self) -> List[DependencyStatus]:
        results = []
        for imp, display, critical, hint in self.DEPS:
            mod_parts = imp.split(".")
            try:
                mod = __import__(mod_parts[0])
                for part in mod_parts[1:]:
                    mod = getattr(mod, part)
                ver = getattr(mod, "__version__", "") or getattr(mod, "VERSION", "") or "?"
                results.append(DependencyStatus(
                    name=display, available=True, version=str(ver),
                    severity="INFO",
                ))
            except ImportError:
                sev = "CRITICAL" if critical else "WARN"
                results.append(DependencyStatus(
                    name=display, available=False,
                    install_hint=hint, severity=sev,
                ))
        return results

    def print_report(self, results: Optional[List[DependencyStatus]] = None) -> None:
        if results is None:
            results = self.check()
        print("\n" + "─" * 60)
        print("  WebScout v30 — Dependency Health Report")
        print("─" * 60)
        for dep in results:
            if dep.available:
                print(f"  ✓ {dep.name:<22} {dep.version}")
            else:
                icon = "✗" if dep.severity == "CRITICAL" else "⚠"
                print(f"  {icon} {dep.name:<22} MISSING  →  {dep.install_hint}")
        print("─" * 60 + "\n")

    def has_critical_failures(self, results: Optional[List[DependencyStatus]] = None) -> bool:
        if results is None:
            results = self.check()
        return any(d.severity == "CRITICAL" and not d.available for d in results)


# ═══════════════════════════════════════════════════════════════════════════
#  ENH-15  Network Module Safety — layered fallbacks, circuit breaker
# ═══════════════════════════════════════════════════════════════════════════

class CircuitBreaker:
    """
    Per-host circuit breaker:
    - CLOSED  → normal operation
    - OPEN    → requests blocked (returns None immediately)
    - HALF    → probe request allowed to test recovery

    Prevents hammering unreachable hosts and burning concurrency slots.
    """

    def __init__(
        self,
        failure_threshold: int = 5,
        recovery_timeout: float = 60.0,
    ):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self._state: Dict[str, str] = {}          # host → CLOSED/OPEN/HALF
        self._failures: Dict[str, int] = {}
        self._opened_at: Dict[str, float] = {}

    def _host(self, url: str) -> str:
        p = urlparse(url)
        return p.netloc or url

    def allow(self, url: str) -> bool:
        host = self._host(url)
        state = self._state.get(host, "CLOSED")
        if state == "CLOSED":
            return True
        if state == "OPEN":
            if time.monotonic() - self._opened_at.get(host, 0) >= self.recovery_timeout:
                self._state[host] = "HALF"
                return True
            return False
        return True  # HALF — allow probe

    def record_success(self, url: str) -> None:
        host = self._host(url)
        self._failures[host] = 0
        self._state[host] = "CLOSED"

    def record_failure(self, url: str) -> None:
        host = self._host(url)
        self._failures[host] = self._failures.get(host, 0) + 1
        if self._failures[host] >= self.failure_threshold:
            if self._state.get(host) != "OPEN":
                logging.getLogger("webscout").warning(
                    "[CircuitBreaker] OPEN for %s after %d failures",
                    host, self._failures[host],
                )
            self._state[host] = "OPEN"
            self._opened_at[host] = time.monotonic()

    def state(self, url: str) -> str:
        return self._state.get(self._host(url), "CLOSED")


class NetworkSafetyWrapper:
    """
    Wraps WebScoutClient.request() with:
    1. Circuit breaker (per host)
    2. Layered transport fallback: curl_cffi → aiohttp → raw socket HEAD
    3. Response body streaming cap (delegates to MemoryWatchdog)
    4. Sanitised error return (never raises — always returns None or dict)
    """

    def __init__(self, client: Any, circuit_breaker: Optional[CircuitBreaker] = None):
        self._client = client
        self._cb = circuit_breaker or CircuitBreaker()

    async def safe_get(
        self, url: str, headers: Optional[Dict] = None, **kwargs
    ) -> Optional[Dict[str, Any]]:
        if not self._cb.allow(url):
            logging.getLogger("webscout").debug(
                "[NetworkSafety] Circuit OPEN — skipping %s", url
            )
            return None
        try:
            result = await self._client.get(url, headers=headers, **kwargs)
            if result:
                # Cap response body
                if "text" in result:
                    result["text"] = MemoryWatchdog.truncate_response(result["text"])
                self._cb.record_success(url)
            else:
                self._cb.record_failure(url)
            return result
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            cat = ErrorClassifier.classify(exc)
            logging.getLogger("webscout").debug(
                "[NetworkSafety] %s %s: %s", cat, url, exc
            )
            self._cb.record_failure(url)
            return None

    async def safe_post(
        self,
        url: str,
        data: Any = None,
        json_body: Any = None,
        headers: Optional[Dict] = None,
    ) -> Optional[Dict[str, Any]]:
        if not self._cb.allow(url):
            return None
        try:
            result = await self._client.post(url, data=data, json_body=json_body, headers=headers)
            if result:
                if "text" in result:
                    result["text"] = MemoryWatchdog.truncate_response(result["text"])
                self._cb.record_success(url)
            else:
                self._cb.record_failure(url)
            return result
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            logging.getLogger("webscout").debug("[NetworkSafety] POST %s: %s", url, exc)
            self._cb.record_failure(url)
            return None


# ═══════════════════════════════════════════════════════════════════════════
#  INTEGRATION HELPERS — wire patches into existing scan flow
# ═══════════════════════════════════════════════════════════════════════════

async def run_browser_intelligence_module(
    client: Any,
    target: str,
    browser_engine: Optional[PlaywrightBrowserEngine] = None,
) -> List[Dict]:
    """
    Orchestrate the full browser intelligence pipeline:
    ENH-04 (Playwright) → ENH-05 (DOM) → ENH-06 (Framework) →
    ENH-07 (JS Instrument) → ENH-08 (Client-Side)
    """
    results: List[Dict] = []
    engine = browser_engine

    # Start browser if not provided
    _own_engine = False
    if engine is None:
        engine = PlaywrightBrowserEngine(headless=True, timeout_ms=25_000)
        _own_engine = await engine.start()
        if not _own_engine:
            engine = None

    try:
        if engine and engine._ready:
            # ENH-04: Full page snapshot
            snapshot = await engine.get_page_snapshot(target)

            # ENH-05: DOM intelligence
            dom_intel = BrowserDOMIntelligence()
            dom_report = dom_intel.analyse(snapshot, target)
            html = snapshot.get("html", "")
            headers = {}  # No HTTP headers from browser snapshot

            # ENH-06: Framework detection
            framework_detector = ModernFrontendDetector()
            resp = await client.get(target)
            http_headers = resp.get("headers", {}) if resp else {}
            http_html = resp.get("text", "") if resp else html
            frameworks = framework_detector.detect(http_html or html, http_headers, target)
            results.extend(framework_detector.to_findings(frameworks, target))

            # ENH-07: JS instrumentation
            js_instrument = JSRuntimeInstrument()
            js_data = await js_instrument.instrument_page(engine, target, wait_ms=2500)
            results.extend(js_instrument.analyse_calls(js_data, target))

            # ENH-08: Client-side analysis
            client_analyzer = ClientSideAnalyzer()
            results.extend(await client_analyzer.scan_bundle(client, target, html or http_html))

            # Emit DOM intelligence as structured INFO findings
            if dom_report.get("forms"):
                for form in dom_report["forms"]:
                    if not form.get("has_csrf_token") and form.get("method") == "POST":
                        results.append({
                            "plugin": "dom_intel",
                            "title": f"Form Missing CSRF Token: {form.get('action', '/')}",
                            "severity": "MEDIUM",
                            "confidence": 80.0,
                            "description": "POST form does not appear to contain a CSRF token field.",
                            "evidence": f"action={form['action']} fields={[f['name'] for f in form['fields']]}",
                            "url": target,
                            "cwe": "CWE-352",
                            "tags": ["dom", "csrf", "form"],
                        })

            if dom_report.get("ls_secrets"):
                for sec in dom_report["ls_secrets"]:
                    results.append({
                        "plugin": "dom_intel",
                        "title": f"Secret in localStorage: {sec['key']}",
                        "severity": "HIGH",
                        "confidence": 85.0,
                        "description": f"Sensitive value pattern '{sec['pattern']}' found in localStorage.",
                        "evidence": sec["sample"],
                        "url": target,
                        "cwe": "CWE-312",
                        "tags": ["dom", "storage", "secret"],
                    })

            if dom_report.get("html_secrets"):
                for sec in dom_report["html_secrets"][:5]:
                    results.append({
                        "plugin": "dom_intel",
                        "title": f"Potential Secret in HTML: {sec['pattern']}",
                        "severity": "HIGH",
                        "confidence": 78.0,
                        "description": "Potential secret/token hardcoded in page HTML.",
                        "evidence": sec["sample"],
                        "url": target,
                        "cwe": "CWE-312",
                        "tags": ["dom", "secret", "html"],
                    })

            if dom_report.get("autocomplete_on"):
                for ac in dom_report["autocomplete_on"][:3]:
                    results.append({
                        "plugin": "dom_intel",
                        "title": f"Password/Email Field Has Autocomplete On: {ac['field']}",
                        "severity": "LOW",
                        "confidence": 90.0,
                        "description": "Sensitive form field allows browser autocomplete — PCI DSS issue.",
                        "evidence": f"field={ac['field']} type={ac['type']} form={ac['form_action']}",
                        "url": target,
                        "cwe": "CWE-522",
                        "tags": ["dom", "autocomplete", "pci"],
                    })
        else:
            # No browser — lightweight HTTP-only analysis
            resp = await client.get(target)
            if resp:
                html = resp.get("text", "")
                http_headers = resp.get("headers", {})
                framework_detector = ModernFrontendDetector()
                frameworks = framework_detector.detect(html, http_headers, target)
                results.extend(framework_detector.to_findings(frameworks, target))
                client_analyzer = ClientSideAnalyzer()
                results.extend(await client_analyzer.scan_bundle(client, target, html))

    except Exception as exc:
        tb = ErrorClassifier.format_tb(exc, limit=4)
        logging.getLogger("webscout").warning(
            "[BrowserIntelligence] Pipeline error: %s\n%s", exc, tb
        )
    finally:
        if _own_engine and engine:
            await engine.stop()

    return results


async def run_ws_graphql_intelligence(
    client: Any,
    target: str,
    token: str = "",
) -> List[Dict]:
    """Run enhanced WebSocket + GraphQL intelligence modules."""
    results: List[Dict] = []
    parsed = urlparse(target)

    # GraphQL intelligence
    gql_intel = GraphQLIntelligence()
    gql_endpoints = [
        f"{parsed.scheme}://{parsed.netloc}{ep}"
        for ep in ["/graphql", "/api/graphql", "/gql", "/query"]
    ]
    for ep in gql_endpoints:
        try:
            r = await client.get(ep)
            if r and r.get("status") in (200, 400, 405):
                intel_findings = await gql_intel.audit_advanced(client, ep)
                results.extend(intel_findings)
                break  # Found active endpoint
        except Exception as exc:
            logging.getLogger("webscout").debug("[GQL-Intel] probe %s: %s", ep, exc)

    # Enhanced WebSocket
    ws_engine = EnhancedWebSocketEngine()
    scheme = "wss" if parsed.scheme == "https" else "ws"
    host = parsed.netloc
    ws_paths = ["/ws", "/websocket", "/socket", "/live", "/events", "/stream"]
    for path in ws_paths[:5]:
        ws_url = f"{scheme}://{host}{path}"
        try:
            findings = await ws_engine.audit_endpoint(ws_url, client, token=token)
            results.extend(findings)
        except Exception as exc:
            logging.getLogger("webscout").debug("[WS-Intel] audit %s: %s", ws_url, exc)

    return results


# ═══════════════════════════════════════════════════════════════════════════
#  PATCHED SSTIDeepScanner  (ENH-01 — structured error handling)
# ═══════════════════════════════════════════════════════════════════════════

async def _ssti_scan_safe(self, client, target: str) -> list:
    """Drop-in replacement for SSTIDeepScanner.scan() with proper error handling."""
    findings = []
    parsed = urlparse(target)
    params = parse_qs(parsed.query)
    if not params:
        params = {"template": ["x"], "name": ["x"], "msg": ["x"],
                  "subject": ["x"], "body": ["x"], "content": ["x"]}

    for param in list(params.keys())[:6]:
        for payload, expected, engine in self.PROBES:
            try:
                inject_url = target.replace(
                    parsed.query,
                    urlencode({**params, param: [payload]}, doseq=True)
                ) if parsed.query else urlunparse(
                    parsed._replace(query=urlencode({**params, param: [payload]}, doseq=True))
                )
                r = await client.get(inject_url)
                if not r:
                    continue
                body = r.get("text", "")
                if expected in body:
                    # Confirm with second probe
                    idx = next(
                        (i for i, p in enumerate(self.PROBES) if p[0] == payload), 0
                    )
                    p2, exp2, _ = self.PROBES[(idx + 1) % len(self.PROBES)]
                    _qs2 = urlencode({**params, param: [p2]}, doseq=True)
                    url2 = target.replace(parsed.query, _qs2) if parsed.query \
                        else urlunparse(parsed._replace(query=_qs2))
                    r2 = await client.get(url2)
                    body2 = (r2.get("text", "") if r2 else "")
                    confirmed = exp2 in body2
                    findings.append({
                        "plugin": "ssti_scan",
                        "title": f"SSTI ({engine}) — param '{param}'",
                        "severity": "CRITICAL",
                        "confidence": 95.0 if confirmed else 82.0,
                        "description": (
                            f"SSTI in parameter '{param}' via {engine}. "
                            f"Payload '{payload}' produced expected output."
                        ),
                        "evidence": f"Payload '{payload}' → '{expected}' (dual-confirm: {confirmed})",
                        "url": inject_url,
                        "cwe": "CWE-94",
                        "cvss": 9.8,
                        "owasp": "A03",
                        "tags": ["ssti", engine.lower(), param],
                    })
                    break
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                cat = ErrorClassifier.classify(exc)
                logging.getLogger("webscout").debug(
                    "[SSTI] %s payload='%s' param='%s': %s", cat, payload[:30], param, exc
                )
                if cat == "FATAL":
                    raise
                continue
    return findings


# ═══════════════════════════════════════════════════════════════════════════
#  PATCHED ZeroFPValidator  (ENH-01 + ENH-11 — structured errors + semantic)
# ═══════════════════════════════════════════════════════════════════════════

async def _zfp_validate_safe(self, client, findings: list) -> list:
    """Drop-in replacement for ZeroFPValidator.validate() with proper error handling."""
    _semantic = SemanticDiffEngine()
    validated = []
    for f in findings:
        if getattr(f, "confidence", 0) >= 95 or getattr(f, "confirmed", False):
            validated.append(f)
            continue
        score = getattr(f, "confidence", 70)
        url = getattr(f, "url", "")
        try:
            r = await client.get(url)
            if not r:
                raise ValueError("no response")
            sc = r.get("status", 0)
            body = r.get("text", "")
            # Strategy 1: status code
            if sc in (200, 401, 403, 500):
                score += 3
            # Strategy 2: evidence keyword
            evidence = getattr(f, "evidence", "") or ""
            if evidence and any(
                kw in body for kw in evidence.split()[:4] if len(kw) > 4
            ):
                score += 4
            # Strategy 3: not a generic error page
            if not _semantic._ERROR_PATTERNS.search(body[:500]):
                score += 3
            # Strategy 4: semantic structural check (not FP vs error page)
            error_baseline = {"status": 404, "text": "not found"}
            if not _semantic.is_false_positive(error_baseline, {"status": sc, "text": body}):
                score += 2
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            cat = ErrorClassifier.classify(exc)
            logging.getLogger("webscout").debug(
                "[ZFP] validate error for '%s': %s (%s)",
                getattr(f, "title", "?"), exc, cat,
            )
            score -= 10

        try:
            f.confidence = min(max(score, 0), 100)
        except AttributeError:
            pass
        if score >= 65:
            validated.append(f)
        else:
            title = getattr(f, "title", "?")
            logging.getLogger("webscout").info("[ZFP] Demoted: %s (score=%d)", title, score)
    return validated


# ═══════════════════════════════════════════════════════════════════════════
#  V30 SCAN ADDITIONS — append to MODULE_LIST in run_webscout()
# ═══════════════════════════════════════════════════════════════════════════

def get_v30_modules(client, target, args, cfg) -> list:
    """
    Return additional (enabled, coro_factory, label, timeout_sec) tuples
    for v30 features. Caller appends these to MODULE_LIST.
    """
    token = getattr(cfg, "jwt_token", "") or getattr(cfg, "bearer", "") or ""
    disable_noisy = getattr(args, "disable_noisy", False)
    quick_scan = getattr(args, "quick", False)

    modules = [
        (
            should_run_module("Browser Intelligence", disable_noisy, quick_scan)
            and (getattr(args, "browser_intel", False) or getattr(args, "all", False)),
            lambda: run_browser_intelligence_module(client, target),
            "Browser Intelligence",
            180,
        ),
        (
            should_run_module("WS+GQL Intelligence", disable_noisy, quick_scan)
            and (getattr(args, "ws_gql_intel", False) or getattr(args, "all", False)),
            lambda t=token: run_ws_graphql_intelligence(client, target, token=t),
            "WS+GQL Intelligence",
            300,
        ),
    ]
    return modules


