# ════════════════════════════════════════════════════════════════════════
#  PROXY ROTATOR — 300 IP AUTO-ROTATION ENGINE
# ════════════════════════════════════════════════════════════════════════

class ProxyRotator:
    """
    Manages a pool of user-supplied proxy IPs with automatic rotation (v22).
    Proxies must be supplied via --proxy-list FILE or --proxy URL.
    When a proxy is detected as banned/rate-limited (HTTP 403/429/503 or
    connection failure), it is marked as failed and the next healthy proxy
    is selected immediately — the scan continues without interruption.
    No built-in public proxies are used (removed in v22 for reliability).
    """

    BAN_STATUSES = {403, 429, 503, 407}

    def __init__(self, proxy_list: list, ban_threshold: int = 3, verbose: bool = False):
        self._proxies: list = list(dict.fromkeys(p.strip() for p in proxy_list if p.strip()))
        self._ban_threshold = ban_threshold
        self._verbose = verbose
        self._index = 0
        self._lock = asyncio.Lock()
        self._failures: Dict[str, int] = defaultdict(int)
        self._banned: set = set()
        if self._proxies:
            log("INFO", f"[ProxyRotator] Loaded {len(self._proxies)} proxies -- "
                        f"auto-rotation enabled (ban_threshold={ban_threshold})")

    @property
    def has_proxies(self) -> bool:
        return bool(self._proxies)

    @property
    def active_count(self) -> int:
        return len(self._proxies) - len(self._banned)

    def current_proxy(self) -> Optional[str]:
        if not self._proxies:
            return None
        available = [p for p in self._proxies if p not in self._banned]
        if not available:
            log("WARN", "[ProxyRotator] All proxies exhausted -- resetting ban list")
            self._banned.clear()
            self._failures.clear()
            available = list(self._proxies)
        idx = self._index % len(available)
        return available[idx]

    async def report_ban(self, proxy: str, status: int = 0, reason: str = ""):
        async with self._lock:
            self._failures[proxy] += 1
            if self._failures[proxy] >= self._ban_threshold or status in self.BAN_STATUSES:
                if proxy not in self._banned:
                    self._banned.add(proxy)
                    log("WARN", f"[ProxyRotator] Proxy BANNED (failures={self._failures[proxy]}, "
                               f"status={status or 'conn-err'}): {proxy}")
                self._index += 1

    async def report_success(self, proxy: str):
        async with self._lock:
            if proxy in self._failures:
                self._failures[proxy] = max(0, self._failures[proxy] - 1)

    async def next_proxy(self) -> Optional[str]:
        async with self._lock:
            self._index += 1
        return self.current_proxy()

    def get_proxy_dict(self, proxy: str) -> dict:
        return {"http": proxy, "https": proxy}

    def status_summary(self) -> str:
        total = len(self._proxies)
        banned = len(self._banned)
        active = total - banned
        return f"[ProxyRotator] Total={total} | Active={active} | Banned={banned}"

    async def validate_pool(self, test_url: str = "http://httpbin.org/ip",
                            concurrency: int = 30, timeout: int = 8) -> int:
        """
        Quickly test all proxies concurrently (up to `concurrency` at once).
        Dead proxies are banned immediately. Returns count of live proxies.
        """
        if not self._proxies:
            return 0
        log("INFO", f"[ProxyRotator] Pre-validating {len(self._proxies)} proxies "
                    f"(concurrency={concurrency}, timeout={timeout}s) ...")
        sem = asyncio.Semaphore(concurrency)
        live = 0

        async def _test(proxy: str) -> bool:
            async with sem:
                try:
                    if HAS_CURL_CFFI:
                        import functools, concurrent.futures
                        loop = asyncio.get_running_loop()
                        def _sync_test():
                            try:
                                r = curl_requests.request(
                                    "GET", test_url,
                                    proxies={"http": proxy, "https": proxy},
                                    timeout=timeout, verify=False,
                                    impersonate="chrome120"
                                )
                                return r.status_code < 500
                            except Exception:
                                return False
                        return await loop.run_in_executor(None, _sync_test)
                    else:
                        conn = aiohttp.TCPConnector(ssl=False)
                        async with aiohttp.ClientSession(connector=conn) as s:
                            to = aiohttp.ClientTimeout(total=timeout)
                            async with s.get(test_url, proxy=proxy, timeout=to) as r:
                                return r.status < 500
                except Exception:
                    return False

        tasks = [_test(p) for p in self._proxies]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        good = []
        for proxy, ok in zip(self._proxies, results):
            if ok is True:
                good.append(proxy)
                live += 1
            else:
                self._banned.add(proxy)
        log("INFO", f"[ProxyRotator] Validation done -- {live}/{len(self._proxies)} proxies are LIVE")
        if good:
            random.shuffle(good)
            self._proxies = good + [p for p in self._proxies if p not in good]
        return live


