    async def detect_waf(self, client, url: str):
        cache_key = urlparse(url).netloc
        if cache_key in self._waf_cache:
            return self._waf_cache[cache_key]

        r = await client.get(url)
        if not r:
            return "unknown", False

        all_headers = " ".join(f"{k}:{v}" for k,v in r["headers"].items()).lower()
        all_cookies = " ".join(r.get("cookies", {}).keys()).lower()
        body_snip   = r["text"][:4000].lower()

        matches = []
        for waf_name, sigs in self.WAF_SIGNATURES.items():
            score = 0
            for pat in sigs.get("headers", []):
                if re.search(pat, all_headers, re.I): score += 3
            for pat in sigs.get("body", []):
                if re.search(pat, body_snip, re.I):   score += 2
            for pat in sigs.get("cookies", []):
                if re.search(pat, all_cookies, re.I):  score += 3
            if score > 0:
                matches.append((waf_name, min(score / 8 * 100, 99.0)))

        probe = url + ("&" if "?" in url else "?") + quote(self.WAF_PROBE)
        r2    = await client.get(probe)
        blocked = bool(r2 and r2["status"] in (400, 403, 406, 429, 503))
        if r2:
            pbody = r2["text"][:4000].lower()
            for waf_name, sigs in self.WAF_SIGNATURES.items():
                for pat in sigs.get("body", []):
                    if re.search(pat, pbody, re.I):
                        matches = [(n, s+15 if n==waf_name else s) for n,s in matches] \
                                  if any(n==waf_name for n,s in matches) \
                                  else matches + [(waf_name, 40.0)]

        if matches:
            matches.sort(key=lambda x: x[1], reverse=True)
            best      = matches[0]
            conf_str  = f"{best[1]:.0f}%"
            waf_label = f"{best[0]} ({conf_str} confidence)"
            if len(matches) > 1:
                others    = ", ".join(n for n,_ in matches[1:3])
                waf_label += f" [also: {others}]"
            log("WARN", f"WAF detected: {waf_label}")
        elif blocked:
            waf_label = "Unknown WAF"
            log("WARN", "WAF blocking detected -- fingerprint not matched")
        else:
            waf_label = "None"
            log("INFO", "No WAF detected")

        result = (waf_label, blocked or bool(matches))
        self._waf_cache[cache_key] = result
        return result

    async def probe_modsec_paranoia_level(self, client, url: str):
        max_pl = 0
        hints  = []
        parsed = urlparse(url)
        base_p = parse_qs(parsed.query) or {"q": [""]}
        tp     = list(base_p.keys())[0]
        for payload, pl in self.MODSEC_PL_PROBES:
            tp_map = {**base_p, tp: [payload]}
            turl   = urlunparse(parsed._replace(query=urlencode(tp_map, doseq=True)))
            r      = await client.get(turl)
            if r and r["status"] in (400, 403, 406, 501):
                max_pl = max(max_pl, pl)
                hints.append(f"PL{pl}: {payload[:40]}")
        return max_pl, hints

    async def fuzz_with_bypass(self, client, url: str, param: str, base_payloads: list) -> list:
        findings  = []
        parsed    = urlparse(url)
        params    = parse_qs(parsed.query)
        waf_name, waf_blocked = await self.detect_waf(client, url)

        is_modsec     = "ModSecurity" in waf_name
        is_cloudflare = "Cloudflare"  in waf_name
        is_aws        = "AWS WAF"     in waf_name

        # ── Select bypass list based on detected WAF ──────────────────────
        extra = []
        if is_modsec:
            extra = self.MODSEC_BYPASS + self.MODSEC3_BYPASS
        if is_cloudflare:
            extra = self.CLOUDFLARE_BYPASS + self.CF_BYPASS
        if is_aws:
            extra = self.AWS_WAF_BYPASS
        if "Imperva" in waf_name or "Incapsula" in waf_name:
            extra += getattr(self, "IMPERVA_BYPASS", [])
        if "Akamai" in waf_name:
            extra += getattr(self, "AKAMAI_BYPASS", [])
        if not extra:
            extra = []

        # Combine base encoders + WAF-specific techniques
        encoders = (self.BYPASS_ENCODERS + extra) if waf_blocked else [self.BYPASS_ENCODERS[0]]

        for payload in base_payloads:
            bypass_found = False
            for enc_name, encoder in encoders:
                if bypass_found:
                    break
                try:    encoded = encoder(payload)
                except Exception as _enc_exc:
                    log("DEBUG", f"[WAFBypass] encoder error: {_enc_exc}")
                    continue

                np   = {**params, param: [encoded]}
                url2 = urlunparse(parsed._replace(query=urlencode(np, doseq=True)))
                r    = await client.get(url2)
                if not r: continue

                not_blocked = r["status"] not in (400, 403, 406, 429, 501, 503)
                reflected   = encoded in r["text"] or payload in r["text"]

                conf = 0.0
                if not_blocked and waf_blocked: conf += 40.0
                if reflected:                   conf += 35.0
                if r["status"] == 200:          conf += 15.0
                if len(r["text"]) > 500:        conf += 10.0

                if conf >= 75.0 and waf_blocked:
                    sev      = "HIGH" if conf >= 90 else "MEDIUM"
                    tag_list = ["waf-bypass", "fuzzing"]
                    if is_modsec:     tag_list.append("modsecurity-bypass")
                    if is_cloudflare: tag_list.append("cloudflare-bypass")
                    if is_aws:        tag_list.append("aws-waf-bypass")

                    findings.append(Finding(
                        plugin="waf_bypass_fuzzer",
                        title=f"WAF Bypass Confirmed [{conf:.0f}%]: '{enc_name}' on param='{param}'",
                        severity=sev,
                        confidence=conf,
                        description=(
                            f"Payload successfully bypassed {waf_name} using "
                            f"'{enc_name}'. The WAF blocked the baseline probe but the "
                            f"obfuscated payload reached the backend application."
                        ),
                        evidence=(
                            f"WAF: {waf_name} | Technique: {enc_name} | "
                            f"HTTP {r['status']} | Confidence: {conf:.0f}%"
                        ),
                        url=url2, payload=encoded, param=param,
                        remediation=(
                            "1. Update WAF rule sets to latest OWASP CRS. "
                            "2. Enable ModSecurity paranoia level >= 2. "
                            "3. Implement server-side input validation independent of WAF. "
                            "4. Enable anomaly scoring and set threshold <= 5."
                        ),
                        cwe="CWE-693",
                        cvss=8.5 if sev == "HIGH" else 6.5,
                        owasp="A05",
                        poc=f"# Bypasses {waf_name} using: {enc_name}\ncurl -sk '{url2}'",
                        tags=tag_list,
                    ))
                    log("VULN", f"WAF BYPASS [{conf:.0f}%]: {enc_name} | param={param}")
                    bypass_found = True

        if is_modsec:
            pl, hints = await self.probe_modsec_paranoia_level(client, url)
            if pl > 0:
                findings.append(Finding(
                    plugin="waf_bypass_fuzzer",
                    title=f"ModSecurity CRS Paranoia Level: PL{pl}/4",
                    severity="MEDIUM" if pl <= 2 else "LOW",
                    confidence=85.0,
                    description=(
                        f"ModSecurity CRS operating at Paranoia Level {pl}/4. "
                        f"Levels 1-2 allow many bypass techniques. "
                        f"Blocked payloads: {'; '.join(hints[:5])}"
                    ),
                    evidence=f"Paranoia Level: {pl}/4 | Blocked PL probes: {len(hints)}",
                    url=url,
                    remediation=(
                        f"Increase CRS paranoia level to 3 or 4 (SecDefaultAction). "
                        f"Current PL{pl} leaves {4-pl} paranoia tiers bypassed."
                    ),
                    cwe="CWE-693", cvss=5.5, owasp="A05",
                    tags=["modsecurity", "paranoia-level", "waf-config"],
                ))

        if not params:
            for word in ["debug","admin","dev","internal","cmd","exec","test","id","user","token","key"]:
                turl = url + ("&" if "?" in url else "?") + f"{word}=ws44probe"
                r    = await client.get(turl)
                if not r or r["status"] == 404: continue
                if "ws44probe" in r["text"] and "&lt;" not in r["text"]:
                    findings.append(Finding(
                        plugin="waf_bypass_fuzzer",
                        title=f"Hidden Parameter Discovered: '{word}'",
                        severity="INFO", confidence=75.0,
                        description=(
                            f"Parameter '{word}' accepted by server and value "
                            f"reflected unencoded in the response."
                        ),
                        evidence=f"URL: {turl} | HTTP {r['status']} | Value reflected",
                        url=turl, param=word, owasp="A05",
                        tags=["fuzzing","hidden-param","parameter-discovery"],
                        remediation="Audit all accepted parameters. Disable debug params in production.",
                    ))
        return findings



