#  MODULE v41-5 — HTTP/2 and h2c Scanner
# ════════════════════════════════════════════════════════════════════════

class HTTP2Scanner:
    """
    Tests HTTP/2 and h2c (HTTP/2 cleartext) specific issues:
    - h2c upgrade on cleartext connections
    - HTTP/2 Rapid Reset (CVE-2023-44487) vulnerability indicators
    - HTTP/2 header injection
    - Downgrade attack detection
    """

    async def _check_h2c_upgrade(self, url: str, timeout: int = 10) -> Optional[dict]:
        """Try h2c upgrade via HTTP/1.1 Upgrade header."""
        parsed = urlparse(url)
        if parsed.scheme != "http":
            return None
        try:
            import socket as _sock
            host = parsed.hostname
            port = parsed.port or 80
            path = parsed.path or "/"

            raw = (
                f"GET {path} HTTP/1.1\r\n"
                f"Host: {host}\r\n"
                "Connection: Upgrade, HTTP2-Settings\r\n"
                "Upgrade: h2c\r\n"
                "HTTP2-Settings: AAMAAABkAAQAAP__\r\n"
                "\r\n"
            ).encode()

            s = _sock.create_connection((host, port), timeout=timeout)
            s.sendall(raw)
            resp = s.recv(4096).decode(errors="replace")
            s.close()

            if "101" in resp and "h2c" in resp.lower():
                return {"upgraded": True, "response": resp[:200]}
            elif "200" in resp.split("\r\n")[0]:
                return {"upgraded": False, "response": resp[:200]}
        except Exception as _h2c_e:
            log("DEBUG", f"[HTTP2] H2C upgrade probe failed: {_h2c_e}")
        return None

    async def _check_rapid_reset_indicator(self, client: "WebScoutClient", url: str) -> bool:
        """
        Check for indicators that suggest HTTP/2 Rapid Reset might work.
        (Full exploitation requires a low-level HTTP/2 client; here we detect indicators.)
        """
        r = await client.get(url)
        if not r:
            return False
        server = r["headers"].get("Server", r["headers"].get("server", ""))
        x_powered = r["headers"].get("X-Powered-By", "")
        alt_svc = r["headers"].get("Alt-Svc", "")

        vulnerable_versions = [
            ("nginx", r"nginx/1\.([0-9]|1[0-8])\b"),
            ("apache", r"Apache/2\.[0-3]"),
            ("h2",    r"h2"),
        ]
        for name, pattern in vulnerable_versions:
            if re.search(pattern, server + alt_svc, re.I):
                return True
        return False

    async def scan(self, client: "WebScoutClient", url: str) -> list:
        findings = []
        log("SCAN", "Running HTTP/2 and h2c scanner...")
        parsed = urlparse(url)

        r = await client.get(url)
        if r:
            alt_svc        = r["headers"].get("Alt-Svc", "")
            upgrade_hdr    = r["headers"].get("Upgrade", "")
            server_hdr     = r["headers"].get("Server", r["headers"].get("server", ""))
            via_hdr        = r["headers"].get("Via", "")
            x_proto        = r["headers"].get("X-Firefox-Spdy", "")
            # HTTP/2 indicators: Alt-Svc "h2", Via "2.0", x-firefox-spdy, or server-side h2 strings
            h2_detected = (
                "h2" in alt_svc
                or "2.0" in via_hdr
                or x_proto == "h2"
                or re.search(r"\bh2\b", server_hdr, re.I) is not None
                or upgrade_hdr.lower() == "h2c"
            )
            if h2_detected:
                h2_evidence = (
                    f"Alt-Svc: {alt_svc or '(none)'} | "
                    f"Via: {via_hdr or '(none)'} | "
                    f"X-Firefox-Spdy: {x_proto or '(none)'} | "
                    f"Server: {server_hdr or '(none)'}"
                )
                findings.append(Finding(
                    plugin="http2_scanner",
                    title="HTTP/2 Supported (Multiple Indicators Detected)",
                    severity="INFO", confidence=100.0,
                    description=(
                        "Server supports HTTP/2 based on one or more response indicators "
                        f"(Alt-Svc, Via, X-Firefox-Spdy, Server header). {h2_evidence}"
                    ),
                    evidence=h2_evidence,
                    url=url,
                    remediation="Ensure HTTP/2 implementation is up to date (CVE-2023-44487 -- Rapid Reset).",
                    tags=["http2", "info"],
                ))

        if parsed.scheme == "http":
            h2c_result = await asyncio.get_running_loop().run_in_executor(
                None, lambda: None
            )
            try:
                loop = asyncio.get_event_loop()
                h2c_result = await loop.run_in_executor(None, lambda: (
                    __import__("socket").create_connection(
                        (parsed.hostname, parsed.port or 80), timeout=5
                    ) and None
                ))
            except Exception:
                h2c_result = None

            if h2c_result is None:
                raw_h2c = (
                    f"GET {parsed.path or '/'} HTTP/1.1\r\n"
                    f"Host: {parsed.netloc}\r\n"
                    "Connection: Upgrade, HTTP2-Settings\r\n"
                    "Upgrade: h2c\r\n"
                    "HTTP2-Settings: AAMAAABkAAQAAP__\r\n"
                    "\r\n"
                )
                try:
                    import socket as _sock
                    s = _sock.create_connection((parsed.hostname, parsed.port or 80), timeout=8)
                    s.sendall(raw_h2c.encode())
                    resp_raw = s.recv(2048).decode(errors="replace")
                    s.close()
                    if "101 Switching" in resp_raw and "h2c" in resp_raw.lower():
                        findings.append(Finding(
                            plugin="http2_scanner",
                            title="h2c Upgrade Accepted (HTTP/2 Cleartext)",
                            severity="MEDIUM", confidence=88.0,
                            description=(
                                "Server accepts HTTP/2 cleartext (h2c) upgrade via HTTP/1.1 Upgrade header. "
                                "h2c on public endpoints may allow request smuggling via HTTP/2 downgrade."
                            ),
                            evidence=f"HTTP 101 Switching Protocols received | Response: {resp_raw[:150]}",
                            url=url,
                            remediation=(
                                "Disable h2c on public-facing servers. Use HTTPS with HTTP/2 only. "
                                "Ensure CDN/proxy strips h2c upgrade headers."
                            ),
                            cwe="CWE-444", cvss=6.5, owasp="A04",
                            tags=["http2", "h2c", "smuggling", "downgrade"],
                        ))
                except Exception as _h2c_smug_e:
                    log("DEBUG", f"[HTTP2] H2C smuggling finding build failed: {_h2c_smug_e}")

        rapid_reset = await self._check_rapid_reset_indicator(client, url)
        if rapid_reset:
            findings.append(Finding(
                plugin="http2_scanner",
                title="HTTP/2 Rapid Reset Vulnerability Indicator (CVE-2023-44487)",
                severity="HIGH", confidence=70.0,
                description=(
                    "Server fingerprint suggests an HTTP/2 implementation version potentially "
                    "affected by CVE-2023-44487 (Rapid Reset DoS). Verify and patch."
                ),
                evidence="Server version or Alt-Svc header indicates potentially vulnerable HTTP/2 stack",
                url=url,
                remediation=(
                    "Update nginx to >=1.25.3, Apache httpd to >=2.4.58, Go to >=1.21.3. "
                    "Enable HTTP/2 stream limits. Monitor for abnormal RST_STREAM floods."
                ),
                cwe="CWE-400", cvss=7.5, owasp="A04",
                tags=["http2", "rapid-reset", "dos", "cve-2023-44487"],
            ))

        r_http2_hdr = await client.get(url, headers={
            ":path": "/admin",
            ":method": "GET",
        })
        if r_http2_hdr and r_http2_hdr["status"] == 200 and "admin" not in url:
            findings.append(Finding(
                plugin="http2_scanner",
                title="HTTP/2 Pseudo-Header Injection -- :path Override",
                severity="MEDIUM", confidence=70.0,
                description="Server may process HTTP/2 pseudo-headers sent via HTTP/1.1 -- potential path override.",
                evidence=f":path: /admin returned HTTP 200",
                url=url,
                remediation="Strip and validate HTTP/2 pseudo-headers at proxy/gateway layer.",
                cwe="CWE-113", cvss=6.5, owasp="A04",
                tags=["http2", "header-injection"],
            ))

        log("OK", f"HTTP/2 scan done -- {len(findings)} issue(s)")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  MODULE v41-6 — Dynamic CSP & Security Header Analyzer
# ════════════════════════════════════════════════════════════════════════

class DynamicCSPAnalyzer:
    """
    Deep Content Security Policy analysis:
    - Detects unsafe-inline, unsafe-eval, wildcard sources
    - Missing nonce or hash directives
    - Overly permissive script-src
    - Missing directives (default-src, frame-ancestors, object-src)
    - Report-only mode (no enforcement)
    - Strict-Transport-Security max-age check
    - Feature-Policy / Permissions-Policy analysis
    """

    DANGEROUS_CSP_VALUES = [
        ("unsafe-inline", "HIGH",   "Allows inline scripts -- XSS protection bypassed"),
        ("unsafe-eval",   "HIGH",   "Allows eval() -- DOM XSS escalation possible"),
        ("*",             "HIGH",   "Wildcard source -- any origin can serve scripts"),
        ("data:",         "MEDIUM", "data: URIs allowed -- XSS bypass vector"),
        ("http:",         "MEDIUM", "HTTP (insecure) sources allowed in CSP"),
    ]

    REQUIRED_DIRECTIVES = [
        "default-src", "script-src", "object-src",
        "frame-ancestors", "base-uri", "form-action",
    ]

    async def scan(self, client: "WebScoutClient", url: str) -> list:
        findings = []
        log("SCAN", "Running dynamic CSP & security header analyzer...")
        r = await client.get(url)
        if not r:
            return findings

        hdrs = {k.lower(): v for k, v in r["headers"].items()}
        csp = hdrs.get("content-security-policy", "")
        csp_ro = hdrs.get("content-security-policy-report-only", "")
        sts = hdrs.get("strict-transport-security", "")
        perms = hdrs.get("permissions-policy", hdrs.get("feature-policy", ""))
        referrer = hdrs.get("referrer-policy", "")

        if csp_ro and not csp:
            findings.append(Finding(
                plugin="csp_analyzer",
                title="CSP in Report-Only Mode (Not Enforced)",
                severity="MEDIUM", confidence=100.0,
                description="CSP is in report-only mode -- no active protection against XSS or data injection.",
                evidence=f"Content-Security-Policy-Report-Only: {csp_ro[:200]}",
                url=url,
                remediation="Switch to Content-Security-Policy header for active enforcement.",
                cwe="CWE-693", cvss=5.3, owasp="A05",
                tags=["csp", "report-only", "misconfiguration"],
            ))

        if not csp and not csp_ro:
            findings.append(Finding(
                plugin="csp_analyzer",
                title="Content-Security-Policy Header Completely Absent",
                severity="MEDIUM", confidence=100.0,
                description="No CSP header set -- XSS attacks have no policy-level mitigation.",
                evidence="Neither CSP nor CSP-Report-Only header present",
                url=url,
                remediation="Implement a strict CSP with nonces or hashes for inline scripts.",
                cwe="CWE-693", cvss=5.4, owasp="A05",
                tags=["csp", "missing"],
            ))
        else:
            active_csp = csp or csp_ro
            for val, sev, desc in self.DANGEROUS_CSP_VALUES:
                if val in active_csp.lower():
                    findings.append(Finding(
                        plugin="csp_analyzer",
                        title=f"CSP Weakness: '{val}' Detected",
                        severity=sev, confidence=100.0,
                        description=f"CSP contains '{val}' -- {desc}.",
                        evidence=f"CSP fragment containing '{val}': {active_csp[:300]}",
                        url=url,
                        remediation=(
                            f"Remove '{val}' from CSP. Use nonces or hashes for inline scripts. "
                            "Avoid eval() usage."
                        ),
                        cwe="CWE-693", cvss=6.5, owasp="A05",
                        tags=["csp", val.replace("-", ""), "misconfiguration"],
                    ))

            directives_present = [d.strip().split()[0] for d in active_csp.split(";") if d.strip()]
            for required in self.REQUIRED_DIRECTIVES:
                if not any(required == d.lower() for d in directives_present):
                    sev = "HIGH" if required in ("object-src", "script-src") else "LOW"
                    findings.append(Finding(
                        plugin="csp_analyzer",
                        title=f"CSP Missing Directive: '{required}'",
                        severity=sev, confidence=95.0,
                        description=f"CSP lacks '{required}' directive -- fallback to default-src may be overly permissive.",
                        evidence=f"Present directives: {directives_present}",
                        url=url,
                        remediation=f"Add '{required}: none' or a specific allowlist to your CSP.",
                        cwe="CWE-693", cvss=4.3, owasp="A05",
                        tags=["csp", "missing-directive"],
                    ))

        if sts:
            ma_match = re.search(r"max-age=(\d+)", sts, re.I)
            if ma_match:
                max_age = int(ma_match.group(1))
                if max_age < 15552000:
                    findings.append(Finding(
                        plugin="csp_analyzer",
                        title=f"HSTS max-age Too Short: {max_age}s (< 180 days)",
                        severity="LOW", confidence=100.0,
                        description=f"HSTS max-age={max_age}s is below the recommended 180 days (15552000s).",
                        evidence=f"Strict-Transport-Security: {sts}",
                        url=url,
                        remediation="Set max-age to at least 31536000 (1 year). Add includeSubDomains; preload.",
                        cwe="CWE-319", cvss=3.7, owasp="A05",
                        tags=["hsts", "misconfiguration"],
                    ))
            if "includesubdomains" not in sts.lower():
                findings.append(Finding(
                    plugin="csp_analyzer",
                    title="HSTS Missing 'includeSubDomains'",
                    severity="LOW", confidence=100.0,
                    description="HSTS does not include subdomains -- subdomain downgrade attacks possible.",
                    evidence=f"Strict-Transport-Security: {sts}",
                    url=url,
                    remediation="Add 'includeSubDomains' to HSTS header.",
                    cwe="CWE-319", cvss=3.1, owasp="A05",
                    tags=["hsts", "misconfiguration"],
                ))

        if not referrer:
            findings.append(Finding(
                plugin="csp_analyzer",
                title="Referrer-Policy Header Missing",
                severity="LOW", confidence=100.0,
                description="No Referrer-Policy -- sensitive URL parameters may leak via Referer header to third parties.",
                evidence="Referrer-Policy header absent",
                url=url,
                remediation="Set Referrer-Policy: strict-origin-when-cross-origin or no-referrer.",
                cwe="CWE-200", cvss=3.1, owasp="A05",
                tags=["referrer-policy", "information-disclosure"],
            ))

        dangerous_features = ["camera", "microphone", "geolocation", "payment", "usb"]
        if not perms:
            findings.append(Finding(
                plugin="csp_analyzer",
                title="Permissions-Policy Header Missing",
                severity="LOW", confidence=100.0,
                description="No Permissions-Policy -- browser features (camera, mic, geolocation) not restricted.",
                evidence="Permissions-Policy header absent",
                url=url,
                remediation="Add Permissions-Policy: camera=(), microphone=(), geolocation=(), payment=().",
                cwe="CWE-693", cvss=2.0, owasp="A05",
                tags=["permissions-policy"],
            ))
        else:
            for feat in dangerous_features:
                if feat not in perms.lower():
                    findings.append(Finding(
                        plugin="csp_analyzer",
                        title=f"Permissions-Policy Missing Restriction: '{feat}'",
                        severity="LOW", confidence=90.0,
                        description=f"Feature '{feat}' not restricted in Permissions-Policy.",
                        evidence=f"Permissions-Policy: {perms[:200]}",
                        url=url,
                        remediation=f"Add '{feat}=()' to Permissions-Policy.",
                        cwe="CWE-693", cvss=1.5, owasp="A05",
                        tags=["permissions-policy", feat],
                    ))

        log("OK", f"CSP analyzer done -- {len(findings)} issue(s)")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  MODULE v41-7 — Advanced Race Condition Scanner
# ════════════════════════════════════════════════════════════════════════

class AdvancedRaceConditionScanner:
    """
    Multi-scenario race condition testing:
    - Coupon code reuse via parallel requests (≤15ms window)
    - Double-spend on purchase/payment endpoints
    - User registration with duplicate email
    - File upload race (multiple simultaneous uploads)
    - Rate limit bypass via concurrent burst
    """

    async def _parallel_burst(self, client: "WebScoutClient", method: str,
                               url: str, count: int = 20,
                               data=None, json_body=None) -> list:
        """Fire `count` requests simultaneously."""
        tasks = [
            client.request(method, url, data=data, json_body=json_body)
            for _ in range(count)
        ]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        exc_count = sum(1 for r in results if isinstance(r, Exception))
        if exc_count:
            log("WARN", f"Race burst to {url}: {exc_count}/{count} request(s) raised exceptions "
                        f"(e.g. {next(r for r in results if isinstance(r, Exception))})")
        return results

    async def test_coupon_race(self, client: "WebScoutClient", url: str,
                                coupon: str = "SAVE10") -> list:
        findings = []
        parsed = urlparse(url)
        base = f"{parsed.scheme}://{parsed.netloc}"

        coupon_endpoints = [
            f"{base}/api/coupon/apply",
            f"{base}/api/cart/coupon",
            f"{base}/coupon",
            f"{base}/discount/apply",
        ]
        for ep in coupon_endpoints:
            results = await self._parallel_burst(
                client, "POST", ep,
                json_body={"coupon": coupon, "code": coupon},
                count=15
            )
            success_count = sum(
                1 for r in results
                if isinstance(r, dict) and r and r.get("status") in (200, 201) and
                any(s in (r.get("text") or "").lower() for s in ["success", "applied", "discount", "saved"])
            )
            if success_count >= 2:
                findings.append(Finding(
                    plugin="race_condition",
                    title=f"Race Condition: Coupon '{coupon}' Applied {success_count}x Simultaneously",
                    severity="HIGH", confidence=88.0,
                    description=(
                        f"Sending {15} parallel coupon apply requests resulted in {success_count} successes -- "
                        "race window allows multiple applications of the same coupon."
                    ),
                    evidence=f"Success count: {success_count}/15 | Endpoint: {ep}",
                    url=ep, payload=coupon,
                    remediation="Use atomic DB operations or distributed locks. Implement idempotency keys.",
                    cwe="CWE-362", cvss=7.5, owasp="A04",
                    tags=["race-condition", "coupon", "business-logic"],
                ))
                log("VULN", f"Race: coupon {coupon} applied {success_count}x at {ep}")
        return findings

    async def test_registration_race(self, client: "WebScoutClient", url: str) -> list:
        findings = []
        parsed = urlparse(url)
        base = f"{parsed.scheme}://{parsed.netloc}"

        reg_email = f"race_{secrets.token_hex(4)}@ws41test.invalid"
        reg_endpoints = [
            f"{base}/api/register", f"{base}/api/auth/register",
            f"{base}/register", f"{base}/signup",
            f"{base}/api/users", f"{base}/api/v1/users",
        ]
        for ep in reg_endpoints:
            payload = {
                "email": reg_email, "username": f"ws41_{secrets.token_hex(4)}",
                "password": "Ws41Test!Pass#" + secrets.token_hex(4),
            }
            results = await self._parallel_burst(client, "POST", ep,
                                                  json_body=payload, count=10)
            success_count = sum(
                1 for r in results
                if isinstance(r, dict) and r and r.get("status") in (200, 201)
            )
            if success_count >= 2:
                findings.append(Finding(
                    plugin="race_condition",
                    title=f"Race Condition: Duplicate User Registration ({success_count}x)",
                    severity="HIGH", confidence=82.0,
                    description=(
                        f"Parallel registration with same email produced {success_count} successes -- "
                        "duplicate account creation possible, uniqueness constraint not atomic."
                    ),
                    evidence=f"Email: {reg_email} | {success_count}/10 requests succeeded | Endpoint: {ep}",
                    url=ep, payload=reg_email,
                    remediation="Use DB unique constraints with proper transaction isolation. Check email uniqueness atomically.",
                    cwe="CWE-362", cvss=6.5, owasp="A04",
                    tags=["race-condition", "registration", "duplicate"],
                ))
        return findings

    async def test_rate_limit_race(self, client: "WebScoutClient", url: str) -> list:
        findings = []
        parsed = urlparse(url)
        base = f"{parsed.scheme}://{parsed.netloc}"

        auth_paths = ["/api/login", "/login", "/api/auth/token",
                      "/api/auth", "/api/v1/auth/login"]
        for path in auth_paths:
            ep = base + path
            results = await self._parallel_burst(
                client, "POST", ep,
                json_body={"username": "admin", "password": "wrong_password_ws41"},
                count=25
            )
            non_429 = sum(
                1 for r in results
                if isinstance(r, dict) and r and r.get("status") not in (429, 403, 423)
            )
            if non_429 >= 20:
                findings.append(Finding(
                    plugin="race_condition",
                    title=f"Rate Limit Bypass via Race Condition -- {path}",
                    severity="MEDIUM", confidence=80.0,
                    description=(
                        f"{non_429}/25 simultaneous login attempts reached the server without rate limiting -- "
                        "brute-force rate limits can be bypassed via parallel requests."
                    ),
                    evidence=f"Non-429 responses: {non_429}/25 | Endpoint: {ep}",
                    url=ep,
                    remediation="Use global rate limiting with atomic counters (Redis INCR). Apply per-IP and per-account limits.",
                    cwe="CWE-307", cvss=6.5, owasp="A07",
                    tags=["race-condition", "rate-limit-bypass", "brute-force"],
                ))
        return findings

    async def scan(self, client: "WebScoutClient", url: str,
                   coupon_codes: list = None) -> list:
        log("SCAN", "Running advanced race condition scanner...")
        findings = []
        for coupon in (coupon_codes or ["SAVE10", "DISCOUNT20", "FREE", "TEST"]):
            findings += await self.test_coupon_race(client, url, coupon)
        findings += await self.test_registration_race(client, url)
        findings += await self.test_rate_limit_race(client, url)
        log("OK", f"Race condition scan done -- {len(findings)} issue(s)")
        return findings


