#  MODULE v41-9 — Smart Credential Guesser
# ════════════════════════════════════════════════════════════════════════

class SmartCredentialGuesser:
    """
    Intelligent credential guessing with:
    - Domain-derived passwords (company name + year/symbol)
    - Common username/password combos
    - Progressive lockout detection
    - Spray mode (one password across many usernames)
    """

    COMMON_USERS = [
        "admin", "administrator", "root", "superuser", "user",
        "test", "demo", "guest", "support", "helpdesk",
        "info", "webmaster", "sysadmin", "operator",
    ]

    COMMON_PASSWORDS = [
        "password", "Password1", "password123", "P@ssw0rd", "admin",
        "admin123", "letmein", "welcome", "qwerty", "12345678",
        "changeme", "secret", "test", "test123", "abc123",
        "111111", "dragon", "iloveyou", "monkey", "login",
        "pass", "master", "hello", "sunshine", "shadow",
    ]

    async def _find_login_endpoint(self, client: "WebScoutClient", url: str) -> Optional[dict]:
        """Locate login form or API endpoint."""
        parsed = urlparse(url)
        base = f"{parsed.scheme}://{parsed.netloc}"
        login_paths = [
            "/login", "/api/login", "/api/auth/login", "/auth/login",
            "/api/auth", "/api/v1/auth/login", "/api/v1/login",
            "/admin/login", "/wp-login.php", "/user/login",
            "/signin", "/api/signin", "/account/login",
        ]
        for path in login_paths:
            r = await client.get(base + path)
            if r and r["status"] in (200, 401, 405):
                is_json = "application/json" in r["headers"].get("content-type", "")
                form_action = re.search(r'<form[^>]+action=["\']([^"\']*)["\']', r["text"], re.I)
                return {
                    "url": base + path, "is_json": is_json,
                    "form_action": form_action.group(1) if form_action else path,
                }
        return None

    def _derive_domain_passwords(self, url: str) -> list:
        """Generate passwords derived from the target domain."""
        parsed = urlparse(url)
        host = parsed.hostname or ""
        domain_parts = host.split(".")
        base_name = domain_parts[0] if domain_parts else "company"

        import datetime as _dt
        year = str(_dt.datetime.now().year)
        prev_year = str(_dt.datetime.now().year - 1)

        derived = [
            base_name, base_name.capitalize(),
            f"{base_name.capitalize()}{year}",
            f"{base_name.capitalize()}{year}!",
            f"{base_name.capitalize()}@{year}",
            f"{base_name}{year}",
            f"{base_name.capitalize()}1",
            f"{base_name.capitalize()}123",
            f"{base_name.capitalize()}!1",
            f"{base_name.upper()}{year}",
            f"Welcome{year}!",
            f"Welcome{prev_year}!",
        ]
        return derived

    async def scan(self, client: "WebScoutClient", url: str) -> list:
        findings = []
        log("PASS", "Running smart credential guesser...")

        endpoint = await self._find_login_endpoint(client, url)
        if not endpoint:
            log("SKIP", "No login endpoint found for credential guessing")
            return findings

        ep_url = endpoint["url"]
        is_json = endpoint["is_json"]
        domain_passwords = self._derive_domain_passwords(url)

        test_passwords = self.COMMON_PASSWORDS[:15] + domain_passwords[:10]
        lockout_detected = False
        found_creds = []

        # Pre-fetch login page to extract CSRF token / nonce if the form requires one
        _CSRF_RE = re.compile(
            r'<input[^>]+name=["\']'
            r'(?:csrf_token|_token|csrfmiddlewaretoken|authenticity_token|_csrf|nonce)["\']'
            r'[^>]+value=["\']([^"\']+)["\']',
            re.I,
        )
        _CSRF_META_RE = re.compile(
            r'<meta[^>]+name=["\']csrf-token["\'][^>]+content=["\']([^"\']+)["\']', re.I
        )

        # Regex to extract XSRF-TOKEN cookie value (Angular / axios double-submit pattern)
        _XSRF_COOKIE_RE = re.compile(
            r'(?:^|;\s*)XSRF-TOKEN=([^;]+)', re.I
        )

        async def _get_csrf_token() -> tuple:
            """
            Return (token_value, field_name, cookie_header) from the login page.

            Covers three CSRF patterns:
              1. Synchronizer token in a hidden <input> field.
              2. Token in a <meta name="csrf-token"> tag (Rails/Laravel style).
              3. Double-submit cookie: XSRF-TOKEN set in Set-Cookie, expected back
                 as X-XSRF-TOKEN header (Angular / axios default behaviour).
            """
            r_page = await client.get(ep_url)
            if not r_page:
                return "", "", ""
            page_text = r_page["text"]
            raw_cookie = r_page.get("headers", {}).get("set-cookie", "")

            # Pattern 1 & 2: form input or <meta>
            m = _CSRF_RE.search(page_text) or _CSRF_META_RE.search(page_text)
            if m:
                token_val = m.group(1)
                fname_m = re.search(r'name=["\']([^"\']+)["\']', m.group(0), re.I)
                fname = fname_m.group(1) if fname_m else "csrf_token"
                return token_val, fname, raw_cookie

            # Pattern 3: XSRF-TOKEN cookie (used even by pure JSON APIs)
            xsrf_m = _XSRF_COOKIE_RE.search(raw_cookie)
            if xsrf_m:
                return xsrf_m.group(1).strip(), "X-XSRF-TOKEN", raw_cookie

            return "", "", ""

        _csrf_val, _csrf_field, _csrf_cookie = await _get_csrf_token()

        for username in self.COMMON_USERS[:8]:
            if lockout_detected:
                break
            for password in test_passwords:
                # Refresh CSRF token per-request for SYNCHRONIZER_TOKEN pattern apps
                if not is_json and _csrf_field:
                    _csrf_val, _csrf_field, _csrf_cookie = await _get_csrf_token()

                if is_json:
                    payload_json = {"username": username, "password": password,
                                    "email": username, "login": username}
                    # Many SPAs protect JSON endpoints via CSRF headers
                    # (X-CSRF-Token, X-CSRFToken, X-XSRF-TOKEN).
                    # Refresh and inject if the login page returned a token.
                    if _csrf_field:
                        _csrf_val, _csrf_field, _csrf_cookie = await _get_csrf_token()
                    json_hdrs: dict = {}
                    if _csrf_val:
                        json_hdrs["X-CSRF-Token"]  = _csrf_val
                        json_hdrs["X-CSRFToken"]    = _csrf_val
                        json_hdrs["X-XSRF-TOKEN"]  = _csrf_val
                    if _csrf_cookie:
                        json_hdrs["Cookie"] = _csrf_cookie
                    r = await client.post(ep_url, json_body=payload_json,
                                          headers=json_hdrs if json_hdrs else None)
                else:
                    form_data = (
                        f"username={quote(username)}&password={quote(password)}"
                        f"&email={quote(username)}"
                    )
                    if _csrf_field and _csrf_val:
                        form_data += f"&{quote(_csrf_field)}={quote(_csrf_val)}"
                    extra_hdrs = {"Content-Type": "application/x-www-form-urlencoded"}
                    if _csrf_cookie:
                        extra_hdrs["Cookie"] = _csrf_cookie
                    r = await client.post(ep_url, data=form_data, headers=extra_hdrs)

                if not r:
                    continue

                if r["status"] == 429 or "too many" in r["text"].lower() or "locked" in r["text"].lower():
                    lockout_detected = True
                    findings.append(Finding(
                        plugin="credential_guesser",
                        title="Account Lockout / Rate Limit Activated During Credential Test",
                        severity="INFO", confidence=95.0,
                        description="Login endpoint activated lockout or rate limiting after credential spray -- lockout is working.",
                        evidence=f"HTTP {r['status']} | Triggered after: {username}:{password}",
                        url=ep_url,
                        remediation="Lockout is working correctly. Ensure lockout notification is sent to account owner.",
                        tags=["credential-guessing", "lockout", "rate-limit"],
                    ))
                    break

                success_indicators = [
                    "logout", "dashboard", "welcome", "profile", "token",
                    "access_token", "session", "authenticated", "success",
                ]
                fail_indicators = [
                    "invalid", "incorrect", "wrong", "failed", "error",
                    "bad credentials", "unauthorized",
                ]

                if r["status"] in (200, 302) and any(s in r["text"].lower() for s in success_indicators):
                    if not any(f in r["text"].lower() for f in fail_indicators):
                        found_creds.append((username, password))
                        findings.append(Finding(
                            plugin="credential_guesser",
                            title=f"Weak Credential Found: {username} / {password}",
                            severity="CRITICAL", confidence=90.0,
                            description=(
                                f"Login succeeded with common credential '{username}:{password}'. "
                                "Account is using a weak/default password."
                            ),
                            evidence=f"HTTP {r['status']} | Success indicators in response",
                            url=ep_url, param="username", payload=f"{username}:{password}",
                            remediation=(
                                "Enforce strong password policy. Require MFA. "
                                "Disable default credentials. Alert on login from new IP."
                            ),
                            cwe="CWE-521", cvss=9.8, owasp="A07",
                            tags=["credential-guessing", "weak-password", "default-credentials"],
                        ))
                        log("VULN", f"Credential found: {username}:{password}")

                await asyncio.sleep(0.1)

        if not lockout_detected and not found_creds:
            findings.append(Finding(
                plugin="credential_guesser",
                title="No Lockout Detected During Credential Spray",
                severity="MEDIUM", confidence=80.0,
                description=(
                    f"Tested {len(self.COMMON_USERS[:8]) * len(test_passwords)} credential combinations "
                    "without triggering account lockout or rate limiting."
                ),
                evidence=f"No 429/lockout response after {len(test_passwords)} attempts per user",
                url=ep_url,
                remediation="Implement account lockout after 5-10 failed attempts. Add IP-based rate limiting.",
                cwe="CWE-307", cvss=7.5, owasp="A07",
                tags=["credential-guessing", "no-lockout"],
            ))

        log("OK", f"Credential guesser done -- {len(found_creds)} credential(s) found")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  MODULE v41-10 — NVD Version Analyzer (CVE Lookup)
# ════════════════════════════════════════════════════════════════════════

class NVDVersionAnalyzer:
    """
    Queries the NIST NVD API to look up CVEs for detected software versions.
    Now also enriches each CVE with EPSS (Exploit Prediction Scoring System)
    probability via the FIRST.org API (Feature 4: CVE Live Feed).

    EPSS score = probability (0.0–1.0) that the CVE will be exploited in the
    next 30 days, derived from threat intel signals. A score ≥ 0.1 (10%)
    indicates active exploitation risk.
    """

    NVD_API_BASE  = "https://services.nvd.nist.gov/rest/json/cves/2.0"
    EPSS_API_BASE = "https://api.first.org/data/v1/epss"

    # In-memory response cache keyed by (keyword, version).
    # Without caching, a scan with 10 detected components makes 10 sequential NVD API
    # calls which quickly triggers the 5 req/30 s rate limit for unauthenticated users.
    # The cache is process-scoped (not cross-run) so data is never stale across restarts.
    _nvd_cache:  dict = {}  # {(keyword, version): [cve_dict, ...]}
    _epss_cache: dict = {}  # {cve_id: {"epss": float, "percentile": float}}

    VERSION_PATTERNS = {
        "Apache": r"Apache[/ ](\d+\.\d+(?:\.\d+)?)",
        "nginx": r"nginx[/ ](\d+\.\d+(?:\.\d+)?)",
        "PHP": r"PHP[/ ](\d+\.\d+(?:\.\d+)?)",
        "OpenSSL": r"OpenSSL[/ ](\d+\.\d+(?:\.\d+)?[a-z]?)",
        "WordPress": r"WordPress (\d+\.\d+(?:\.\d+)?)",
        "jQuery": r"jquery[/ @](\d+\.\d+(?:\.\d+)?)",
        "Bootstrap": r"Bootstrap[/ ](\d+\.\d+(?:\.\d+)?)",
        "Django": r"Django[/ ](\d+\.\d+(?:\.\d+)?)",
        "Laravel": r"Laravel[/ ](\d+\.\d+(?:\.\d+)?)",
        "Node.js": r"Node\.js[/ ](\d+\.\d+(?:\.\d+)?)",
        "Express": r"Express[/ ](\d+\.\d+(?:\.\d+)?)",
        "Spring": r"Spring[/ ](\d+\.\d+(?:\.\d+)?)",
        "Struts": r"Struts[/ ](\d+\.\d+(?:\.\d+)?)",
        "Tomcat": r"Apache Tomcat[/ ](\d+\.\d+(?:\.\d+)?)",
    }

    async def _query_epss(self, client: "WebScoutClient",
                           cve_ids: list) -> dict:
        """
        Query FIRST.org EPSS API for exploit probability of a list of CVE IDs.
        Returns dict: {cve_id: {"epss": float, "percentile": float}}

        EPSS (Exploit Prediction Scoring System) scores reflect the probability
        (0.0–1.0) of active exploitation within the next 30 days.
        Scores ≥ 0.10 indicate significant active exploitation risk.
        """
        if not cve_ids:
            return {}
        result = {}
        try:
            # Check cache first
            uncached = [c for c in cve_ids if c not in NVDVersionAnalyzer._epss_cache]
            if uncached:
                # EPSS API accepts comma-separated CVE IDs
                _batch = ",".join(uncached[:20])
                r = await client.get(
                    self.EPSS_API_BASE,
                    params={"cve": _batch, "limit": 20},
                    headers={"Accept": "application/json"},
                )
                if r and r.get("status") == 200:
                    try:
                        data = json.loads(r["text"])
                        for item in data.get("data", []):
                            cid = item.get("cve", "")
                            if cid:
                                NVDVersionAnalyzer._epss_cache[cid] = {
                                    "epss":       float(item.get("epss", 0.0)),
                                    "percentile": float(item.get("percentile", 0.0)),
                                }
                    except Exception as _silenced_exc:
                        log("DEBUG", f"[suppressed] {_silenced_exc}")
        except Exception as _epss_e:
            log("DEBUG", f"[NVD] EPSS query failed (non-fatal): {_epss_e}")

        for cid in cve_ids:
            result[cid] = NVDVersionAnalyzer._epss_cache.get(
                cid, {"epss": 0.0, "percentile": 0.0})
        return result

    async def _query_nvd(self, client: "WebScoutClient", keyword: str,
                          version: str, nvd_api_key: str = "") -> list:
        """
        Query NVD API (live) for CVEs matching software+version.
        Enriches each CVE with EPSS exploit-probability from FIRST.org.

        Results are cached in NVDVersionAnalyzer._nvd_cache so that repeated
        lookups for the same (keyword, version) pair within a single scan session
        never trigger additional API requests (avoids rate-limit HTTP 429).
        """
        _cache_key = (keyword.lower(), version)
        if _cache_key in NVDVersionAnalyzer._nvd_cache:
            log("DEBUG", f"NVD cache hit for {keyword} {version}")
            return NVDVersionAnalyzer._nvd_cache[_cache_key]
        try:
            params = {
                "keywordSearch": f"{keyword} {version}",
                "resultsPerPage": 15,
                # Pull only CVEs from the NVD live feed (no static DB)
            }
            headers = {}
            if nvd_api_key:
                headers["apiKey"] = nvd_api_key

            r = None
            _max_retries = 3
            _backoff = 10
            for _attempt in range(_max_retries):
                r = await client.get(self.NVD_API_BASE, params=params, headers=headers)
                if r and r["status"] == 429:
                    log("WARN", (
                        f"NVD API rate-limited (HTTP 429) -- retry {_attempt + 1}/{_max_retries} "
                        f"after {_backoff}s. Without an API key, NIST enforces 5 req/30 s. "
                        "Use --nvd-api-key for 50 req/30 s. "
                        "Free key: https://nvd.nist.gov/developers/request-an-api-key"
                    ))
                    await asyncio.sleep(_backoff)
                    _backoff = min(_backoff * 2, 60)
                    continue
                break

            if not r or r["status"] != 200:
                NVDVersionAnalyzer._nvd_cache[_cache_key] = []
                return []

            data = json.loads(r["text"])
            cves = []
            for item in data.get("vulnerabilities", []):
                cve        = item.get("cve", {})
                cve_id     = cve.get("id", "")
                metrics    = cve.get("metrics", {})
                cvss_score = 0.0
                severity   = "UNKNOWN"
                for key in ["cvssMetricV31", "cvssMetricV30", "cvssMetricV2"]:
                    if key in metrics and metrics[key]:
                        data_v     = metrics[key][0].get("cvssData", {})
                        cvss_score = data_v.get("baseScore", 0.0)
                        severity   = data_v.get("baseSeverity", "UNKNOWN")
                        break
                desc_list = cve.get("descriptions", [])
                desc      = next(
                    (d["value"] for d in desc_list if d.get("lang") == "en"), "")
                published = cve.get("published", "")[:10]   # YYYY-MM-DD
                cves.append({
                    "id": cve_id, "score": cvss_score,
                    "severity": severity, "description": desc[:200],
                    "published": published,
                    "epss": 0.0, "epss_percentile": 0.0,
                })

            # ── Enrich with EPSS scores ───────────────────────────────────
            if cves:
                epss_map = await self._query_epss(client, [c["id"] for c in cves])
                for c in cves:
                    e = epss_map.get(c["id"], {})
                    c["epss"]            = e.get("epss", 0.0)
                    c["epss_percentile"] = e.get("percentile", 0.0)

            # Sort: EPSS score first (active exploitation priority), then CVSS
            result = sorted(cves, key=lambda x: (-(x["epss"]), -(x["score"])))
            NVDVersionAnalyzer._nvd_cache[_cache_key] = result
            return result
        except Exception as e:
            log("WARN", f"NVD API query failed for {keyword} {version}: {e}")
            NVDVersionAnalyzer._nvd_cache[_cache_key] = []
            return []

    async def scan(self, client: "WebScoutClient", url: str,
                   nvd_api_key: str = "") -> list:
        """
        Live CVE Feed scan (Feature 4): queries NVD API in real-time and
        enriches each result with EPSS exploit-probability.
        """
        findings = []
        log("SCAN", "Running NVD live CVE feed analyzer...")

        r = await client.get(url)
        if not r:
            return findings

        combined = r["text"] + " ".join(f"{k}:{v}" for k, v in r["headers"].items())

        detected_versions = {}
        for software, pattern in self.VERSION_PATTERNS.items():
            m = re.search(pattern, combined, re.I)
            if m:
                detected_versions[software] = m.group(1)
                log("SCAN", f"NVD: detected {software} {m.group(1)}")

        if not detected_versions:
            log("OK", "NVD: No software versions detected in responses")
            return findings

        for software, version in detected_versions.items():
            cves         = await self._query_nvd(client, software, version, nvd_api_key)
            critical_high = [c for c in cves if c["score"] >= 7.0]
            actively_exploited = [c for c in cves if c.get("epss", 0.0) >= 0.10]

            if critical_high or actively_exploited:
                worst = (actively_exploited or critical_high)[0]
                epss_str = (
                    f"EPSS: {worst['epss']:.1%} exploitation probability "
                    f"(top {(1 - worst.get('epss_percentile', 0)) * 100:.0f}th percentile)"
                    if worst.get("epss", 0.0) > 0 else ""
                )
                sev = "CRITICAL" if worst["score"] >= 9.0 or worst.get("epss", 0) >= 0.30 else "HIGH"
                findings.append(Finding(
                    plugin="nvd_analyzer",
                    title=(
                        f"{'[ACTIVELY EXPLOITED] ' if worst.get('epss',0)>=0.10 else ''}"
                        f"CVE Match: {software} {version} -- "
                        f"{worst['id']} (CVSS {worst['score']})"
                    ),
                    severity=sev,
                    confidence=90.0,
                    description=(
                        f"{software} version {version} matches "
                        f"{len(critical_high)} CVE(s) with CVSS ≥7.0 "
                        f"and {len(actively_exploited)} with EPSS ≥10%. "
                        f"Worst: {worst['id']} (CVSS {worst['score']}) -- "
                        f"{worst['description']}. "
                        f"{epss_str}"
                    ),
                    evidence=(
                        f"Software: {software} {version} | "
                        f"Published: {worst.get('published','?')} | "
                        f"CVEs (CVSS≥7): {[c['id'] for c in critical_high[:3]]} | "
                        f"EPSS≥10%: {[c['id'] for c in actively_exploited[:3]]} | "
                        f"Highest CVSS: {worst['score']} | "
                        f"{epss_str}"
                    ),
                    url=url,
                    remediation=(
                        f"Update {software} to the latest stable version immediately. "
                        f"Review: https://nvd.nist.gov/vuln/search/results?query="
                        f"{software}+{version} | "
                        f"EPSS: https://api.first.org/data/v1/epss?cve={worst['id']}"
                    ),
                    cwe="CWE-1104", cvss=worst["score"], owasp="A06",
                    tags=(["nvd", "cve", "outdated-component", software.lower()] +
                          (["epss-high", "actively-exploited"]
                           if worst.get("epss", 0) >= 0.10 else [])),
                ))
                log("WARN",
                    f"NVD: {software} {version} → {len(critical_high)} high CVE(s), "
                    f"{len(actively_exploited)} actively exploited (EPSS≥10%)")
            elif cves:
                best_epss = max(c.get("epss", 0.0) for c in cves)
                findings.append(Finding(
                    plugin="nvd_analyzer",
                    title=f"Known Version Detected: {software} {version} ({len(cves)} CVE match(es))",
                    severity="LOW", confidence=75.0,
                    description=(
                        f"{software} {version} has {len(cves)} known CVE(s), "
                        f"none above CVSS 7.0. Highest EPSS: {best_epss:.1%}"
                    ),
                    evidence=(
                        f"CVEs: {[c['id'] for c in cves[:3]]} | "
                        f"Max EPSS: {best_epss:.3f}"
                    ),
                    url=url,
                    remediation=f"Keep {software} updated. Monitor NVD for new CVEs.",
                    cwe="CWE-1104", cvss=cves[0]["score"] if cves else 0.0,
                    owasp="A06", tags=["nvd", "cve", software.lower()],
                ))
            else:
                log("OK", f"NVD: {software} {version} -- no matching CVEs found")

        log("OK", f"NVD live CVE feed done -- {len(findings)} finding(s)")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  MODULE v41-11 — Advanced WebSocket Scanner
# ════════════════════════════════════════════════════════════════════════

class AdvancedWebSocketScanner:
    """
    Enhanced WebSocket security testing:
    - Large frame DoS (oversized messages)
    - JSON injection in messages
    - Authentication weakness (unauthenticated WS connections)
    - Replay attack detection
    - Origin header validation bypass
    """

    HAS_WEBSOCKETS = False
    _websockets_warned: bool = False  # class-level: emit install hint only once

    def __init__(self):
        try:
            import importlib
            spec = importlib.util.find_spec("websockets")
            self.HAS_WEBSOCKETS = spec is not None
        except Exception:
            self.HAS_WEBSOCKETS = False

    async def scan(self, client: "WebScoutClient", url: str) -> list:
        findings = []
        if not self.HAS_WEBSOCKETS:
            if not AdvancedWebSocketScanner._websockets_warned:
                AdvancedWebSocketScanner._websockets_warned = True
                log("INFO", (
                    "[AdvWebSocket] 'websockets' package not installed -- "
                    "deep WebSocket testing is disabled. "
                    "Install with: pip install websockets -- then re-run."
                ))
            return findings
        log("SCAN", "Running advanced WebSocket scanner...")

        parsed = urlparse(url)
        host = parsed.netloc
        ws_url = url.replace("https://", "wss://").replace("http://", "ws://")

        r = await client.get(url)
        if not r:
            return findings

        ws_endpoints = []
        body = r["text"]

        for m in re.finditer(r'''(?:new WebSocket|io\.connect|socket\.io)\s*\(\s*["'`]([^"'`]+)["'`]''',
                              body, re.I):
            ep = m.group(1)
            if not ep.startswith("ws"):
                ep = ws_url.rstrip("/") + ep
            ws_endpoints.append(ep)

        for m in re.finditer(r'"(wss?://[^"]+)"', body, re.I):
            ws_endpoints.append(m.group(1))

        if not ws_endpoints:
            for path in ["/ws", "/socket", "/websocket", "/io", "/socket.io"]:
                ws_test = f"wss://{host}{path}" if parsed.scheme == "https" else f"ws://{host}{path}"
                ws_endpoints.append(ws_test)

        if not self.HAS_WEBSOCKETS:
            if ws_endpoints:
                findings.append(Finding(
                    plugin="advanced_websocket",
                    title=f"WebSocket Endpoints Discovered (Install websockets for deep testing)",
                    severity="INFO", confidence=80.0,
                    description=f"Found {len(ws_endpoints)} potential WebSocket endpoint(s). Install 'websockets' package for full testing.",
                    evidence=f"Endpoints: {ws_endpoints[:5]}",
                    url=url,
                    remediation="pip install websockets -- then re-run for full WebSocket security audit.",
                    tags=["websocket", "setup"],
                ))
            return findings

        import websockets as _ws

        for ws_ep in ws_endpoints[:3]:
            try:
                async with _ws.connect(
                    ws_ep, additional_headers={"Origin": "https://evil.ws41test.invalid"},
                    open_timeout=5, close_timeout=5
                ) as ws:
                    findings.append(Finding(
                        plugin="advanced_websocket",
                        title=f"WebSocket Accepts Arbitrary Origin",
                        severity="MEDIUM", confidence=88.0,
                        description="WebSocket connection accepted with untrusted Origin header -- CSRF/CSWSH risk.",
                        evidence=f"Connected to {ws_ep} with Origin: evil.ws41test.invalid",
                        url=ws_ep,
                        remediation="Validate Origin header on WebSocket handshake against allowlist.",
                        cwe="CWE-346", cvss=6.5, owasp="A01",
                        tags=["websocket", "origin-bypass", "csrf"],
                    ))

                    injection_payloads = [
                        '{"__proto__":{"polluted":"ws41"}}',
                        '{"action":"/../admin","data":"test"}',
                        '{"id":"1 OR 1=1","action":"query"}',
                        '<script>alert(1)</script>',
                        "A" * 65536,
                    ]
                    for payload in injection_payloads:
                        try:
                            await ws.send(payload)
                            resp = await asyncio.wait_for(ws.recv(), timeout=3.0)
                            if "ws41" in str(resp) or "polluted" in str(resp):
                                findings.append(Finding(
                                    plugin="advanced_websocket",
                                    title="WebSocket JSON Injection / Prototype Pollution",
                                    severity="HIGH", confidence=85.0,
                                    description="WebSocket message reflection indicates JSON injection or prototype pollution.",
                                    evidence=f"Payload: {payload[:80]} | Response: {str(resp)[:100]}",
                                    url=ws_ep, payload=payload,
                                    remediation="Validate and sanitize all WebSocket messages server-side.",
                                    cwe="CWE-20", cvss=7.5, owasp="A03",
                                    tags=["websocket", "injection"],
                                ))
                        except asyncio.TimeoutError:
                            log("DEBUG", f"[AdvWebSocket] Payload probe timed out on {ws_ep}")
                        except Exception as _ws_probe_e:
                            log("DEBUG", f"[AdvWebSocket] Payload probe error on {ws_ep}: {_ws_probe_e}")

            except Exception as e:
                if "403" in str(e) or "401" in str(e):
                    findings.append(Finding(
                        plugin="advanced_websocket",
                        title=f"WebSocket Endpoint Found (Auth Required): {ws_ep}",
                        severity="INFO", confidence=80.0,
                        description="WebSocket endpoint exists but requires authentication.",
                        evidence=f"Connection error: {str(e)[:100]}",
                        url=ws_ep,
                        remediation="Verify authentication tokens are validated on WebSocket handshake, not just HTTP upgrade.",
                        tags=["websocket", "authentication"],
                    ))

        log("OK", f"Advanced WebSocket scan done -- {len(findings)} issue(s)")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  MODULE v41-12 — Advanced GraphQL Scanner
# ════════════════════════════════════════════════════════════════════════

class AdvancedGraphQLScanner:
    """
    Deep GraphQL security testing:
    - Merge query attack (query batching abuse)
    - Schema extraction with introspection disabled (field suggestion)
    - Field duplication DoS
    - Circular fragment detection
    - Directive injection
    - Authorization bypass via query aliasing
    """

    async def _find_graphql_endpoint(self, client: "WebScoutClient", url: str) -> Optional[str]:
          parsed = urlparse(url)
          base = f"{parsed.scheme}://{parsed.netloc}"
          for path in ["/graphql", "/api/graphql", "/graphql/v1", "/query", "/gql"]:
              try:
                  r = await client.post(
                      base + path,
                      json_body={"query": "{__typename}"},
                      headers={"Content-Type": "application/json"},
                  )
                  if r and r["status"] == 200 and "__typename" in r.get("text", ""):
                      log("OK", f"[GraphQL] Active endpoint confirmed: {base + path}")
                      return base + path
              except Exception as _gql_probe_exc:
                  log("DEBUG", f"[GraphQL] Probe error at {base + path}: {_gql_probe_exc}")
          return None
    async def test_field_suggestion_extraction(self, client: "WebScoutClient",
                                                 ep: str) -> list:
        """Extract schema types via field suggestion errors even when introspection is disabled."""
        findings = []
        probe_q = '{"query": "{__typ {nam}}"}'
        r = await client.post(ep, data=probe_q,
                               headers={"Content-Type": "application/json"})
        if not r:
            return findings
        body = r["text"]
        if "Did you mean" in body or "suggestion" in body.lower():
            suggestions = re.findall(r'"([a-zA-Z_][a-zA-Z0-9_]*)"', body)
            if suggestions:
                findings.append(Finding(
                    plugin="graphql_advanced",
                    title="GraphQL Schema Leakage via Field Suggestion (Introspection Disabled)",
                    severity="MEDIUM", confidence=88.0,
                    description=(
                        "GraphQL error messages reveal type/field names via 'Did you mean?' suggestions -- "
                        "schema can be reconstructed even with introspection disabled."
                    ),
                    evidence=f"Suggestions found: {suggestions[:10]}",
                    url=ep,
                    remediation="Disable field suggestions in production. Use generic error messages.",
                    cwe="CWE-209", cvss=5.3, owasp="A05",
                    tags=["graphql", "schema-leak", "suggestion"],
                ))
        return findings

    async def test_batching_abuse(self, client: "WebScoutClient", ep: str) -> list:
        """Test query batching for amplification and brute-force bypass."""
        findings = []
        batch_query = [
            {"query": f'{{user_{i}: __typename}}'}
            for i in range(100)
        ]
        r = await client.post(ep, json_body=batch_query,
                               headers={"Content-Type": "application/json"})
        if r and r["status"] == 200 and r["text"].count("__typename") >= 50:
            findings.append(Finding(
                plugin="graphql_advanced",
                title="GraphQL Query Batching Accepted (100 queries in single request)",
                severity="HIGH", confidence=90.0,
                description=(
                    "Server processed a batch of 100 GraphQL queries in a single HTTP request -- "
                    "enables brute-force rate limit bypass and amplification DoS."
                ),
                evidence=f"100 batched queries → {r['text'].count('__typename')} results",
                url=ep,
                remediation="Disable or limit query batching. Add per-batch rate limiting.",
                cwe="CWE-400", cvss=7.5, owasp="A04",
                tags=["graphql", "batching", "rate-limit-bypass", "dos"],
            ))
        return findings

    async def test_directive_injection(self, client: "WebScoutClient", ep: str) -> list:
        """Test for directive injection that could bypass field-level authorization."""
        findings = []
        payloads = [
            '{"query": "{__schema @include(if: true) { types { name } } }"}',
            '{"query": "{viewer { sensitiveField @skip(if: false) } }"}',
        ]
        for payload in payloads:
            r = await client.post(ep, data=payload,
                                   headers={"Content-Type": "application/json"})
            if r and r["status"] == 200 and "types" in r.get("text", ""):
                findings.append(Finding(
                    plugin="graphql_advanced",
                    title="GraphQL Directive Injection -- Introspection via @include",
                    severity="MEDIUM", confidence=80.0,
                    description="GraphQL directive injection (@include/@skip) bypasses schema restrictions.",
                    evidence=f"Payload: {payload[:100]} | Response contained schema data",
                    url=ep, payload=payload,
                    remediation="Validate and sanitize GraphQL directives server-side. Apply field-level authorization.",
                    cwe="CWE-285", cvss=5.3, owasp="A01",
                    tags=["graphql", "directive", "injection"],
                ))
                break
        return findings

    async def test_circular_fragment(self, client: "WebScoutClient", ep: str) -> list:
        """Test for circular fragment DoS (stack overflow via recursive fragments)."""
        findings = []
        q = """
        fragment A on __Schema { types { ...B } }
        fragment B on __Type { fields { type { ...A } } }
        query { __schema { ...A } }
        """
        r = await client.post(ep, json_body={"query": q},
                               headers={"Content-Type": "application/json"})
        if r:
            elapsed = r.get("time_ms", 0)
            if r["status"] == 500 or elapsed > 5000:
                findings.append(Finding(
                    plugin="graphql_advanced",
                    title="GraphQL Circular Fragment DoS",
                    severity="HIGH", confidence=80.0,
                    description="Circular fragment query caused server error or extreme delay -- DoS via recursive fragments.",
                    evidence=f"HTTP {r['status']} | Response time: {elapsed}ms",
                    url=ep,
                    remediation="Implement query depth limiting and fragment cycle detection.",
                    cwe="CWE-400", cvss=6.5, owasp="A04",
                    tags=["graphql", "dos", "circular-fragment"],
                ))
        return findings

    async def scan(self, client: "WebScoutClient", url: str) -> list:
        findings = []
        log("SCAN", "Running advanced GraphQL scanner...")
        ep = await self._find_graphql_endpoint(client, url)
        if not ep:
            log("SKIP", "No GraphQL endpoint found")
            return findings
        log("OK", f"GraphQL endpoint: {ep}")
        findings += await self.test_field_suggestion_extraction(client, ep)
        findings += await self.test_batching_abuse(client, ep)
        findings += await self.test_directive_injection(client, ep)
        findings += await self.test_circular_fragment(client, ep)
        log("OK", f"Advanced GraphQL scan done -- {len(findings)} issue(s)")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  MODULE v41-13 — ML Anomaly Detector (Isolation Forest)
# ════════════════════════════════════════════════════════════════════════

class MLAnomalyDetector:
    """
    Machine-learning based anomaly detection using Isolation Forest algorithm
    (implemented from scratch to avoid sklearn dependency).
    Detects unusual HTTP response patterns that may indicate unknown vulnerabilities
    or undocumented behavior.
    """

    # 50+ probe paths to provide a statistically more meaningful training set
    # for the Isolation Forest.  More samples reduce false positives significantly
    # because normal cluster tightens and anomalies stand out more clearly.
    PROBE_PATHS = [
        "/", "/index.html", "/login", "/logout", "/register",
        "/api", "/api/v1/health", "/api/v2", "/api/v3",
        "/admin", "/admin/login", "/administrator", "/wp-admin",
        "/api/users", "/api/user", "/api/profile", "/api/me",
        "/config", "/debug", "/status", "/health", "/ping",
        "/search?q=test", "/api/v1/users?limit=10", "/404_xyz_nonexistent",
        "/metrics", "/actuator", "/actuator/health", "/actuator/env",
        "/env", "/api/v1/admin", "/api/v1/config", "/.git/config",
        "/swagger.json", "/.env", "/api/v1/auth/token",
        "/phpinfo.php", "/info.php", "/.well-known/security.txt",
        "/robots.txt", "/sitemap.xml", "/crossdomain.xml",
        "/api/v1/orders", "/api/v1/products", "/api/v1/payments",
        "/api/v1/settings", "/api/v1/logs", "/api/v1/stats",
        "/backup.sql", "/db_backup.sql", "/web.config",
        "/server-status", "/server-info",
        "/api/graphql", "/graphql", "/gql",
        "/api/v1/tokens", "/api/v1/keys", "/api/v1/secrets",
    ]

    def _fit_isolation_forest(self, data: list, n_trees: int = 50,
                               sample_size: int = 16) -> list:
        """Minimal Isolation Forest: returns anomaly score per sample (higher = more anomalous)."""
        if len(data) < 4:
            return [0.0] * len(data)

        import random as _rand
        _rand.seed(42)  # Fixed seed for reproducible anomaly scores across runs

        def _isolation_tree(X: list, max_depth: int) -> dict:
            if len(X) <= 1 or max_depth <= 0:
                return {"type": "leaf", "size": len(X)}
            feature = _rand.randint(0, len(X[0]) - 1)
            vals = [x[feature] for x in X]
            mn, mx = min(vals), max(vals)
            if mn == mx:
                return {"type": "leaf", "size": len(X)}
            split = _rand.uniform(mn, mx)
            left = [x for x in X if x[feature] < split]
            right = [x for x in X if x[feature] >= split]
            return {
                "type": "node", "feature": feature, "split": split,
                "left": _isolation_tree(left, max_depth - 1),
                "right": _isolation_tree(right, max_depth - 1),
            }

        def _path_length(node: dict, x: list, depth: int = 0) -> float:
            if node["type"] == "leaf":
                n = node["size"]
                if n <= 1:
                    return depth
                h = 2 * (sum(1/i for i in range(1, n)) - (n-1)/n)
                return depth + h
            if x[node["feature"]] < node["split"]:
                return _path_length(node["left"], x, depth + 1)
            return _path_length(node["right"], x, depth + 1)

        import math as _math
        max_depth = int(_math.ceil(_math.log2(max(sample_size, 2))))
        scores = []
        for xi in data:
            avg_path = 0.0
            for _ in range(n_trees):
                sample = _rand.sample(data, min(sample_size, len(data)))
                tree = _isolation_tree(sample, max_depth)
                avg_path += _path_length(tree, xi)
            avg_path /= n_trees
            n = sample_size
            c_n = 2 * (sum(1/i for i in range(1, n)) - (n-1)/n) if n > 1 else 1.0
            score = 2 ** (-avg_path / c_n)
            scores.append(score)
        return scores

    async def scan(self, client: "WebScoutClient", base_url: str) -> list:
        findings = []
        log("AI", "Running ML anomaly detector (Isolation Forest)...")
        parsed = urlparse(base_url)
        base = f"{parsed.scheme}://{parsed.netloc}"

        feature_vectors = []
        probe_results = []

        for path in self.PROBE_PATHS:
            t0 = time.perf_counter()
            r = await client.get(base + path)
            elapsed = time.perf_counter() - t0
            if not r:
                continue

            body = r["text"]
            from math import log2 as _log2
            freq = {}
            for ch in body[:2000]:
                freq[ch] = freq.get(ch, 0) + 1
            ln = len(body[:2000]) or 1
            entropy = -sum((c/ln)*_log2(c/ln) for c in freq.values() if c > 0)

            json_keys = 0
            try:
                if "application/json" in r["headers"].get("content-type", ""):
                    obj = json.loads(body)
                    json_keys = len(obj) if isinstance(obj, dict) else 0
            except Exception as _ml_json_e:
                log("DEBUG", f"ML: JSON parse error for {path}: {_ml_json_e}")

            vec = [
                float(r["status"]) / 1000.0,
                min(len(body), 100000) / 100000.0,
                min(elapsed, 10.0) / 10.0,
                len(r["headers"]) / 50.0,
                entropy / 8.0,
                float(json_keys) / 100.0,
            ]
            feature_vectors.append(vec)
            probe_results.append({"path": path, "status": r["status"],
                                   "size": len(body), "time": elapsed,
                                   "entropy": entropy, "url": base + path})

        if len(feature_vectors) < 4:
            log("WARN", "ML: insufficient probe data for anomaly detection")
            return findings

        scores = self._fit_isolation_forest(feature_vectors)

        THRESHOLD = 0.65
        anomalies = sorted(
            [(scores[i], probe_results[i]) for i in range(len(scores)) if scores[i] > THRESHOLD],
            key=lambda x: -x[0]
        )

        # Note on statistical reliability: this Isolation Forest is trained on
        # ~16-22 probe responses only, which is a very small sample.  Scores are
        # directionally useful but NOT statistically reliable — both false positives
        # (normal endpoints that look unusual among few peers) and false negatives
        # (vulnerabilities that blend with other anomalous responses) are common.
        # All ML findings MUST be treated as "Indicative -- manual verification required."
        # Confidence is capped at 65% regardless of score to reflect this limitation.
        _ML_MAX_CONFIDENCE = 65.0
        _sample_count = len(feature_vectors)

        for score, meta in anomalies[:5]:
            # Downgrade severity by one level vs raw score to account for low sample reliability
            sev = "MEDIUM" if score > 0.80 else "LOW"
            findings.append(Finding(
                plugin="ml_anomaly",
                title=f"ML Anomaly Detected [Indicative] -- {meta['path']} (score={score:.3f})",
                severity=sev,
                confidence=min(_ML_MAX_CONFIDENCE, score * 80),
                description=(
                    f"Isolation Forest flagged '{meta['path']}' as anomalous (score={score:.3f}). "
                    f"HTTP {meta['status']} | Size: {meta['size']}B | "
                    f"Time: {meta['time']:.2f}s | Entropy: {meta['entropy']:.2f}. "
                    "IMPORTANT: model trained on only "
                    f"{_sample_count} probe responses -- results are indicative only. "
                    "Manual verification is required before treating this as a confirmed vulnerability."
                ),
                evidence=(
                    f"Anomaly score: {score:.3f} (threshold={THRESHOLD}) | "
                    f"Training samples: {_sample_count} | "
                    f"Path: {meta['path']} | Status: {meta['status']} | "
                    f"Size: {meta['size']} | Entropy: {meta['entropy']:.2f}"
                ),
                url=meta["url"],
                remediation=(
                    "Investigate this path manually. Verify expected behavior and access controls. "
                    "Do not treat this as a confirmed vulnerability without manual analysis."
                ),
                cwe="CWE-200", cvss=3.0, owasp="A05",
                poc=f"curl -s -o /dev/null -w '%{{http_code}} %{{size_download}} %{{time_total}}' {meta['url']}",
                tags=["ml", "anomaly", "isolation-forest", "indicative"],
            ))
            log("AI", f"ML anomaly [indicative]: {meta['path']} score={score:.3f}")

        log("OK", f"ML anomaly detection done -- {len(findings)} anomaly/ies found")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  MODULE v41-14 — Performance Monitor & Analytics
# ════════════════════════════════════════════════════════════════════════

class PerformanceMonitor:
    """
    Analyzes scan performance metrics and response timing:
    - Identifies slow endpoints (potential DoS vectors or bottlenecks)
    - Detects false-positive-prone paths
    - Measures scan coverage efficiency
    - Identifies rate-limit induced delays
    - Generates performance summary report
    """

    async def scan(self, client: "WebScoutClient", url: str,
                   existing_findings: list = None) -> list:
        findings = []
        log("SCAN", "Running performance monitor & analytics...")
        parsed = urlparse(url)
        base = f"{parsed.scheme}://{parsed.netloc}"

        probe_paths = ["/", "/api", "/login", "/api/v1/health", "/nonexistent_ws41"]
        timing_data = []

        for path in probe_paths:
            times = []
            # 7 samples provide a statistically meaningful average and variance estimate
            # (3 samples are insufficient — single outlier dominates the mean).
            for _ in range(7):
                t0 = time.perf_counter()
                r = await client.get(base + path)
                times.append(time.perf_counter() - t0)
            avg_time = sum(times) / len(times)
            variance = sum((t - avg_time)**2 for t in times) / len(times)
            timing_data.append({
                "path": path, "avg": avg_time,
                "min": min(times), "max": max(times),
                "variance": variance,
            })

        slow_paths = [d for d in timing_data if d["avg"] > 2.0]
        for slow in slow_paths:
            findings.append(Finding(
                plugin="performance_monitor",
                title=f"Slow Response Detected -- {slow['path']} (avg={slow['avg']:.2f}s)",
                severity="MEDIUM", confidence=85.0,
                description=(
                    f"Path '{slow['path']}' averages {slow['avg']:.2f}s response time "
                    f"(min={slow['min']:.2f}s, max={slow['max']:.2f}s). "
                    "Slow endpoints are potential DoS amplification vectors and indicate performance issues."
                ),
                evidence=f"Avg: {slow['avg']:.2f}s | Min: {slow['min']:.2f}s | Max: {slow['max']:.2f}s | Variance: {slow['variance']:.4f}",
                url=base + slow["path"],
                remediation="Profile server-side code. Add caching. Investigate database query performance.",
                cwe="CWE-400", cvss=3.0, owasp="A05",
                tags=["performance", "slow-response", "dos-potential"],
            ))

        high_variance = [d for d in timing_data if d["variance"] > 1.0 and d["avg"] > 0.5]
        for hv in high_variance:
            findings.append(Finding(
                plugin="performance_monitor",
                title=f"High Response Time Variance -- {hv['path']} (σ²={hv['variance']:.2f})",
                severity="LOW", confidence=75.0,
                description=(
                    f"Path '{hv['path']}' shows high timing variance (σ²={hv['variance']:.2f}) -- "
                    "suggests inconsistent server load, connection pooling issues, or time-based injection sensitivity."
                ),
                evidence=f"Variance: {hv['variance']:.4f} | Times: {[round(hv['min'],2), round(hv['avg'],2), round(hv['max'],2)]}",
                url=base + hv["path"],
                remediation="Investigate server-side performance inconsistency. Consider connection pooling and caching.",
                cwe="CWE-400", cvss=2.0, owasp="A05",
                tags=["performance", "variance", "timing"],
            ))

        stats = client.stats
        total_requests = stats.get("requests", 0)
        timeouts = stats.get("timeouts", 0)
        errors = stats.get("errors", 0)
        rate_limited = stats.get("rate_limited", 0)

        perf_summary = {
            "total_requests": total_requests,
            "timeouts": timeouts,
            "errors": errors,
            "rate_limited": rate_limited,
            "timeout_rate": f"{(timeouts/max(total_requests,1))*100:.1f}%",
            "error_rate": f"{(errors/max(total_requests,1))*100:.1f}%",
        }

        if rate_limited > 0:
            findings.append(Finding(
                plugin="performance_monitor",
                title=f"Rate Limiting Encountered During Scan ({rate_limited} requests throttled)",
                severity="INFO", confidence=100.0,
                description=(
                    f"Scanner was rate-limited {rate_limited} time(s) -- target has active rate limiting. "
                    "Consider increasing --delay and reducing --concurrency for better coverage."
                ),
                evidence=f"Rate-limited requests: {rate_limited} | Total: {total_requests}",
                url=url,
                remediation="Rate limiting is a security control -- ensure it is consistent across all endpoints.",
                tags=["performance", "rate-limiting", "scan-quality"],
            ))

        if timeouts > total_requests * 0.1 and total_requests > 10:
            findings.append(Finding(
                plugin="performance_monitor",
                title=f"High Timeout Rate During Scan ({perf_summary['timeout_rate']})",
                severity="LOW", confidence=80.0,
                description=(
                    f"{timeouts} timeout(s) out of {total_requests} requests ({perf_summary['timeout_rate']}) -- "
                    "high timeout rate may indicate scan coverage gaps or server instability."
                ),
                evidence=f"Timeouts: {timeouts} | Errors: {errors} | Total: {total_requests}",
                url=url,
                remediation="Increase --timeout value. Check server stability. Reduce --concurrency.",
                tags=["performance", "timeouts", "scan-quality"],
            ))

        findings.append(Finding(
            plugin="performance_monitor",
            title="Scan Performance Summary",
            severity="INFO", confidence=100.0,
            description=(
                f"Scan statistics: {total_requests} total requests | "
                f"{timeouts} timeouts ({perf_summary['timeout_rate']}) | "
                f"{errors} errors ({perf_summary['error_rate']}) | "
                f"{rate_limited} rate-limited | "
                f"Avg response time across probes: {sum(d['avg'] for d in timing_data)/len(timing_data):.2f}s"
            ),
            evidence=json.dumps(perf_summary),
            url=url,
            remediation="Review scan parameters for optimal speed/accuracy tradeoff.",
            tags=["performance", "summary", "analytics"],
        ))

        log("OK", f"Performance monitor done -- {len(findings)} finding(s)")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  MODULE v41-15 — Advanced SameSite & CSRF Scanner
# ════════════════════════════════════════════════════════════════════════

class AdvancedSameSiteCSRFScanner:
    """
    Advanced CSRF testing with SameSite bypass scenarios:
    - SameSite=Lax bypass via GET requests with state-changing effects
    - SameSite=Lax bypass via top-level navigation in iframes
    - SameSite=None without Secure flag
    - Token predictability attacks (sequential or low-entropy tokens)
    - Double-submit cookie bypass
    - Content-type based CSRF (JSON with text/plain)
    """

    async def test_samesite_lax_get_bypass(self, client: "WebScoutClient",
                                             url: str) -> list:
        """Test if state-changing operations are possible via GET (SameSite=Lax bypass)."""
        findings = []
        r = await client.get(url)
        if not r:
            return findings

        # Tightened patterns: require action keywords in both the tag AND a meaningful path segment
        # (not just any link that contains these words in anchor text or outer content)
        state_change_patterns = [
            r'<a[^>]+href=["\'][^"\']*[/?](delete|remove|logout|cancel|purchase|transfer|confirm)[^"\']*["\']',
            r'<form[^>]+method=["\']get["\'][^>]*action=["\'][^"\']*[/?](delete|buy|confirm|transfer|update)[^"\']*["\']',
        ]

        # Success indicators: body should signal that a state change happened, not just a 200
        success_indicators = [
            "success", "deleted", "removed", "confirmed", "cancelled",
            "logged out", "transferred", "updated", "purchased",
        ]
        # Error indicators: if present the endpoint rejected the request → not a real bypass
        error_indicators = [
            "csrf", "token", "invalid", "forbidden", "not allowed",
            "access denied", "unauthorized", "error", "bad request",
        ]

        for pat in state_change_patterns:
            matches = re.findall(pat, r["text"], re.I)
            for match in matches[:3]:
                href = re.search(r'href=["\']([^"\']+)["\']', match, re.I)
                action = re.search(r'action=["\']([^"\']+)["\']', match, re.I)
                target = href.group(1) if href else (action.group(1) if action else "")
                if not target:
                    continue
                full_url = urljoin(url, target)
                test_r = await client.get(full_url)
                if not test_r or test_r["status"] not in (200, 302):
                    continue
                body_lower = test_r["text"].lower()
                # Only flag if response body confirms success AND has no CSRF/error rejection
                has_success = any(s in body_lower for s in success_indicators)
                has_error   = any(e in body_lower for e in error_indicators)
                if has_success and not has_error:
                    findings.append(Finding(
                        plugin="advanced_csrf",
                        title="SameSite=Lax Bypass: State-Changing GET Request",
                        severity="HIGH", confidence=82.0,
                        description=(
                            f"State-changing operation via GET found at '{full_url}'. "
                            "SameSite=Lax cookies are sent on top-level GET navigations -- "
                            "attacker can trigger this action from another site via link or redirect."
                        ),
                        evidence=(
                            f"GET {full_url} → HTTP {test_r['status']} | "
                            f"Success indicator found in body | Pattern: {match[:100]}"
                        ),
                        url=full_url,
                        remediation=(
                            "State-changing operations must use POST, PUT, or DELETE. "
                            "Add CSRF token validation. Use SameSite=Strict for sensitive cookies."
                        ),
                        cwe="CWE-352", cvss=8.1, owasp="A01",
                        tags=["csrf", "samesite-lax-bypass", "get-based-csrf"],
                    ))
        return findings

    async def test_samesite_none_insecure(self, client: "WebScoutClient",
                                           url: str) -> list:
        """Detect SameSite=None cookies without Secure flag."""
        findings = []
        r = await client.get(url)
        if not r:
            return findings
        cookies = r["headers"].get("Set-Cookie", "")
        if not cookies:
            return findings
        cookie_list = cookies.split(",") if "," in cookies else [cookies]
        for ck in cookie_list:
            ck_lower = ck.lower()
            has_samesite_none = "samesite=none" in ck_lower
            has_secure = "secure" in ck_lower
            if has_samesite_none and not has_secure:
                findings.append(Finding(
                    plugin="advanced_csrf",
                    title="Cookie SameSite=None Without Secure Flag",
                    severity="HIGH", confidence=100.0,
                    description=(
                        "Cookie has SameSite=None but is missing the Secure flag. "
                        "Modern browsers reject SameSite=None without Secure, but this may expose "
                        "the cookie on HTTP connections and indicates a misconfiguration."
                    ),
                    evidence=f"Set-Cookie: {ck[:150]}",
                    url=url,
                    remediation="Add Secure flag to all cookies with SameSite=None. Use HTTPS exclusively.",
                    cwe="CWE-614", cvss=7.5, owasp="A07",
                    tags=["csrf", "samesite", "cookie", "misconfiguration"],
                ))
        return findings

    async def test_content_type_csrf(self, client: "WebScoutClient",
                                      url: str) -> list:
        """Test JSON endpoints accessible via text/plain Content-Type (CSRF via form)."""
        findings = []
        parsed = urlparse(url)
        params = parse_qs(parsed.query)

        r = await client.get(url)
        if not r:
            return findings

        forms = re.findall(r'<form[^>]+action=["\']([^"\']*)["\'][^>]*>.*?</form>',
                           r["text"], re.DOTALL | re.I)
        for form_action in forms[:5]:
            ep = urljoin(url, form_action)
            json_payload = '{"test":"ws41csrf","action":"update"}'
            r2 = await client.post(
                ep, data=json_payload,
                headers={"Content-Type": "text/plain"}
            )
            if r2 and r2["status"] in (200, 201):
                body = r2["text"].lower()
                if not any(e in body for e in ["invalid", "error", "bad request", "wrong content-type"]):
                    findings.append(Finding(
                        plugin="advanced_csrf",
                        title=f"CSRF via Content-Type Confusion (text/plain for JSON)",
                        severity="HIGH", confidence=80.0,
                        description=(
                            f"Endpoint '{ep}' accepts JSON payload with Content-Type: text/plain -- "
                            "enables CSRF attacks via HTML form since browsers send form data as text/plain."
                        ),
                        evidence=f"POST {ep} with Content-Type: text/plain → HTTP {r2['status']}",
                        url=ep,
                        remediation="Strictly validate Content-Type header. Reject non-JSON content-types on JSON APIs.",
                        cwe="CWE-352", cvss=8.0, owasp="A01",
                        tags=["csrf", "content-type-confusion"],
                    ))
        return findings

    async def test_token_predictability(self, client: "WebScoutClient",
                                         url: str) -> list:
        """Collect multiple CSRF tokens and check for patterns or low entropy."""
        findings = []
        tokens = []
        for _ in range(5):
            r = await client.get(url)
            if not r:
                continue
            tok = SessionCSRFManager._extract_csrf(r["text"])
            if tok and len(tok) >= 4:
                tokens.append(tok)
            await asyncio.sleep(0.2)

        if len(tokens) < 3:
            return findings

        if len(set(tokens)) == 1:
            findings.append(Finding(
                plugin="advanced_csrf",
                title="CSRF Token is Static (Same Value Across All Requests)",
                severity="CRITICAL", confidence=98.0,
                description="CSRF token is identical across multiple requests -- completely predictable and bypassable.",
                evidence=f"Token: {tokens[0]} | All {len(tokens)} tokens identical",
                url=url,
                remediation="Generate a unique, cryptographically random CSRF token per session AND per request.",
                cwe="CWE-330", cvss=9.1, owasp="A01",
                tags=["csrf", "static-token", "predictable"],
            ))
            return findings

        entropies = []
        for tok in tokens:
            if not tok:
                continue
            freq = {}
            for ch in tok:
                freq[ch] = freq.get(ch, 0) + 1
            ln = len(tok)
            ent = -sum((c/ln)*log2(c/ln) for c in freq.values() if c > 0)
            entropies.append(ent)

        avg_entropy = sum(entropies) / len(entropies) if entropies else 0
        if avg_entropy < 3.0:
            findings.append(Finding(
                plugin="advanced_csrf",
                title=f"CSRF Token Low Entropy (avg={avg_entropy:.2f} bits/char)",
                severity="HIGH", confidence=85.0,
                description=(
                    f"CSRF tokens have average entropy of {avg_entropy:.2f} bits/char -- "
                    "below the recommended minimum of 3.0 bits/char. Tokens may be predictable."
                ),
                evidence=f"Tokens: {tokens[:3]} | Entropies: {[round(e,2) for e in entropies]}",
                url=url,
                remediation="Use cryptographically random 256-bit tokens. Avoid timestamp or sequential-based tokens.",
                cwe="CWE-330", cvss=7.5, owasp="A01",
                tags=["csrf", "low-entropy", "predictable"],
            ))
        return findings

    async def scan(self, client: "WebScoutClient", url: str) -> list:
        log("SCAN", "Running advanced SameSite & CSRF scanner...")
        findings = []
        findings += await self.test_samesite_lax_get_bypass(client, url)
        findings += await self.test_samesite_none_insecure(client, url)
        findings += await self.test_content_type_csrf(client, url)
        try:
            findings += await self.test_token_predictability(client, url)
        except Exception as _csrf_pred_e:
            log("DEBUG", f"[AdvCSRF] token_predictability probe failed: {_csrf_pred_e}")
        log("OK", f"Advanced CSRF/SameSite scan done -- {len(findings)} issue(s)")
        return findings


