#  MODULE v38-4 — Prototype Pollution Scanner
# ════════════════════════════════════════════════════════════════════════

class PrototypePollutionScanner:
    """Detect JavaScript prototype pollution vulnerabilities."""

    PP_PAYLOADS = [
        "__proto__[polluted]=webscout38",
        "__proto__.polluted=webscout38",
        "constructor[prototype][polluted]=webscout38",
        "constructor.prototype.polluted=webscout38",
        "__proto__[admin]=true",
        "__proto__[isAdmin]=true",
        "__proto__[role]=admin",
        "__proto__[debug]=true",
        '{"__proto__":{"polluted":"webscout38"}}',
        '{"constructor":{"prototype":{"polluted":"webscout38"}}}',
    ]

    SERVER_PP_PATHS = [
        "/api/user/update",
        "/api/settings",
        "/api/profile",
        "/api/config",
        "/user/update",
        "/settings/update",
        "/profile",
    ]

    async def scan(self, client: WebScoutClient, base_url: str) -> list:
        findings = []
        parsed = urlparse(base_url)
        base = f"{parsed.scheme}://{parsed.netloc}"

        # GET-based prototype pollution (query string)
        for payload in self.PP_PAYLOADS[:6]:
            if "=" in payload and "[" in payload:
                # query string style
                test_url = base_url + ("&" if "?" in base_url else "?") + payload
                r = await client.get(test_url)
                if r and "webscout38" in r["text"]:
                    findings.append(Finding(
                        plugin="proto_pollution",
                        title="Prototype Pollution via Query String",
                        severity="HIGH", confidence=85.0,
                        description="Server reflects prototype pollution payload -- client/server-side PP possible.",
                        evidence=f"Payload: {payload} | Response snippet: {r['text'][:200]}",
                        url=test_url, payload=payload,
                        remediation="Sanitize object keys. Block __proto__, constructor, prototype. Use Object.create(null).",
                        cwe="CWE-1321", cvss=7.5, owasp="A03",
                        poc=f"curl -sk '{test_url}'",
                        tags=["prototype-pollution", "javascript"],
                    ))
                    log("VULN", f"Prototype pollution via query string: {payload[:50]}")

        # POST-based prototype pollution (JSON body)
        for path in self.SERVER_PP_PATHS:
            url = base + path
            for json_payload in [
                {"__proto__": {"polluted": "webscout38"}},
                {"constructor": {"prototype": {"polluted": "webscout38"}}},
                {"__proto__": {"admin": True, "isAdmin": True}},
            ]:
                r = await client.post(url, json_body=json_payload)
                if not r:
                    continue
                body_lower = r["text"].lower()
                if "webscout38" in r["text"] or (
                    r["status"] == 200 and "admin" in body_lower and json_payload.get("__proto__", {}).get("admin")
                ):
                    findings.append(Finding(
                        plugin="proto_pollution",
                        title=f"Server-Side Prototype Pollution -- {path}",
                        severity="CRITICAL", confidence=88.0,
                        description="JSON body with __proto__ key accepted and may pollute server-side object.",
                        evidence=f"Endpoint: {url} | Payload: {json.dumps(json_payload)[:120]}",
                        url=url, payload=str(json_payload),
                        remediation="Use JSON schema validation. Strip __proto__/constructor keys before merging.",
                        cwe="CWE-1321", cvss=9.8, owasp="A03",
                        poc=f"curl -sk -X POST {url} -H 'Content-Type: application/json' -d '{json.dumps(json_payload)}'",
                        tags=["prototype-pollution", "sspp"],
                    ))
                    log("VULN", f"Server-side PP at {path}")
                    break

        # Check for client-side PP indicators in JavaScript
        page = await client.get(base_url)
        if page:
            js_urls = re.findall(r'src=["\']([^"\']+\.js[^"\']*)["\']', page["text"], re.I)
            for js_url in js_urls[:5]:
                jr = await client.get(urljoin(base_url, js_url))
                if not jr:
                    continue
                dangerous_patterns = [
                    r"Object\.assign\s*\(",
                    r"merge\s*\([^)]*,\s*[^)]*\)",
                    r"\[key\]\s*=\s*value",
                    r"for\s*\(\s*(?:var|let|const)\s+\w+\s+in\s+\w+\)",
                    r"deepmerge|deepMerge|_.merge\(",
                ]
                for pat in dangerous_patterns:
                    if re.search(pat, jr["text"]):
                        findings.append(Finding(
                            plugin="proto_pollution",
                            title=f"Potential Client-Side PP Pattern: {js_url.split('/')[-1][:40]}",
                            severity="LOW", confidence=50.0,
                            description=f"JS file uses unsafe merge pattern ('{pat}') susceptible to prototype pollution.",
                            evidence=f"Pattern: {pat} | File: {js_url}",
                            url=urljoin(base_url, js_url),
                            remediation="Use lodash >=4.17.21, or safe merge implementations that filter __proto__.",
                            cwe="CWE-1321", owasp="A03",
                            tags=["prototype-pollution", "client-side", "javascript"],
                        ))
                        break

        log("OK", f"Prototype pollution scan done -- {len(findings)} finding(s)")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  MODULE v38-5 — Email Security Scanner (SPF / DKIM / DMARC)
# ════════════════════════════════════════════════════════════════════════

class EmailSecurityScanner:
    """Check DNS-based email security: SPF, DKIM, DMARC."""

    async def scan(self, client: WebScoutClient, base_url: str) -> list:
        findings = []
        parsed = urlparse(base_url)
        domain = parsed.hostname or ""
        loop = asyncio.get_event_loop()

        # SPF
        spf = await loop.run_in_executor(None, self._txt_record, domain)
        spf_records = [r for r in spf if r.startswith("v=spf1")]
        if not spf_records:
            findings.append(Finding(
                plugin="email_security",
                title=f"Missing SPF Record -- {domain}",
                severity="HIGH", confidence=100.0,
                description="No SPF TXT record found. Domain can be used for email spoofing.",
                evidence=f"Domain: {domain} | SPF records found: 0",
                url=base_url,
                remediation='Add SPF record: "v=spf1 include:yourmailprovider.com -all"',
                cwe="CWE-290", cvss=7.5, owasp="A07",
                tags=["email", "spf", "spoofing"],
            ))
        else:
            spf_val = spf_records[0]
            if "+all" in spf_val:
                findings.append(Finding(
                    plugin="email_security",
                    title=f"SPF Record Uses +all (Permissive) -- {domain}",
                    severity="CRITICAL", confidence=100.0,
                    description="SPF record with '+all' allows any server to send email as this domain.",
                    evidence=f"SPF: {spf_val}",
                    url=base_url,
                    remediation='Change +all to -all or ~all in SPF record.',
                    cwe="CWE-290", cvss=9.1, owasp="A07",
                    tags=["email", "spf", "spoofing"],
                ))
            elif "~all" in spf_val:
                findings.append(Finding(
                    plugin="email_security",
                    title=f"SPF Record Uses ~all (SoftFail) -- {domain}",
                    severity="MEDIUM", confidence=100.0,
                    description="SPF SoftFail (~all) still allows spoofed email to pass some filters.",
                    evidence=f"SPF: {spf_val}",
                    url=base_url,
                    remediation='Use -all (HardFail) to fully reject unauthorized senders.',
                    cwe="CWE-290", cvss=5.3, owasp="A07",
                    tags=["email", "spf"],
                ))

        # DMARC
        dmarc = await loop.run_in_executor(None, self._txt_record, f"_dmarc.{domain}")
        dmarc_records = [r for r in dmarc if r.startswith("v=DMARC1")]
        if not dmarc_records:
            findings.append(Finding(
                plugin="email_security",
                title=f"Missing DMARC Record -- {domain}",
                severity="HIGH", confidence=100.0,
                description="No DMARC policy found. Domain vulnerable to email spoofing and phishing.",
                evidence=f"Domain: _dmarc.{domain} | No DMARC found",
                url=base_url,
                remediation='Add DMARC: "v=DMARC1; p=reject; rua=mailto:dmarc@yourdomain.com"',
                cwe="CWE-290", cvss=7.5, owasp="A07",
                tags=["email", "dmarc", "spoofing"],
            ))
        else:
            dmarc_val = dmarc_records[0]
            if "p=none" in dmarc_val:
                findings.append(Finding(
                    plugin="email_security",
                    title=f"DMARC Policy is 'none' -- {domain}",
                    severity="MEDIUM", confidence=100.0,
                    description="DMARC policy p=none takes no action on failures -- monitoring only.",
                    evidence=f"DMARC: {dmarc_val}",
                    url=base_url,
                    remediation='Change DMARC policy to p=quarantine or p=reject.',
                    cwe="CWE-290", cvss=5.3, owasp="A07",
                    tags=["email", "dmarc"],
                ))

        # DKIM (common selectors)
        dkim_found = False
        for selector in ["default", "google", "mail", "email", "k1", "s1", "s2", "dkim"]:
            dkim_domain = f"{selector}._domainkey.{domain}"
            recs = await loop.run_in_executor(None, self._txt_record, dkim_domain)
            if any("v=DKIM1" in r or "p=" in r for r in recs):
                dkim_found = True
                break
        if not dkim_found:
            findings.append(Finding(
                plugin="email_security",
                title=f"No DKIM Record Found -- {domain}",
                severity="MEDIUM", confidence=70.0,
                description="No DKIM TXT record detected at common selectors. Email integrity unverified.",
                evidence=f"Checked selectors: default, google, mail, email, k1, s1, s2, dkim",
                url=base_url,
                remediation="Configure DKIM signing for outbound email and publish DKIM public key in DNS.",
                cwe="CWE-290", cvss=5.3, owasp="A07",
                tags=["email", "dkim"],
            ))

        log("OK", f"Email security scan done -- {len(findings)} finding(s)")
        return findings

    def _txt_record(self, domain: str) -> list:
        """Return TXT records for domain using dnspython (preferred) or nslookup fallback.

        Note: For best SPF/DMARC resolution results, install dnspython:
            pip install dnspython
        Without it, nslookup is used as a fallback which may fail on minimal systems.
        """
        try:
            import dns.resolver  # type: ignore
            answers = dns.resolver.resolve(domain, "TXT")
            return [b.decode() for rdata in answers for b in rdata.strings]
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        try:
            # Pure Python raw socket DNS TXT query
            import socket as _dns_sock
            import random as _dns_rand
            def _build_txt_query(dom):
                txid = _dns_rand.randint(0,65535).to_bytes(2,"big")
                hdr  = txid + b"\x01\x00\x00\x01\x00\x00\x00\x00\x00\x00"
                q    = b""
                for lbl in dom.rstrip(".").split("."):
                    enc = lbl.encode(); q += bytes([len(enc)]) + enc
                q += b"\x00\x00\x10\x00\x01"
                return hdr + q
            pkt = _build_txt_query(domain)
            sock = _dns_sock.socket(_dns_sock.AF_INET, _dns_sock.SOCK_DGRAM)
            sock.settimeout(5)
            sock.sendto(pkt, ("8.8.8.8", 53))
            data, _ = sock.recvfrom(4096)
            sock.close()
            records = []
            ancount = (data[6] << 8) | data[7]
            if ancount > 0:
                # Simple extraction: find TXT strings after answers
                idx = data.find(b"\x00\x10\x00\x01")  # TXT IN marker
                while idx != -1 and idx < len(data) - 4:
                    idx2 = data.find(b"\x00\x10\x00\x01", idx + 1)
                    if idx2 == -1: break
                    rdlen = (data[idx2+8] << 8) | data[idx2+9] if idx2+10 <= len(data) else 0
                    if rdlen > 0 and idx2 + 10 + rdlen <= len(data):
                        txt_raw = data[idx2+10:idx2+10+rdlen]
                        i = 0
                        while i < len(txt_raw):
                            tlen = txt_raw[i]; i += 1
                            records.append(txt_raw[i:i+tlen].decode("ascii", errors="replace"))
                            i += tlen
                    idx = idx2 + 1
            return records
        except Exception:
            return []


