def _v19_embedded_start(self):
    """
    Wraps original EmbeddedCollaboratorServer.start() to additionally
    spin up the enhanced OOB server (DNS + HTTP) when dnslib is present.
    """
    port = _v19_orig_embedded_start(self)
    # Attach enhanced OOB server as a sibling attribute
    try:
        self._enhanced_oob = OOBServerEnhanced(
            http_host="0.0.0.0",
            dns_port=OOBServerEnhanced._DEFAULT_DNS_PORT,
        )
        self._enhanced_oob.start()
        log("INFO",
            f"[EmbeddedCollaboratorServer] OOBServerEnhanced attached -- "
            f"DNS={'active' if _HAS_DNSLIB else 'N/A'} | "
            f"HTTP port={self._enhanced_oob._http_port}")
    except Exception as _e:
        log("WARN", f"[EmbeddedCollaboratorServer] OOBServerEnhanced init failed: {_e}")
        self._enhanced_oob = None
    return port

_v19_orig_embedded_stop = EmbeddedCollaboratorServer.stop

def _v19_embedded_stop(self):
    """Stop enhanced OOB server alongside original."""
    if getattr(self, "_enhanced_oob", None):
        try:
            self._enhanced_oob.stop()
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
    _v19_orig_embedded_stop(self)

EmbeddedCollaboratorServer.start = _v19_embedded_start
