def _ip_in_cdn_ranges_v25(ip_str: str) -> str:
    """Return CDN name if IP matches known CDN ranges, else empty string."""
    try:
        ip = _ipaddress.ip_address(ip_str)
        for cdn_name, ranges in CDN_IP_RANGES_V25.items():
            for cidr in ranges:
                try:
                    if ip in _ipaddress.ip_network(cidr, strict=False):
                        return cdn_name
                except Exception:
                    continue
    except Exception as _silenced_exc:
        log("DEBUG", f"[suppressed] {_silenced_exc}")
    return ""


# ════════════════════════════════════════════════════════════════════════
#  M-25-01 — CDN DETECTION ENGINE
# ════════════════════════════════════════════════════════════════════════

class CDNDetectionEngine:
    """Detect CDN/WAF via DNS IP-range lookup, HTTP header fingerprinting, CNAME analysis."""

    CDN_HEADERS = {
        "cf-ray": "Cloudflare", "cf-cache-status": "Cloudflare",
        "x-served-by": "Fastly", "fastly-restarts": "Fastly",
        "x-amz-cf-id": "AWS CloudFront", "x-amz-cf-pop": "AWS CloudFront",
        "x-azure-ref": "Azure Front Door",
        "x-sucuri-id": "Sucuri", "x-iinfo": "Imperva Incapsula",
        "x-akamai-transformed": "Akamai", "akamai-gr-why": "Akamai",
        "x-cache": "Generic CDN", "via": "Proxy/CDN", "x-varnish": "Varnish CDN",
    }

    CNAME_CDN_PATTERNS = {
        r"cloudflare\.com": "Cloudflare", r"akamaiedge\.net": "Akamai",
        r"akamaitech\.net": "Akamai", r"edgesuite\.net": "Akamai",
        r"fastly\.net": "Fastly", r"cloudfront\.net": "AWS CloudFront",
        r"azureedge\.net": "Azure CDN", r"azurefd\.net": "Azure Front Door",
        r"incapdns\.net": "Imperva Incapsula", r"sucuri\.net": "Sucuri",
        r"stackpathcdn\.com": "StackPath", r"cdn77\.org": "CDN77",
    }

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse
        hostname = urlparse(target).hostname or ""
        if not hostname:
            return findings

        detected_cdns = set()
        evidence_parts = []

        try:
            ips = list({info[4][0] for info in _socket.getaddrinfo(hostname, None)})
            for ip in ips:
                cdn = _ip_in_cdn_ranges_v25(ip)
                if cdn:
                    detected_cdns.add(cdn)
                    evidence_parts.append(f"IP {ip} is in {cdn} range")
                else:
                    evidence_parts.append(f"IP {ip} — not in known CDN ranges (potential origin)")
        except Exception as e:
            evidence_parts.append(f"DNS lookup failed: {e}")

        try:
            resp = await client.get(target)
            if resp:
                hdr_lower = {k.lower(): v for k, v in resp.get("headers", {}).items()}
                for hdr_key, cdn_name in self.CDN_HEADERS.items():
                    if hdr_key in hdr_lower:
                        detected_cdns.add(cdn_name)
                        evidence_parts.append(f"Header '{hdr_key}: {hdr_lower[hdr_key][:60]}' -> {cdn_name}")
        except Exception as e:
            evidence_parts.append(f"HTTP header check failed: {e}")

        if _HAS_DNSPYTHON:
            try:
                answers = _dns_resolver.resolve(hostname, "CNAME")
                for rdata in answers:
                    cname_target = str(rdata.target).lower()
                    for pattern, cdn_name in self.CNAME_CDN_PATTERNS.items():
                        if re.search(pattern, cname_target):
                            detected_cdns.add(cdn_name)
                            evidence_parts.append(f"CNAME {hostname} -> {cname_target} -> {cdn_name}")
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        sev = "INFO"
        title = f"CDN/WAF Detected: {', '.join(sorted(detected_cdns))}" if detected_cdns else "No CDN/WAF Detected — Direct Origin Exposed"
        desc = (f"Target protected by: {', '.join(sorted(detected_cdns))}. Direct IP access may bypass WAF."
                if detected_cdns else "Target is NOT behind a CDN/WAF. Origin IP is directly exposed.")

        findings.append(Finding(
            plugin="cdn_detection",
            title=title, severity=sev, confidence=90.0,
            description=desc,
            evidence="\n".join(evidence_parts[:10]),
            url=target,
            remediation="Ensure origin server is not directly accessible. Use CDN IP allowlisting.",
            tags=["cdn", "waf", "bypass", "recon"],
        ))
        log("CDN", f"CDNDetectionEngine: {detected_cdns or 'no CDN'}")
        return findings


