#  M-25-02 — HISTORICAL DNS ENGINE
# ════════════════════════════════════════════════════════════════════════

class HistoricalDNSEngine:
    """Discover historical IPs via HackerTarget, AlienVault OTX, BufferOver."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse
        hostname = urlparse(target).hostname or ""
        if not hostname:
            return findings

        historical_ips = set()
        sources_used = []

        for url, parse_fn in [
            (f"https://api.hackertarget.com/hostsearch/?q={hostname}",
             lambda text: [l.split(",")[1].strip() for l in text.splitlines()
                           if len(l.split(",")) >= 2]),
            (f"https://otx.alienvault.com/api/v1/indicators/domain/{hostname}/passive_dns",
             lambda text: [e.get("address", "") for e in
                           (json.loads(text) if text.startswith("{") else {}).get("passive_dns", [])]),
        ]:
            try:
                resp = await client.get(url, headers={"Accept": "application/json"})
                if resp and resp.get("status") == 200:
                    text = resp.get("text", "") or ""
                    for ip in parse_fn(text):
                        try:
                            _ipaddress.ip_address(ip)
                            historical_ips.add(ip)
                        except Exception as _silenced_exc:
                            log("DEBUG", f"[suppressed] {_silenced_exc}")
                    src = "HackerTarget" if "hackertarget" in url else "AlienVault OTX"
                    if src not in sources_used:
                        sources_used.append(src)
            except Exception as e:
                log("DEBUG", f"[HistoricalDNS] {url[:40]}: {e}")

        if historical_ips:
            non_cdn = [ip for ip in historical_ips if not _ip_in_cdn_ranges_v25(ip)]
            cdn_ips = [f"{ip}({_ip_in_cdn_ranges_v25(ip)})" for ip in historical_ips
                       if _ip_in_cdn_ranges_v25(ip)]
            findings.append(Finding(
                plugin="historical_dns",
                title=f"Historical DNS — {len(historical_ips)} IPs Found",
                severity="HIGH" if non_cdn else "INFO",
                confidence=80.0,
                description=(f"Found {len(historical_ips)} historical IPs via {', '.join(sources_used)}. "
                             + (f"Non-CDN origin IPs: {', '.join(non_cdn[:5])}" if non_cdn else "")),
                evidence=f"Non-CDN: {', '.join(non_cdn)}\nCDN: {', '.join(cdn_ips[:8])}",
                url=target,
                remediation="Ensure historical origin IPs are not directly accessible. Use firewall allowlisting.",
                tags=["historical-dns", "cdn-bypass", "recon", "origin-ip"],
            ))
        log("DNS", f"HistoricalDNSEngine: {len(historical_ips)} IPs")
        return findings


