#  M-25-03 — SSL SAN IP EXTRACTOR
# ════════════════════════════════════════════════════════════════════════

class SSLSANIPExtractor:
    """Extract IPs from SSL certificate SANs using crt.sh and direct TLS inspection."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse
        hostname = urlparse(target).hostname or ""
        if not hostname:
            return findings

        san_ips = set()
        san_domains = set()
        certs_found = 0

        try:
            url = f"https://crt.sh/?q={hostname}&output=json"
            resp = await client.get(url, headers={"Accept": "application/json"})
            if resp and resp.get("status") == 200:
                data = resp.get("json", []) or []
                certs_found = len(data) if isinstance(data, list) else 0
                for entry in (data if isinstance(data, list) else []):
                    for name in (entry.get("name_value", "") or "").splitlines():
                        name = name.strip().lstrip("*.")
                        try:
                            _ipaddress.ip_address(name)
                            san_ips.add(name)
                        except Exception:
                            if name and "." in name:
                                san_domains.add(name)
        except Exception as e:
            log("DEBUG", f"[SSLSANIPExtractor] crt.sh: {e}")

        try:
            ctx = _ssl_v25.create_default_context()
            ctx.check_hostname = False
            ctx.verify_mode = _ssl_v25.CERT_NONE
            loop = asyncio.get_event_loop()

            def _get_cert():
                try:
                    sock = _socket.create_connection((hostname, 443), timeout=10)
                    ssl_sock = ctx.wrap_socket(sock, server_hostname=hostname)
                    cert = ssl_sock.getpeercert()
                    ssl_sock.close()
                    return cert
                except Exception:
                    return None

            cert = await asyncio.wait_for(loop.run_in_executor(None, _get_cert), timeout=15)
            if cert:
                for san_type, san_val in cert.get("subjectAltName", []):
                    if san_type == "IP Address":
                        san_ips.add(san_val)
                    elif san_type == "DNS":
                        san_domains.add(san_val.lstrip("*."))
        except Exception as e:
            log("DEBUG", f"[SSLSANIPExtractor] TLS: {e}")

        if san_ips:
            non_cdn = [ip for ip in san_ips if not _ip_in_cdn_ranges_v25(ip)]
            findings.append(Finding(
                plugin="ssl_san_ip_extractor",
                title=f"SSL SANs Contain {len(san_ips)} IP Address(es)",
                severity="HIGH" if non_cdn else "INFO",
                confidence=92.0,
                description=(f"SSL certificates for {hostname} contain {len(san_ips)} IP SANs "
                             f"from {certs_found} CT logs."
                             + (f" Non-CDN origin IPs: {', '.join(non_cdn)}" if non_cdn else "")),
                evidence=f"IP SANs: {', '.join(sorted(san_ips))}\nDomain SANs: {', '.join(list(san_domains)[:10])}",
                url=target,
                remediation="Do not include origin IPs in SSL certificate SANs. Use separate certificates for CDN and origin.",
                tags=["ssl", "san", "ip-leak", "cdn-bypass", "cert-transparency"],
            ))
        if san_domains:
            findings.append(Finding(
                plugin="ssl_san_domains",
                title=f"SSL Certificate Exposes {len(san_domains)} Domains",
                severity="INFO", confidence=90.0,
                description=f"Certificate transparency reveals {len(san_domains)} related domains.",
                evidence=f"Domains: {', '.join(list(san_domains)[:20])}",
                url=target,
                tags=["ssl", "san", "domain-enumeration"],
            ))
        log("SSL", f"SSLSANIPExtractor: {len(san_ips)} IPs, {len(san_domains)} domains")
        return findings


