#  M-25-04 — PASSIVE SUBDOMAIN ENGINE
# ════════════════════════════════════════════════════════════════════════

class PassiveSubdomainEngine:
    """Passive subdomain enumeration via crt.sh, HackerTarget, AlienVault OTX, Entrust CT."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse
        hostname = urlparse(target).hostname or ""
        parts = hostname.split(".")
        root_domain = ".".join(parts[-2:]) if len(parts) >= 2 else hostname

        subdomains = set()
        sources = []

        query_configs = [
            (f"https://crt.sh/?q=%.{root_domain}&output=json", "crt.sh",
             lambda data: [n.strip().lower().lstrip("*.")
                           for e in (data if isinstance(data, list) else [])
                           for n in (e.get("name_value", "") or "").splitlines()]),
            (f"https://api.hackertarget.com/hostsearch/?q={root_domain}", "HackerTarget",
             lambda data: [l.split(",")[0].strip().lower()
                           for l in (data if isinstance(data, str) else "").splitlines()
                           if l.strip()]),
        ]

        for url, source, extractor in query_configs:
            try:
                resp = await client.get(url, headers={"Accept": "application/json"})
                if resp and resp.get("status") == 200:
                    raw = resp.get("json") or resp.get("text") or ""
                    names = extractor(raw)
                    for name in names:
                        if name.endswith(root_domain) and name != root_domain:
                            subdomains.add(name)
                    sources.append(source)
            except Exception as e:
                log("DEBUG", f"[PassiveSubdomain] {source}: {e}")

        if subdomains:
            interesting = [s for s in subdomains if any(
                kw in s for kw in ["dev", "staging", "test", "admin", "api",
                                   "internal", "vpn", "mail", "old", "backup"]
            )]
            findings.append(Finding(
                plugin="passive_subdomain",
                title=f"Passive Subdomain Enumeration — {len(subdomains)} Subdomains",
                severity="INFO", confidence=88.0,
                description=(f"Discovered {len(subdomains)} subdomains for {root_domain} "
                             f"via {', '.join(sources)} (no API key required)."),
                evidence=f"Sources: {', '.join(sources)}\nSample: {', '.join(list(subdomains)[:20])}",
                url=target,
                remediation="Review subdomains for security misconfigurations. Protect staging/admin subdomains.",
                tags=["subdomain", "recon", "cert-transparency", "passive"],
            ))
            if interesting:
                findings.append(Finding(
                    plugin="passive_subdomain_interesting",
                    title=f"Sensitive Subdomains: {', '.join(interesting[:5])}",
                    severity="MEDIUM", confidence=72.0,
                    description=f"Found {len(interesting)} potentially sensitive subdomains.",
                    evidence=f"Sensitive: {', '.join(interesting)}",
                    url=target,
                    remediation="Restrict non-production subdomains with auth/IP allowlisting.",
                    tags=["subdomain", "sensitive", "dev-exposure"],
                ))
        log("RECON", f"PassiveSubdomainEngine: {len(subdomains)} subdomains")
        return findings


