#  M-25-05 — MX/SPF/DMARC IP EXTRACTOR
# ════════════════════════════════════════════════════════════════════════

class MXSPFDMARCIPExtractor:
    """Extract IPs from MX/SPF records and check DMARC policy."""

    SPF_IP4 = re.compile(r"ip4:([\d./]+)")
    SPF_IP6 = re.compile(r"ip6:([0-9a-fA-F:/]+)")

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse
        hostname = urlparse(target).hostname or ""
        parts = hostname.split(".")
        root_domain = ".".join(parts[-2:]) if len(parts) >= 2 else hostname

        if not _HAS_DNSPYTHON:
            log("SKIP", "[MXSPFDMARCIPExtractor] dnspython not available")
            return findings

        mx_ips, spf_ips, evidence = set(), set(), []

        try:
            for rdata in _dns_resolver.resolve(root_domain, "MX"):
                mx_host = str(rdata.exchange).rstrip(".")
                evidence.append(f"MX: {mx_host} (priority {rdata.preference})")
                try:
                    for info in _socket.getaddrinfo(mx_host, None):
                        mx_ips.add(info[4][0])
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        dmarc_policy = ""
        try:
            for rdata in _dns_resolver.resolve(root_domain, "TXT"):
                txt = "".join(str(rdata).replace('"', "").split())
                if txt.startswith("v=spf1"):
                    evidence.append(f"SPF: {txt[:200]}")
                    spf_ips.update(self.SPF_IP4.findall(txt))
                    spf_ips.update(self.SPF_IP6.findall(txt))
                if txt.startswith("v=DMARC1"):
                    dmarc_policy = txt
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        if not dmarc_policy:
            try:
                for rdata in _dns_resolver.resolve(f"_dmarc.{root_domain}", "TXT"):
                    txt = str(rdata).replace('"', "")
                    if "DMARC1" in txt:
                        dmarc_policy = txt
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        all_ips = mx_ips | spf_ips
        if all_ips:
            non_cdn = [ip for ip in all_ips if not _ip_in_cdn_ranges_v25(ip)]
            findings.append(Finding(
                plugin="mx_spf_dmarc",
                title=f"Email Infrastructure IPs: {len(all_ips)} addresses",
                severity="INFO", confidence=85.0,
                description=(f"Email infrastructure reveals {len(mx_ips)} MX IPs, {len(spf_ips)} SPF blocks. "
                             + (f"Non-CDN IPs: {', '.join(non_cdn[:5])}" if non_cdn else "")),
                evidence="\n".join(evidence[:15]),
                url=target,
                tags=["mx", "spf", "dmarc", "ip-discovery"],
            ))

        p_match = re.search(r"p=(none|quarantine|reject)", dmarc_policy, re.I)
        policy_val = p_match.group(1).lower() if p_match else "missing"
        if policy_val in ("none", "missing"):
            findings.append(Finding(
                plugin="dmarc_weak",
                title=f"DMARC Policy '{policy_val}' — Email Spoofing Possible",
                severity="MEDIUM", confidence=93.0,
                description=f"DMARC policy for {root_domain} is '{policy_val}'. Email spoofing is possible.",
                evidence=dmarc_policy or f"No DMARC record at _dmarc.{root_domain}",
                url=target,
                remediation="Set DMARC to p=reject. Add: _dmarc TXT \"v=DMARC1; p=reject; rua=mailto:dmarc@domain\"",
                tags=["dmarc", "email-spoofing", "misconfiguration"],
            ))
        log("DNS", f"MXSPFDMARCIPExtractor: {len(all_ips)} IPs, DMARC={policy_val}")
        return findings


