#  M-25-09 — DIRECT IP CONNECTOR
# ════════════════════════════════════════════════════════════════════════

class DirectIPConnector:
    """Connect to origin IP with Host header to bypass CDN/WAF."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse, urlunparse
        parsed = urlparse(target)
        hostname = parsed.hostname or ""

        candidate_ips = set()
        try:
            for info in _socket.getaddrinfo(hostname, None, _socket.AF_INET):
                candidate_ips.add(info[4][0])
        except Exception:
            return findings

        non_cdn_ips = [ip for ip in candidate_ips if not _ip_in_cdn_ranges_v25(ip)]

        for ip in non_cdn_ips[:5]:
            for port, is_https in [(443, True), (80, False), (8443, True), (8080, False)]:
                direct_url = f"{'https' if is_https else 'http'}://{ip}:{port}{parsed.path or '/'}"
                try:
                    resp = await client.get(direct_url, headers={"Host": hostname})
                    if resp and resp.get("status", 0) in range(200, 500):
                        findings.append(Finding(
                            plugin="direct_ip_bypass",
                            title=f"CDN Bypass Confirmed — Direct Origin at {ip}:{port}",
                            severity="HIGH", confidence=88.0,
                            description=(f"Direct connection to {ip}:{port} with Host:{hostname} "
                                        f"returned HTTP {resp.get('status')}, bypassing CDN/WAF entirely."),
                            evidence=f"URL: {direct_url}\nHost: {hostname}\nStatus: {resp.get('status')}",
                            url=direct_url,
                            remediation="Allow only CDN IP ranges at origin firewall. Use CDN origin auth tokens.",
                            tags=["cdn-bypass", "origin-exposure", "waf-bypass", "host-header"],
                        ))
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
        log("BYPASS", f"DirectIPConnector: {len(findings)} bypasses")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  M-25-10 — RESPONSE FINGERPRINT MATCHER
# ════════════════════════════════════════════════════════════════════════

class ResponseFingerprintMatcher:
    """Compare CDN vs direct IP responses to confirm bypass validity."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse
        parsed = urlparse(target)
        hostname = parsed.hostname or ""

        try:
            cdn_resp = await client.get(target)
            if not cdn_resp:
                return findings
            cdn_body = cdn_resp.get("text", "") or ""
            cdn_title = re.search(r"<title[^>]*>(.*?)</title>", cdn_body, re.I | re.S)
            cdn_title = cdn_title.group(1).strip() if cdn_title else ""
        except Exception:
            return findings

        try:
            ip = _socket.gethostbyname(hostname)
        except Exception:
            return findings

        if not _ip_in_cdn_ranges_v25(ip):
            return findings  # Already direct access

        for port in [80, 8080]:
            direct_url = f"http://{ip}:{port}{parsed.path or '/'}"
            try:
                resp = await client.get(direct_url, headers={"Host": hostname})
                if not resp:
                    continue
                direct_body = resp.get("text", "") or ""
                direct_title = re.search(r"<title[^>]*>(.*?)</title>", direct_body, re.I | re.S)
                direct_title = direct_title.group(1).strip() if direct_title else ""
                cdn_words = set(cdn_body[:500].split())
                direct_words = set(direct_body[:500].split())
                similarity = len(cdn_words & direct_words) / max(len(cdn_words), 1)
                if (cdn_title and cdn_title == direct_title) or similarity > 0.7:
                    findings.append(Finding(
                        plugin="response_fingerprint_match",
                        title=f"Origin Confirmed at {ip}:{port} ({similarity:.0%} similarity)",
                        severity="HIGH", confidence=91.0,
                        description=(f"Response from {ip}:{port} matches CDN response ({similarity:.0%} similarity"
                                     + (", title match" if cdn_title == direct_title else "") + "). Origin confirmed."),
                        evidence=f"CDN title: '{cdn_title}'\nDirect URL: {direct_url}\nSimilarity: {similarity:.0%}",
                        url=direct_url,
                        remediation="Block HTTP on port 80 at origin. Use HTTPS with CDN auth.",
                        tags=["response-match", "cdn-bypass", "origin-confirmed"],
                    ))
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        log("MATCH", f"ResponseFingerprintMatcher: {len(findings)} confirmed")
        return findings


