#  M-25-11 — CDN PROVIDER FINGERPRINTER
# ════════════════════════════════════════════════════════════════════════

class CDNProviderFingerprinter:
    """Deep CDN/WAF provider fingerprinting with provider-specific bypass hints."""

    FINGERPRINTS = {
        "Akamai": {
            "headers": ["x-check-cacheable", "x-akamai-transformed", "x-serial"],
            "bypass": ["HTTP/2 to bypass HTTP/1.1-specific WAF rules",
                       "Fragment requests with Range headers",
                       "Use X-Forwarded-For: 127.0.0.1 to spoof trusted IP"],
        },
        "Fastly": {
            "headers": ["x-served-by", "fastly-restarts", "x-timer", "fastly-debug-digest"],
            "bypass": ["Vary cache via X-Forwarded-Host", "Use HEAD to probe origin",
                       "Exploit Fastly VCL edge dictionaries"],
        },
        "AWS CloudFront": {
            "headers": ["x-amz-cf-id", "x-amz-cf-pop"],
            "bypass": ["Direct S3 bucket access if misconfigured",
                       "X-Forwarded-For header injection",
                       "Lambda@Edge function URL if exposed"],
        },
        "Imperva Incapsula": {
            "headers": ["x-iinfo", "incap-session-id"],
            "cookies": ["incap_ses_", "visid_incap_"],
            "bypass": ["Residential proxy IP bypass", "Slow request rate"],
        },
        "Sucuri": {
            "headers": ["x-sucuri-id", "x-sucuri-cache"],
            "bypass": ["Direct origin IP (Sucuri does not change origin IP)",
                       "Use --historical-dns to find pre-Sucuri IPs"],
        },
    }

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        try:
            resp = await client.get(target)
            if not resp:
                return findings
            hdrs = {k.lower(): v for k, v in resp.get("headers", {}).items()}
            cookies_raw = str(hdrs.get("set-cookie", ""))
        except Exception as e:
            log("DEBUG", f"[CDNFingerprint] {e}")
            return findings

        for provider, fp in self.FINGERPRINTS.items():
            score = 0
            evidence_parts = []
            for hdr in fp.get("headers", []):
                if hdr.lower() in hdrs:
                    score += 2
                    evidence_parts.append(f"Header: {hdr}={hdrs[hdr.lower()][:60]}")
            for cookie in fp.get("cookies", []):
                if cookie.lower() in cookies_raw.lower():
                    score += 2
                    evidence_parts.append(f"Cookie: {cookie}")
            if score >= 2:
                findings.append(Finding(
                    plugin="cdn_provider_fingerprint",
                    title=f"CDN/WAF Identified: {provider}",
                    severity="INFO", confidence=min(50 + score * 10, 95.0),
                    description=(f"Provider: {provider}. Known bypass techniques:\n"
                                 + "\n".join(f"  - {b}" for b in fp.get("bypass", []))),
                    evidence="\n".join(evidence_parts),
                    url=target,
                    tags=["cdn", "fingerprint", provider.lower().replace(" ", "-")],
                ))
        log("CDN", f"CDNProviderFingerprinter: {[f.title for f in findings]}")
        return findings


