#  M-25-12 — HTTP/2 CDN BYPASS
# ════════════════════════════════════════════════════════════════════════

class HTTP2CDNBypass:
    """Identify WAF-blocked patterns that may bypass via HTTP/2 protocol differences."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse
        hostname = urlparse(target).hostname or ""
        blocked_patterns = []

        for vuln_type, payload in [
            ("SQLi", "' OR '1'='1"), ("XSS", "<script>alert(1)</script>"),
            ("Path Traversal", "../../../etc/passwd"), ("SSTI", "{{7*7}}"),
        ]:
            test_url = f"{target}{'?' if '?' not in target else '&'}waf_test={payload}"
            try:
                r = await client.get(test_url)
                if r:
                    status = r.get("status", 200)
                    body = r.get("text", "") or ""
                    waf_blocked = (status in (403, 406, 429, 503) or
                                   any(kw in body.lower() for kw in
                                       ["access denied", "blocked", "firewall", "waf", "forbidden"]))
                    if waf_blocked:
                        blocked_patterns.append((vuln_type, status))
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        if blocked_patterns:
            findings.append(Finding(
                plugin="http2_cdn_bypass",
                title=f"WAF Blocks {len(blocked_patterns)} Patterns — Test HTTP/2 Bypass",
                severity="INFO", confidence=65.0,
                description=(f"WAF blocks {', '.join(t for t,_ in blocked_patterns)} in HTTP/1.1. "
                             f"Test same payloads via HTTP/2 — some WAFs have inconsistent H2 rule coverage.\n"
                             f"Test: curl --http2 '{target}?test=<payload>'"),
                evidence=f"Blocked: {blocked_patterns}",
                url=target,
                remediation="Ensure WAF rules apply consistently to HTTP/1.1 and HTTP/2 traffic.",
                tags=["http2", "waf-bypass", "protocol"],
            ))
        log("H2", f"HTTP2CDNBypass: {len(blocked_patterns)} blocked patterns")
        return findings


