#  M-25-13 — WEBSOCKET CDN BYPASS
# ════════════════════════════════════════════════════════════════════════

class WebSocketCDNBypass:
    """Test if WebSocket upgrade requests bypass WAF/CDN filtering."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse, urlunparse
        parsed = urlparse(target)
        hostname = parsed.hostname or ""
        ws_scheme = "wss" if parsed.scheme == "https" else "ws"
        ws_url = urlunparse(parsed._replace(scheme=ws_scheme))

        try:
            import websockets
            try:
                async with websockets.connect(
                    ws_url,
                    additional_headers={
                        "X-Forwarded-For": "127.0.0.1",
                        "Origin": f"https://{hostname}",
                    },
                    open_timeout=8, close_timeout=5,
                ) as ws:
                    await ws.send('{"action":"test","data":"<script>alert(1)</script>"}')
                    try:
                        response = await asyncio.wait_for(ws.recv(), timeout=5)
                        if "<script>" in str(response):
                            findings.append(Finding(
                                plugin="websocket_waf_bypass",
                                title="WebSocket Bypasses WAF — XSS Reflected",
                                severity="HIGH", confidence=85.0,
                                description="WebSocket channel passes XSS payload through WAF without sanitization.",
                                evidence=f"WS URL: {ws_url}\nReceived: {str(response)[:200]}",
                                url=ws_url,
                                remediation="Apply message-level filtering to WebSocket connections.",
                                tags=["websocket", "cdn-bypass", "xss"],
                            ))
                    except asyncio.TimeoutError:
                        pass
                findings.append(Finding(
                    plugin="websocket_cdn_info",
                    title="WebSocket Connection Accepted — CDN Passes WS Traffic",
                    severity="INFO", confidence=80.0,
                    description="CDN/WAF passes WebSocket traffic. WS message inspection may be limited.",
                    evidence=f"WS URL: {ws_url}",
                    url=ws_url,
                    tags=["websocket", "cdn", "waf"],
                ))
            except Exception as e:
                log("DEBUG", f"[WSCDNBypass] {e}")
        except ImportError:
            log("SKIP", "[WebSocketCDNBypass] websockets not available")
        log("WS", f"WebSocketCDNBypass: {len(findings)} findings")
        return findings


