#  M-25-14 — BEHAVIORAL ANALYSIS ENGINE
# ════════════════════════════════════════════════════════════════════════

class BehavioralAnalysisEngine:
    """Detect cache poisoning, host injection, backend rotation, rate limits."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse
        hostname = urlparse(target).hostname or ""

        # Backend rotation
        server_ids = set()
        for _ in range(5):
            try:
                resp = await client.get(target)
                if resp:
                    hdrs = {k.lower(): v for k, v in resp.get("headers", {}).items()}
                    for hdr in ["via", "server", "x-served-by", "x-cache"]:
                        if hdr in hdrs:
                            server_ids.add(f"{hdr}:{hdrs[hdr]}")
                await asyncio.sleep(0.2)
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        if len(server_ids) > 1:
            findings.append(Finding(
                plugin="backend_rotation",
                title=f"Multiple Backends Detected ({len(server_ids)} signatures)",
                severity="INFO", confidence=80.0,
                description="Load balancer rotates between multiple backend servers. Stateful attacks may be inconsistent.",
                evidence=f"Unique server signatures:\n" + "\n".join(sorted(server_ids)),
                url=target,
                remediation="Ensure consistent security configuration across all backend servers.",
                tags=["load-balancer", "backend-rotation"],
            ))

        # Cache poisoning via X-Forwarded-Host
        try:
            poison_val = f"evil-{int(time.time())}.attacker.com"
            resp = await client.get(target, headers={"X-Forwarded-Host": poison_val})
            if resp and poison_val in (resp.get("text", "") or ""):
                findings.append(Finding(
                    plugin="cache_poisoning",
                    title="Web Cache Poisoning via X-Forwarded-Host",
                    severity="HIGH", confidence=90.0,
                    description=f"X-Forwarded-Host ({poison_val!r}) reflected in response body — cache poisoning possible.",
                    evidence=f"Header: X-Forwarded-Host: {poison_val}\nReflected: YES",
                    url=target,
                    remediation="Validate X-Forwarded-Host against allowlist. Strip unknown forwarding headers at CDN.",
                    tags=["cache-poisoning", "header-injection"],
                ))
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        # Host header injection
        try:
            fake_host = f"attacker-{int(time.time())}.evil.com"
            resp = await client.get(target, headers={"Host": fake_host})
            if resp:
                body = resp.get("text", "") or ""
                location = resp.get("headers", {}).get("location", "") or ""
                if fake_host in body or fake_host in location:
                    findings.append(Finding(
                        plugin="host_header_injection",
                        title="Host Header Injection — Reflected in Response",
                        severity="HIGH", confidence=87.0,
                        description=f"Arbitrary Host ({fake_host!r}) reflected in response. Enables password-reset poisoning and cache poisoning.",
                        evidence=f"Host: {fake_host}\nIn body: {fake_host in body}\nIn redirect: {fake_host in location}",
                        url=target,
                        remediation="Validate Host header against strict allowlist.",
                        tags=["host-header", "injection", "cache-poisoning"],
                    ))
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        log("BEHAV", f"BehavioralAnalysisEngine: {len(findings)} findings")
        return findings


