#  M-25-15 — USE-AFTER-FREE SCANNER
# ════════════════════════════════════════════════════════════════════════

class UseAfterFreeScanner:
    """Detect memory corruption indicators in web application responses."""

    MEMORY_PATTERNS = [
        (r"0x[0-9a-fA-F]{8,16}", "Memory address leak"),
        (r"\bSEGV\b|\bSIGSEGV\b", "Segmentation fault"),
        (r"core dumped", "Core dump reference"),
        (r"use.?after.?free", "UAF mention in error"),
        (r"heap.?corrup", "Heap corruption"),
        (r"double.?free", "Double free error"),
        (r"buffer.?overf", "Buffer overflow"),
        (r"null.?pointer.?deref", "Null pointer dereference"),
        (r"out of memory|Cannot allocate memory", "Memory exhaustion"),
    ]

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        try:
            resp = await client.get(f"{target}?data={'A' * 1000}")
            if not resp:
                return findings
            body = resp.get("text", "") or ""
            for pattern, description in self.MEMORY_PATTERNS:
                match = re.search(pattern, body, re.I)
                if match:
                    findings.append(Finding(
                        plugin="uaf_memory_corruption",
                        title=f"Memory Corruption Indicator: {description}",
                        severity="CRITICAL", confidence=78.0,
                        description=f"Response contains '{description}' pattern suggesting memory safety vulnerability.",
                        evidence=f"Pattern: {pattern}\nMatch: {match.group(0)}\nContext: {body[max(0,match.start()-80):match.end()+80]}",
                        url=target,
                        remediation="Review memory management. Enable ASLR, stack canaries, safe allocators.",
                        tags=["uaf", "memory-corruption", "critical"],
                    ))

            # WebAssembly detection
            wasm_urls = re.findall(r'["\']([^"\']*\.wasm)["\']', body)
            if wasm_urls:
                findings.append(Finding(
                    plugin="wasm_detected",
                    title=f"WebAssembly Modules Found — Memory Safety Risk",
                    severity="INFO", confidence=70.0,
                    description=f"Found {len(wasm_urls)} WASM module(s). May contain memory safety issues if compiled from C/C++.",
                    evidence=f"WASM: {wasm_urls[:5]}",
                    url=target,
                    tags=["wasm", "memory-safety"],
                ))
        except Exception as e:
            log("DEBUG", f"[UAFScanner] {e}")
        log("UAF", f"UseAfterFreeScanner: {len(findings)} findings")
        return findings


