#  M-25-16 — ADVANCED RACE CONDITION V2
# ════════════════════════════════════════════════════════════════════════

class AdvancedRaceConditionV2:
    """Race condition testing via concurrent burst requests on common endpoints."""

    RACE_PATHS = ["/api/checkout", "/api/order", "/api/coupon/apply",
                  "/api/transfer", "/api/vote", "/account/password-reset"]

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse, urljoin
        parsed = urlparse(target)
        base = f"{parsed.scheme}://{parsed.netloc}"

        for path in self.RACE_PATHS:
            race_url = urljoin(base, path)
            try:
                probe = await client.get(race_url)
                if not probe or probe.get("status", 404) == 404:
                    continue

                results = await asyncio.gather(
                    *[client.post(race_url, data=json.dumps({"race": "probe"}),
                                  headers={"Content-Type": "application/json"})
                      for _ in range(15)],
                    return_exceptions=True
                )
                valid = [r for r in results if isinstance(r, dict) and r]
                success_count = sum(1 for r in valid if r.get("status", 0) in (200, 201, 302))

                if success_count > 1:
                    findings.append(Finding(
                        plugin="race_condition_v2",
                        title=f"Race Condition — {success_count} Concurrent Successes at {race_url}",
                        severity="HIGH", confidence=80.0,
                        description=(f"{success_count} of 15 concurrent requests succeeded at {race_url}. "
                                     "Suggests non-atomic operation vulnerable to race condition (double-spend, limit bypass)."),
                        evidence=f"Concurrent: 15\nSuccesses: {success_count}\nStatuses: {sorted({r.get('status') for r in valid})}",
                        url=race_url,
                        remediation="Use DB-level locking (SELECT FOR UPDATE). Add idempotency keys. Rate-limit per user.",
                        tags=["race-condition", "toctou", "business-logic"],
                    ))
            except Exception as e:
                log("DEBUG", f"[RaceV2] {race_url}: {e}")
        log("RACE", f"AdvancedRaceConditionV2: {len(findings)} findings")
        return findings


