#  M-25-17 — YARA INTEGRATION ENGINE
# ════════════════════════════════════════════════════════════════════════

class YARAIntegrationEngine:
    """Apply YARA rules and built-in patterns to HTTP responses."""

    BUILTIN_PATTERNS = {
        "Credit Card": r"\b(?:4[0-9]{12}(?:[0-9]{3})?|5[1-5][0-9]{14}|3[47][0-9]{13})\b",
        "AWS Access Key": r"\bAKIA[0-9A-Z]{16}\b",
        "Private Key": r"-----BEGIN (?:RSA |EC )?PRIVATE KEY-----",
        "GitHub Token": r"\bghp_[a-zA-Z0-9]{36}\b",
        "JWT Token": r"eyJ[a-zA-Z0-9_-]+\.eyJ[a-zA-Z0-9_-]+\.[a-zA-Z0-9_-]+",
        "PHP Webshell": r"(?i)eval\s*\(\s*(?:base64_decode|gzinflate|str_rot13)\s*\(",
        "Database Credentials": r"(?i)(?:password|passwd)\s*[=:]\s*['\"][^'\"]{6,}['\"]",
        "Internal IP": r"\b(?:10\.\d{1,3}\.\d{1,3}\.\d{1,3}|192\.168\.\d{1,3}\.\d{1,3})\b",
        "Path Traversal Success": r"root:x:0:0:|daemon:",
        "SQL Error": r"(?i)(?:ORA-\d{5}|mysql_fetch|You have an error in your SQL)",
        "API Key Leak": r"(?i)(?:api[_-]?key|apikey)\s*[=:]\s*['\"]?([a-zA-Z0-9_\-]{20,})",
        "Eth Private Key": r"(?:0x)?[0-9a-fA-F]{64}(?:\s|$|[\"'])",
    }

    YARA_SRC = """
rule WebShell { strings: $s1="eval(base64_decode" nocase $s2="system($_GET" nocase
    $s3="passthru($_POST" nocase condition: any of them }
rule Credentials { strings: $s1=/AKIA[0-9A-Z]{16}/ $s2=/-----BEGIN RSA PRIVATE KEY-----/
    $s3=/ghp_[a-zA-Z0-9]{36}/ condition: any of them }
"""

    def __init__(self):
        self._compiled = None
        if _HAS_YARA:
            try:
                self._compiled = _yara.compile(source=self.YARA_SRC)
            except Exception as e:
                log("WARN", f"[YARA] Compile error: {e}")

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        try:
            resp = await client.get(target)
            if not resp:
                return findings
            body = resp.get("text", "") or ""
        except Exception:
            return findings

        matches = []
        if self._compiled and _HAS_YARA:
            try:
                for m in self._compiled.match(data=body.encode("utf-8", errors="replace")):
                    matches.append({"rule": m.rule, "source": "YARA"})
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        for name, pattern in self.BUILTIN_PATTERNS.items():
            m = re.search(pattern, body)
            if m:
                val = m.group(0)
                if any(k in name for k in ["Key", "Credential", "Card", "Token"]):
                    val = val[:6] + "***"
                matches.append({"rule": name, "match": val, "source": "Builtin"})

        for m in matches:
            rule = m.get("rule", "")
            is_crit = any(k in rule for k in ["Webshell", "Private Key", "Credit", "AWS"])
            findings.append(Finding(
                plugin="yara_match",
                title=f"{'[CRITICAL] ' if is_crit else ''}Pattern Match: {rule}",
                severity="CRITICAL" if is_crit else "HIGH",
                confidence=88.0 if m.get("source") == "YARA" else 80.0,
                description=f"Pattern '{rule}' matched in HTTP response. May indicate credentials, webshell, or sensitive data exposure.",
                evidence=f"Rule: {rule}\nMatch: {m.get('match','')}\nSource: {m.get('source')}",
                url=target,
                remediation="Investigate match immediately. Rotate credentials if exposed. Remove webshells.",
                tags=["yara", "sensitive-data", rule.lower().replace(" ", "-")],
            ))
        log("YARA", f"YARAIntegrationEngine: {len(matches)} matches")
        return findings


