#  M-25-18 — OAUTH2/SAML DEEP SCANNER
# ════════════════════════════════════════════════════════════════════════

class OAuth2SAMLDeepScanner:
    """Deep OAuth2/SAML analysis: open redirect, missing state, JWT confusion."""

    OAUTH_PATHS = [
        "/oauth/authorize", "/oauth2/authorize", "/.well-known/openid-configuration",
        "/oauth/token", "/oauth2/token", "/saml/sso", "/saml2/sso",
        "/.auth/login", "/connect/authorize",
    ]

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse, urljoin
        parsed = urlparse(target)
        base = f"{parsed.scheme}://{parsed.netloc}"

        oauth_endpoints = []
        for path in self.OAUTH_PATHS:
            url = urljoin(base, path)
            try:
                resp = await client.get(url)
                if resp and resp.get("status", 404) not in (404, 405):
                    oauth_endpoints.append(url)
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        for ep in oauth_endpoints:
            # Open redirect test
            for redirect_uri in ["https://evil.com", f"https://{parsed.netloc}@evil.com"]:
                try:
                    test_url = f"{ep}?response_type=code&client_id=test&redirect_uri={redirect_uri}&state=x&scope=openid"
                    resp = await client.get(test_url)
                    if resp:
                        location = resp.get("headers", {}).get("location", "") or ""
                        if resp.get("status") in (301, 302, 307) and "evil.com" in location:
                            findings.append(Finding(
                                plugin="oauth2_open_redirect",
                                title="OAuth2 Open Redirect in redirect_uri",
                                severity="HIGH", confidence=88.0,
                                description=f"OAuth2 endpoint {ep} accepts arbitrary redirect_uri and redirects to: {location}",
                                evidence=f"Probe redirect_uri: {redirect_uri}\nRedirected to: {location}",
                                url=test_url,
                                remediation="Validate redirect_uri against strict allowlist. Use exact string matching.",
                                tags=["oauth2", "open-redirect", "token-theft"],
                            ))
                            break
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
            # Missing state
            try:
                test_url = f"{ep}?response_type=code&client_id=test&redirect_uri={base}&scope=openid"
                resp = await client.get(test_url)
                if resp and resp.get("status", 404) not in (404, 400, 405):
                    if "state" not in (resp.get("text", "") or "").lower():
                        findings.append(Finding(
                            plugin="oauth2_csrf",
                            title="OAuth2 Missing State Parameter — CSRF Risk",
                            severity="MEDIUM", confidence=72.0,
                            description=f"OAuth2 endpoint {ep} accepts requests without 'state'. OAuth CSRF attacks possible.",
                            evidence=f"Request without state returned HTTP {resp.get('status')}",
                            url=test_url,
                            remediation="Generate cryptographically random state per request. Use PKCE additionally.",
                            tags=["oauth2", "csrf", "state-missing"],
                        ))
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        # JWT algorithm confusion check
        try:
            resp = await client.get(target)
            if resp:
                body = (resp.get("text", "") or "") + str(resp.get("headers", {}))
                jwts = re.findall(r"eyJ[a-zA-Z0-9_-]+\.eyJ[a-zA-Z0-9_-]+\.[a-zA-Z0-9_-]*", body)
                for jwt_token in jwts[:3]:
                    try:
                        hdr_json = json.loads(
                            _b64.urlsafe_b64decode(jwt_token.split(".")[0] + "==").decode("utf-8", errors="replace")
                        )
                        alg = hdr_json.get("alg", "")
                        if alg.lower() == "none":
                            findings.append(Finding(
                                plugin="jwt_none_alg",
                                title="JWT with 'alg:none' — Signature Bypass!",
                                severity="CRITICAL", confidence=95.0,
                                description="JWT using 'alg:none' means signature is not verified. Attacker can forge tokens.",
                                evidence=f"JWT header: {json.dumps(hdr_json)}\nToken: {jwt_token[:80]}",
                                url=target,
                                remediation="Always require a valid signature algorithm. Reject 'alg:none'.",
                                tags=["jwt", "no-signature", "auth-bypass"],
                            ))
                        elif alg.upper() in ("RS256", "RS384", "RS512", "ES256"):
                            findings.append(Finding(
                                plugin="jwt_algo_confusion",
                                title=f"JWT Asymmetric Algorithm ({alg}) — Algorithm Confusion Risk",
                                severity="MEDIUM", confidence=75.0,
                                description=f"JWT using {alg}. Test RS256->HS256 downgrade using the public key as HMAC secret.",
                                evidence=f"Header: {json.dumps(hdr_json)}\nToken: {jwt_token[:80]}",
                                url=target,
                                remediation="Explicitly whitelist expected algorithm. Never accept 'alg:none'.",
                                tags=["jwt", "algorithm-confusion"],
                            ))
                    except Exception as _silenced_exc:
                        log("DEBUG", f"[suppressed] {_silenced_exc}")
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        log("AUTH", f"OAuth2SAMLDeepScanner: {len(oauth_endpoints)} endpoints, {len(findings)} findings")
        return findings


