#  M-25-19 — WEBSOCKET SECURITY DEEP
# ════════════════════════════════════════════════════════════════════════

class WebSocketSecurityDeep:
    """Deep WebSocket security: CSWSH, insecure ws://, subprotocol abuse."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse, urlunparse
        parsed = urlparse(target)
        hostname = parsed.hostname or ""

        ws_endpoints = []
        try:
            resp = await client.get(target)
            if resp:
                body = resp.get("text", "") or ""
                ws_endpoints = re.findall(r'["\']?(wss?://[^\s\'"<>]+)["\']?', body, re.I)[:10]
                if parsed.scheme == "https":
                    insecure = [u for u in ws_endpoints if u.startswith("ws://")]
                    if insecure:
                        findings.append(Finding(
                            plugin="insecure_websocket",
                            title=f"Insecure ws:// on HTTPS Page ({len(insecure)} endpoints)",
                            severity="HIGH", confidence=95.0,
                            description="HTTPS page loads WebSocket over insecure ws:// — traffic is interception-vulnerable.",
                            evidence=f"Insecure WS: {insecure[:5]}",
                            url=target,
                            remediation="Always use wss:// on HTTPS pages.",
                            tags=["websocket", "insecure", "mixed-content"],
                        ))
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        # CSWSH test
        if ws_endpoints:
            ws_url = ws_endpoints[0]
            try:
                import websockets
                try:
                    async with websockets.connect(
                        ws_url,
                        additional_headers={"Origin": "https://evil-attacker.com"},
                        open_timeout=8, close_timeout=5,
                    ):
                        findings.append(Finding(
                            plugin="cswsh",
                            title="Cross-Site WebSocket Hijacking — Origin Not Validated",
                            severity="HIGH", confidence=87.0,
                            description=f"WS at {ws_url} accepted connection with arbitrary Origin (https://evil-attacker.com). CSWSH possible.",
                            evidence=f"WS URL: {ws_url}\nTest Origin: https://evil-attacker.com\nResult: accepted",
                            url=ws_url,
                            remediation="Validate Origin header against allowlist. Require WS auth tokens.",
                            tags=["websocket", "cswsh", "csrf"],
                        ))
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
            except ImportError:
                pass

        log("WS", f"WebSocketSecurityDeep: {len(findings)} findings")
        return findings


