#  M-25-21 — GRAPHQL INTROSPECTION DEEP
# ════════════════════════════════════════════════════════════════════════

class GraphQLIntrospectionDeep:
    """GraphQL introspection, batch DoS, and injection testing."""

    GQL_PATHS = ["/graphql", "/api/graphql", "/graphql/v1", "/v1/graphql",
                 "/gql", "/query", "/graphiql", "/playground"]
    INTRO_QUERY = '{"query": "{ __schema { types { name } } }"}'
    BATCH_QUERY = json.dumps([{"query": "{ __typename }"}] * 100)

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse, urljoin
        base = f"{urlparse(target).scheme}://{urlparse(target).netloc}"

        endpoints = []
        for path in self.GQL_PATHS:
            url = urljoin(base, path)
            try:
                resp = await client.post(url, data='{"query":"{ __typename }"}',
                                         headers={"Content-Type": "application/json"})
                if resp and resp.get("status", 404) not in (404, 405):
                    body = resp.get("text", "") or ""
                    if "__typename" in body or '"data"' in body or '"errors"' in body:
                        endpoints.append(url)
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        for gql_url in endpoints:
            # Introspection
            try:
                resp = await client.post(gql_url, data=self.INTRO_QUERY,
                                         headers={"Content-Type": "application/json"})
                if resp and resp.get("status") == 200:
                    data = resp.get("json") or {}
                    if "__schema" in (resp.get("text") or "") or data.get("data", {}).get("__schema"):
                        types_count = len(data.get("data", {}).get("__schema", {}).get("types", []))
                        findings.append(Finding(
                            plugin="graphql_introspection",
                            title=f"GraphQL Introspection Enabled ({types_count} types exposed)",
                            severity="MEDIUM", confidence=95.0,
                            description=f"Full GraphQL schema exposed at {gql_url} — all types, mutations, queries visible to attackers.",
                            evidence=f"Types: {types_count}\nEndpoint: {gql_url}",
                            url=gql_url,
                            remediation="Disable introspection in production. Use query depth/complexity limits.",
                            tags=["graphql", "introspection", "schema-exposure"],
                        ))
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
            # Batch DoS
            try:
                t0 = time.monotonic()
                resp = await client.post(gql_url, data=self.BATCH_QUERY,
                                         headers={"Content-Type": "application/json"})
                elapsed = time.monotonic() - t0
                if resp and resp.get("status") == 200 and elapsed > 2.0:
                    findings.append(Finding(
                        plugin="graphql_batch_dos",
                        title=f"GraphQL Batch Query DoS ({elapsed:.1f}s for 100 queries)",
                        severity="MEDIUM", confidence=78.0,
                        description=f"100 batched queries took {elapsed:.1f}s — DoS via query amplification possible.",
                        evidence=f"Batch: 100 queries\nTime: {elapsed:.1f}s",
                        url=gql_url,
                        remediation="Limit batch sizes. Implement query rate limiting and complexity analysis.",
                        tags=["graphql", "batch-query", "dos"],
                    ))
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
            # SQLi via GraphQL
            for sqli in ['{"query":"{ user(id: \\"1 OR 1=1--\\") { id } }"}']:
                try:
                    resp = await client.post(gql_url, data=sqli,
                                             headers={"Content-Type": "application/json"})
                    if resp and re.search(r"(SQL|syntax|database|ORA-|mysql_)", resp.get("text", "") or "", re.I):
                        findings.append(Finding(
                            plugin="graphql_sqli",
                            title="GraphQL SQL Injection",
                            severity="CRITICAL", confidence=82.0,
                            description="GraphQL arguments passed unsanitized to SQL. SQL error triggered.",
                            evidence=f"Payload: {sqli[:100]}\nError: {(resp.get('text',''))[:200]}",
                            url=gql_url,
                            remediation="Use parameterized queries. Sanitize all GraphQL arguments.",
                            tags=["graphql", "sqli", "critical"],
                        ))
                        break
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
        log("GQL", f"GraphQLIntrospectionDeep: {len(endpoints)} endpoints, {len(findings)} findings")
        return findings


