#  M-25-22 — CLOUD MISCONFIGURATION SCANNER
# ════════════════════════════════════════════════════════════════════════

class CloudMisconfigScanner:
    """Detect exposed S3 buckets, Azure blobs, GCP buckets, Firebase, and config files."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse, urljoin
        parsed = urlparse(target)
        hostname = parsed.hostname or ""
        parts = hostname.split(".")
        root_domain = ".".join(parts[-2:]) if len(parts) >= 2 else hostname
        prefix = parts[0] if len(parts) >= 3 else root_domain.split(".")[0]

        bucket_names = [root_domain, hostname, prefix,
                        f"{prefix}-backup", f"{prefix}-static", f"{prefix}-assets",
                        f"{prefix}-uploads", f"{prefix}-prod", f"{prefix}-staging"]

        for bucket in bucket_names[:6]:
            for s3_url in [f"https://{bucket}.s3.amazonaws.com/",
                           f"https://s3.amazonaws.com/{bucket}/"]:
                try:
                    resp = await client.get(s3_url)
                    if resp:
                        status = resp.get("status", 0)
                        body = resp.get("text", "") or ""
                        if status == 200 and "ListBucketResult" in body:
                            findings.append(Finding(
                                plugin="s3_public_listing",
                                title=f"S3 Bucket Publicly Listed: {bucket}",
                                severity="CRITICAL", confidence=95.0,
                                description=f"S3 bucket '{bucket}' allows public listing — all files accessible.",
                                evidence=f"URL: {s3_url}\nListing: {body[:300]}",
                                url=s3_url,
                                remediation="Remove public-read ACL. Enable S3 Block Public Access.",
                                tags=["s3", "bucket-exposure", "critical"],
                            ))
                        elif status == 403:
                            findings.append(Finding(
                                plugin="s3_bucket_exists",
                                title=f"S3 Bucket Exists (Private): {bucket}",
                                severity="INFO", confidence=85.0,
                                description=f"S3 bucket '{bucket}' exists but is private (HTTP 403).",
                                evidence=f"URL: {s3_url}", url=s3_url,
                                tags=["s3", "cloud-recon"],
                            ))
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
        # Firebase
        try:
            fb_url = f"https://{prefix}.firebaseio.com/.json"
            resp = await client.get(fb_url)
            if resp and resp.get("status") == 200:
                body = resp.get("text", "") or ""
                if body and body.strip() not in ("null", ""):
                    findings.append(Finding(
                        plugin="firebase_exposed",
                        title=f"Firebase Database Publicly Readable: {prefix}",
                        severity="CRITICAL", confidence=92.0,
                        description=f"Firebase at {fb_url} returns data without authentication.",
                        evidence=f"URL: {fb_url}\nData: {body[:300]}",
                        url=fb_url,
                        remediation="Set Firebase security rules to require authentication.",
                        tags=["firebase", "nosql-exposure", "critical"],
                    ))
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        # Exposed config files
        for config_path in ["/.env", "/.env.local", "/.env.production", "/.aws/credentials",
                            "/config.yml", "/config.json", "/server.key", "/private.key"]:
            try:
                config_url = urljoin(f"{parsed.scheme}://{parsed.netloc}", config_path)
                resp = await client.get(config_url)
                if resp and resp.get("status") == 200:
                    body = resp.get("text", "") or ""
                    if re.search(r"(?i)(password|secret|key|token|db_|aws_|api_)[^\n]{3,}", body):
                        findings.append(Finding(
                            plugin="exposed_config_file",
                            title=f"Sensitive Config File Exposed: {config_path}",
                            severity="CRITICAL", confidence=90.0,
                            description=f"Config file {config_path} is public and contains credentials.",
                            evidence=f"URL: {config_url}\nContent: {body[:200]}",
                            url=config_url,
                            remediation="Block access via web server config. Move sensitive config outside web root. Rotate credentials.",
                            tags=["config-exposure", "credentials", "critical"],
                        ))
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        log("CLOUD", f"CloudMisconfigScanner: {len(findings)} findings")
        return findings


