#  M-25-23 — HTML5 INTERACTIVE REPORTER
# ════════════════════════════════════════════════════════════════════════

class HTML5InteractiveReporter:
    """Generate interactive HTML5 security report with Chart.js visualizations."""

    def generate(self, findings: list, target: str, out_dir: str = ".") -> str:
        import os
        sev = {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "LOW": 0, "INFO": 0}
        for f in findings:
            s = str(getattr(f, "severity", "INFO")).upper()
            sev[s] = sev.get(s, 0) + 1

        confs = [float(getattr(f, "confidence", 50) or 50) for f in findings]
        avg_conf = sum(confs) / max(len(confs), 1)

        rows = []
        for i, f in enumerate(findings):
            s = str(getattr(f, "severity", "INFO")).upper()
            t = (getattr(f, "title", "") or "").replace("<", "&lt;").replace(">", "&gt;")
            p = getattr(f, "plugin", "") or ""
            c = float(getattr(f, "confidence", 0) or 0)
            u = (getattr(f, "url", target) or target)
            e = (getattr(f, "evidence", "") or "").replace("<", "&lt;").replace(">", "&gt;")
            d = (getattr(f, "description", "") or "").replace("<", "&lt;").replace(">", "&gt;")
            r = (getattr(f, "remediation", "") or "").replace("<", "&lt;").replace(">", "&gt;")
            did = f"d{i}"
            rows.append(f'<tr data-sev="{s}"><td><span class="b b-{s.lower()}">{s}</span></td>'
                        f'<td>{t}<div class="dt" id="{did}"><b>Description:</b> {d}<br><b>Evidence:</b> {e}<br><b>Fix:</b> {r}</div></td>'
                        f'<td>{p}</td><td>{c:.0f}%</td>'
                        f'<td title="{u}">{u[:55]}{"…" if len(u)>55 else ""}</td>'
                        f'<td><button onclick="tgl(\'{did}\')" class="btn">Details</button></td></tr>')

        html = f"""<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">
<title>WebScout v25 Report — {target}</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4/dist/chart.umd.min.js"></script>
<style>
:root{{--bg:#0f1117;--card:#1a1d27;--acc:#e74c3c;--text:#e8eaf6;--sub:#8892a4;--bdr:#2c2f3f}}
*{{box-sizing:border-box;margin:0;padding:0}}body{{background:var(--bg);color:var(--text);font-family:system-ui,sans-serif}}
.hdr{{background:linear-gradient(135deg,#1a1d27,#0d1117);padding:2rem;border-bottom:2px solid var(--acc)}}
.hdr h1{{font-size:1.8rem;color:var(--acc)}}.hdr p{{color:var(--sub);margin-top:.3rem}}
.cards{{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:1rem;padding:1.5rem}}
.card{{background:var(--card);border-radius:12px;padding:1.2rem;text-align:center;border:1px solid var(--bdr)}}
.card .num{{font-size:2.2rem;font-weight:700}}.card .lbl{{font-size:.8rem;color:var(--sub);margin-top:.2rem}}
.c .num{{color:#e74c3c}}.h .num{{color:#e67e22}}.m .num{{color:#f1c40f}}.l .num{{color:#3498db}}.i .num{{color:#9b59b6}}.a .num{{color:#2ecc71}}
.sec{{padding:1.5rem}}.sec h2{{font-size:1.2rem;color:var(--acc);margin-bottom:1rem;border-bottom:1px solid var(--bdr);padding-bottom:.5rem}}
.cg{{display:grid;grid-template-columns:1fr 1fr;gap:1.5rem;margin-bottom:1.5rem}}
.cb{{background:var(--card);border-radius:12px;padding:1rem;border:1px solid var(--bdr)}}.cb canvas{{max-height:280px}}
.srch{{width:100%;padding:.6rem 1rem;background:var(--card);border:1px solid var(--bdr);border-radius:8px;color:var(--text);margin-bottom:1rem}}
.srch:focus{{outline:none;border-color:var(--acc)}}
.fltrs{{display:flex;gap:.5rem;flex-wrap:wrap;margin-bottom:1rem}}
.fbtn{{padding:.4rem .9rem;border:1px solid var(--bdr);background:var(--card);color:var(--text);border-radius:6px;cursor:pointer;font-size:.85rem}}
.fbtn.act,.fbtn:hover{{background:var(--acc);border-color:var(--acc)}}
table{{width:100%;border-collapse:collapse;font-size:.88rem}}thead{{background:#1e2130}}
th{{padding:.7rem 1rem;text-align:left;color:var(--sub);border-bottom:2px solid var(--bdr)}}
td{{padding:.65rem 1rem;border-bottom:1px solid var(--bdr);vertical-align:top}}tr:hover td{{background:#1e2130}}
.b{{display:inline-block;padding:.2rem .6rem;border-radius:4px;font-size:.75rem;font-weight:700}}
.b-critical{{background:#e74c3c22;color:#e74c3c;border:1px solid #e74c3c44}}
.b-high{{background:#e67e2222;color:#e67e22;border:1px solid #e67e2244}}
.b-medium{{background:#f1c40f22;color:#f1c40f;border:1px solid #f1c40f44}}
.b-low{{background:#3498db22;color:#3498db;border:1px solid #3498db44}}
.b-info{{background:#9b59b622;color:#9b59b6;border:1px solid #9b59b644}}
.dt{{display:none;background:#0f1117;padding:.7rem;border-radius:6px;margin-top:.4rem;font-family:monospace;font-size:.8rem;white-space:pre-wrap;max-height:200px;overflow-y:auto}}
.btn{{background:none;border:1px solid var(--bdr);color:var(--sub);padding:.2rem .5rem;border-radius:4px;cursor:pointer;font-size:.75rem}}
.btn:hover{{color:var(--text)}}footer{{text-align:center;padding:2rem;color:var(--sub);font-size:.8rem;border-top:1px solid var(--bdr)}}
</style></head><body>
<div class="hdr"><h1>&#128737; WebScout v25 Security Report</h1>
<p>Target: <strong>{target}</strong> &nbsp;|&nbsp; Date: {datetime.now().strftime('%Y-%m-%d %H:%M UTC')} &nbsp;|&nbsp; Findings: <strong>{len(findings)}</strong></p></div>
<div class="cards">
<div class="card c"><div class="num">{sev['CRITICAL']}</div><div class="lbl">CRITICAL</div></div>
<div class="card h"><div class="num">{sev['HIGH']}</div><div class="lbl">HIGH</div></div>
<div class="card m"><div class="num">{sev['MEDIUM']}</div><div class="lbl">MEDIUM</div></div>
<div class="card l"><div class="num">{sev['LOW']}</div><div class="lbl">LOW</div></div>
<div class="card i"><div class="num">{sev['INFO']}</div><div class="lbl">INFO</div></div>
<div class="card a"><div class="num">{avg_conf:.0f}%</div><div class="lbl">AVG CONFIDENCE</div></div>
</div>
<div class="sec"><h2>Severity Distribution</h2>
<div class="cg">
<div class="cb"><canvas id="pie"></canvas></div>
<div class="cb"><canvas id="bar"></canvas></div>
</div></div>
<div class="sec"><h2>Findings ({len(findings)})</h2>
<input class="srch" type="text" id="srch" placeholder="Search findings..." oninput="ft()">
<div class="fltrs">
<button class="fbtn act" onclick="sf('all',this)">All ({len(findings)})</button>
<button class="fbtn" onclick="sf('CRITICAL',this)">Critical ({sev['CRITICAL']})</button>
<button class="fbtn" onclick="sf('HIGH',this)">High ({sev['HIGH']})</button>
<button class="fbtn" onclick="sf('MEDIUM',this)">Medium ({sev['MEDIUM']})</button>
<button class="fbtn" onclick="sf('LOW',this)">Low ({sev['LOW']})</button>
<button class="fbtn" onclick="sf('INFO',this)">Info ({sev['INFO']})</button>
</div>
<table><thead><tr><th>Sev</th><th>Title</th><th>Plugin</th><th>Conf</th><th>URL</th><th></th></tr></thead>
<tbody id="tb">{"".join(rows)}</tbody></table></div>
<footer>WebScout Ultimate v25 &nbsp;|&nbsp; {datetime.now().strftime('%Y-%m-%d %H:%M UTC')}</footer>
<script>
var cf='all';var rows=document.querySelectorAll('#tb tr[data-sev]');
var data=[{sev['CRITICAL']},{sev['HIGH']},{sev['MEDIUM']},{sev['LOW']},{sev['INFO']}];
var labels=['Critical','High','Medium','Low','Info'];
var colors=['#e74c3c','#e67e22','#f1c40f','#3498db','#9b59b6'];
new Chart(document.getElementById('pie'),{{type:'doughnut',data:{{labels:labels,datasets:[{{data:data,backgroundColor:colors,borderWidth:0}}]}},options:{{plugins:{{legend:{{position:'bottom',labels:{{color:'#e8eaf6'}}}}}},responsive:true}}}});
new Chart(document.getElementById('bar'),{{type:'bar',data:{{labels:labels,datasets:[{{data:data,backgroundColor:colors}}]}},options:{{plugins:{{legend:{{display:false}}}},scales:{{x:{{ticks:{{color:'#8892a4'}},grid:{{color:'#2c2f3f'}}}},y:{{ticks:{{color:'#8892a4'}},grid:{{color:'#2c2f3f'}}}}}},responsive:true}}}});
function sf(f,btn){{cf=f;document.querySelectorAll('.fbtn').forEach(b=>b.classList.remove('act'));btn.classList.add('act');ft();}}
function ft(){{var q=document.getElementById('srch').value.toLowerCase();rows.forEach(function(r){{var s=r.getAttribute('data-sev');r.style.display=(cf==='all'||s===cf)&&(!q||r.textContent.toLowerCase().includes(q))?'':'none';}});}}
function tgl(id){{var el=document.getElementById(id);el.style.display=el.style.display==='block'?'none':'block';}}
</script></body></html>"""

        os.makedirs(out_dir, exist_ok=True)
        fname = f"webscout_v25_report_{int(time.time())}.html"
        fpath = os.path.join(out_dir, fname)
        with open(fpath, "w", encoding="utf-8") as fh:
            fh.write(html)
        log("REPORT", f"HTML5InteractiveReporter: {fpath}")
        return fpath

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        return []


# ════════════════════════════════════════════════════════════════════════
#  M-25-24 — ATTACK GRAPH BUILDER V25
# ════════════════════════════════════════════════════════════════════════

class AttackGraphBuilderV25:
    """Build interactive D3.js attack graph from scan findings."""

    def generate(self, findings: list, target: str, out_dir: str = ".") -> str:
        import os
        nodes = [{"id": "target", "label": target[:40], "type": "TARGET", "description": target}]
        links = []

        phases = {"recon": [], "initial": [], "exploit": [], "exfil": []}
        for f in findings:
            p = getattr(f, "plugin", "") or ""
            if any(k in p for k in ["cdn", "subdomain", "recon", "historical", "ssl_san", "passive", "dns"]):
                phases["recon"].append(f)
            elif any(k in p for k in ["sqli", "xss", "ssti", "ssrf", "bypass", "inject", "smuggling"]):
                phases["exploit"].append(f)
            elif any(k in p for k in ["exposed", "leak", "disclosure", "config", "s3", "firebase", "yara"]):
                phases["exfil"].append(f)
            else:
                phases["initial"].append(f)

        phase_labels = {"recon": "Reconnaissance", "initial": "Initial Access",
                        "exploit": "Exploitation", "exfil": "Data Exfiltration"}
        phase_sevs = {"recon": "INFO", "initial": "LOW", "exploit": "HIGH", "exfil": "CRITICAL"}

        for phase_key, phase_findings in phases.items():
            if not phase_findings:
                continue
            pid = f"phase_{phase_key}"
            nodes.append({"id": pid, "label": phase_labels[phase_key], "severity": phase_sevs[phase_key],
                          "description": f"{len(phase_findings)} findings"})
            links.append({"source": "target", "target": pid, "exploit": phase_key == "exploit"})
            sev_order = {"CRITICAL": 4, "HIGH": 3, "MEDIUM": 2, "LOW": 1, "INFO": 0}
            for fi in sorted(phase_findings, key=lambda x: sev_order.get(str(getattr(x, "severity", "INFO")).upper(), 0), reverse=True)[:4]:
                fid = f"f{id(fi)}"
                nodes.append({"id": fid, "label": (getattr(fi, "title", "") or "")[:25],
                              "severity": str(getattr(fi, "severity", "INFO")).upper(),
                              "description": (getattr(fi, "description", "") or "")[:150]})
                links.append({"source": pid, "target": fid,
                              "exploit": str(getattr(fi, "severity", "")).upper() == "CRITICAL"})

        colors = {"CRITICAL": "#e74c3c", "HIGH": "#e67e22", "MEDIUM": "#f1c40f",
                  "LOW": "#3498db", "INFO": "#9b59b6", "TARGET": "#2ecc71"}

        html = f"""<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Attack Graph — {target}</title>
<script src="https://d3js.org/d3.v7.min.js"></script>
<style>body{{background:#0f1117;margin:0;overflow:hidden;font-family:system-ui}}
svg{{width:100vw;height:100vh}}.node circle{{stroke-width:2px;cursor:pointer}}
.node text{{fill:#e8eaf6;font-size:11px;pointer-events:none}}
.link{{stroke:#444;stroke-width:1.5px;stroke-dasharray:4}}.link.x{{stroke:#e74c3c;stroke-width:2.5px;stroke-dasharray:none}}
.tip{{position:absolute;background:#1a1d27;border:1px solid #444;padding:.6rem;border-radius:8px;font-size:.8rem;color:#e8eaf6;pointer-events:none;display:none;max-width:280px}}
h1{{position:absolute;top:1rem;left:1rem;color:#e74c3c;font-size:1.1rem;margin:0}}</style></head>
<body><h1>&#9875; Attack Graph</h1><div class="tip" id="tip"></div><svg id="g"></svg>
<script>
var N={json.dumps(nodes)},L={json.dumps(links)};
var cm={json.dumps(colors)};
var svg=d3.select("#g"),W=window.innerWidth,H=window.innerHeight;
var sim=d3.forceSimulation(N).force("link",d3.forceLink(L).id(d=>d.id).distance(130))
  .force("charge",d3.forceManyBody().strength(-300)).force("center",d3.forceCenter(W/2,H/2))
  .force("collision",d3.forceCollide().radius(42));
var link=svg.append("g").selectAll(".link").data(L).join("line").attr("class",d=>"link"+(d.exploit?" x":""));
var node=svg.append("g").selectAll(".node").data(N).join("g").attr("class","node")
  .call(d3.drag().on("start",(e,d)=>{{if(!e.active)sim.alphaTarget(.3).restart();d.fx=d.x;d.fy=d.y;}})
    .on("drag",(e,d)=>{{d.fx=e.x;d.fy=e.y;}}).on("end",(e,d)=>{{if(!e.active)sim.alphaTarget(0);d.fx=null;d.fy=null;}}));
node.append("circle").attr("r",d=>d.type==="TARGET"?22:16)
  .attr("fill",d=>(cm[d.severity||d.type]||"#555")+"33").attr("stroke",d=>cm[d.severity||d.type]||"#555");
node.append("text").attr("dy","0.35em").attr("text-anchor","middle").text(d=>d.label.substring(0,18)+(d.label.length>18?"…":""));
var tip=document.getElementById("tip");
node.on("mouseover",(e,d)=>{{tip.style.display="block";tip.style.left=(e.pageX+10)+"px";tip.style.top=(e.pageY-20)+"px";
  tip.innerHTML="<b>"+d.label+"</b><br>"+(d.severity?"Sev: <b>"+d.severity+"</b><br>":"")+(d.description||"");}})
  .on("mouseout",()=>{{tip.style.display="none"}});
sim.on("tick",()=>{{link.attr("x1",d=>d.source.x).attr("y1",d=>d.source.y).attr("x2",d=>d.target.x).attr("y2",d=>d.target.y);
  node.attr("transform",d=>`translate(${{d.x}},${{d.y}})`)}});
</script></body></html>"""

        os.makedirs(out_dir, exist_ok=True)
        fpath = os.path.join(out_dir, f"webscout_v25_attack_graph_{int(time.time())}.html")
        with open(fpath, "w", encoding="utf-8") as fh:
            fh.write(html)
        log("GRAPH", f"AttackGraphBuilderV25: {fpath}")
        return fpath

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        return []


# ════════════════════════════════════════════════════════════════════════
#  M-25-25 — SLOW AND LOW EVASION MODE
# ════════════════════════════════════════════════════════════════════════

class SlowAndLowEvasionMode:
    """Stealth scanning with human-like delays to avoid rate-limit/IDS triggers."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse, urljoin
        base = f"{urlparse(target).scheme}://{urlparse(target).netloc}"

        statuses, delays = [], []
        for page in [target, f"{base}/", f"{base}/about", f"{base}/contact"]:
            delay = random.uniform(2.0, 8.0)
            delays.append(delay)
            await asyncio.sleep(delay)
            try:
                resp = await client.get(page, headers={
                    "Accept": "text/html,application/xhtml+xml,*/*;q=0.8",
                    "Accept-Language": "en-US,en;q=0.5",
                    "Connection": "keep-alive",
                })
                if resp:
                    statuses.append(resp.get("status", 0))
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        if statuses:
            findings.append(Finding(
                plugin="slow_low_evasion",
                title=f"Slow & Low Test — {len(statuses)} Requests, No Rate Limit Triggered",
                severity="INFO", confidence=80.0,
                description=(f"Completed {len(statuses)} requests over {sum(delays):.0f}s "
                             f"with {min(delays):.1f}–{max(delays):.1f}s delays. "
                             "No rate limiting triggered. Use this mode for stealthy reconnaissance."),
                evidence=f"Statuses: {statuses}\nDelays: {[f'{d:.1f}s' for d in delays]}",
                url=target,
                tags=["evasion", "slow-low", "stealth"],
            ))
        log("EVADE", f"SlowAndLowEvasionMode: {len(statuses)} requests")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  M-25-26 — UA ROTATION PROXY MANAGER
# ════════════════════════════════════════════════════════════════════════

class UARotationProxyManager:
    """Test UA discrimination and content variation across User-Agents."""

    UAS = [
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124.0.0.0 Safari/537.36",
        "Mozilla/5.0 (X11; Linux x86_64; rv:125.0) Gecko/20100101 Firefox/125.0",
        "Mozilla/5.0 (iPhone; CPU iPhone OS 17_4 like Mac OS X) AppleWebKit/605.1.15 Mobile/15E148 Safari/604.1",
        "Mozilla/5.0 (compatible; Googlebot/2.1; +http://www.google.com/bot.html)",
        "curl/8.6.0",
    ]

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        ua_results = {}

        for ua in self.UAS:
            try:
                resp = await client.get(target, headers={"User-Agent": ua})
                if resp:
                    ua_results[ua[:50]] = (resp.get("status", 0), len(resp.get("text", "") or ""))
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        if ua_results:
            statuses = set(s for s, _ in ua_results.values())
            body_sizes = [bl for _, bl in ua_results.values()]
            max_diff = max(body_sizes) - min(body_sizes) if body_sizes else 0

            if len(statuses) > 1:
                findings.append(Finding(
                    plugin="ua_discrimination",
                    title="UA Discrimination — Different Status Codes per User-Agent",
                    severity="MEDIUM", confidence=82.0,
                    description=f"Different HTTP status codes returned per UA: {statuses}. Bot detection or cloaking present.",
                    evidence="\n".join(f"{ua}: HTTP {s}, {bl}b" for ua, (s, bl) in ua_results.items()),
                    url=target,
                    remediation="Ensure security controls apply consistently regardless of User-Agent.",
                    tags=["ua-discrimination", "bot-detection", "cloaking"],
                ))
            elif max_diff > 5000:
                findings.append(Finding(
                    plugin="ua_content_variation",
                    title=f"Content Varies by UA — Up to {max_diff:,} Bytes Difference",
                    severity="INFO", confidence=75.0,
                    description="Response body size varies significantly by User-Agent (mobile vs desktop content difference).",
                    evidence="\n".join(f"{ua}: {bl}b" for ua, (_, bl) in ua_results.items()),
                    url=target,
                    tags=["ua-variation", "content-negotiation"],
                ))
        log("UA", f"UARotationProxyManager: {len(ua_results)} UAs tested")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  M-25-27 — DISTRIBUTED SCAN COORDINATOR
# ════════════════════════════════════════════════════════════════════════

class DistributedScanCoordinator:
    """Discover and health-check related internal endpoints."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse, urljoin
        parsed = urlparse(target)
        base = f"{parsed.scheme}://{parsed.netloc}"

        related = set()
        try:
            resp = await client.get(target)
            if resp:
                body = resp.get("text", "") or ""
                for link in re.findall(r'href=["\']([^"\']*)["\']', body, re.I):
                    if link.startswith("/") and not link.startswith("//"):
                        related.add(urljoin(base, link))
                    elif link.startswith(base):
                        related.add(link)
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        reachable = []
        if related:
            results = await asyncio.gather(
                *[client.get(u) for u in list(related)[:20]],
                return_exceptions=True
            )
            for url, resp in zip(list(related)[:20], results):
                if isinstance(resp, dict) and resp.get("status", 0) in range(200, 400):
                    reachable.append((url, resp["status"]))

        if reachable:
            findings.append(Finding(
                plugin="endpoint_discovery",
                title=f"Endpoint Discovery — {len(reachable)} Reachable from {len(related)} Found",
                severity="INFO", confidence=85.0,
                description=f"Found {len(reachable)} reachable internal endpoints via HTML link analysis.",
                evidence="\n".join(f"{u}: HTTP {s}" for u, s in reachable[:10]),
                url=target,
                tags=["distributed-scan", "endpoint-discovery"],
            ))
        log("DIST", f"DistributedScanCoordinator: {len(reachable)} reachable")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  M-25-28 — SMART CONTRACT SCANNER
# ════════════════════════════════════════════════════════════════════════

class SmartContractScanner:
    """Detect Web3/blockchain security issues in web application code."""

    PATTERNS = {
        "Private Key Exposure": (r"(?:0x)?[0-9a-fA-F]{64}(?:\s|$|[\"'])", "CRITICAL"),
        "Ethereum RPC Endpoint": (r"(?:infura\.io|alchemyapi\.io)/v[23]/[0-9a-f]{32}", "CRITICAL"),
        "Mnemonic Seed Words": (r"\b(?:abandon|ability|able)\b.{0,200}\b(?:zoo|zone|zero)\b", "CRITICAL"),
        "Reentrancy Pattern": (r"\.transfer\s*\(|\.send\s*\(|\.call\.value\s*\(", "HIGH"),
        "tx.origin Auth": (r"tx\.origin\s*==", "HIGH"),
        "Selfdestruct": (r"selfdestruct\s*\(", "HIGH"),
        "Delegatecall": (r"\.delegatecall\s*\(", "HIGH"),
        "Hardcoded ETH Address": (r"0x[0-9a-fA-F]{40}", "INFO"),
        "Web3 Provider URL": (r"(?:mainnet|ropsten|rinkeby)\.infura\.io", "MEDIUM"),
    }

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urljoin, urlparse
        base = f"{urlparse(target).scheme}://{urlparse(target).netloc}"

        contents = []
        try:
            resp = await client.get(target)
            if resp:
                body = resp.get("text", "") or ""
                if not re.search(r"(?i)(wallet|crypto|ethereum|web3|blockchain|solidity)", body):
                    return findings
                contents.append(("page", body))
                for js_url in re.findall(r'src=["\']([^"\']+\.js[^"\']*)["\']', body, re.I)[:8]:
                    try:
                        jr = await client.get(urljoin(base, js_url))
                        if jr and jr.get("status") == 200:
                            contents.append((js_url, jr.get("text", "") or ""))
                    except Exception as _silenced_exc:
                        log("DEBUG", f"[suppressed] {_silenced_exc}")
        except Exception:
            return findings

        eth_addrs = set()
        for src, content in contents:
            for name, (pattern, sev) in self.PATTERNS.items():
                matches = re.findall(pattern, content, re.I)
                if matches:
                    if name == "Hardcoded ETH Address":
                        eth_addrs.update(m.strip() for m in matches[:5])
                        continue
                    preview = str(matches[0])[:60]
                    if "Key" in name or "Mnemonic" in name:
                        preview = preview[:8] + "***"
                    findings.append(Finding(
                        plugin="smart_contract",
                        title=f"Web3 Risk: {name}",
                        severity=sev, confidence=80.0,
                        description=f"Pattern '{name}' detected in {src}.",
                        evidence=f"Source: {src}\nMatch: {preview}",
                        url=target,
                        remediation=f"Review and secure: {name}",
                        tags=["smart-contract", "web3", name.lower().replace(" ", "-")],
                    ))

        if len(eth_addrs) > 3:
            findings.append(Finding(
                plugin="eth_addresses_exposed",
                title=f"Ethereum Addresses Hardcoded: {len(eth_addrs)}",
                severity="INFO", confidence=78.0,
                description=f"Found {len(eth_addrs)} hardcoded Ethereum addresses.",
                evidence=f"Addresses: {', '.join(list(eth_addrs)[:6])}",
                url=target,
                tags=["smart-contract", "eth-address"],
            ))

        log("SC", f"SmartContractScanner: {len(findings)} findings")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  M-25-29 — TRADING API ANALYZER
# ════════════════════════════════════════════════════════════════════════

class TradingAPIAnalyzer:
    """Security analysis of trading/financial platform APIs."""

    ENDPOINTS = ["/api/v1/order", "/api/order", "/orders", "/api/balance",
                 "/api/v1/ticker", "/api/account", "/api/v1/withdraw", "/api/positions"]

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse, urljoin
        base = f"{urlparse(target).scheme}://{urlparse(target).netloc}"

        try:
            resp = await client.get(target)
            if resp:
                body = resp.get("text", "") or ""
                if not re.search(r"(?i)(trading|exchange|orderbook|ticker|bid|ask|crypto|forex|stock.?market)", body):
                    return findings
        except Exception:
            return findings

        found_eps = []
        for path in self.ENDPOINTS:
            url = urljoin(base, path)
            try:
                resp = await client.get(url)
                if resp and resp.get("status", 404) not in (404, 405, 410):
                    found_eps.append((url, resp.get("status")))
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        if not found_eps:
            return findings

        # IDOR on order endpoints
        for ep_url, _ in [(u, s) for u, s in found_eps if "order" in u.lower()][:2]:
            for oid in range(1, 5):
                try:
                    resp = await client.get(f"{ep_url}/{oid}")
                    if resp and resp.get("status") == 200:
                        data = resp.get("json") or resp.get("text") or {}
                        if isinstance(data, dict) and any(k in data for k in ["order_id", "amount", "price"]):
                            findings.append(Finding(
                                plugin="trading_idor",
                                title=f"Trading IDOR — Order #{oid} Accessible Without Auth",
                                severity="HIGH", confidence=82.0,
                                description=f"Order {oid} accessible without authentication at {ep_url}/{oid}.",
                                evidence=f"URL: {ep_url}/{oid}\nData: {str(data)[:200]}",
                                url=f"{ep_url}/{oid}",
                                remediation="Authenticate all order endpoints. Use opaque UUIDs.",
                                tags=["idor", "trading", "order-exposure"],
                            ))
                            break
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
        # Price manipulation
        for ep_url, _ in found_eps[:2]:
            for payload in [{"price": "-100"}, {"price": "NaN"}, {"amount": "0"}]:
                try:
                    resp = await client.post(ep_url, data=json.dumps(payload),
                                             headers={"Content-Type": "application/json"})
                    if resp and resp.get("status") in (200, 201):
                        body = str(resp.get("json") or resp.get("text") or "")
                        if not any(err in body.lower() for err in ["error", "invalid", "validation"]):
                            findings.append(Finding(
                                plugin="trading_price_manipulation",
                                title=f"Trading Price/Amount Manipulation Accepted",
                                severity="CRITICAL", confidence=75.0,
                                description=f"Invalid value {payload} accepted without validation error.",
                                evidence=f"Endpoint: {ep_url}\nPayload: {payload}\nResponse: {body[:200]}",
                                url=ep_url,
                                remediation="Strict server-side validation for all financial values.",
                                tags=["trading", "price-manipulation", "critical"],
                            ))
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
        log("TRADING", f"TradingAPIAnalyzer: {len(found_eps)} endpoints, {len(findings)} findings")
        return findings


