#  M-25-30 — DIGITAL WALLET SCANNER
# ════════════════════════════════════════════════════════════════════════

class DigitalWalletScanner:
    """Security testing for digital wallet and payment applications."""

    WALLET_PATHS = ["/api/wallet", "/api/balance", "/api/send", "/api/transfer",
                    "/api/withdraw", "/wallet/backup", "/api/seed"]

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse, urljoin
        base = f"{urlparse(target).scheme}://{urlparse(target).netloc}"

        try:
            resp = await client.get(target)
            if resp:
                body = resp.get("text", "") or ""
                indicator_count = sum(1 for kw in ["wallet", "balance", "send", "receive",
                                                    "crypto", "bitcoin", "withdraw", "seed"]
                                      if kw.lower() in body.lower())
                if indicator_count < 3:
                    return findings
        except Exception:
            return findings

        found_eps = []
        for path in self.WALLET_PATHS:
            url = urljoin(base, path)
            try:
                resp = await client.get(url)
                if resp and resp.get("status", 404) != 404:
                    found_eps.append(url)
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        if not found_eps:
            return findings

        # Brute-force protection test
        for ep in [u for u in found_eps if any(k in u for k in ["pin", "auth", "login", "unlock"])][:1]:
            results = []
            for pin in ["0000", "1234", "1111", "0001", "9999"]:
                try:
                    resp = await client.post(ep, data=json.dumps({"pin": pin}),
                                             headers={"Content-Type": "application/json"})
                    if resp:
                        results.append(resp.get("status", 0))
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
            if results and 429 not in results and 423 not in results:
                findings.append(Finding(
                    plugin="wallet_brute_force",
                    title="Wallet PIN/Password Lacks Brute-Force Protection",
                    severity="HIGH", confidence=78.0,
                    description=f"5 PIN attempts at {ep} without rate limit or lockout.",
                    evidence=f"Statuses: {results}",
                    url=ep,
                    remediation="Lock after 3–5 attempts. Add rate limiting. Require 2FA.",
                    tags=["wallet", "brute-force", "pin"],
                ))

        # Seed exposure
        for path in ["/api/wallet/backup", "/api/seed", "/api/mnemonic"]:
            url = urljoin(base, path)
            try:
                resp = await client.get(url)
                if resp and resp.get("status") == 200:
                    body = resp.get("text", "") or ""
                    if re.search(r"\b(?:mnemonic|seed|phrase|word)\b", body, re.I):
                        findings.append(Finding(
                            plugin="wallet_seed_exposure",
                            title="Wallet Seed/Mnemonic Endpoint Exposed",
                            severity="CRITICAL", confidence=85.0,
                            description=f"Wallet backup endpoint {url} may expose seed phrases/private keys.",
                            evidence=f"URL: {url}\nResponse: {body[:200]}",
                            url=url,
                            remediation="Require strong auth + 2FA for exports. Encrypt seed client-side.",
                            tags=["wallet", "seed-phrase", "critical"],
                        ))
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        log("WALLET", f"DigitalWalletScanner: {len(findings)} findings")
        return findings


