#  M-25-31 — ALIENVAULT OTX ENGINE
# ════════════════════════════════════════════════════════════════════════

class AlienVaultOTXEngine:
    """Threat intelligence via AlienVault OTX (free VirusTotal alternative)."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse
        hostname = urlparse(target).hostname or ""

        for indicator, kind in [(hostname, "domain"),
                                 (lambda: _socket.gethostbyname(hostname), "IPv4")]:
            try:
                if callable(indicator):
                    indicator = indicator()
                url = f"https://otx.alienvault.com/api/v1/indicators/{kind}/{indicator}/general"
                resp = await client.get(url, headers={"Accept": "application/json"})
                if resp and resp.get("status") == 200:
                    data = resp.get("json") or {}
                    pulse_count = data.get("pulse_info", {}).get("count", 0)
                    reputation = data.get("reputation", 0)
                    tags_found = [t for p in data.get("pulse_info", {}).get("pulses", [])[:5]
                                  for t in p.get("tags", [])]
                    country = data.get("country_name", "")
                    asn = data.get("asn", "")

                    if pulse_count > 0 or reputation < 0:
                        findings.append(Finding(
                            plugin="otx_threat_intel",
                            title=f"OTX: {indicator} in {pulse_count} Threat Pulse(s)",
                            severity="HIGH" if pulse_count > 3 else "MEDIUM",
                            confidence=80.0,
                            description=(f"{indicator} ({country}, {asn}) found in {pulse_count} OTX pulses "
                                        f"(reputation: {reputation}). Tags: {', '.join(set(tags_found)[:8])}"),
                            evidence=f"Indicator: {indicator}\nPulses: {pulse_count}\nReputation: {reputation}",
                            url=target,
                            remediation="Investigate threat associations. Review DNS history.",
                            tags=["threat-intel", "otx", "reputation"],
                        ))
                    elif country:
                        findings.append(Finding(
                            plugin="otx_geo_info",
                            title=f"OTX: {indicator} — {country} ({asn})",
                            severity="INFO", confidence=90.0,
                            description=f"OTX geolocation: {country}, ASN: {asn}, Pulses: {pulse_count}",
                            evidence=f"IP: {indicator}\nCountry: {country}\nASN: {asn}",
                            url=target,
                            tags=["threat-intel", "otx", "geolocation"],
                        ))
            except Exception as e:
                log("DEBUG", f"[OTX] {e}")

        log("OTX", f"AlienVaultOTXEngine: {len(findings)} findings")
        return findings


