#  M-25-32 — DNSDUMPSTER/HACKERTARGET
# ════════════════════════════════════════════════════════════════════════

class DNSDumpsterHackerTarget:
    """DNS intelligence via HackerTarget, zone transfer test, DoH validation."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse
        hostname = urlparse(target).hostname or ""
        parts = hostname.split(".")
        root_domain = ".".join(parts[-2:]) if len(parts) >= 2 else hostname

        # HackerTarget DNS lookup
        try:
            resp = await client.get(f"https://api.hackertarget.com/dnslookup/?q={root_domain}")
            if resp and resp.get("status") == 200:
                text = resp.get("text", "") or ""
                if "error" not in text.lower() and text.strip():
                    records = [l.strip() for l in text.splitlines() if l.strip()]
                    findings.append(Finding(
                        plugin="dns_intelligence",
                        title=f"DNS Intelligence — {len(records)} Records for {root_domain}",
                        severity="INFO", confidence=88.0,
                        description=f"Collected {len(records)} DNS records via HackerTarget (free SecurityTrails alternative).",
                        evidence="DNS Records:\n" + "\n".join(records[:20]),
                        url=target,
                        tags=["dns", "intelligence", "hackertarget"],
                    ))
        except Exception as e:
            log("DEBUG", f"[DNSDumpster] DNS lookup: {e}")

        # Reverse IP
        try:
            ip = _socket.gethostbyname(hostname)
            resp = await client.get(f"https://api.hackertarget.com/reverseiplookup/?q={ip}")
            if resp and resp.get("status") == 200:
                text = resp.get("text", "") or ""
                if "error" not in text.lower():
                    co_hosted = [l.strip() for l in text.splitlines() if l.strip()]
                    if len(co_hosted) > 1:
                        others = [h for h in co_hosted if h != hostname and root_domain not in h]
                        findings.append(Finding(
                            plugin="reverse_ip_cohosted",
                            title=f"Reverse IP: {len(co_hosted)} Domains on {ip}",
                            severity="INFO", confidence=85.0,
                            description=(f"Shared hosting: {len(co_hosted)} domains on {ip}. "
                                        + (f"Other tenants: {', '.join(others[:5])}" if others else "")),
                            evidence=f"IP: {ip}\nCo-hosted: {', '.join(co_hosted[:15])}",
                            url=target,
                            remediation="Shared hosting creates cross-tenant risks. Consider dedicated hosting.",
                            tags=["reverse-ip", "shared-hosting"],
                        ))
        except Exception as e:
            log("DEBUG", f"[DNSDumpster] Reverse IP: {e}")

        # Zone transfer test
        if _HAS_DNSPYTHON:
            try:
                import dns.zone
                import dns.query
                nameservers = []
                try:
                    for rdata in _dns_resolver.resolve(root_domain, "NS"):
                        nameservers.append(str(rdata.target).rstrip("."))
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
                for ns in nameservers[:3]:
                    try:
                        ns_ip = _socket.gethostbyname(ns)
                        zone = dns.zone.from_xfr(dns.query.xfr(ns_ip, root_domain, timeout=10))
                        if zone:
                            names = list(zone.nodes.keys())
                            findings.append(Finding(
                                plugin="dns_zone_transfer",
                                title=f"DNS Zone Transfer ALLOWED from {ns}!",
                                severity="HIGH", confidence=97.0,
                                description=f"Nameserver {ns} allows zone transfers — {len(names)} records exposed.",
                                evidence=f"NS: {ns}\nRecords: {len(names)}\nSample: {', '.join(str(n) for n in names[:10])}",
                                url=target,
                                remediation="Restrict zone transfers to authorized secondaries only. Use TSIG auth.",
                                tags=["zone-transfer", "dns"],
                            ))
                    except Exception as _silenced_exc:
                        log("DEBUG", f"[suppressed] {_silenced_exc}")
            except Exception as e:
                log("DEBUG", f"[DNSDumpster] Zone transfer: {e}")

        log("DNS", f"DNSDumpsterHackerTarget: {len(findings)} findings")
        return findings


