#  M-25-33 — CRT.SH/ENTRUST CENSYS ALTERNATIVE
# ════════════════════════════════════════════════════════════════════════

class CRTSHEntrustCensys:
    """Certificate transparency asset discovery — free Censys/Shodan alternative."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse
        hostname = urlparse(target).hostname or ""
        parts = hostname.split(".")
        root_domain = ".".join(parts[-2:]) if len(parts) >= 2 else hostname

        all_certs, sources = [], []

        try:
            resp = await client.get(f"https://crt.sh/?q={root_domain}&output=json",
                                    headers={"Accept": "application/json"})
            if resp and resp.get("status") == 200:
                data = resp.get("json") or []
                if isinstance(data, list):
                    all_certs.extend(data)
                    sources.append("crt.sh")
        except Exception as e:
            log("DEBUG", f"[CRTSH] {e}")

        try:
            resp = await client.get(
                f"https://ctsearch.entrust.com/api/v1/certificates?fields=subjectDN&domain={root_domain}&limit=50",
                headers={"Accept": "application/json"})
            if resp and resp.get("status") == 200:
                data = resp.get("json") or {}
                all_certs.extend(data.get("certificates", []))
                sources.append("Entrust CT")
        except Exception as e:
            log("DEBUG", f"[CRTSH] Entrust: {e}")

        unique_domains, wildcards, expired = set(), [], []
        for cert in all_certs:
            name = cert.get("name_value", "") or cert.get("subjectDN", "") or ""
            for line in name.splitlines():
                line = line.strip()
                if line:
                    if line.startswith("*"):
                        wildcards.append(line)
                    unique_domains.add(line.lstrip("*."))
            not_after = cert.get("not_after", "") or cert.get("validTo", "")
            if not_after:
                try:
                    exp = datetime.fromisoformat(not_after.replace("Z", "+00:00"))
                    if exp < datetime.now(exp.tzinfo):
                        expired.append(cert)
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
        if unique_domains:
            findings.append(Finding(
                plugin="ct_asset_discovery",
                title=f"CT Asset Discovery — {len(unique_domains)} Domains, {len(all_certs)} Certs",
                severity="INFO", confidence=90.0,
                description=(f"Found {len(all_certs)} certs, {len(unique_domains)} domains "
                             f"via {', '.join(sources)} (free Censys alternative)."),
                evidence=(f"Sources: {', '.join(sources)}\nCerts: {len(all_certs)}\n"
                          f"Domains: {len(unique_domains)}\nWildcards: {len(set(wildcards))}\n"
                          f"Expired: {len(expired)}\nSample: {', '.join(list(unique_domains)[:15])}"),
                url=target,
                remediation="Review all discovered assets for security misconfigurations.",
                tags=["cert-transparency", "asset-discovery", "censys-alternative"],
            ))

        if expired:
            findings.append(Finding(
                plugin="expired_certificates",
                title=f"Expired SSL Certificates: {len(expired)}",
                severity="MEDIUM", confidence=85.0,
                description=f"CT logs show {len(expired)} expired certificates for {root_domain}.",
                evidence=f"Expired: {[c.get('name_value','')[:50] for c in expired[:5]]}",
                url=target,
                remediation="Renew or decommission expired certificate services. Use auto-renewal.",
                tags=["certificate", "expired", "tls"],
            ))

        if wildcards:
            findings.append(Finding(
                plugin="wildcard_certificates",
                title=f"Wildcard Certificates: {', '.join(set(wildcards)[:3])}",
                severity="LOW", confidence=90.0,
                description=f"Wildcard certs cover all subdomains — single compromise exposes all.",
                evidence=f"Wildcards: {list(set(wildcards))}",
                url=target,
                remediation="Use specific certs per service. Rotate wildcards regularly.",
                tags=["certificate", "wildcard"],
            ))

        log("CT", f"CRTSHEntrustCensys: {len(all_certs)} certs, {len(unique_domains)} domains")
        return findings


# ════════════════════════════════════════════════════════════════════════
#  M-25-34 — CERT SAN IP EXTRACTOR (DEEP)
# ════════════════════════════════════════════════════════════════════════

class CertSANIPExtractor:
    """Deep SSL SAN IP extraction with subnet correlation and CDN bypass analysis."""

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        findings = []
        from urllib.parse import urlparse
        hostname = urlparse(target).hostname or ""
        parts = hostname.split(".")
        root_domain = ".".join(parts[-2:]) if len(parts) >= 2 else hostname

        all_san_ips = set()
        evidence = []

        # crt.sh IP SANs
        try:
            resp = await client.get(f"https://crt.sh/?q={root_domain}&output=json",
                                    headers={"Accept": "application/json"})
            if resp and resp.get("status") == 200:
                for entry in (resp.get("json") or []):
                    if isinstance(entry, dict):
                        for name in (entry.get("name_value", "") or "").splitlines():
                            name = name.strip().lstrip("*.")
                            try:
                                ip = _ipaddress.ip_address(name)
                                if not ip.is_private:
                                    all_san_ips.add(str(ip))
                            except Exception as _silenced_exc:
                                log("DEBUG", f"[suppressed] {_silenced_exc}")
        except Exception as e:
            log("DEBUG", f"[CertSANIPDeep] crt.sh: {e}")

        # Direct TLS inspection on multiple ports
        for port in [443, 8443, 4443]:
            try:
                ctx = _ssl_v25.create_default_context()
                ctx.check_hostname = False
                ctx.verify_mode = _ssl_v25.CERT_NONE
                loop = asyncio.get_event_loop()

                def _get_cert(h=hostname, p=port):
                    try:
                        sock = _socket.create_connection((h, p), timeout=8)
                        ssl_sock = ctx.wrap_socket(sock, server_hostname=h)
                        c = ssl_sock.getpeercert()
                        ssl_sock.close()
                        return c
                    except Exception:
                        return None

                cert = await asyncio.wait_for(loop.run_in_executor(None, _get_cert), timeout=12)
                if cert:
                    for san_type, san_val in cert.get("subjectAltName", []):
                        if san_type == "IP Address":
                            try:
                                ip = _ipaddress.ip_address(san_val)
                                if not ip.is_private:
                                    all_san_ips.add(str(ip))
                                    evidence.append(f"Port {port} TLS: IP SAN {san_val}")
                            except Exception as _silenced_exc:
                                log("DEBUG", f"[suppressed] {_silenced_exc}")
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        if all_san_ips:
            subnets = {}
            for ip_str in all_san_ips:
                try:
                    subnet = str(_ipaddress.ip_network(f"{ip_str}/24", strict=False))
                    subnets[subnet] = subnets.get(subnet, []) + [ip_str]
                except Exception as _silenced_exc:
                    log("DEBUG", f"[suppressed] {_silenced_exc}")
            origin_ips = [ip for ip in all_san_ips if not _ip_in_cdn_ranges_v25(ip)]
            cdn_ips = [ip for ip in all_san_ips if _ip_in_cdn_ranges_v25(ip)]

            findings.append(Finding(
                plugin="cert_san_ip_deep",
                title=f"Deep SSL SAN — {len(all_san_ips)} IPs in {len(subnets)} /24 Subnets",
                severity="HIGH" if origin_ips else "INFO",
                confidence=91.0,
                description=(f"SSL SAN analysis found {len(all_san_ips)} IPs across {len(subnets)} /24 subnets.\n"
                             + (f"NON-CDN origin IPs: {', '.join(origin_ips[:8])}\n" if origin_ips else "")
                             + (f"CDN IPs: {', '.join(cdn_ips[:5])}" if cdn_ips else "")),
                evidence=(f"Total IP SANs: {len(all_san_ips)}\nNon-CDN: {', '.join(origin_ips)}\n"
                          f"Subnets: {', '.join(list(subnets.keys())[:8])}\nTLS details:\n" + "\n".join(evidence[:8])),
                url=target,
                remediation="Avoid IP addresses in SSL SANs. Use separate certs for CDN and origin. Restrict direct access.",
                tags=["ssl", "san", "ip-extraction", "cdn-bypass", "origin-ip"],
            ))

            if subnets and origin_ips:
                findings.append(Finding(
                    plugin="origin_subnet",
                    title=f"Origin Subnet Identified: {', '.join(list(subnets.keys())[:3])}",
                    severity="MEDIUM", confidence=75.0,
                    description=f"Scanning nearby IPs in these subnets may reveal staging/admin infrastructure.",
                    evidence=f"Subnets: {list(subnets.keys())}",
                    url=target,
                    tags=["subnet", "origin-discovery"],
                ))

        log("CERT", f"CertSANIPExtractor: {len(all_san_ips)} IP SANs")
        return findings


