        ("--mx-spf-dmarc",     "Extract IPs from MX/SPF; check DMARC policy"),
        ("--ipv6-bypass",      "Test IPv6 CDN bypass via AAAA records"),
        ("--header-leak",      "Detect IP and server fingerprint leaks in headers"),
        ("--port-scan",        "Scan common ports on target IP"),
        ("--direct-ip-connect","Test direct IP+Host-header CDN bypass"),
        ("--response-match",   "Confirm CDN bypass by response fingerprint match"),
        # Set 2
        ("--cdn-fingerprint",  "Deep CDN provider fingerprinting (Akamai/Fastly/CloudFront)"),
        ("--http2-bypass",     "Identify WAF-blocked patterns for HTTP/2 bypass test"),
        ("--ws-cdn-bypass",    "Test WebSocket CDN/WAF bypass"),
        ("--behavioral-analysis","Cache poisoning, host injection, backend rotation"),
        ("--uaf-scan",         "Detect Use-After-Free and memory corruption indicators"),
        ("--race-v2",          "Advanced race condition testing"),
        ("--yara",             "Apply YARA/pattern rules to responses"),
        ("--oauth2-deep",      "Deep OAuth2/SAML analysis (redirect, JWT confusion)"),
        ("--ws-security-deep", "Deep WebSocket security (CSWSH, origin bypass)"),
        ("--http-smuggling-deep","Advanced HTTP smuggling (CL.TE, TE.CL, TE.TE)"),
        ("--graphql-deep",     "GraphQL introspection, batch DoS, injection"),
        ("--cloud-misconfig",  "Cloud misconfiguration (S3/Azure/GCP/Firebase)"),
        ("--html5-report",     "Generate interactive HTML5 security report"),
        ("--attack-graph-v25", "Build D3.js interactive attack graph"),
        ("--slow-and-low",     "Slow & low evasion mode (natural delays)"),
        ("--ua-rotation",      "Test UA discrimination and content variation"),
        ("--distributed-scan", "Distributed endpoint discovery"),
        ("--smart-contract",   "Smart contract/Web3 vulnerability scanning"),
        ("--trading-api",      "Trading platform API security analysis"),
        ("--wallet-scan",      "Digital wallet application security testing"),
        ("--otx",              "AlienVault OTX threat intelligence (VirusTotal alt)"),
        ("--dns-intelligence", "DNS intelligence via HackerTarget (SecurityTrails alt)"),
        ("--ct-censys",        "Certificate transparency asset discovery (Censys alt)"),
        ("--cert-san-deep",    "Deep SSL SAN IP extraction with subnet analysis"),
