# ════════════════════════════════════════════════════════════════════════
#  PATCH run_webscout() TO INCLUDE v25 MODULES
# ════════════════════════════════════════════════════════════════════════

_orig_run_webscout_v24 = run_webscout


async def run_webscout(target: str, args) -> tuple:
    """Patched run_webscout() — runs original then appends v25 modules."""
    result = await _orig_run_webscout_v24(target, args)

    if isinstance(result, tuple) and len(result) >= 2:
        findings = list(result[0])
        rest = result[1:]
    else:
        findings = list(result) if result else []
        rest = ({},)

    all_mods = getattr(args, "all_modules", False) or getattr(args, "run_all", False)
    v25_all  = getattr(args, "v25_all", False) or all_mods
    cdn_all  = getattr(args, "cdn_all", False) or v25_all

    async def _safe_v25_run(scanner_cls, label):
        try:
            log("SCAN", f"[v25] {label}")
            res = await scanner_cls().scan(client, target)
            if res:
                log("OK", f"[v25] {label}: {len(res)} finding(s)")
            return res or []
        except Exception as e:
            log("WARN", f"[v25] {label}: {e}")
            return []

    try:
        cfg = ScanConfig(
            timeout=getattr(args, "timeout", 60),
            concurrency=getattr(args, "concurrency", 3),
            delay=getattr(args, "delay", 0.5),
            rate_limit=getattr(args, "rate_limit", 30),
            retries=getattr(args, "retries", 4),
            proxy=getattr(args, "proxy", "") or "",
            proxy_list=_load_proxy_list(
                getattr(args, "proxy_list", None),
                no_proxy=getattr(args, "no_proxy", False)
            ),
            proxy_ban_threshold=getattr(args, "proxy_ban_threshold", 1),
            proxy_timeout=getattr(args, "proxy_timeout", 8),
            cookies=getattr(args, "cookie", "") or "",
            custom_headers={k: v for h in (getattr(args, "header", None) or [])
                            for k, v in [h.split(":", 1)] if ":" in h},
            jwt_token=getattr(args, "jwt", "") or "",
            bearer=getattr(args, "bearer", "") or "",
            basic_auth=(getattr(args, "basic_user", ""), getattr(args, "basic_pass", ""))
                if hasattr(args, "basic_user") else ("", ""),
            verify_ssl=not getattr(args, "unsafe_disable_ssl_verification", False),
            verbose=getattr(args, "verbose", False),
            allow_private_targets=getattr(args, "allow_private_targets", False),
            safe_mode=not getattr(args, "no_safe_mode", False),
            max_findings=max(1, getattr(args, "max_findings", 1000)),
        )
        # NOTE: WebScoutClient has no init() method — constructor is sufficient
        client = WebScoutClient(cfg)
    except Exception as e:
        log("WARN", f"[v25] client init: {e}")
        return result

    v25_modules = [
        # Set 1
        (cdn_all or getattr(args, "cdn_detect",        False), CDNDetectionEngine,        "CDN Detection"),
        (cdn_all or getattr(args, "historical_dns",    False), HistoricalDNSEngine,       "Historical DNS"),
        (cdn_all or getattr(args, "ssl_san_ips",       False), SSLSANIPExtractor,         "SSL SAN IPs"),
        (cdn_all or getattr(args, "passive_subdomain", False), PassiveSubdomainEngine,    "Passive Subdomain"),
        (cdn_all or getattr(args, "mx_spf_dmarc",      False), MXSPFDMARCIPExtractor,    "MX/SPF/DMARC"),
        (cdn_all or getattr(args, "ipv6_bypass",       False), IPv6DirectScanner,         "IPv6 Bypass"),
        (cdn_all or getattr(args, "header_leak",       False), HeaderLeakDetector,        "Header Leak"),
        (cdn_all or getattr(args, "port_scan",         False), CommonPortScanner,         "Port Scan"),
        (cdn_all or getattr(args, "direct_ip_connect", False), DirectIPConnector,         "Direct IP Connect"),
        (cdn_all or getattr(args, "response_match",    False), ResponseFingerprintMatcher,"Response Match"),
        # Set 2
        (v25_all or getattr(args, "cdn_fingerprint",       False), CDNProviderFingerprinter,    "CDN Fingerprint"),
        (v25_all or getattr(args, "http2_bypass",          False), HTTP2CDNBypass,              "HTTP/2 Bypass"),
        (v25_all or getattr(args, "ws_cdn_bypass",         False), WebSocketCDNBypass,          "WS CDN Bypass"),
        (v25_all or getattr(args, "behavioral_analysis",   False), BehavioralAnalysisEngine,    "Behavioral Analysis"),
        (v25_all or getattr(args, "uaf_scan",              False), UseAfterFreeScanner,         "UAF Scanner"),
        (v25_all or getattr(args, "race_v2",               False), AdvancedRaceConditionV2,     "Race Condition v2"),
        (v25_all or getattr(args, "yara",                  False), YARAIntegrationEngine,       "YARA Integration"),
        (v25_all or getattr(args, "oauth2_deep",           False), OAuth2SAMLDeepScanner,       "OAuth2/SAML Deep"),
        (v25_all or getattr(args, "ws_security_deep",      False), WebSocketSecurityDeep,       "WS Security Deep"),
        (v25_all or getattr(args, "http_smuggling_deep",   False), HTTPSmugglingDeep,           "HTTP Smuggling Deep"),
        (v25_all or getattr(args, "graphql_deep",          False), GraphQLIntrospectionDeep,    "GraphQL Deep"),
        (v25_all or getattr(args, "cloud_misconfig",       False), CloudMisconfigScanner,       "Cloud Misconfig"),
        (v25_all or getattr(args, "slow_and_low",          False), SlowAndLowEvasionMode,       "Slow & Low"),
        (v25_all or getattr(args, "ua_rotation",           False), UARotationProxyManager,      "UA Rotation"),
        (v25_all or getattr(args, "distributed_scan",      False), DistributedScanCoordinator,  "Distributed Scan"),
        (v25_all or getattr(args, "smart_contract",        False), SmartContractScanner,        "Smart Contract"),
        (v25_all or getattr(args, "trading_api",           False), TradingAPIAnalyzer,          "Trading API"),
        (v25_all or getattr(args, "wallet_scan",           False), DigitalWalletScanner,        "Wallet Scanner"),
        (v25_all or getattr(args, "otx",                   False), AlienVaultOTXEngine,         "AlienVault OTX"),
        (v25_all or getattr(args, "dns_intelligence",      False), DNSDumpsterHackerTarget,     "DNS Intelligence"),
        (v25_all or getattr(args, "ct_censys",             False), CRTSHEntrustCensys,          "CT/Censys Alt"),
        (v25_all or getattr(args, "cert_san_deep",         False), CertSANIPExtractor,          "Cert SAN Deep"),
    ]

    v25_findings = []
    for enabled, scanner_cls, label in v25_modules:
        if enabled:
            new = await _safe_v25_run(scanner_cls, label)
            v25_findings.extend(new)

    out_dir = getattr(args, "out_dir", ".") or "."
    all_findings = findings + v25_findings

    # Post-scan HTML5 report
    if v25_findings or (v25_all or getattr(args, "html5_report", False)):
        try:
            path = HTML5InteractiveReporter().generate(all_findings, target, out_dir)
            print(f"\n  [v25] HTML5 Interactive Report: {path}")
        except Exception as e:
            log("WARN", f"[v25] HTML report: {e}")

    # Post-scan attack graph
    if v25_all or getattr(args, "attack_graph_v25", False):
        try:
            path = AttackGraphBuilderV25().generate(all_findings, target, out_dir)
            print(f"  [v25] Attack Graph: {path}")
        except Exception as e:
            log("WARN", f"[v25] Attack graph: {e}")

    try:
        await client.close()
    except Exception as _silenced_exc:
        log("DEBUG", f"[suppressed] {_silenced_exc}")
    return (all_findings,) + rest



