    # DNS record type codes
    DNS_TYPES = {"A": 1, "NS": 2, "CNAME": 5, "MX": 15, "TXT": 16,
                 "AAAA": 28, "SRV": 33, "SOA": 6, "PTR": 12, "ANY": 255}

    def __init__(self, resolvers: list = None, concurrency: int = 100, timeout: float = 3.0):
        self.resolvers   = resolvers or [
            "8.8.8.8", "8.8.4.4",        # Google
            "1.1.1.1", "1.0.0.1",        # Cloudflare
            "9.9.9.9",                    # Quad9
            "208.67.222.222",             # OpenDNS
        ]
        self.concurrency = concurrency
        self.timeout     = timeout
        self._sem        = asyncio.Semaphore(concurrency)
        self._wildcard_ips: set = set()

    def _build_dns_query(self, domain: str, qtype: int = 1) -> bytes:
        """Build a minimal DNS query packet."""
        txid  = random.randint(0, 65535).to_bytes(2, "big")
        flags = b"\x01\x00"  # standard recursive query
        qdcount = b"\x00\x01"
        ancount = b"\x00\x00"
        nscount = b"\x00\x00"
        arcount = b"\x00\x00"
        header  = txid + flags + qdcount + ancount + nscount + arcount

        # Encode domain name
        qname = b""
        for label in domain.rstrip(".").split("."):
            enc = label.encode()
            qname += bytes([len(enc)]) + enc
        qname += b"\x00"

        question = qname + qtype.to_bytes(2, "big") + b"\x00\x01"  # QTYPE + QCLASS (IN)
        return header + question

    def _parse_dns_name(self, data: bytes, offset: int) -> tuple:
        """Parse a DNS name from packet data. Returns (name, new_offset)."""
        labels = []
        visited = set()
        while offset < len(data):
            length = data[offset]
            if length == 0:
                offset += 1
                break
            if (length & 0xC0) == 0xC0:  # Pointer
                if offset + 1 >= len(data):
                    break
                ptr = ((length & 0x3F) << 8) | data[offset + 1]
                if ptr in visited:
                    break
                visited.add(ptr)
                name, _ = self._parse_dns_name(data, ptr)
                labels.append(name)
                offset += 2
                break
            else:
                offset += 1
                labels.append(data[offset:offset + length].decode("ascii", errors="replace"))
                offset += length
        return ".".join(labels), offset

    def _parse_dns_response(self, data: bytes, qtype: int) -> list:
        """Parse DNS response and extract answer records."""
        if len(data) < 12:
            return []
        answers   = []
        ancount   = (data[6] << 8) | data[7]
        if ancount == 0:
            return []

        # Skip header (12 bytes) + question section
        offset = 12
        try:
            # Skip question name
            _, offset = self._parse_dns_name(data, offset)
            offset += 4  # QTYPE + QCLASS

            for _ in range(min(ancount, 20)):
                if offset >= len(data):
                    break
                _, offset = self._parse_dns_name(data, offset)
                if offset + 10 > len(data):
                    break
                rtype  = (data[offset] << 8) | data[offset + 1]
                # rclass = (data[offset+2] << 8) | data[offset+3]
                # ttl    = int.from_bytes(data[offset+4:offset+8], "big")
                rdlen  = (data[offset + 8] << 8) | data[offset + 9]
                offset += 10

                rdata = data[offset:offset + rdlen]
                offset += rdlen

                if rtype == 1 and rdlen == 4:      # A
                    answers.append({"type": "A",    "value": ".".join(str(b) for b in rdata)})
                elif rtype == 28 and rdlen == 16:  # AAAA
                    import socket as _s
                    try:
                        answers.append({"type": "AAAA", "value": _s.inet_ntop(_s.AF_INET6, rdata)})
                    except Exception as _silenced_exc:
                        log("DEBUG", f"[suppressed] {_silenced_exc}")
                elif rtype in (2, 5, 12):          # NS/CNAME/PTR
                    name, _ = self._parse_dns_name(data, offset - rdlen)
                    typ_name = {2: "NS", 5: "CNAME", 12: "PTR"}.get(rtype, str(rtype))
                    answers.append({"type": typ_name, "value": name})
                elif rtype == 15:                  # MX
                    pref = (rdata[0] << 8) | rdata[1]
                    name, _ = self._parse_dns_name(data, offset - rdlen + 2)
                    answers.append({"type": "MX", "value": f"{pref} {name}"})
                elif rtype == 16:                  # TXT
                    txt_parts = []
                    i = 0
                    while i < len(rdata):
                        tlen = rdata[i]; i += 1
                        txt_parts.append(rdata[i:i+tlen].decode("ascii", errors="replace"))
                        i += tlen
                    answers.append({"type": "TXT", "value": " ".join(txt_parts)})
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        return answers

    async def _query(self, domain: str, qtype: str = "A") -> list:
        """Send a DNS UDP query using raw sockets via asyncio executor."""
        qtype_code = self.DNS_TYPES.get(qtype.upper(), 1)
        packet     = self._build_dns_query(domain, qtype_code)
        # BUG-7 FIX: capture txid so we can verify the response isn't stale/spoofed
        sent_txid  = packet[:2]  # RFC 1035 §4.1.1: bytes 0-1 are Transaction ID
        resolver   = random.choice(self.resolvers)

        async with self._sem:
            loop = asyncio.get_event_loop()
            try:
                def _do_query():
                    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
                    sock.settimeout(self.timeout)
                    try:
                        sock.sendto(packet, (resolver, 53))
                        resp, _ = sock.recvfrom(4096)
                        return resp
                    finally:
                        sock.close()

                resp = await asyncio.wait_for(
                    loop.run_in_executor(None, _do_query),
                    timeout=self.timeout + 1,
                )
                # BUG-7 FIX: discard responses with wrong txid (stale/spoofed UDP packets)
                if not _dns_verify_txid(resp, sent_txid):
                    log("DEBUG",
                        f"[DNS-txid] mismatch for {domain} "
                        f"(sent={sent_txid.hex()} got={resp[:2].hex() if len(resp)>=2 else 'short'})"
                        " — response discarded")
                    return []
                return self._parse_dns_response(resp, qtype_code)
            except Exception:
                return []

    async def _query_doh(self, domain: str, qtype: str = "A") -> list:
        """Fallback: DNS-over-HTTPS via Cloudflare DoH."""
        try:
            url = f"https://cloudflare-dns.com/dns-query?name={domain}&type={qtype}"
            import aiohttp
            async with aiohttp.ClientSession() as sess:
                async with sess.get(
                    url,
                    headers={"Accept": "application/dns-json"},
                    timeout=aiohttp.ClientTimeout(total=5),
                    ssl=False,
                ) as resp:
                    if resp.status == 200:
                        data = await resp.json(content_type=None)
                        answers = []
                        for ans in data.get("Answer", []):
                            answers.append({
                                "type": qtype,
                                "value": ans.get("data", ""),
                            })
                        return answers
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        return []

    async def _detect_wildcard(self, domain: str):
        """Detect if domain has wildcard DNS (all subdomains resolve)."""
        random_sub = f"{secrets.token_hex(12)}.{domain}"
        records    = await self._query(random_sub, "A")
        if not records:
            records = await self._query_doh(random_sub, "A")
        for r in records:
            if r["type"] == "A":
                self._wildcard_ips.add(r["value"])

    async def _probe_subdomain(self, domain: str, subdomain: str) -> Optional[dict]:
        """Probe a single subdomain. Returns result dict or None."""
        fqdn    = f"{subdomain}.{domain}"
        records = await self._query(fqdn, "A")
        if not records:
            records = await self._query_doh(fqdn, "A")

        ips = [r["value"] for r in records if r["type"] == "A"]
        if not ips:
            # Try CNAME
            cnames = await self._query(fqdn, "CNAME")
            if cnames:
                cname_val = cnames[0]["value"]
                return {"fqdn": fqdn, "ips": [], "cname": cname_val}
            return None

        # Filter wildcard IPs
        real_ips = [ip for ip in ips if ip not in self._wildcard_ips]
        if not real_ips:
            return None

        return {"fqdn": fqdn, "ips": real_ips, "cname": None}

    async def enumerate_records(self, domain: str) -> dict:
        """Full DNS record enumeration for a domain."""
        results = {}
        for qtype in ["A", "AAAA", "MX", "TXT", "NS", "SOA", "CNAME"]:
            records = await self._query(domain, qtype)
            if not records:
                records = await self._query_doh(domain, qtype)
            if records:
                results[qtype] = [r["value"] for r in records]
        return results

    async def brute_force_subdomains(self, domain: str) -> list:
        """Brute-force subdomain discovery."""
        await self._detect_wildcard(domain)
        if self._wildcard_ips:
            log("WARN", f"[DNSIntel] Wildcard DNS detected: {self._wildcard_ips} — filtering")

        tasks   = [self._probe_subdomain(domain, sub) for sub in self.SUBDOMAIN_WORDLIST]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        found   = [r for r in results if r and not isinstance(r, Exception)]
        return found

    async def scan(self, client: "WebScoutClient", target: str) -> list:
        """Full DNS intelligence scan. Returns Finding list."""
        parsed = urlparse(target)
        domain = parsed.hostname or target
        # Strip 'www.' prefix for apex enumeration
        if domain.startswith("www."):
            domain = domain[4:]

        findings = []
        log("INFO", f"[DNSIntel] Enumerating DNS records for {domain}")

        # ── Record enumeration ─────────────────────────────────────────
        records = await self.enumerate_records(domain)
        if records:
            findings.append(Finding(
                plugin="dns_intelligence",
                title=f"DNS Records Enumerated: {domain}",
                severity="INFO",
                confidence=100.0,
                description=f"Complete DNS record enumeration for {domain}.",
                evidence="\n".join(f"{t}: {', '.join(v[:3])}" for t, v in records.items()),
                url=target,
                tags=["dns", "enumeration", "records"],
            ))

        # ── SPF/DMARC/DKIM analysis ────────────────────────────────────
        txt_records = records.get("TXT", [])
        spf_found   = any("v=spf1" in r.lower() for r in txt_records)
        dmarc_r     = await self._query(f"_dmarc.{domain}", "TXT")
        dkim_r      = await self._query(f"default._domainkey.{domain}", "TXT")
        dmarc_found = bool(dmarc_r)

        if not spf_found:
            findings.append(Finding(
                plugin="dns_intelligence",
                title="Missing SPF Record",
                severity="MEDIUM",
                confidence=95.0,
                description=f"Domain {domain} has no SPF TXT record. Email spoofing is possible.",
                evidence=f"No 'v=spf1' TXT record found for {domain}",
                url=target,
                remediation="Add an SPF record: example: v=spf1 include:_spf.google.com ~all",
                cwe="CWE-290", cvss=5.4, owasp="A07",
                tags=["dns", "spf", "email-spoofing"],
            ))
        if not dmarc_found:
            findings.append(Finding(
                plugin="dns_intelligence",
                title="Missing DMARC Record",
                severity="MEDIUM",
                confidence=95.0,
                description=f"Domain {domain} has no DMARC policy. Email can be spoofed without rejection.",
                evidence=f"No TXT record at _dmarc.{domain}",
                url=target,
                remediation="Add DMARC record: _dmarc.DOMAIN. IN TXT \"v=DMARC1; p=reject; rua=mailto:...\"",
                cwe="CWE-290", cvss=5.4, owasp="A07",
                tags=["dns", "dmarc", "email-spoofing"],
            ))
        else:
            dmarc_txt = " ".join(r["value"] for r in dmarc_r)
            if "p=none" in dmarc_txt.lower():
                findings.append(Finding(
                    plugin="dns_intelligence",
                    title="DMARC Policy Set to 'none' (No Enforcement)",
                    severity="LOW",
                    confidence=95.0,
                    description=f"DMARC policy is monitoring-only (p=none). Spoofed emails are not rejected.",
                    evidence=f"DMARC: {dmarc_txt[:150]}",
                    url=target,
                    remediation="Change DMARC policy to p=quarantine or p=reject.",
                    cwe="CWE-290", cvss=3.7, owasp="A07",
                    tags=["dns", "dmarc", "weak-policy"],
                ))

        # ── Zone transfer attempt ──────────────────────────────────────
        ns_records = records.get("NS", [])
        for ns in ns_records[:3]:
            ns_clean = ns.rstrip(".")
            try:
                loop = asyncio.get_event_loop()
                def _axfr_probe():
                    try:
                        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                        s.settimeout(5)
                        s.connect((ns_clean, 53))
                        # Build AXFR query over TCP
                        axfr_pkt = self._build_dns_query(domain, self.DNS_TYPES["ANY"])
                        length_prefix = len(axfr_pkt).to_bytes(2, "big")
                        s.sendall(length_prefix + axfr_pkt)
                        resp = s.recv(4096)
                        s.close()
                        return resp
                    except Exception:
                        return b""
                resp = await asyncio.wait_for(
                    loop.run_in_executor(None, _axfr_probe), timeout=6
                )
                if resp and len(resp) > 100:
                    findings.append(Finding(
                        plugin="dns_intelligence",
                        title=f"DNS Zone Transfer Possible via {ns_clean}",
                        severity="HIGH",
                        confidence=85.0,
                        description=(
                            f"Nameserver {ns_clean} appears to allow AXFR zone transfer. "
                            "This leaks all DNS records for the domain."
                        ),
                        evidence=f"AXFR response received ({len(resp)} bytes) from {ns_clean}",
                        url=target,
                        remediation="Restrict AXFR to authorized secondary name servers only.",
                        cwe="CWE-200", cvss=7.5, owasp="A05",
                        tags=["dns", "zone-transfer", "axfr"],
                    ))
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        # ── Subdomain brute force ──────────────────────────────────────
        log("INFO", f"[DNSIntel] Brute-forcing {len(self.SUBDOMAIN_WORDLIST)} subdomains")
        subs_found = await self.brute_force_subdomains(domain)

        if subs_found:
            findings.append(Finding(
                plugin="dns_intelligence",
                title=f"Subdomains Discovered: {len(subs_found)}",
                severity="INFO",
                confidence=99.0,
                description=f"DNS brute-force found {len(subs_found)} live subdomains.",
                evidence="\n".join(
                    f"{s['fqdn']} → {', '.join(s['ips'][:2]) or s.get('cname','')}"
                    for s in subs_found[:20]
                ),
                url=target,
                tags=["dns", "subdomains", "enumeration"],
            ))

        # ── Subdomain takeover detection ───────────────────────────────
        for sub in subs_found:
            cname = sub.get("cname", "") or ""
            for sig, provider in self.TAKEOVER_SIGNATURES.items():
                if sig in cname:
                    # Verify the target doesn't exist
                    try:
                        r = await client.get(f"https://{sub['fqdn']}")
                        body = (r or {}).get("text", "")
                        if any(x in body.lower() for x in [
                            "there is no app", "no such app", "project not found",
                            "not found", "error 404", "doesn't exist", "no such bucket",
                            "repository not found", "domain not configured",
                        ]):
                            findings.append(Finding(
                                plugin="dns_intelligence",
                                title=f"Subdomain Takeover Risk: {sub['fqdn']}",
                                severity="CRITICAL",
                                confidence=90.0,
                                description=(
                                    f"Subdomain {sub['fqdn']} points to {provider} ({cname}) "
                                    "but the resource no longer exists. An attacker can register "
                                    "this resource and serve malicious content under your domain."
                                ),
                                evidence=f"CNAME: {cname} → {provider}\nResponse suggests unclaimed resource",
                                url=f"https://{sub['fqdn']}",
                                remediation=(
                                    f"Remove the CNAME record for {sub['fqdn']} or reclaim the "
                                    f"{provider} resource immediately."
                                ),
                                cwe="CWE-350", cvss=9.3, owasp="A05",
                                tags=["dns", "subdomain-takeover", provider.lower()],
                            ))
                    except Exception as _silenced_exc:
                        log("DEBUG", f"[suppressed] {_silenced_exc}")
        log("OK", f"[DNSIntel] Done — {len(findings)} DNS finding(s)")
        return findings


