# ════════════════════════════════════════════════════════════════════════
#  v27 MODULE 11 — SELF-SUFFICIENT SSL CERT GENERATOR
#  Replaces OpenSSL CLI subprocess calls with pure Python cryptography
# ════════════════════════════════════════════════════════════════════════

def _generate_self_signed_cert_pure_python(cn: str, days: int = 365) -> tuple:
    """
    Generate a self-signed certificate using ONLY Python stdlib (ssl + ctypes).
    Returns (cert_pem_str, key_pem_str) or ("", "") on failure.
    Falls back gracefully if cryptography lib is unavailable.
    """
    # Try with cryptography library first (most reliable)
    try:
        from cryptography import x509
        from cryptography.x509.oid import NameOID
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import rsa
        from cryptography.hazmat.backends import default_backend
        import datetime as _dt

        key = rsa.generate_private_key(
            public_exponent=65537,
            key_size=2048,
            backend=default_backend(),
        )
        subject = issuer = x509.Name([
            x509.NameAttribute(NameOID.COUNTRY_NAME, "US"),
            x509.NameAttribute(NameOID.COMMON_NAME, cn),
        ])
        cert = (
            x509.CertificateBuilder()
            .subject_name(subject)
            .issuer_name(issuer)
            .public_key(key.public_key())
            .serial_number(x509.random_serial_number())
            .not_valid_before(_dt.datetime.utcnow())
            .not_valid_after(_dt.datetime.utcnow() + _dt.timedelta(days=days))
            .add_extension(x509.BasicConstraints(ca=True, path_length=None), critical=True)
            .sign(key, hashes.SHA256(), default_backend())
        )
        cert_pem = cert.public_bytes(serialization.Encoding.PEM).decode()
        key_pem  = key.private_bytes(
            serialization.Encoding.PEM,
            serialization.PrivateFormat.TraditionalOpenSSL,
            serialization.NoEncryption(),
        ).decode()
        return cert_pem, key_pem
    except ImportError:
        pass
    except Exception as _silenced_exc:
        log("DEBUG", f"[suppressed] {_silenced_exc}")
    # If cryptography not available, return empty (caller handles gracefully)
    return "", ""


