# ────────────────────────────────────────────────────────────────────────────
#  1. TTL MANIPULATION
#  Send probes with carefully chosen TTL values to confuse IDS systems that
#  rely on hop-count whitelisting or TTL-based session tracking.
# ────────────────────────────────────────────────────────────────────────────
class TTLManipulator:
    """
    Varies the IP TTL on outgoing packets to evade IDS/IPS systems that
    use TTL to reconstruct TCP sessions or whitelist known hop-counts.

    Strategy
    --------
    - DECOY mode  : send ghost packets with TTL just below server distance
                    (they die before reaching the server, confuse mid-path IDS)
    - MIMIC mode  : set TTL to match a specific OS fingerprint (64=Linux,
                    128=Windows, 255=network device)
    - RANDOM mode : randomise TTL within a plausible range each request
    """

    OS_TTL = {
        "linux":   64,
        "windows": 128,
        "bsd":     64,
        "ios":     64,
        "network": 255,
        "solaris": 255,
    }

    def __init__(self, target_ip: str, mode: str = "mimic", mimic_os: str = "linux"):
        self.target_ip = target_ip
        self.mode      = mode.lower()
        self.mimic_os  = mimic_os.lower()
        self._hops     = None          # estimated hops to target

    def estimate_hops(self) -> int:
        """Estimate hop count to target via ICMP TTL exceeded messages."""
        if not HAS_SCAPY:
            return 10   # safe default
        try:
            for ttl in range(1, 32):
                pkt = _scapy.IP(dst=self.target_ip, ttl=ttl) / _scapy.ICMP()
                reply = _scapy.sr1(pkt, timeout=1, verbose=0)
                if reply and reply.src == self.target_ip:
                    self._hops = ttl
                    return ttl
                if reply and reply.type == 0:   # echo reply — we got there
                    self._hops = ttl
                    return ttl
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        self._hops = 10
        return self._hops

    def get_ttl(self) -> int:
        if self.mode == "mimic":
            return self.OS_TTL.get(self.mimic_os, 64)
        if self.mode == "random":
            return random.randint(48, 128)
        if self.mode == "decoy":
            hops = self._hops or self.estimate_hops()
            # TTL that dies 1 hop before target  →  confuses mid-path IDS
            return max(1, hops - 1)
        return 64

    def craft_decoy_burst(self, payload: bytes, count: int = 5) -> list:
        """
        Return a list of Scapy packets with TTL values that die before the
        target.  Send these BEFORE the real packet to confuse stateful IDS.
        """
        if not HAS_SCAPY:
            return []
        hops = self._hops or self.estimate_hops()
        pkts = []
        for _ in range(count):
            ttl = random.randint(1, max(1, hops - 1))
            pkt = _scapy.IP(dst=self.target_ip, ttl=ttl) /                     _scapy.TCP(dport=443, flags="S") /                     _scapy.Raw(load=payload)
            pkts.append(pkt)
        return pkts


# ────────────────────────────────────────────────────────────────────────────
#  2. TCP WINDOW SIZE MANIPULATION
#  Many WAFs fingerprint clients via TCP window size.  Spoofing the window
#  size makes the scanner look like a browser or specific OS.
# ────────────────────────────────────────────────────────────────────────────
class TCPWindowManipulator:
    """
    Overrides the TCP receive window size advertised in SYN packets to:
      a) defeat OS-based fingerprinting by WAFs
      b) trigger slow-path processing in some IDS implementations
      c) mimic specific browsers or operating systems
    """

    # Real-world window sizes observed from popular OSes/browsers
    PROFILES = {
        "chrome_linux":   65535,
        "chrome_windows": 64240,
        "firefox":        65535,
        "safari":         65535,
        "ios":            65535,
        "android":        29200,
        "windows10":      64240,
        "linux_kernel":   29200,
        "tiny":           512,      # triggers slow-path on some IDS
        "zero":           0,        # RST bait / evasion probe
    }

    def __init__(self, profile: str = "chrome_linux"):
        self.profile  = profile
        self.win_size = self.PROFILES.get(profile, 65535)

    def get_window(self) -> int:
        return self.win_size

    def randomise(self) -> int:
        """Return a plausible random window size."""
        self.win_size = random.choice(list(self.PROFILES.values()))
        return self.win_size

    def apply_to_socket(self, sock: socket.socket):
        """
        Apply window size via SO_RCVBUF (influences advertised window).
        Note: full control requires raw sockets (see RawTCPStack below).
        """
        try:
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, self.win_size)
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")


# ────────────────────────────────────────────────────────────────────────────
#  3. IP FRAGMENTATION
#  Split the HTTP request across multiple IP fragments so each fragment is
#  too small for the IDS to inspect independently.
# ────────────────────────────────────────────────────────────────────────────
class IPFragmenter:
    """
    Fragments IP packets carrying the HTTP payload into small chunks.
    Many IDS/IPS systems only inspect the first fragment (which contains
    the TCP header but not the full payload), effectively blinding them.

    Requires raw sockets and Scapy.
    """

    def __init__(self, target_ip: str, target_port: int = 443,
                 frag_size: int = 8):
        self.target_ip   = target_ip
        self.target_port = target_port
        self.frag_size   = frag_size   # bytes per fragment (multiples of 8)

    def send_fragmented(self, payload: bytes, src_port: int = None) -> bool:
        """
        Fragment and send an IP payload to the target.
        Returns True on success.
        """
        if not HAS_SCAPY:
            log("WARN", "[IPFragmenter] scapy required for fragmentation")
            return False
        try:
            src_port = src_port or random.randint(49152, 65535)
            ip   = _scapy.IP(dst=self.target_ip)
            tcp  = _scapy.TCP(dport=self.target_port, sport=src_port, flags="PA")
            pkt  = ip / tcp / _scapy.Raw(load=payload)
            # Fragment at IP layer
            frags = _scapy.fragment(pkt, fragsize=self.frag_size)
            _scapy.send(frags, verbose=0)
            return True
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
            return False

    def probe_fragmentation_support(self) -> dict:
        """Check if the target re-assembles fragments (IDS blind-spot test)."""
        if not HAS_SCAPY:
            return {"supported": None, "reason": "scapy missing"}
        result = {"frag_size": self.frag_size, "sent": False, "echo": False}
        try:
            probe   = b"GET / HTTP/1.0\r\nHost: probe\r\n\r\n"
            success = self.send_fragmented(probe)
            result["sent"] = success
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        return result


# ────────────────────────────────────────────────────────────────────────────
#  4. TCP OPTIONS OBFUSCATION
#  Forge unusual or contradictory TCP option fields.  Some IDS implementations
#  parse options incorrectly, causing them to mis-classify or drop the session.
# ────────────────────────────────────────────────────────────────────────────
class TCPOptionsObfuscator:
    """
    Builds exotic TCP option combinations to:
      - Defeat IDS TCP session reconstruction
      - Confuse WAF fingerprinting logic
      - Trigger parsing bugs in older IDS software

    Options injected:
      - Timestamp with skewed values (evades timestamp-based rate limiting)
      - NOP sled padding
      - Window Scale with unusual multiplier
      - SACK Permitted
      - MD5 Signature option (RFC 2385) — most IDS ignore it
    """

    @staticmethod
    def build_options(skew_ts: bool = True,
                      fake_md5: bool = False,
                      large_scale: bool = False) -> list:
        """Return a list of Scapy-compatible TCP options."""
        ts_val = int(time.time())
        if skew_ts:
            # Add random jitter to disguise scan timing
            ts_val += random.randint(-3600, 3600)

        options = [
            ("NOP",        None),
            ("NOP",        None),
            ("Timestamp",  (ts_val, 0)),
            ("SAckOK",     b""),
            ("WScale",     14 if large_scale else random.choice([6, 7, 8])),
        ]
        if fake_md5:
            # RFC 2385 MD5 option (kind=19) — injected as raw bytes
            fake_sig = random.randbytes(16)
            options.append(("MD5header", fake_sig))
        return options

    @staticmethod
    def apply_to_scapy_packet(pkt, **kwargs):
        """Inject obfuscated options into a Scapy TCP layer."""
        if not HAS_SCAPY:
            return pkt
        try:
            pkt[_scapy.TCP].options = TCPOptionsObfuscator.build_options(**kwargs)
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        return pkt


# ────────────────────────────────────────────────────────────────────────────
#  5. CUSTOM RAW TCP STACK
#  Full raw-socket TCP handshake without the OS TCP/IP stack.
#  Gives complete control over every byte of the TCP/IP header.
# ────────────────────────────────────────────────────────────────────────────
class RawTCPStack:
    """
    Implements a minimal TCP client using raw sockets (IPPROTO_RAW).
    Bypasses the OS network stack, giving full control over:
      - IP TTL, flags, ID, TOS
      - TCP sequence numbers, window size, options, flags
      - Packet timing and interleaving

    Requires root/CAP_NET_RAW privileges.
    """

    def __init__(self, dst_ip: str, dst_port: int,
                 src_ip: str = None,
                 ttl: int = 64,
                 window: int = 65535):
        self.dst_ip   = dst_ip
        self.dst_port = dst_port
        self.src_ip   = src_ip or self._local_ip()
        self.ttl      = ttl
        self.window   = window
        self.src_port = random.randint(49152, 65535)
        self.seq      = random.randint(0, 2**32 - 1)
        self.ack      = 0

    @staticmethod
    def _local_ip() -> str:
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            s.connect(("8.8.8.8", 80))
            ip = s.getsockname()[0]
            s.close()
            return ip
        except Exception:
            return "127.0.0.1"

    def _checksum(self, data: bytes) -> int:
        if len(data) % 2:
            data += b"\x00"
        total = 0
        for i in range(0, len(data), 2):
            total += (data[i] << 8) + data[i + 1]
        total  = (total >> 16) + (total & 0xFFFF)
        total += total >> 16
        return ~total & 0xFFFF

    def _build_ip_header(self, payload_len: int, protocol: int = 6) -> bytes:
        ip_id    = random.randint(0, 65535)
        ihl      = 5
        version  = 4
        tos      = 0
        tot_len  = 20 + payload_len
        frag_off = 0
        proto    = protocol
        checksum = 0
        src      = socket.inet_aton(self.src_ip)
        dst      = socket.inet_aton(self.dst_ip)
        header   = struct.pack("!BBHHHBBH4s4s",
                               (version << 4) | ihl, tos, tot_len,
                               ip_id, frag_off, self.ttl, proto,
                               checksum, src, dst)
        checksum = self._checksum(header)
        return struct.pack("!BBHHHBBH4s4s",
                           (version << 4) | ihl, tos, tot_len,
                           ip_id, frag_off, self.ttl, proto,
                           checksum, src, dst)

    def _build_tcp_header(self, flags: int, data: bytes = b"") -> bytes:
        offset   = 5          # data offset (header length / 4)
        checksum = 0
        urg_ptr  = 0
        header   = struct.pack("!HHLLBBHHH",
                               self.src_port, self.dst_port,
                               self.seq, self.ack,
                               (offset << 4), flags, self.window,
                               checksum, urg_ptr)
        # Pseudo-header for checksum
        pseudo   = struct.pack("!4s4sBBH",
                               socket.inet_aton(self.src_ip),
                               socket.inet_aton(self.dst_ip),
                               0, 6, len(header) + len(data))
        checksum = self._checksum(pseudo + header + data)
        return struct.pack("!HHLLBBHHH",
                           self.src_port, self.dst_port,
                           self.seq, self.ack,
                           (offset << 4), flags, self.window,
                           checksum, urg_ptr)

    def syn(self) -> bool:
        """Send SYN packet (raw socket). Returns True if privileged enough."""
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_RAW,
                                 socket.IPPROTO_RAW)
            sock.setsockopt(socket.IPPROTO_IP, socket.IP_HDRINCL, 1)
            tcp  = self._build_tcp_header(0x02)   # SYN flag
            ip   = self._build_ip_header(len(tcp))
            sock.sendto(ip + tcp, (self.dst_ip, 0))
            sock.close()
            self.seq += 1
            return True
        except PermissionError:
            log("WARN", "[RawTCPStack] Root privileges required for raw sockets")
            return False
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
            return False

    def send_data(self, payload: bytes) -> bool:
        """Send data over raw TCP (PSH+ACK)."""
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_RAW,
                                 socket.IPPROTO_RAW)
            sock.setsockopt(socket.IPPROTO_IP, socket.IP_HDRINCL, 1)
            tcp  = self._build_tcp_header(0x18, payload)  # PSH+ACK
            ip   = self._build_ip_header(len(tcp) + len(payload))
            sock.sendto(ip + tcp + payload, (self.dst_ip, 0))
            sock.close()
            self.seq += len(payload)
            return True
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
            return False


# ────────────────────────────────────────────────────────────────────────────
#  6. TCP CONGESTION CONTROL MIMIC
#  Simulate a congested TCP connection: slow start, drip-feed, random delays.
#  This causes IDS reassembly timeouts and defeats rate-based detection.
# ────────────────────────────────────────────────────────────────────────────
class CongestionMimic:
    """
    Mimics TCP slow-start and congestion avoidance behaviour to:
      - Evade rate-based IDS/IPS signatures
      - Defeat time-window correlation in WAF rule engines
      - Look like a legitimate congested TCP connection

    Usage
    -----
    cm = CongestionMimic(sock)
    cm.send_slow(b"GET / HTTP/1.1\r\nHost: target\r\n\r\n")
    """

    def __init__(self, sock: socket.socket,
                 initial_cwnd: int = 1,
                 mss: int = 1460,
                 jitter_ms: float = 50.0):
        self.sock       = sock
        self.cwnd       = initial_cwnd   # congestion window (in MSS units)
        self.mss        = mss
        self.jitter_ms  = jitter_ms
        self.ssthresh   = 64             # slow-start threshold
        self._sent      = 0

    def _jitter(self):
        jitter = random.uniform(0, self.jitter_ms / 1000.0)
        time.sleep(jitter)

    def _slow_start_step(self):
        """Double cwnd each round-trip (slow-start phase)."""
        if self.cwnd < self.ssthresh:
            self.cwnd = min(self.cwnd * 2, self.ssthresh)
        else:
            self.cwnd += 1

    def send_slow(self, data: bytes) -> int:
        """
        Send data by drip-feeding chunks sized according to the current
        congestion window.  Returns total bytes sent.
        """
        offset = 0
        while offset < len(data):
            chunk_size = self.cwnd * self.mss
            chunk      = data[offset:offset + chunk_size]
            try:
                self.sock.sendall(chunk)
                self._sent  += len(chunk)
                offset      += len(chunk)
                self._jitter()
                self._slow_start_step()
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
                break
        return self._sent

    def simulate_retransmit(self):
        """Trigger a simulated retransmit event — halve cwnd (like a real loss)."""
        self.ssthresh = max(self.cwnd // 2, 2)
        self.cwnd     = 1
        time.sleep(random.uniform(0.2, 1.0))


# ────────────────────────────────────────────────────────────────────────────
#  7. REAL ORIGIN IP DISCOVERY
#  Find the actual server IP behind a CDN (Cloudflare, Akamai, Fastly, etc.)
#  or WAF and open a direct connection that bypasses the protection layer.
# ────────────────────────────────────────────────────────────────────────────
class OriginIPDiscovery:
    """
    Attempts to discover the real origin server IP behind a CDN or WAF using
    multiple passive and active techniques:

      T1  DNS history (SecurityTrails-style historic records)
      T2  SSL certificate Subject Alternative Names
      T3  Subdomain enumeration (common patterns)
      T4  HTTP header leakage (X-Origin-IP, X-Backend-Server, Via, etc.)
      T5  Email header origin (MX → SPF → A record chain)
      T6  Favicon hash matching against Shodan
      T7  Direct IP range scan (ASN-filtered, port 80/443)
      T8  HTTPS SNI bypass (connect to IP, send original Host header)

    Once a candidate IP is found, it is verified by sending the original
    Host header directly to the IP to confirm a matching response.
    """

    LEAKAGE_HEADERS = [
        "X-Origin-IP", "X-Real-IP", "X-Backend-Server",
        "X-Forwarded-Server", "X-Served-By", "X-Cache",
        "CF-RAY", "Via", "X-Powered-By", "Server",
        "X-Varnish", "X-Cache-Hits", "X-Drupal-Cache",
        "X-Proxy-Cache", "X-WP-Total-Pages",
    ]

    CDN_RANGES = {
        "cloudflare": [
            "103.21.244.0/22", "103.22.200.0/22", "103.31.4.0/22",
            "104.16.0.0/13",   "104.24.0.0/14",   "108.162.192.0/18",
            "131.0.72.0/22",   "141.101.64.0/18",  "162.158.0.0/15",
            "172.64.0.0/13",   "173.245.48.0/20",  "188.114.96.0/20",
            "190.93.240.0/20", "197.234.240.0/22", "198.41.128.0/17",
        ],
        "akamai":    ["23.0.0.0/12", "23.32.0.0/11", "104.64.0.0/10"],
        "fastly":    ["23.235.32.0/20", "199.27.72.0/21", "185.31.16.0/22"],
        "cloudfront":["13.32.0.0/15", "13.35.0.0/16", "52.84.0.0/15"],
    }

    def __init__(self, target: str, timeout: int = 5):
        # target may be a URL or hostname
        self.target   = target.rstrip("/")
        self.hostname = target.split("//")[-1].split("/")[0].split(":")[0]
        self.timeout  = timeout
        self.candidates: list[dict] = []

    # ── T1: Current DNS resolution ──────────────────────────────────────────
    def _t1_current_dns(self) -> list[str]:
        ips = []
        try:
            results = socket.getaddrinfo(self.hostname, None)
            ips = list({r[4][0] for r in results})
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        return ips

    # ── T2: SSL certificate SANs ────────────────────────────────────────────
    def _t2_ssl_sans(self) -> list[str]:
        """Extract IPs listed in the SSL certificate SAN field."""
        ips = []
        try:
            ctx  = ssl.create_default_context()
            ctx.check_hostname = False
            ctx.verify_mode    = ssl.CERT_NONE
            with socket.create_connection((self.hostname, 443),
                                          timeout=self.timeout) as raw:
                with ctx.wrap_socket(raw, server_hostname=self.hostname) as tls:
                    cert = tls.getpeercert()
                    for san_type, san_val in cert.get("subjectAltName", []):
                        if san_type == "IP Address":
                            ips.append(san_val)
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        return ips

    # ── T3: Common subdomain DNS probes ─────────────────────────────────────
    def _t3_subdomain_probe(self) -> list[str]:
        """Probe common subdomains that often bypass CDN (direct/origin/backend)."""
        BYPASS_SUBS = [
            "direct", "origin", "backend", "server", "real",
            "admin", "staging", "dev", "internal", "api",
            "mail", "smtp", "ftp", "cpanel", "webmail",
            "dashboard", "portal", "app", "static", "media",
        ]
        parts  = self.hostname.split(".")
        domain = ".".join(parts[-2:]) if len(parts) >= 2 else self.hostname
        ips    = []
        for sub in BYPASS_SUBS:
            fqdn = f"{sub}.{domain}"
            try:
                ip = socket.gethostbyname(fqdn)
                if ip and not self._is_cdn(ip):
                    ips.append(ip)
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
        return list(set(ips))

    # ── T4: HTTP header leakage ──────────────────────────────────────────────
    def _t4_header_leakage(self, response_headers: dict) -> list[str]:
        """Extract IP addresses leaked in HTTP response headers."""
        import re as _re
        ips = []
        ip_re = _re.compile(
            r"\b(?:(?:25[0-5]|2[0-4]\d|[01]?\d\d?)\.){3}"
            r"(?:25[0-5]|2[0-4]\d|[01]?\d\d?)\b"
        )
        for hdr in self.LEAKAGE_HEADERS:
            val = response_headers.get(hdr, "")
            if val:
                for match in ip_re.findall(val):
                    try:
                        ipaddress.ip_address(match)
                        if not ipaddress.ip_address(match).is_private:
                            ips.append(match)
                    except Exception as _silenced_exc:
                        log("DEBUG", f"[suppressed] {_silenced_exc}")
        return ips

    # ── T5: SPF record → IP extraction ──────────────────────────────────────
    def _t5_spf_ips(self) -> list[str]:
        """Parse SPF TXT records to find mail server IPs (often same origin)."""
        if not HAS_DNSPYTHON:
            return []
        ips = []
        try:
            parts  = self.hostname.split(".")
            domain = ".".join(parts[-2:])
            answers = _dns_resolver.resolve(domain, "TXT")
            for rdata in answers:
                txt = b" ".join(rdata.strings).decode("utf-8", errors="ignore")
                if "v=spf1" in txt:
                    # Extract ip4: directives
                    import re as _re
                    for ip4 in _re.findall(r"ip4:([\d\.]+(?:/\d+)?)", txt):
                        base = ip4.split("/")[0]
                        try:
                            ipaddress.ip_address(base)
                            ips.append(base)
                        except Exception as _silenced_exc:
                            log("DEBUG", f"[suppressed] {_silenced_exc}")
                    # Resolve include: domains
                    for inc in _re.findall(r"include:(\S+)", txt):
                        try:
                            ip = socket.gethostbyname(inc)
                            if ip:
                                ips.append(ip)
                        except Exception as _silenced_exc:
                            log("DEBUG", f"[suppressed] {_silenced_exc}")
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        return list(set(ips))

    # ── T6: Favicon hash ────────────────────────────────────────────────────
    def _t6_favicon_hash(self, favicon_bytes: bytes) -> str:
        """
        Compute the MurmurHash3 of a favicon (Shodan-style).
        The hash can be used offline against Shodan to find the origin IP.
        """
        import base64 as _b64
        b64 = _b64.encodebytes(favicon_bytes).decode()
        # Shodan uses a custom mmh3 — approximated here with SHA256 prefix
        return hashlib.sha256(b64.encode()).hexdigest()[:16]

    # ── T7: CDN IP range check ───────────────────────────────────────────────
    def _is_cdn(self, ip: str) -> bool:
        """Return True if the IP belongs to a known CDN range."""
        try:
            addr = ipaddress.ip_address(ip)
            for cdn, ranges in self.CDN_RANGES.items():
                for cidr in ranges:
                    if addr in ipaddress.ip_network(cidr, strict=False):
                        return True
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        return False

    # ── T8: SNI bypass verification ──────────────────────────────────────────
    def verify_origin(self, ip: str, port: int = 443) -> dict:
        """
        Connect directly to candidate IP, send original Host header,
        compare response fingerprint to the CDN-fronted response.
        """
        result = {"ip": ip, "port": port, "verified": False,
                  "status": None, "server": None}
        try:
            ctx = ssl.create_default_context()
            ctx.check_hostname = False
            ctx.verify_mode    = ssl.CERT_NONE
            with socket.create_connection((ip, port),
                                          timeout=self.timeout) as raw:
                with ctx.wrap_socket(raw, server_hostname=self.hostname) as tls:
                    req = (
                        f"GET / HTTP/1.1\r\n"
                        f"Host: {self.hostname}\r\n"
                        f"User-Agent: Mozilla/5.0 (compatible; WebScout/28)\r\n"
                        f"Connection: close\r\n\r\n"
                    ).encode()
                    tls.sendall(req)
                    resp = b""
                    while True:
                        chunk = tls.recv(4096)
                        if not chunk:
                            break
                        resp += chunk
                        if len(resp) > 16384:
                            break
            lines  = resp.split(b"\r\n")
            status = lines[0].decode(errors="ignore") if lines else ""
            hdrs   = {}
            for line in lines[1:]:
                if b":" in line:
                    k, _, v = line.partition(b":")
                    hdrs[k.decode(errors="ignore").strip().lower()] =                           v.decode(errors="ignore").strip()
            result["verified"] = "HTTP/" in status
            result["status"]   = status
            result["server"]   = hdrs.get("server", "unknown")
            result["headers"]  = hdrs
        except Exception as _silenced_exc:
            log("DEBUG", f"[suppressed] {_silenced_exc}")
        return result

    # ── Main Discovery Runner ────────────────────────────────────────────────
    async def discover(self, response_headers: dict = None) -> dict:
        """
        Run all discovery techniques and return a structured report.
        """
        report = {
            "hostname":    self.hostname,
            "candidates":  [],
            "confirmed":   [],
            "cdn_detected": False,
            "techniques":  {},
        }

        # T1
        t1 = self._t1_current_dns()
        report["techniques"]["T1_current_dns"] = t1
        cdn_fronted = [ip for ip in t1 if self._is_cdn(ip)]
        if cdn_fronted:
            report["cdn_detected"] = True
            log("WARN", f"[OriginIP] CDN detected for {self.hostname}: "
                        f"{cdn_fronted}")

        # T2
        t2 = self._t2_ssl_sans()
        report["techniques"]["T2_ssl_sans"] = t2

        # T3
        t3 = self._t3_subdomain_probe()
        report["techniques"]["T3_subdomains"] = t3

        # T4
        t4 = self._t4_header_leakage(response_headers or {})
        report["techniques"]["T4_header_leak"] = t4

        # T5
        t5 = self._t5_spf_ips()
        report["techniques"]["T5_spf"] = t5

        # Aggregate unique candidates (excluding known CDN IPs)
        all_ips = set(t1 + t2 + t3 + t4 + t5)
        non_cdn = [ip for ip in all_ips if not self._is_cdn(ip)]
        report["candidates"] = non_cdn

        if not non_cdn:
            log("WARN", "[OriginIP] No non-CDN candidates found via passive techniques")
        else:
            log("OK", f"[OriginIP] {len(non_cdn)} candidate origin IPs found: "
                      f"{non_cdn[:5]}")

        # T8: Verify each candidate
        for ip in non_cdn[:10]:   # cap at 10 to avoid abuse
            ver = self.verify_origin(ip)
            if ver["verified"]:
                ver["bypass_cmd"] = (
                    f"curl -sk https://{ip}/ "
                    f"-H 'Host: {self.hostname}' "
                    f"--resolve '{self.hostname}:443:{ip}'"
                )
                report["confirmed"].append(ver)
                log("OK", f"[OriginIP] CONFIRMED origin IP: {ip} "
                          f"({ver['server']}) — bypass CDN directly!")

        return report


# ────────────────────────────────────────────────────────────────────────────
#  UNIFIED EVASION ENGINE
#  Orchestrates all 7 techniques in a single convenient class.
# ────────────────────────────────────────────────────────────────────────────
class NetworkEvasionEngine:
    """
    Top-level engine combining all network evasion techniques.

    Usage
    -----
    engine = NetworkEvasionEngine(target_url="https://example.com")
    asyncio.run(engine.run_all())
    """

    def __init__(self, target_url: str,
                 stealth_level: int = 3,
                 mimic_os: str = "chrome_linux"):
        self.target_url = target_url
        host            = target_url.split("//")[-1].split("/")[0]
        self.hostname   = host.split(":")[0]
        self.port       = 443 if "https://" in target_url else 80
        self.stealth    = stealth_level
        self.mimic_os   = mimic_os
        self._ip        = None

    def _resolve(self) -> str:
        if not self._ip:
            try:
                self._ip = socket.gethostbyname(self.hostname)
            except Exception as _silenced_exc:
                log("DEBUG", f"[suppressed] {_silenced_exc}")
                self._ip = self.hostname
        return self._ip

    async def run_all(self) -> dict:
        ip = self._resolve()
        log("INT", f"[NetworkEvasion] Target: {self.hostname} → {ip}")

        results = {
            "target":      self.hostname,
            "resolved_ip": ip,
        }

        # 1. TTL
        ttl_m = TTLManipulator(ip, mode="mimic", mimic_os="linux")
        results["ttl"] = {
            "mode":  "mimic",
            "value": ttl_m.get_ttl(),
        }
        log("OK", f"[TTL] Using TTL={ttl_m.get_ttl()} (OS mimic: linux)")

        # 2. Window size
        win_m = TCPWindowManipulator(profile="chrome_linux")
        results["tcp_window"] = {
            "profile": "chrome_linux",
            "size":    win_m.get_window(),
        }
        log("OK", f"[Window] TCP window={win_m.get_window()} (Chrome/Linux profile)")

        # 3. Options
        opts = TCPOptionsObfuscator.build_options(skew_ts=True)
        results["tcp_options"] = str(opts)
        log("OK", "[Options] Obfuscated TCP options generated")

        # 4. Fragmentation probe (only with scapy)
        if HAS_SCAPY:
            frag = IPFragmenter(ip, self.port, frag_size=8)
            results["fragmentation"] = frag.probe_fragmentation_support()
            log("OK", f"[Frag] Fragment probe sent (size=8 bytes)")
        else:
            results["fragmentation"] = {"skipped": "scapy not installed"}

        # 5. Raw TCP (only if root)
        raw = RawTCPStack(ip, self.port,
                          ttl=ttl_m.get_ttl(),
                          window=win_m.get_window())
        results["raw_tcp"] = {"syn_sent": raw.syn()}

        # 6. Congestion mimic — info only (requires active connection)
        results["congestion_mimic"] = {
            "mode":        "slow_start",
            "initial_cwnd": 1,
            "mss":         1460,
            "jitter_ms":   50,
        }
        log("OK", "[Congestion] Slow-start mimic configured (cwnd=1, mss=1460)")

        # 7. Origin IP discovery
        log("INT", f"[OriginIP] Starting origin IP discovery for {self.hostname}...")
        disc = OriginIPDiscovery(self.target_url, timeout=5)
        results["origin_ip"] = await disc.discover()

        return results



