    async def scan(self, client, target: str) -> list:
        if not HAS_PLAYWRIGHT:
            log("WARN", "[EliteBrowserIntel] playwright not installed — skipping. "
                        "pip install playwright && playwright install chromium")
            return []
        try:
            return await asyncio.wait_for(self._run(target), timeout=600)
        except asyncio.TimeoutError:
            log("WARN", "[EliteBrowserIntel] Timeout after 600s")
            return self._findings
        except Exception as e:
            log("WARN", f"[EliteBrowserIntel] Error: {e}")
            return self._findings

    async def _run(self, target: str) -> list:
        async with async_playwright() as pw:
            browser = await pw.chromium.launch(
                headless=self.headless,
                args=["--no-sandbox", "--disable-setuid-sandbox",
                      "--disable-blink-features=AutomationControlled",
                      "--disable-dev-shm-usage"])
