import base64 as _b64, struct, hmac, hashlib as _hs

class EliteAuthSessionHandler:
    """
    Elite Auth/Session Handling — comprehensive authentication security testing.
    Tests: JWT weaknesses, session fixation, CSRF, cookie security,
           session expiry, parallel session limits, auth bypass.
    """

    _WEAK_JWT_SECRETS = [
        "secret", "password", "123456", "test", "key", "jwt_secret",
        "mysecret", "changeme", "qwerty", "admin", "letmein",
        "", "none", "null", "undefined", "your-256-bit-secret"
    ]

    _COMMON_JWT_ALGORITHMS = ["HS256", "HS384", "HS512", "RS256", "none"]

    async def scan(self, client, target: str) -> list:
        findings = []
        log("INFO", f"[EliteAuth] Analyzing auth/session: {target}")
        try:
            resp = await asyncio.wait_for(client.get(target), timeout=15)
            headers    = dict(resp.headers) if hasattr(resp, 'headers') else {}
            cookies    = self._extract_cookies(resp)
            body       = await resp.text() if hasattr(resp, 'text') else ""

            findings += self._analyze_cookies(cookies, target)
            findings += self._analyze_security_headers(headers, target)
            findings += await self._test_session_fixation(client, target)
            findings += await self._test_jwt_weaknesses(client, target, body, cookies)
            findings += await self._test_auth_bypass(client, target)
            findings += self._analyze_csrf_tokens(body, target)
            findings += await self._test_session_expiry(client, target)
            findings += await self._test_concurrent_sessions(client, target)

        except Exception as e:
            log("WARN", f"[EliteAuth] {e}")
        log("OK", f"[EliteAuth] {len(findings)} findings")
        return findings

    def _extract_cookies(self, resp) -> list:
        cookies = []
        try:
            if hasattr(resp, 'cookies'):
                for k, v in resp.cookies.items():
                    cookies.append({"name": k, "value": str(v)})
            raw = resp.headers.get("set-cookie", "")
            if raw:
                cookies.append({"name": "_raw", "value": raw, "raw": True})
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return cookies

    def _analyze_cookies(self, cookies: list, url: str) -> list:
        findings = []
        is_https = url.startswith("https://")

        raw_cookie_header = ""
        for c in cookies:
            if c.get("raw"):
                raw_cookie_header = c.get("value", "")
                break

        if not raw_cookie_header:
            return findings

        # Parse individual Set-Cookie headers
        parts = raw_cookie_header.lower()
        session_name_patterns = ["session", "sessid", "auth", "jwt", "token",
                                 "sid", "phpsessid", "jsessionid", "aspsessionid"]
        has_session = any(p in parts for p in session_name_patterns)

        if has_session:
            checks = {
                "HttpOnly": ("httponly", "HIGH",
                             "Session cookie missing HttpOnly flag — JavaScript can steal it (XSS risk)."),
                "Secure":   ("secure",   "HIGH" if is_https else "MEDIUM",
                             "Session cookie missing Secure flag — sent over HTTP in plaintext."),
                "SameSite": ("samesite", "MEDIUM",
                             "Session cookie missing SameSite attribute — CSRF risk."),
            }
            for flag, (attr, sev, desc) in checks.items():
                if attr not in parts:
                    findings.append(Finding(
                        title=f"Session Cookie Missing {flag} Flag",
                        url=url, severity=sev,
                        description=desc,
                        evidence=f"Set-Cookie: {raw_cookie_header[:150]}",
                        tags=["auth", "cookie", "session", flag.lower()],
                        confidence=90))

            # Check for predictable session ID
            for c in cookies:
                if any(p in c.get("name","").lower() for p in session_name_patterns):
                    val = c.get("value", "")
                    entropy = self._estimate_entropy(val)
                    if entropy < 50 and len(val) > 0:
                        findings.append(Finding(
                            title=f"Low-Entropy Session ID: {c.get('name')}",
                            url=url, severity="HIGH",
                            description=f"Session cookie '{c.get('name')}' has low entropy "
                                        f"(~{entropy:.0f} bits). May be predictable/brute-forceable.",
                            evidence=f"cookie={c.get('name')} entropy={entropy:.1f}bits",
                            tags=["auth", "session", "entropy", "brute-force"],
                            confidence=75))

        return findings

    def _analyze_security_headers(self, headers: dict, url: str) -> list:
        findings = []
        hl = {k.lower(): v for k, v in headers.items()}

        checks = [
            ("strict-transport-security", "MEDIUM",
             "Missing HSTS header — HTTP downgrade attacks possible."),
            ("x-frame-options", "MEDIUM",
             "Missing X-Frame-Options — clickjacking risk."),
            ("x-content-type-options", "LOW",
             "Missing X-Content-Type-Options — MIME sniffing attack."),
            ("content-security-policy", "MEDIUM",
             "Missing Content-Security-Policy — XSS mitigation absent."),
        ]
        for header, sev, desc in checks:
            if header not in hl:
                findings.append(Finding(
                    title=f"Missing Security Header: {header}",
                    url=url, severity=sev,
                    description=desc,
                    evidence=f"header={header} status=missing",
                    tags=["auth", "security-header", header.replace("-","")],
                    confidence=95))
        return findings

    async def _test_session_fixation(self, client, target: str) -> list:
        findings = []
        try:
            r1 = await asyncio.wait_for(client.get(target), timeout=10)
            cookies_before = dict(r1.cookies) if hasattr(r1,'cookies') else {}
            r2 = await asyncio.wait_for(client.get(target), timeout=10)
            cookies_after  = dict(r2.cookies) if hasattr(r2,'cookies') else {}
            # If session ID is the same across unauthenticated requests
            session_keys = [k for k in cookies_before
                            if any(p in k.lower() for p in ["sess","sid","session"])]
            for k in session_keys:
                if k in cookies_after and cookies_before[k] == cookies_after[k]:
                    findings.append(Finding(
                        title=f"Potentially Static Session ID: {k}",
                        url=target, severity="MEDIUM",
                        description=f"Session cookie '{k}' does not change between requests. "
                                    "If it also doesn't change after login, session fixation exists.",
                        evidence=f"cookie={k} value_stable=True",
                        tags=["auth", "session-fixation", "session"],
                        confidence=55))
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings

    async def _test_jwt_weaknesses(self, client, target: str,
                                    body: str, cookies: list) -> list:
        findings = []
        # Collect JWT tokens from page body and cookies
        jwt_pattern = re.compile(
            r'eyJ[A-Za-z0-9\-_]+\.eyJ[A-Za-z0-9\-_]+\.[A-Za-z0-9\-_]*')
        jwts = jwt_pattern.findall(body)
        for c in cookies:
            val = c.get("value", "")
            if jwt_pattern.match(val):
                jwts.append(val)

        for jwt in jwts[:5]:
            parts = jwt.split(".")
            if len(parts) != 3:
                continue
            try:
                header  = json.loads(_b64.b64decode(
                    parts[0] + "=" * (-len(parts[0]) % 4)))
                payload = json.loads(_b64.b64decode(
                    parts[1] + "=" * (-len(parts[1]) % 4)))
            except Exception:
                continue

            alg = header.get("alg", "")

            # alg=none
            if alg.lower() == "none":
                findings.append(Finding(
                    title="JWT with alg=none (Signature Bypass)",
                    url=target, severity="CRITICAL",
                    description="JWT uses alg=none — no signature verification. "
                                "Any payload can be accepted.",
                    evidence=f"jwt_header={json.dumps(header)}",
                    tags=["auth", "jwt", "alg-none", "bypass"],
                    confidence=95))

            # Weak HS algorithm — try brute force
            if alg.startswith("HS"):
                for secret in self._WEAK_JWT_SECRETS:
                    sig_input = f"{parts[0]}.{parts[1]}".encode()
                    expected  = _b64.urlsafe_b64encode(
                        hmac.new(secret.encode(), sig_input,
                                 _hs.sha256 if alg == "HS256" else
                                 _hs.sha384 if alg == "HS384" else _hs.sha512
                                 ).digest()).rstrip(b"=").decode()
                    if expected == parts[2]:
                        findings.append(Finding(
                            title=f"JWT Signed with Weak Secret: '{secret}'",
                            url=target, severity="CRITICAL",
                            description=f"JWT signature verified with weak secret '{secret}'. "
                                        "Full token forgery possible.",
                            evidence=f"alg={alg} secret={secret!r} payload={json.dumps(payload)[:150]}",
                            tags=["auth", "jwt", "weak-secret", "forgery"],
                            confidence=99))
                        break

            # Check sensitive data in payload
            sensitive_keys = ["password", "secret", "private_key", "credit_card", "ssn"]
            for sk in sensitive_keys:
                if sk in payload:
                    findings.append(Finding(
                        title=f"Sensitive Data in JWT Payload: {sk}",
                        url=target, severity="HIGH",
                        description=f"JWT payload contains sensitive field '{sk}'. "
                                    "JWT payloads are base64-decoded by anyone.",
                        evidence=f"payload_key={sk}",
                        tags=["auth", "jwt", "sensitive-data", "information-disclosure"],
                        confidence=85))

            # Check expiry
            exp = payload.get("exp")
            if exp is None:
                findings.append(Finding(
                    title="JWT Without Expiration (exp) Claim",
                    url=target, severity="HIGH",
                    description="JWT has no 'exp' claim — token never expires. "
                                "Stolen tokens remain valid forever.",
                    evidence=f"payload={json.dumps(payload)[:150]}",
                    tags=["auth", "jwt", "no-expiry"],
                    confidence=90))
            elif isinstance(exp, int) and exp - time.time() > 86400 * 30:
                findings.append(Finding(
                    title="JWT with Excessively Long Expiration",
                    url=target, severity="MEDIUM",
                    description=f"JWT expires in {(exp - time.time()) / 86400:.0f} days. "
                                "Long-lived tokens increase exposure window.",
                    evidence=f"exp={exp} days_remaining={(exp-time.time())/86400:.0f}",
                    tags=["auth", "jwt", "long-expiry"],
                    confidence=80))

        return findings

    async def _test_auth_bypass(self, client, target: str) -> list:
        findings = []
        bypass_headers = [
            {"X-Original-URL": "/admin"},
            {"X-Forwarded-Host": "localhost"},
            {"X-Custom-IP-Authorization": "127.0.0.1"},
            {"X-Originating-IP": "127.0.0.1"},
            {"X-Remote-IP": "127.0.0.1"},
            {"X-Remote-Addr": "127.0.0.1"},
            {"X-Real-IP": "127.0.0.1"},
            {"X-Forwarded-For": "127.0.0.1"},
        ]
        # Try admin endpoint with bypass headers
        base = _urlparse.urlparse(target)
        admin_url = f"{base.scheme}://{base.netloc}/admin"
        try:
            normal = await asyncio.wait_for(client.get(admin_url), timeout=8)
            if normal.status_code == 403:
                for hdrs in bypass_headers[:5]:
                    try:
                        r = await asyncio.wait_for(
                            client.get(admin_url, headers=hdrs), timeout=8)
                        if r.status_code == 200:
                            findings.append(Finding(
                                title=f"Auth Bypass via Header: {list(hdrs.keys())[0]}",
                                url=admin_url, severity="CRITICAL",
                                description=f"Admin endpoint returned 403 normally, but returned "
                                            f"200 with header {list(hdrs.keys())[0]}: {list(hdrs.values())[0]}",
                                evidence=f"header={hdrs} status=200",
                                tags=["auth", "bypass", "header-injection", "admin"],
                                confidence=90))
                    except Exception as _ex:
                        logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings

    def _analyze_csrf_tokens(self, body: str, url: str) -> list:
        findings = []
        # Forms with POST but no visible CSRF token
        forms = re.findall(r'<form[^>]*method=["\']?post["\']?[^>]*>(.*?)</form>',
                           body, re.I | re.S)
        for form_body in forms:
            csrf_found = re.search(
                r'input[^>]+name=["\'](?:_token|csrf|csrfmiddlewaretoken|'
                r'authenticity_token|nonce|__RequestVerificationToken)["\']',
                form_body, re.I)
            if not csrf_found:
                action = re.search(r'<form[^>]+action=["\']([^"\']+)["\']', body, re.I)
                action_url = action.group(1) if action else url
                findings.append(Finding(
                    title="POST Form Without CSRF Token in Source",
                    url=url, severity="HIGH",
                    description=f"A POST form (action={action_url}) has no CSRF token field.",
                    evidence=form_body[:200],
                    tags=["auth", "csrf", "form"],
                    confidence=70))
        return findings

    async def _test_session_expiry(self, client, target: str) -> list:
        findings = []
        try:
            r = await asyncio.wait_for(client.get(target), timeout=10)
            for header_name in ["set-cookie"]:
                val = r.headers.get(header_name, "").lower()
                if "expires" not in val and "max-age" not in val:
                    if any(p in val for p in ["sess", "auth", "token"]):
                        findings.append(Finding(
                            title="Session Cookie Without Expiration",
                            url=target, severity="MEDIUM",
                            description="Session cookie has no Expires or Max-Age attribute. "
                                        "It becomes a session cookie (expires when browser closes), "
                                        "but shared computers create a risk.",
                            evidence=f"Set-Cookie: {val[:150]}",
                            tags=["auth", "session", "no-expiry", "cookie"],
                            confidence=65))
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings

    async def _test_concurrent_sessions(self, client, target: str) -> list:
        findings = []
        # Make two simultaneous requests and check if both get valid sessions
        try:
            r1, r2 = await asyncio.gather(
                client.get(target), client.get(target))
            c1 = dict(r1.cookies) if hasattr(r1, 'cookies') else {}
            c2 = dict(r2.cookies) if hasattr(r2, 'cookies') else {}
            for k in c1:
                if k in c2 and c1[k] != c2[k]:
                    findings.append(Finding(
                        title="Concurrent Sessions Allowed",
                        url=target, severity="LOW",
                        description=f"Server issues different session IDs for concurrent requests "
                                    f"(cookie: {k}). Multiple concurrent sessions are allowed.",
                        evidence=f"cookie={k}",
                        tags=["auth", "session", "concurrent"],
                        confidence=60))
                    break
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings

    def _estimate_entropy(self, value: str) -> float:
        if not value:
            return 0.0
        import math
        char_set = len(set(value))
        if char_set == 0:
            return 0.0
        return len(value) * math.log2(char_set)


