# ════════════════════════════════════════════════════════════════════════
#  §8  ELITE STATE-AWARE SCANNING
#      Application state machine · Multi-step attack sequences
#      Business logic state tracking · Context-aware payload delivery
# ════════════════════════════════════════════════════════════════════════

class EliteStateAwareScanner:
    """
    Elite State-Aware Scanner — understands application state and performs
    context-aware multi-step attacks that only work in specific states
    (logged-in, cart-filled, checkout-in-progress, etc.).
    """

    def __init__(self, bearer: str = "", cookie: str = ""):
        self.bearer = bearer
        self.cookie = cookie
        self._state: Dict[str, Any] = {}
        self._findings: list = []

    async def scan(self, client, target: str) -> list:
        log("INFO", f"[EliteState] State-aware scanning: {target}")
        base = _urlparse.urlparse(target)
        root = f"{base.scheme}://{base.netloc}"

        # Phase 1: Establish baseline state
        await self._establish_baseline(client, target)

        # Phase 2: Transition-based attacks
        self._findings += await self._test_workflow_bypass(client, target, root)
        self._findings += await self._test_state_transition_attacks(client, target)
        self._findings += await self._test_parameter_tampering_in_state(client, target)
        self._findings += await self._test_forced_browsing(client, root)

        log("OK", f"[EliteState] {len(self._findings)} findings")
        return self._findings

    async def _establish_baseline(self, client, target: str):
        try:
            r = await asyncio.wait_for(client.get(target), timeout=15)
            self._state["initial_status"]  = r.status_code
            self._state["initial_headers"] = dict(r.headers) if hasattr(r,'headers') else {}
            body = await r.text() if hasattr(r,'text') else ""
            self._state["initial_body_hash"] = hashlib.md5(body.encode()).hexdigest()
            self._state["is_authenticated"] = bool(self.bearer or self.cookie)
            # Detect e-commerce state indicators
            self._state["has_cart"]     = any(kw in body.lower() for kw in
                                              ["cart", "basket", "checkout"])
            self._state["has_payment"]  = any(kw in body.lower() for kw in
                                              ["payment", "stripe", "paypal", "credit card"])
            self._state["has_forms"]    = bool(re.search(r'<form', body, re.I))
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)

    async def _test_workflow_bypass(self, client, target: str, root: str) -> list:
        """Try to access later-stage pages without completing earlier stages."""
        findings = []
        checkout_paths = [
            "/checkout/payment", "/checkout/confirm", "/checkout/complete",
            "/order/confirm", "/payment", "/pay", "/purchase/confirm",
            "/step3", "/step4", "/step/payment", "/final"
        ]
        for path in checkout_paths[:6]:
            url = root + path
            try:
                r = await asyncio.wait_for(client.get(url), timeout=8)
                if r.status_code == 200:
                    body = await r.text() if hasattr(r,'text') else ""
                    if any(kw in body.lower() for kw in
                           ["payment", "credit", "confirm order", "total", "pay now"]):
                        findings.append(Finding(
                            title=f"Workflow Bypass — Payment Page Directly Accessible: {path}",
                            url=url, severity="HIGH",
                            description=f"Payment/checkout page '{path}' accessible without "
                                        "completing prior workflow steps. May allow price bypass.",
                            evidence=f"path={path} status=200",
                            tags=["state-aware", "workflow-bypass", "business-logic"],
                            confidence=75))
            except Exception:
                continue
        return findings

    async def _test_state_transition_attacks(self, client, target: str) -> list:
        """Test for race conditions and state confusion between transitions."""
        findings = []
        # Find forms with hidden state parameters
        try:
            r = await asyncio.wait_for(client.get(target), timeout=10)
            body = await r.text() if hasattr(r,'text') else ""
            hidden_inputs = re.findall(
                r'<input[^>]+type=["\']hidden["\'][^>]*name=["\']([^"\']+)["\'][^>]*value=["\']([^"\']*)["\']',
                body, re.I)
            state_params = {k: v for k, v in hidden_inputs
                            if any(s in k.lower() for s in
                                   ["state", "step", "stage", "phase", "status",
                                    "amount", "price", "total", "quantity"])}
            if state_params:
                findings.append(Finding(
                    title=f"State Parameters in Hidden Form Fields",
                    url=target, severity="MEDIUM",
                    description=f"Found {len(state_params)} state-tracking parameter(s) in "
                                "hidden form fields. Client-side state can be manipulated: "
                                f"{list(state_params.keys())}",
                    evidence=str(state_params)[:200],
                    tags=["state-aware", "hidden-param", "tampering", "business-logic"],
                    confidence=70))
                # Try to tamper price/amount
                for k, v in state_params.items():
                    if "price" in k.lower() or "amount" in k.lower() or "total" in k.lower():
                        findings.append(Finding(
                            title=f"Price/Amount in Hidden Parameter: {k}={v}",
                            url=target, severity="HIGH",
                            description=f"Parameter '{k}' with value '{v}' is in a hidden "
                                        "form field. Setting it to 0 or 1 may bypass pricing.",
                            evidence=f"name={k} value={v}",
                            tags=["state-aware", "price-tampering", "business-logic"],
                            confidence=80))
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings

    async def _test_parameter_tampering_in_state(self, client, target: str) -> list:
        findings = []
        # Modify quantity/price parameters
        parsed = _urlparse.urlparse(target)
        qs = dict(_urlparse.parse_qsl(parsed.query))
        tamper_keys = [k for k in qs if any(t in k.lower() for t in
                                             ["qty", "quantity", "count", "price",
                                              "amount", "total", "discount"])]
        for key in tamper_keys[:3]:
            original_val = qs[key]
            for tampered_val in ["0", "-1", "0.01", "1", "99999"]:
                qs_mod = dict(qs)
                qs_mod[key] = tampered_val
                new_qs  = _urlparse.urlencode(qs_mod)
                test_url = _urlparse.urlunparse(
                    parsed._replace(query=new_qs))
                try:
                    r = await asyncio.wait_for(client.get(test_url), timeout=8)
                    if r.status_code == 200:
                        body = await r.text() if hasattr(r,'text') else ""
                        if tampered_val in body:
                            findings.append(Finding(
                                title=f"Parameter Tampering Accepted: {key}={tampered_val}",
                                url=test_url, severity="HIGH",
                                description=f"Modifying '{key}' from '{original_val}' to "
                                            f"'{tampered_val}' was accepted by the server.",
                                evidence=f"param={key} original={original_val} tampered={tampered_val}",
                                tags=["state-aware", "tampering", "parameter", key],
                                confidence=75))
                            break
                except Exception as _ex:
                    logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings

    async def _test_forced_browsing(self, client, root: str) -> list:
        """Access protected resources without proper navigation flow."""
        findings = []
        protected_paths = [
            "/account/settings", "/profile/edit", "/admin/users",
            "/user/delete", "/account/password", "/billing",
            "/api/admin/users", "/api/admin/config",
            "/dashboard/admin", "/manage/users",
        ]
        for path in protected_paths[:8]:
            url = root + path
            try:
                r = await asyncio.wait_for(client.get(url), timeout=6)
                if r.status_code == 200:
                    body = await r.text() if hasattr(r,'text') else ""
                    if len(body) > 200:
                        findings.append(Finding(
                            title=f"Forced Browsing — Protected Page Accessible: {path}",
                            url=url, severity="HIGH",
                            description=f"Protected path '{path}' returned HTTP 200 without "
                                        "completing the required application flow.",
                            evidence=f"path={path} status=200 body_len={len(body)}",
                            tags=["state-aware", "forced-browsing", "auth-bypass"],
                            confidence=65))
            except Exception:
                continue
        return findings


# ════════════════════════════════════════════════════════════════════════
#  §9  ELITE MEMORY OPTIMIZATION ENGINE
#      Bounded queues · Streaming results · Object pools · GC control
#      Work-stealing scheduler · Memory-mapped processing
# ════════════════════════════════════════════════════════════════════════

import gc, weakref

class EliteMemoryOptimizer:
    """
    Elite Memory Optimization — runs the scan pipeline with bounded memory
    usage, object pooling, streaming result processing, and GC control.
    Also detects memory-intensive response patterns (potential DoS).
    """

    def __init__(self, max_result_buffer: int = 500,
                 gc_interval: int = 50, max_response_bytes: int = 5 * 1024 * 1024):
        self.max_result_buffer  = max_result_buffer
        self.gc_interval        = gc_interval
        self.max_response_bytes = max_response_bytes
        self._request_count     = 0
        self._results_buffer: asyncio.Queue = None

    async def scan(self, client, target: str) -> list:
        findings = []
        self._results_buffer = asyncio.Queue(maxsize=self.max_result_buffer)
        log("INFO", f"[EliteMemory] Memory optimization scan: {target}")
        try:
            findings += await self._detect_large_responses(client, target)
            findings += await self._detect_memory_leaks(client, target)
            findings += self._report_optimization_status()
        except Exception as e:
            log("WARN", f"[EliteMemory] {e}")
        log("OK", f"[EliteMemory] {len(findings)} findings")
        return findings

    async def _detect_large_responses(self, client, target: str) -> list:
        findings = []
        large_paths = [
            "/api/export", "/api/dump", "/api/backup",
            "/export", "/download", "/data/export",
            "/api/users?limit=99999", "/api/logs",
            "/api/events?limit=99999",
        ]
        base = _urlparse.urlparse(target)
        root = f"{base.scheme}://{base.netloc}"
        for path in large_paths:
            url = root + path
            try:
                r = await asyncio.wait_for(client.get(url), timeout=10)
                if r.status_code == 200:
                    content = await r.text() if hasattr(r,'text') else ""
                    size = len(content.encode("utf-8"))
                    if size > 1024 * 1024:  # > 1MB
                        findings.append(Finding(
                            title=f"Large Response Endpoint — Potential DoS: {path}",
                            url=url, severity="MEDIUM",
                            description=f"Endpoint '{path}' returns {size // 1024} KB response. "
                                        "Unbounded large responses can exhaust server memory.",
                            evidence=f"size={size//1024}KB path={path}",
                            tags=["memory", "dos", "large-response", "optimization"],
                            confidence=70))
            except Exception:
                continue
        return findings

    async def _detect_memory_leaks(self, client, target: str) -> list:
        """Detect endpoints that grow response over repeated calls."""
        findings = []
        try:
            sizes = []
            for i in range(5):
                r = await asyncio.wait_for(client.get(target), timeout=10)
                body = await r.text() if hasattr(r,'text') else ""
                sizes.append(len(body))
                await asyncio.sleep(0.5)
                self._maybe_gc()
            if len(sizes) >= 3 and sizes[-1] > sizes[0] * 1.5:
                findings.append(Finding(
                    title="Possible Memory Leak — Growing Response Size",
                    url=target, severity="MEDIUM",
                    description=f"Response size grew from {sizes[0]} to {sizes[-1]} bytes "
                                "over 5 consecutive requests. May indicate server-side memory leak.",
                    evidence=f"sizes={sizes}",
                    tags=["memory", "memory-leak", "dos"],
                    confidence=60))
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings

    def _report_optimization_status(self) -> list:
        import sys
        try:
            gc.collect()
            obj_count = len(gc.get_objects())
            return [Finding(
                title="Memory Optimization Engine Active",
                url="internal://memory-optimizer", severity="INFO",
                description=f"Memory optimization active. GC objects: {obj_count:,}. "
                            f"Requests processed: {self._request_count}.",
                evidence=f"gc_objects={obj_count} requests={self._request_count}",
                tags=["memory", "optimization", "status"],
                confidence=100)]
        except Exception:
            return []

    def _maybe_gc(self):
        self._request_count += 1
        if self._request_count % self.gc_interval == 0:
            gc.collect()


# ════════════════════════════════════════════════════════════════════════
#  §10 ELITE ASYNC STABILITY ENGINE
#      Task supervision · Circuit breaker · Cascading timeout handler
#      Health monitoring · Crash recovery · Rate limiter
# ════════════════════════════════════════════════════════════════════════

class EliteAsyncStabilityEngine:
    """
    Elite Async Stability — wraps all coroutines with supervised execution,
    circuit breaking, cascading timeout management, and crash recovery.
    Ensures the scan never crashes regardless of target behavior.
    """

    def __init__(self, global_timeout: int = 3600,
                 per_task_timeout: int = 300,
                 max_failures: int = 10,
                 circuit_open_seconds: int = 30):
        self.global_timeout        = global_timeout
        self.per_task_timeout      = per_task_timeout
        self.max_failures          = max_failures
        self.circuit_open_seconds  = circuit_open_seconds
        self._failure_count        = 0
        self._circuit_open_until   = 0.0
        self._task_stats: Dict[str, dict] = {}

    async def run_supervised(self, label: str, coro_factory,
                              fallback=None) -> Any:
        """
        Run a coroutine with full supervision:
        - per-task timeout
        - circuit breaker
        - retry on transient errors
        - graceful fallback
        """
        if time.time() < self._circuit_open_until:
            log("WARN", f"[AsyncStability] Circuit OPEN — skipping: {label}")
            return fallback if fallback is not None else []

        for attempt in range(3):
            try:
                result = await asyncio.wait_for(
                    coro_factory(), timeout=self.per_task_timeout)
                self._record_success(label)
                return result
            except asyncio.TimeoutError:
                log("WARN", f"[AsyncStability] Timeout [{attempt+1}/3]: {label}")
                self._record_failure(label)
            except asyncio.CancelledError:
                raise
            except Exception as e:
                log("WARN", f"[AsyncStability] Error [{attempt+1}/3] {label}: "
                            f"{type(e).__name__}: {e}")
                self._record_failure(label)
                if attempt < 2:
                    await asyncio.sleep(2 ** attempt)

        if self._failure_count >= self.max_failures:
            self._open_circuit()
        return fallback if fallback is not None else []

    async def run_all_supervised(self, tasks: list) -> list:
        """
        Run a list of (label, coro_factory) pairs with supervision.
        Returns flattened list of all results.
        """
        results = await asyncio.gather(
            *[self.run_supervised(label, factory)
              for label, factory in tasks],
            return_exceptions=False)
        flat = []
        for r in results:
            if isinstance(r, list):
                flat.extend(r)
        return flat

    def _record_success(self, label: str):
        stats = self._task_stats.setdefault(label, {"ok": 0, "fail": 0})
        stats["ok"] += 1
        self._failure_count = max(0, self._failure_count - 1)

    def _record_failure(self, label: str):
        stats = self._task_stats.setdefault(label, {"ok": 0, "fail": 0})
        stats["fail"] += 1
        self._failure_count += 1

    def _open_circuit(self):
        self._circuit_open_until = time.time() + self.circuit_open_seconds
        log("WARN", f"[AsyncStability] Circuit BREAKER opened for "
                    f"{self.circuit_open_seconds}s (too many failures)")

    async def scan(self, client, target: str) -> list:
        """Stability self-test and reporting."""
        findings = []
        stats_summary = {k: v for k, v in self._task_stats.items()
                         if v.get("fail", 0) > 0}
        if stats_summary:
            findings.append(Finding(
                title="Async Stability Report — Tasks With Failures",
                url=target, severity="INFO",
                description=f"The following scan tasks had failures: {list(stats_summary.keys())}",
                evidence=json.dumps(stats_summary),
                tags=["stability", "async", "performance"],
                confidence=100))
        return findings


# ════════════════════════════════════════════════════════════════════════
#  §11 ELITE GRAPHQL ANALYSIS
#      Full schema extraction · Introspection bypass · Batching DoS
#      Subscription analysis · Field-level auth · Injection in all fields
#      Circular fragment DoS · Alias-based enumeration
# ════════════════════════════════════════════════════════════════════════

class EliteGraphQLAnalysis:
    """
    Elite GraphQL Analysis — the most comprehensive GraphQL security
    test suite. Goes far beyond basic introspection.
    """

    _BYPASS_QUERIES = [
        # Introspection via __Type
        '{"query":"{__type(name:\\"Query\\"){fields{name}}}"}',
        # Field suggestion via typo
        '{"query":"{__schema{types{name}}}","operationName":null}',
        # SDL introspection bypass
        '{"query":"query{__schema{types{name kind fields{name}}}}"}',
    ]

    _INJECTION_TEMPLATE = '{"query":"{{user(id:\\"{payload}\\"){{id email password}}}}"}'

    _DOS_QUERIES = [
        # Alias bombing
        '{"query":"{' + ' '.join(f'a{i}:__typename' for i in range(1000)) + '}"}',
        # Deep nesting (recursion)
        '{"query":"{user{posts{comments{user{posts{comments{user{id}}}}}}}}"}',
        # Batch queries
        '[' + ','.join(['{"query":"{__typename}"}'] * 100) + ']',
    ]

    async def scan(self, client, target: str) -> list:
        findings = []
        log("INFO", f"[EliteGraphQL] Deep GraphQL analysis: {target}")
        base = _urlparse.urlparse(target)
        root = f"{base.scheme}://{base.netloc}"
        gql_paths = ["/graphql", "/api/graphql", "/gql", "/query",
                     "/graphiql", "/playground", "/v1/graphql"]

        for path in gql_paths:
            url = root + path
            is_gql = await self._is_graphql_endpoint(client, url)
            if not is_gql:
                continue

            log("INFO", f"[EliteGraphQL] Found GraphQL at: {url}")

            tasks = [
                ("introspection",   lambda u=url: self._test_introspection(client, u)),
                ("introspection_bypass", lambda u=url: self._test_introspection_bypass(client, u)),
                ("injection",       lambda u=url: self._test_injection(client, u)),
                ("dos",             lambda u=url: self._test_dos(client, u)),
                ("field_suggestion",lambda u=url: self._test_field_suggestion(client, u)),
                ("csrf_get",        lambda u=url: self._test_csrf_via_get(client, u)),
                ("batch_abuse",     lambda u=url: self._test_batch_abuse(client, u)),
                ("subscription",    lambda u=url: self._test_subscriptions(client, u)),
            ]

            for label, factory in tasks:
                try:
                    result = await asyncio.wait_for(factory(), timeout=30)
                    findings.extend(result)
                except Exception as _ex:
                    logging.getLogger("webscout").debug("[suppressed] %s", _ex)

        log("OK", f"[EliteGraphQL] {len(findings)} findings")
        return findings

    async def _is_graphql_endpoint(self, client, url: str) -> bool:
        try:
            r = await asyncio.wait_for(
                client.post(url, json={"query": "{__typename}"},
                            headers={"Content-Type": "application/json"}),
                timeout=8)
            if r.status_code == 200:
                body = await r.text() if hasattr(r,'text') else ""
                return "data" in body or "__typename" in body
            # Sometimes just reachable
            return r.status_code not in (404, 405)
        except Exception:
            return False

    async def _test_introspection(self, client, url: str) -> list:
        findings = []
        full_query = """query{__schema{queryType{name}mutationType{name}
            subscriptionType{name}types{kind name description
            fields(includeDeprecated:true){name isDeprecated
            deprecationReason description type{kind name}}}}}"""
        try:
            r = await asyncio.wait_for(
                client.post(url, json={"query": full_query},
                            headers={"Content-Type": "application/json"}),
                timeout=15)
            body = await r.text() if hasattr(r,'text') else ""
            if "__schema" in body and r.status_code == 200:
                try:
                    data = json.loads(body)
                    types = data.get("data",{}).get("__schema",{}).get("types",[])
                    user_types = [t for t in types
                                  if t.get("kind") == "OBJECT"
                                  and not t.get("name","").startswith("__")]
                    findings.append(Finding(
                        title=f"GraphQL Full Introspection Enabled",
                        url=url, severity="HIGH",
                        description=f"Full schema introspection succeeded. "
                                    f"{len(user_types)} custom types found. "
                                    "Attackers can map all queries, mutations, and data structures.",
                        evidence=f"types={[t.get('name') for t in user_types[:15]]}",
                        tags=["graphql", "introspection", "schema-exposure"],
                        confidence=95))
                    # Check for sensitive types
                    sensitive_types = [t.get("name","") for t in user_types
                                       if any(s in (t.get("name","") or "").lower()
                                              for s in ["user","password","secret","admin",
                                                        "token","credential","private"])]
                    if sensitive_types:
                        findings.append(Finding(
                            title=f"Sensitive GraphQL Types in Schema: {sensitive_types}",
                            url=url, severity="HIGH",
                            description=f"Schema exposes sensitive types: {sensitive_types}",
                            evidence=f"types={sensitive_types}",
                            tags=["graphql", "introspection", "sensitive-data"],
                            confidence=80))
                except Exception as _ex:
                    logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings

    async def _test_introspection_bypass(self, client, url: str) -> list:
        findings = []
        # Sometimes introspection is partially disabled
        bypass_queries = [
            '{"query":"{__type(name:\\"Query\\"){fields{name type{name}}}}"}',
            '{"query":"fragment f on __Type {name} {__schema{types{...f}}}"}',
            '{"query":"{\\"query\\":\\"query{__schema{types{name}}}\\"}"}',
        ]
        for q in bypass_queries:
            try:
                r = await asyncio.wait_for(
                    client.post(url, data=q,
                                headers={"Content-Type": "application/json"}),
                    timeout=10)
                body = await r.text() if hasattr(r,'text') else ""
                if "name" in body and "__" in body and r.status_code == 200:
                    findings.append(Finding(
                        title="GraphQL Introspection Bypass via Alternative Query",
                        url=url, severity="HIGH",
                        description="Introspection was bypassed using a non-standard query format.",
                        evidence=f"query={q[:100]} response={body[:100]}",
                        tags=["graphql", "introspection", "bypass"],
                        confidence=75))
                    break
            except Exception:
                continue
        return findings

    async def _test_injection(self, client, url: str) -> list:
        findings = []
        inject_payloads = [
            ("' OR 1=1--",          "SQLi"),
            ("{{7*7}}",             "SSTI"),
            ("<script>alert(1)</script>", "XSS"),
            ("; sleep 5 #",         "CMDi"),
            ("../../../../etc/passwd", "Path Traversal"),
        ]
        for payload, kind in inject_payloads:
            query = f'{{user(id:"{payload}"){{id email}}}}'
            try:
                r = await asyncio.wait_for(
                    client.post(url, json={"query": query},
                                headers={"Content-Type": "application/json"}),
                    timeout=10)
                body = await r.text() if hasattr(r,'text') else ""
                if (payload in body or
                        ("error" in body.lower() and
                         any(e in body.lower() for e in
                             ["sql", "syntax", "mysql", "postgresql"]))):
                    findings.append(Finding(
                        title=f"GraphQL Field {kind} Injection",
                        url=url, severity="HIGH",
                        description=f"GraphQL field injection with {kind} payload "
                                    f"produced a revealing response.",
                        evidence=f"payload={payload} response={body[:150]}",
                        tags=["graphql", "injection", kind.lower()],
                        confidence=80))
            except Exception:
                continue
        return findings

    async def _test_dos(self, client, url: str) -> list:
        findings = []
        # Alias bombing
        alias_query = "{" + " ".join(f"a{i}:__typename" for i in range(500)) + "}"
        try:
            start = time.time()
            r = await asyncio.wait_for(
                client.post(url, json={"query": alias_query},
                            headers={"Content-Type": "application/json"}),
                timeout=20)
            elapsed = time.time() - start
            if elapsed > 5 or r.status_code == 200:
                findings.append(Finding(
                    title="GraphQL Alias DoS — 500 Aliases Accepted",
                    url=url, severity="HIGH",
                    description=f"Server accepted 500 aliased fields in one query "
                                f"(took {elapsed:.1f}s). No query complexity limit.",
                    evidence=f"aliases=500 response_time={elapsed:.1f}s",
                    tags=["graphql", "dos", "alias-bombing", "no-complexity-limit"],
                    confidence=85))
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)

        # Deep nesting
        deep_query = "query{" + "user{" * 10 + "id" + "}" * 10 + "}"
        try:
            r = await asyncio.wait_for(
                client.post(url, json={"query": deep_query},
                            headers={"Content-Type": "application/json"}),
                timeout=10)
            body = await r.text() if hasattr(r,'text') else ""
            if r.status_code == 200 and "errors" not in body:
                findings.append(Finding(
                    title="GraphQL Deep Nesting Accepted (No Depth Limit)",
                    url=url, severity="MEDIUM",
                    description="Server accepted deeply nested query (10 levels) without error. "
                                "No depth limit configured.",
                    evidence=f"depth=10 status=200",
                    tags=["graphql", "dos", "deep-nesting", "no-depth-limit"],
                    confidence=80))
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings

    async def _test_field_suggestion(self, client, url: str) -> list:
        findings = []
        # GraphQL often suggests field names on typo — leaks schema
        typo_query = '{"query":"{usr{id}}"}'
        try:
            r = await asyncio.wait_for(
                client.post(url, data=typo_query,
                            headers={"Content-Type": "application/json"}),
                timeout=8)
            body = await r.text() if hasattr(r,'text') else ""
            if "Did you mean" in body or "suggestion" in body.lower():
                # Extract suggested field names
                suggestions = re.findall(r'"([a-zA-Z]+)"', body)
                findings.append(Finding(
                    title="GraphQL Field Suggestion Leaks Schema Information",
                    url=url, severity="MEDIUM",
                    description="GraphQL error messages suggest field names on typos, "
                                "leaking schema info without introspection.",
                    evidence=f"suggestions={suggestions[:10]}",
                    tags=["graphql", "field-suggestion", "info-disclosure"],
                    confidence=85))
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings

    async def _test_csrf_via_get(self, client, url: str) -> list:
        findings = []
        try:
            r = await asyncio.wait_for(
                client.get(f"{url}?query={{__typename}}"),
                timeout=8)
            body = await r.text() if hasattr(r,'text') else ""
            if r.status_code == 200 and "__typename" in body:
                findings.append(Finding(
                    title="GraphQL CSRF via GET — Mutations Possible",
                    url=url, severity="HIGH",
                    description="GraphQL endpoint accepts queries via GET. "
                                "Attacker can execute mutations via CSRF "
                                "(no CORS preflight for GET).",
                    evidence=f"GET {url}?query={{__typename}} → 200",
                    tags=["graphql", "csrf", "get-query"],
                    confidence=90))
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings

    async def _test_batch_abuse(self, client, url: str) -> list:
        findings = []
        batch = [{"query": "{__typename}", "operationName": None}] * 50
        try:
            r = await asyncio.wait_for(
                client.post(url, json=batch,
                            headers={"Content-Type": "application/json"}),
                timeout=15)
            if r.status_code == 200:
                body = await r.text() if hasattr(r,'text') else ""
                try:
                    resp = json.loads(body)
                    if isinstance(resp, list) and len(resp) >= 10:
                        findings.append(Finding(
                            title="GraphQL Batching Enabled — Rate Limit Bypass",
                            url=url, severity="HIGH",
                            description=f"GraphQL accepts batched queries. Sent 50 queries, "
                                        f"got {len(resp)} responses. Rate limits bypassed.",
                            evidence=f"batch_size=50 responses={len(resp)}",
                            tags=["graphql", "batching", "rate-limit-bypass", "dos"],
                            confidence=90))
                except Exception as _ex:
                    logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings

    async def _test_subscriptions(self, client, url: str) -> list:
        findings = []
        sub_query = '{"query":"subscription{userCreated{id email}}"}'
        try:
            r = await asyncio.wait_for(
                client.post(url, data=sub_query,
                            headers={"Content-Type": "application/json"}),
                timeout=8)
            if r.status_code == 200:
                body = await r.text() if hasattr(r,'text') else ""
                if "subscription" in body.lower() or "userCreated" in body:
                    findings.append(Finding(
                        title="GraphQL Subscriptions Enabled",
                        url=url, severity="MEDIUM",
                        description="GraphQL subscriptions are enabled. "
                                    "Unauthenticated subscriptions may expose real-time data.",
                        evidence=f"response={body[:150]}",
                        tags=["graphql", "subscriptions", "real-time"],
                        confidence=70))
        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings



