class EliteClientSideAnalysis:
    """
    Elite Client-Side Analysis — static analysis of all client-side
    JavaScript, CSS, HTML, and source maps. Detects secrets, vulnerable
    libraries, DOM XSS sinks, insecure direct references, and
    frontend-specific misconfigurations.
    """

    _VULN_LIBS = {
        "jquery-1."    : ("jQuery 1.x", "HIGH",   "CVE-2019-11358 prototype pollution, "
                                                   "CVE-2020-11022/11023 XSS"),
        "jquery-2."    : ("jQuery 2.x", "HIGH",   "CVE-2019-11358, CVE-2020-11022"),
        "jquery-3.0"   : ("jQuery 3.0", "MEDIUM", "CVE-2019-11358"),
        "jquery-3.1"   : ("jQuery 3.1", "MEDIUM", "CVE-2019-11358"),
        "jquery-3.2"   : ("jQuery 3.2", "MEDIUM", "CVE-2019-11358"),
        "jquery-3.3"   : ("jQuery 3.3", "MEDIUM", "CVE-2019-11358"),
        "angular.js/1.": ("AngularJS 1.x", "HIGH","CVE-2019-14863 XSS, EOL since 2021"),
        "angular/1."   : ("AngularJS 1.x", "HIGH","EOL — no security patches"),
        "bootstrap/3." : ("Bootstrap 3.x", "MEDIUM","CVE-2019-8331 XSS in tooltip/popover"),
        "bootstrap/4.0": ("Bootstrap 4.0", "MEDIUM","CVE-2019-8331"),
        "lodash/4.17.1": ("Lodash 4.17.1x","HIGH", "CVE-2019-10744 prototype pollution"),
        "lodash@4.17.1": ("Lodash 4.17.1x","HIGH", "CVE-2019-10744"),
        "handlebars/"  : ("Handlebars",    "HIGH", "CVE-2019-19919 prototype pollution"),
        "moment.js/2." : ("Moment.js 2.x", "LOW",  "RegExp DoS, deprecated"),
        "dompurify/0." : ("DOMPurify 0.x", "HIGH", "Old — lacks modern XSS protections"),
        "dompurify/1." : ("DOMPurify 1.x", "MEDIUM","Update to 2.x+"),
        "react/16.0"   : ("React 16.0",    "MEDIUM","dangerouslySetInnerHTML XSS if misused"),
        "vue/2.0"      : ("Vue 2.0",       "LOW",  "EOL — no security patches"),
        "underscore/1.": ("Underscore <1.13","MEDIUM","CVE-2021-23358 arbitrary code execution"),
        "socket.io/1." : ("Socket.io 1.x", "HIGH", "Multiple known vulnerabilities, EOL"),
        "socket.io/2." : ("Socket.io 2.x", "MEDIUM","Multiple CVEs, recommend 4.x"),
        "axios/0."     : ("Axios 0.x",     "MEDIUM","SSRF via redirect, update to 1.x"),
    }

    _DOM_XSS_SOURCES = [
        "location.hash", "location.search", "location.href",
        "document.URL", "document.referrer", "document.cookie",
        "window.name", "location.pathname", "document.documentURI",
        "history.state", "opener.location"
    ]

    _DOM_XSS_SINKS = [
        "innerHTML", "outerHTML", "document.write", "document.writeln",
        "eval(", "setTimeout(", "setInterval(", "Function(",
        "location.href=", "location.replace(", "window.open(",
        "insertAdjacentHTML", "DOMParser", "document.domain",
        "document.execCommand"
    ]

    async def scan(self, client, target: str) -> list:
        findings = []
        log("INFO", f"[EliteClientSide] Analyzing client-side code: {target}")
        try:
            r = await asyncio.wait_for(client.get(target), timeout=15)
            html  = await r.text() if hasattr(r,'text') else ""
            base  = _urlparse.urlparse(target)
            root  = f"{base.scheme}://{base.netloc}"

            findings += self._analyze_html_inline(html, target)
            findings += await self._analyze_js_bundles(client, html, root)
            findings += self._detect_vulnerable_libs(html, target)
            findings += await self._check_csp_bypass(client, target)

        except Exception as e:
            log("WARN", f"[EliteClientSide] {e}")
        log("OK", f"[EliteClientSide] {len(findings)} findings")
        return findings

    def _analyze_html_inline(self, html: str, url: str) -> list:
        findings = []
        # Inline scripts
        inline_scripts = re.findall(r'<script[^>]*>(.*?)</script>', html, re.S | re.I)
        for script in inline_scripts:
            # DOM XSS source→sink flow detection
            for source in self._DOM_XSS_SOURCES:
                if source in script:
                    for sink in self._DOM_XSS_SINKS:
                        if sink in script:
                            findings.append(Finding(
                                title=f"Potential DOM XSS: {source} → {sink}",
                                url=url, severity="HIGH",
                                description=f"Inline script reads from DOM source "
                                            f"'{source}' and writes to sink '{sink}'. "
                                            "If unsanitized, this is DOM XSS.",
                                evidence=f"source={source} sink={sink} "
                                         f"script_preview={script[:150]}",
                                tags=["client-side", "dom-xss", "source-sink",
                                      source.replace(".", "-"), sink.replace("(","").replace("=","")],
                                confidence=80))
                            break

            # Secrets in inline scripts
            for pat, kind in EliteBrowserIntelligence._SECRET_PATTERNS:
                for m in re.finditer(pat, script):
                    findings.append(Finding(
                        title=f"{kind} in Inline Script",
                        url=url, severity="CRITICAL",
                        description=f"Hardcoded {kind} found in an inline <script> tag.",
                        evidence=m.group(0)[:150],
                        tags=["client-side", "secret", kind.lower().replace(" ","-"),
                              "inline-script"],
                        confidence=85))

            # Dangerous eval patterns
            if re.search(r'eval\s*\(', script):
                ctx = re.search(r'.{0,50}eval\s*\(.{0,50}', script)
                findings.append(Finding(
                    title="eval() in Inline Script",
                    url=url, severity="MEDIUM",
                    description="Inline script uses eval(). "
                                "If user input reaches eval(), it's code injection.",
                    evidence=ctx.group(0) if ctx else "eval() found",
                    tags=["client-side", "eval", "code-injection"],
                    confidence=70))

        # Event handlers with dangerous patterns
        events = re.findall(r'on\w+\s*=\s*["\']([^"\']{0,200})["\']', html, re.I)
        for event in events:
            if any(s in event for s in ["location", "eval", "document.write",
                                        "innerHTML", "setTimeout", "atob("]):
                findings.append(Finding(
                    title="Dangerous Inline Event Handler",
                    url=url, severity="MEDIUM",
                    description=f"HTML event handler contains dangerous pattern: {event[:100]}",
                    evidence=event[:150],
                    tags=["client-side", "event-handler", "dom-xss"],
                    confidence=70))

        # data-* attributes with sensitive info
        data_attrs = re.findall(
            r'data-(?:token|jwt|key|secret|auth|password|api[_-]?key)'
            r'\s*=\s*["\']([^"\']+)["\']', html, re.I)
        for val in data_attrs:
            findings.append(Finding(
                title="Sensitive Data in HTML data-* Attribute",
                url=url, severity="HIGH",
                description=f"Sensitive value found in HTML data attribute: {val[:60]}",
                evidence=val[:100],
                tags=["client-side", "data-attribute", "sensitive-data"],
                confidence=80))

        return findings

    async def _analyze_js_bundles(self, client, html: str, root: str) -> list:
        findings = []
        srcs = re.findall(r'<script[^>]+src=["\']([^"\']+)["\']', html, re.I)
        base_url = _urlparse.urlparse(root)

        for src in srcs[:20]:
            if not src.startswith("http"):
                src = root + (src if src.startswith("/") else "/" + src)
            if _urlparse.urlparse(src).netloc != base_url.netloc:
                continue
            try:
                r = await asyncio.wait_for(client.get(src), timeout=10)
                content = await r.text() if hasattr(r,'text') else ""

                # Source→sink flow in bundle
                for source in self._DOM_XSS_SOURCES[:5]:
                    if source in content:
                        for sink in self._DOM_XSS_SINKS[:5]:
                            if sink in content:
                                # Check proximity (within 500 chars)
                                src_pos  = content.find(source)
                                sink_pos = content.find(sink)
                                if abs(src_pos - sink_pos) < 500:
                                    findings.append(Finding(
                                        title=f"DOM XSS Risk in Bundle: {source} → {sink}",
                                        url=src, severity="HIGH",
                                        description=f"JS bundle contains {source} source "
                                                    f"and {sink} sink in close proximity.",
                                        evidence=content[min(src_pos,sink_pos):
                                                        min(src_pos,sink_pos)+200],
                                        tags=["client-side", "dom-xss", "bundle",
                                              source.replace(".", "-")],
                                        confidence=70))
                                break

                # Vulnerable patterns
                dangerous_patterns = [
                    (r'document\.cookie\s*=', "Cookie manipulation", "MEDIUM"),
                    (r'window\.location\s*=\s*[a-z\$_]', "Open redirect via location", "HIGH"),
                    (r'postMessage\s*\([^,)]+,\s*["\*]["\']', "postMessage with wildcard", "HIGH"),
                    (r'localStorage\.setItem\s*\(\s*["\'](?:token|jwt|auth)', "Token in localStorage", "MEDIUM"),
                    (r'fetch\s*\(.*eval\s*\(', "eval of fetch response", "CRITICAL"),
                ]
                for pat, desc, sev in dangerous_patterns:
                    for m in re.finditer(pat, content):
                        findings.append(Finding(
                            title=f"Dangerous Pattern in JS Bundle: {desc}",
                            url=src, severity=sev,
                            description=f"{desc} detected in JavaScript bundle.",
                            evidence=m.group(0)[:150],
                            tags=["client-side", "bundle", "dangerous-pattern",
                                  desc.lower().replace(" ","-")],
                            confidence=70))

            except Exception:
                continue
        return findings

    def _detect_vulnerable_libs(self, html: str, url: str) -> list:
        findings = []
        for pattern, (name, sev, desc) in self._VULN_LIBS.items():
            if pattern in html.lower():
                findings.append(Finding(
                    title=f"Vulnerable JavaScript Library: {name}",
                    url=url, severity=sev,
                    description=f"Detected {name} which has known vulnerabilities. {desc}",
                    evidence=f"pattern={pattern}",
                    tags=["client-side", "vulnerable-lib", "outdated",
                          name.lower().split()[0]],
                    confidence=85))
        return findings

    async def _check_csp_bypass(self, client, target: str) -> list:
        findings = []
        try:
            r = await asyncio.wait_for(client.get(target), timeout=10)
            csp = r.headers.get("Content-Security-Policy", "")
            if not csp:
                return findings

            # Check for bypass-enabling directives
            bypass_checks = [
                ("unsafe-inline", "HIGH",
                 "CSP allows 'unsafe-inline' — inline scripts bypass CSP XSS protection."),
                ("unsafe-eval", "HIGH",
                 "CSP allows 'unsafe-eval' — eval() and Function() bypass CSP."),
                ("unsafe-hashes", "MEDIUM",
                 "CSP allows 'unsafe-hashes' — weakens hash-based CSP."),
                ("*", "MEDIUM",
                 "CSP uses wildcard (*) in source list — too permissive."),
                ("data:", "MEDIUM",
                 "CSP allows data: URIs — can be used for XSS via data: scripts."),
                ("http:", "HIGH",
                 "CSP allows http: — allows loading insecure scripts."),
            ]
            for directive, sev, desc in bypass_checks:
                if directive in csp:
                    findings.append(Finding(
                        title=f"Weak CSP Directive: {directive}",
                        url=target, severity=sev,
                        description=desc,
                        evidence=f"CSP: {csp[:200]}",
                        tags=["client-side", "csp", "bypass",
                              directive.replace("*","wildcard").replace(":","")],
                        confidence=90))

            # Check for missing directives
            required = ["default-src", "script-src", "object-src", "base-uri"]
            for req in required:
                if req not in csp:
                    findings.append(Finding(
                        title=f"CSP Missing Directive: {req}",
                        url=target, severity="MEDIUM",
                        description=f"Content-Security-Policy missing '{req}' directive. "
                                    "May allow injection via that resource type.",
                        evidence=f"CSP: {csp[:150]}",
                        tags=["client-side", "csp", "missing-directive", req.replace("-","")],
                        confidence=85))

        except Exception as _ex:
            logging.getLogger("webscout").debug("[suppressed] %s", _ex)
        return findings


