try:
    _orig_run_webscout_v28 = run_webscout
except NameError:
    _orig_run_webscout_v28 = None

async def run_webscout(target: str, args, client=None) -> list:
    """Patched run_webscout with v29 Elite module integration."""
    # Run original scan
    if _orig_run_webscout_v28 is not None:
        findings = await _orig_run_webscout_v28(target, args)
    else:
        findings = []

    # Inject v29 Elite modules
    v29_enabled = (getattr(args, "v29_all", False) or
                   getattr(args, "run_all", False) or
                   getattr(args, "deep_scan", False) or
                   any(getattr(args, f"elite_{m}", False)
                       for m in ["browser", "browser_auto", "js_runtime",
                                 "websocket", "frontend", "auth", "api",
                                 "state", "memory", "async", "graphql",
                                 "client", "orchestration", "oob", "correlation"]))

    if v29_enabled:
        try:
            # Build a temporary client if not provided
            if client is None:
                import aiohttp as _aiohttp
                async with _aiohttp.ClientSession() as _client:
                    v29_findings = await _run_v29_modules(_client, target, args, findings)
                    findings.extend(v29_findings)
            else:
                v29_findings = await _run_v29_modules(client, target, args, findings)
                findings.extend(v29_findings)
        except Exception as e:
            log("WARN", f"[v29] Pipeline error: {e}")

    return findings


