try:
    _orig_main_v28 = main
except NameError:
    _orig_main_v28 = None

def main():
    """Patched main() with v29 argparse flags."""
    import argparse as _ap
    # We need to intercept before parse_args — use known pattern
    if _orig_main_v28 is not None:
        # Inject v29 flags into sys.argv processing
        # by monkey-patching ArgumentParser.parse_args
        _real_parse = _ap.ArgumentParser.parse_args
        def _patched_parse(self, args=None, namespace=None):
            _add_v29_argparse_flags(self)
            return _real_parse(self, args, namespace)
        _ap.ArgumentParser.parse_args = _patched_parse
        try:
            _orig_main_v28()
        finally:
            _ap.ArgumentParser.parse_args = _real_parse
    else:
        log("WARN", "[v29] Original main() not found")

