# ═══════════════════════════════════════════════════════════════════════════
#  v30 STARTUP HOOK — patches main() with v30 flags + structured logging
# ═══════════════════════════════════════════════════════════════════════════

def _v30_patch_argparse():
  """
  Monkey-patches ArgumentParser.parse_args to inject v30 flags before
  the original main() calls parse_args(). This is safe and non-destructive.
  """
  import argparse as _ap_mod
  _orig_parse = _ap_mod.ArgumentParser.parse_args

  def _patched_parse(self_, args=None, namespace=None):
      # Add v30 argument group if not already present
      try:
          group_names = [g.title for g in self_._action_groups]
          if "v30 Enhancements" not in group_names:
              grp = self_.add_argument_group("v30 Enhancements")
              for flag, dest, help_txt in [
                  ("--browser-intel",   "browser_intel",   "[ENH-04-08] Playwright browser + DOM + JS intelligence"),
                  ("--ws-gql-intel",    "ws_gql_intel",    "[ENH-09-10] Enhanced WebSocket + GraphQL intelligence"),
                  ("--disable-noisy",   "disable_noisy",   "[ENH-12] Disable noisy/theoretical modules"),
                  ("--quick",           "quick",           "[ENH-12] Skip long-running experimental modules (fast mode)"),
                  ("--dep-check",       "dep_check",       "[ENH-14] Show dependency health report and exit"),
              ]:
                  try:
                      grp.add_argument(flag, dest=dest, action="store_true", help=help_txt)
                  except Exception as _ex:
                      logging.getLogger("webscout").debug("[suppressed] %s", _ex)
      except Exception as _ex:
          logging.getLogger("webscout").debug("[suppressed] %s", _ex)
      result = _orig_parse(self_, args, namespace)
      # Handle dep-check before anything else
      try:
          if getattr(result, "dep_check", False):
              DependencyHealthChecker().print_report()
              import sys; sys.exit(0)
      except Exception as _ex:
          logging.getLogger("webscout").debug("[suppressed] %s", _ex)
      # Configure structured logging
      try:
          import logging as _v30lg
          _v30lg.basicConfig(
              level=_v30lg.DEBUG if getattr(result, "verbose", False) else _v30lg.WARNING,
              format="%(asctime)s [%(name)s] %(levelname)s %(message)s",
              datefmt="%H:%M:%S",
          )
      except Exception as _ex:
          logging.getLogger("webscout").debug("[suppressed] %s", _ex)
      # Warn about critical missing deps
      try:
          _deps = DependencyHealthChecker().check()
          _crit = [d for d in _deps if d.severity == "CRITICAL" and not d.available]
          if _crit:
              import sys
              print("\n[WebScout v30] Critical dependencies missing:", file=sys.stderr)
              for d in _crit:
                  print(f"  ✗ {d.name} — install with: {d.install_hint}", file=sys.stderr)
              print(file=sys.stderr)
      except Exception as _ex:
          logging.getLogger("webscout").debug("[suppressed] %s", _ex)
      return result

  _ap_mod.ArgumentParser.parse_args = _patched_parse


