    async def _query_nvd(self, keyword: str, max_results: int = 5) -> list[dict]:
        """Query NVD API for CVEs related to a keyword."""
        results = []
        try:
            import aiohttp
            params = {
                "keywordSearch": keyword,
                "resultsPerPage": max_results,
            }
            timeout = aiohttp.ClientTimeout(total=10)
            async with aiohttp.ClientSession(timeout=timeout) as sess:
                async with sess.get(self.NVD_API_BASE, params=params,
                                    ssl=False) as resp:
                    if resp.status == 200:
                        data = await resp.json()
                        for vuln in data.get("vulnerabilities", []):
                            cve = vuln.get("cve", {})
                            cve_id = cve.get("id", "")
                            descriptions = cve.get("descriptions", [])
                            desc = next(
                                (d["value"] for d in descriptions if d.get("lang") == "en"),
                                "No description"
                            )
                            metrics = cve.get("metrics", {})
                            cvss_v3 = metrics.get("cvssMetricV31", [{}])[0].get(
                                "cvssData", {}).get("baseScore", 0)
                            results.append({
                                "cve": cve_id,
                                "description": desc[:300],
                                "cvss": cvss_v3,
                            })
        except Exception:
            pass
        return results

    def match_local_cves(self, technologies: list[str], headers: dict,
                          html: str) -> list[dict]:
        """Match detected technologies against local CVE database."""
        matches = []
        combined = html[:20000].lower() + " ".join(
            f"{k.lower()}: {v.lower()}" for k, v in headers.items()
        )

        for tech in technologies:
            tech_key = tech.lower()
            if tech_key in self.CRITICAL_CVE_DB:
                for cve in self.CRITICAL_CVE_DB[tech_key]:
                    matches.append({**cve, "technology": tech})

        # Also check server header for version-specific CVEs
        server = headers.get("Server", headers.get("server", "")).lower()
        for product in ["apache", "nginx", "openssl", "php"]:
            if product in server and product in self.CRITICAL_CVE_DB:
                for cve in self.CRITICAL_CVE_DB[product]:
                    if not any(m["cve"] == cve["cve"] for m in matches):
                        matches.append({**cve, "technology": product.title()})

        # Check for Log4j indicators
        if re.search(r"java|spring|struts|log4j|tomcat", combined, re.I):
            for cve in self.CRITICAL_CVE_DB.get("log4j", []):
                matches.append({**cve, "technology": "Log4j/Java"})
            for cve in self.CRITICAL_CVE_DB.get("spring", []):
                matches.append({**cve, "technology": "Spring"})

        return matches

    async def scan(self, client, target: str) -> list:
        """Correlate findings with CVE database."""
        log("SCAN", "[CVEIntegration] Starting CVE correlation...")
        findings = []

        base_r = await client.get(target)
        if not base_r:
            return findings

        html = base_r.get("text", "")
        hdrs = base_r.get("headers", {})

        # Get technology list from OSINTScanner
        from_osint = OSINTScanner()
        technologies = from_osint.fingerprint_technologies(html, hdrs)

        # Match against local DB
        cve_matches = self.match_local_cves(technologies, hdrs, html)

        for match in cve_matches:
            exploit_text = " (Public Exploit Available)" if match.get("exploit") else ""
            findings.append(Finding(
                plugin="cve_integration",
                title=f"{match['cve']}: {match['desc'][:80]}{exploit_text}",
                severity="CRITICAL" if match["cvss"] >= 9.0
                         else "HIGH" if match["cvss"] >= 7.0
                         else "MEDIUM",
                confidence=65.0,  # Technology detected but version unconfirmed
                description=(
                    f"{match['cve']}: {match['desc']}\n\n"
                    f"Technology: {match.get('technology', 'Unknown')}\n"
                    f"Affected versions: {match.get('versions_affected', 'Check NVD')}\n"
                    f"CVSS Score: {match['cvss']}\n"
                    f"Public Exploit: {'YES — Exploitation in the wild reported' if match.get('exploit') else 'No known public exploit'}\n\n"
                    "Note: Version was not confirmed — manual verification required. "
                    "If the detected technology is running an affected version, this is exploitable."
                ),
                evidence=(
                    f"Technology detected: {match.get('technology', 'Unknown')}\n"
                    f"Server header: {hdrs.get('Server', hdrs.get('server', 'N/A'))}\n"
                    f"Technologies found: {', '.join(technologies)}\n"
                    f"NVD Reference: https://nvd.nist.gov/vuln/detail/{match['cve']}"
                ),
                url=target,
                remediation=(
                    f"1. Confirm the exact version of {match.get('technology', 'the technology')} in use.\n"
                    f"2. If running an affected version ({match.get('versions_affected', 'see NVD')}), "
                    f"update immediately.\n"
                    f"3. Refer to: https://nvd.nist.gov/vuln/detail/{match['cve']}\n"
                    "4. Apply vendor security patches without delay."
                ),
                cwe="CWE-1035",
                cvss=match["cvss"],
                owasp="A06",
                tags=["cve", match["cve"].lower().replace("-","_"),
                      match.get("technology", "").lower(),
                      "known-vulnerability"],
            ))

        # Try NVD API for additional CVEs
        if technologies:
            for tech in technologies[:3]:  # Limit API calls
                nvd_results = await self._query_nvd(tech)
                for nvd_cve in nvd_results:
                    if nvd_cve["cvss"] >= 9.0:  # Only critical from NVD
                        if not any(f.title.startswith(nvd_cve["cve"]) for f in findings):
                            findings.append(Finding(
                                plugin="cve_integration",
                                title=f"{nvd_cve['cve']} [NVD]: {nvd_cve['description'][:70]}",
                                severity="CRITICAL",
                                confidence=50.0,
                                description=(
                                    f"NVD reports a critical CVE ({nvd_cve['cvss']} CVSS) "
                                    f"related to '{tech}':\n{nvd_cve['description']}"
                                ),
                                evidence=f"NVD API result for '{tech}': {nvd_cve}",
                                url=target,
                                remediation=(
                                    f"Verify if this CVE applies to your {tech} version. "
                                    f"See: https://nvd.nist.gov/vuln/detail/{nvd_cve['cve']}"
                                ),
                                cwe="CWE-1035",
                                cvss=nvd_cve["cvss"],
                                owasp="A06",
                                tags=["cve", "nvd", nvd_cve["cve"].lower().replace("-","_")],
                            ))

        log("INFO", f"[CVEIntegration] Done. {len(findings)} findings.")
        return findings


