#  09.  INFRASTRUCTURE BRUTE-FORCER
# ──────────────────────────────────────────────────────────────────────────────

class InfrastructureBruteForcer:
    """
    Tests for weak credentials and default passwords across:
      • HTTP Basic/Digest authentication
      • Admin panel login forms (POST)
      • Directory path brute-force
      • Parameter-based authentication endpoints
    Note: Rate-limited and safe — designed for authorized penetration testing.
    """

    COMMON_CREDENTIALS = [
        ("admin",    "admin"),
        ("admin",    "password"),
        ("admin",    "123456"),
        ("admin",    "admin123"),
        ("admin",    ""),
        ("root",     "root"),
        ("root",     "password"),
        ("root",     ""),
        ("admin",    "letmein"),
        ("admin",    "welcome"),
        ("admin",    "pass"),
        ("admin",    "changeme"),
        ("test",     "test"),
        ("demo",     "demo"),
        ("user",     "user"),
        ("administrator", "administrator"),
        ("administrator", "password"),
        ("guest",    "guest"),
        ("operator", "operator"),
        ("sa",       ""),
        ("sa",       "sa"),
    ]

    ADMIN_PATHS = [
        "/admin/", "/admin", "/administrator/", "/admin/login",
        "/wp-admin/", "/wp-login.php", "/manager/", "/management/",
        "/panel/", "/cpanel/", "/login", "/signin", "/auth/login",
        "/backend/", "/console/", "/control/", "/admin/index.php",
        "/admin.php", "/admincp/", "/moderator/", "/webadmin/",
        "/phpmyadmin/", "/pma/", "/adminer/", "/db/",
        "/:admin/", "/secure/", "/private/", "/restricted/",
    ]

    DIRECTORY_WORDLIST = [
        "admin", "administrator", "backup", "backups", "bak", "config",
        "configs", "data", "database", "db", "debug", "dev", "downloads",
        "files", "images", "img", "includes", "install", "js", "lib",
        "libs", "log", "logs", "media", "old", "panel", "phpMyAdmin",
        "private", "script", "scripts", "secret", "secrets", "setup",
        "src", "static", "temp", "test", "tests", "tmp", "upload",
        "uploads", "user", "users", "vendor", "web", "webadmin",
        "cms", "api", "api2", "v1", "v2", "app", "apps", "source",
        "priv", "hidden", "internal", "secure", "readonly", "export",
        "import", "archive", "archives", "docs", "documentation",
        "swagger", "openapi", "graphql", "rest", "service", "services",
    ]

    async def test_http_basic_auth(self, client, url: str) -> list:
        """Test HTTP Basic Authentication with common credentials."""
        findings = []

        # First check if Basic auth is required
        r = await client.get(url)
        if not r or r["status"] != 401:
            return findings

        www_auth = r.get("headers", {}).get("WWW-Authenticate", "")
        if "basic" not in www_auth.lower():
            return findings

        log("INFO", f"[BruteForcer] HTTP Basic Auth detected at {url} — testing credentials...")

        for username, password in self.COMMON_CREDENTIALS:
            creds = base64.b64encode(f"{username}:{password}".encode()).decode()
            auth_r = await client.get(url, headers={"Authorization": f"Basic {creds}"})

            if auth_r and auth_r["status"] == 200:
                findings.append(Finding(
                    plugin="brute_force",
                    title=f"Weak HTTP Basic Auth Credentials: {username}:{password or '(empty)'}",
                    severity="CRITICAL",
                    confidence=99.0,
                    description=(
                        f"HTTP Basic Authentication at {url} was bypassed using "
                        f"default credentials '{username}:{password or '(empty)'}'. "
                        "Any attacker can gain access using these credentials."
                    ),
                    evidence=(
                        f"URL: {url}\n"
                        f"WWW-Authenticate: {www_auth}\n"
                        f"Credentials tested: {username}:{password or '(empty)'}\n"
                        f"Response: HTTP 200 ({auth_r.get('length',0)} bytes)"
                    ),
                    url=url,
                    remediation=(
                        "Change default credentials immediately. "
                        "Use strong, unique passwords (16+ chars, mixed types). "
                        "Consider replacing Basic Auth with token-based authentication. "
                        "Enable account lockout after failed attempts."
                    ),
                    cwe="CWE-521",
                    cvss=9.8,
                    owasp="A07",
                    tags=["brute-force", "weak-credentials", "basic-auth",
                          f"user:{username}"],
                ))
                return findings  # Found — stop

            await asyncio.sleep(0.3)  # Rate limit

        return findings

    async def discover_admin_panels(self, client, base_url: str) -> list:
        """Discover accessible admin panels."""
        findings = []

        async def _probe(path: str):
            url = base_url.rstrip("/") + path
            r = await client.get(url, allow_redirects=False)
            if not r:
                return None
            if r["status"] in (200, 401, 403):
                body = r.get("text", "").lower()
                # Confirm it's actually an admin panel
                admin_signals = ["login", "password", "username", "admin",
                                 "dashboard", "sign in", "sign-in",
                                 "administrator", "panel", "control"]
                if (r["status"] == 200 and
                        any(s in body[:2000] for s in admin_signals)):
                    return (url, r["status"], "Admin panel (200 + login form)")
                elif r["status"] in (401, 403):
                    return (url, r["status"], "Protected admin panel (401/403)")
            return None

        tasks = [_probe(p) for p in self.ADMIN_PATHS]
        results = await asyncio.gather(*tasks, return_exceptions=True)

        for res in results:
            if not res or isinstance(res, Exception):
                continue
            url, status, description = res
            sev = "HIGH" if status == 200 else "MEDIUM"
            findings.append(Finding(
                plugin="brute_force",
                title=f"Admin Panel Discovered: {url} (HTTP {status})",
                severity=sev,
                confidence=80.0,
                description=(
                    f"An administrative panel was found at {url} (HTTP {status}). "
                    f"{description}. "
                    "Admin panels are prime targets for credential attacks and "
                    "authentication bypass vulnerabilities."
                ),
                evidence=f"GET {url} → HTTP {status}",
                url=url,
                remediation=(
                    "Restrict admin panel access to trusted IP ranges only. "
                    "Implement multi-factor authentication (MFA). "
                    "Use a non-default admin URL. "
                    "Implement account lockout and brute-force protection."
                ),
                cwe="CWE-284",
                cvss=7.5 if sev == "HIGH" else 5.3,
                owasp="A07",
                tags=["admin-panel", "brute-force-target", "discovery"],
            ))
        return findings

    async def directory_bruteforce(self, client, base_url: str,
                                    max_dirs: int = 60) -> list:
        """Brute-force common directory names."""
        findings = []
        found_dirs = []

        sem = asyncio.Semaphore(20)

        async def _check_dir(word: str):
            async with sem:
                url = base_url.rstrip("/") + "/" + word + "/"
                r = await client.get(url, allow_redirects=False)
                if not r:
                    return
                if r["status"] in (200, 301, 302, 403):
                    body = r.get("text", "").lower()
                    # Filter out generic 404-as-200 pages
                    if r["status"] == 200 and any(
                        x in body[:500] for x in ["not found", "404", "no such"]
                    ):
                        return
                    found_dirs.append((url, r["status"], r.get("length", 0)))

        wordlist = self.DIRECTORY_WORDLIST[:max_dirs]
        await asyncio.gather(*[_check_dir(w) for w in wordlist], return_exceptions=True)

        if found_dirs:
            findings.append(Finding(
                plugin="brute_force",
                title=f"Directory Brute-Force: {len(found_dirs)} Directories Found",
                severity="INFO",
                confidence=85.0,
                description=(
                    f"Directory brute-force discovered {len(found_dirs)} accessible "
                    "directories. These may contain sensitive files, backup data, "
                    "or admin interfaces."
                ),
                evidence="Discovered directories:\n" + "\n".join(
                    f"  HTTP {s} {u} ({l}b)"
                    for u, s, l in found_dirs[:20]
                ),
                url=base_url,
                remediation=(
                    "Disable directory listing. "
                    "Remove unnecessary directories from web root. "
                    "Restrict access to sensitive directories via authentication."
                ),
                cwe="CWE-538",
                cvss=4.0,
                owasp="A05",
                tags=["directory-bruteforce", "discovery", "reconnaissance"],
            ))
        return findings

    async def scan(self, client, target: str) -> list:
        """Run all brute-force checks."""
        log("SCAN", "[InfrastructureBruteForcer] Starting infrastructure brute-forcing...")
        findings = []

        tasks = [
            self.test_http_basic_auth(client, target),
            self.discover_admin_panels(client, target),
            self.directory_bruteforce(client, target),
        ]
        for result in await asyncio.gather(*tasks, return_exceptions=True):
            if isinstance(result, list):
                findings.extend(result)

        log("INFO", f"[InfrastructureBruteForcer] Done. {len(findings)} findings.")
        return findings


