# V34-11  REST API EXCELLENCE
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

class RESTAPIExcellenceEngine:
    """
    Elite REST API security analysis:
    - OpenAPI/Swagger spec discovery and parsing
    - Full endpoint enumeration from spec
    - Authorization matrix testing (each endpoint × auth level)
    - Mass assignment vulnerability testing
    - HTTP method testing (verb tampering)
    - Content negotiation abuse
    - Parameter pollution (HPP)
    - API versioning exploitation
    - Rate limiting bypass techniques
    - JWT/OAuth token abuse
    - API key enumeration in responses
    """

    SWAGGER_PATHS = [
        "/swagger.json", "/swagger.yaml", "/swagger/v1/swagger.json",
        "/api-docs", "/api-docs/v1", "/api-docs/v2",
        "/openapi.json", "/openapi.yaml", "/openapi/v3/api-docs",
        "/v1/swagger.json", "/v2/swagger.json", "/v3/swagger.json",
        "/.well-known/openapi.json",
        "/swagger-ui.html", "/swagger-ui/",
    ]

    HTTP_METHODS = ["GET", "POST", "PUT", "PATCH", "DELETE",
                    "OPTIONS", "HEAD", "TRACE", "CONNECT"]

    async def discover_api_spec(self, client: Any, target: str) -> Optional[Dict]:
        """Discover and parse OpenAPI/Swagger specification."""
        parsed = urlparse(target)
        base = f"{parsed.scheme}://{parsed.netloc}"

        for path in self.SWAGGER_PATHS:
            url = base + path
            try:
                r = await client.get(url)
                if not r or r.get("status") != 200:
                    continue
                text = r.get("text", "")
                # Try JSON parsing
                try:
                    spec = json.loads(text)
                    if "paths" in spec or "swagger" in spec or "openapi" in spec:
                        _logger.info("[RESTExcellence] API spec found: %s", url)
                        return {"url": url, "spec": spec}
                except json.JSONDecodeError:
                    pass
                # Try YAML
                if HAS_YAML and ("swagger:" in text or "openapi:" in text):
                    try:
                        import yaml
                        spec = yaml.safe_load(text)
                        if spec and ("paths" in spec):
                            return {"url": url, "spec": spec}
                    except Exception:
                        pass
            except Exception:
                pass
        return None

    async def extract_endpoints(self, spec: Dict, base_url: str) -> List[Dict]:
        """Extract all API endpoints from OpenAPI spec."""
        endpoints: List[Dict] = []
        paths = spec.get("paths", {})
        base_path = spec.get("basePath", "")
        servers = spec.get("servers", [])
        server_url = servers[0].get("url", "") if servers else base_path

        for path, path_item in paths.items():
            for method, operation in path_item.items():
                if method.upper() not in [m.upper() for m in self.HTTP_METHODS]:
                    continue
                endpoint_url = urljoin(base_url, (server_url + path).lstrip("/"))
                parameters = operation.get("parameters", [])
                security = operation.get("security", [{}])
                endpoints.append({
                    "url": endpoint_url,
                    "method": method.upper(),
                    "path": path,
                    "parameters": parameters,
                    "requires_auth": bool(security and security != [{}]),
                    "summary": operation.get("summary", ""),
                    "tags": operation.get("tags", []),
                })
        return endpoints

    async def test_authorization_matrix(
        self, client: Any, endpoints: List[Dict], token: str = ""
    ) -> List[Dict]:
        """Test each endpoint with/without authentication."""
        findings: List[Dict] = []

        for ep in endpoints[:30]:  # Limit to 30 to avoid excessive requests
            url = ep["url"]
            method = ep["method"]
            requires_auth = ep["requires_auth"]

            try:
                # Test without auth
                r_no_auth = await client.request(method, url)
                status_no_auth = r_no_auth.get("status", 0) if r_no_auth else 0

                # Test with auth
                auth_headers = {"Authorization": f"Bearer {token}"} if token else {}
                r_auth = await client.request(method, url, headers=auth_headers)
                status_auth = r_auth.get("status", 0) if r_auth else 0

                # Analyze results
                if requires_auth and status_no_auth in (200, 201):
                    findings.append({
                        "plugin": "rest_api_excellence",
                        "title": f"API Auth Bypass: {method} {ep['path']}",
                        "severity": "HIGH",
                        "confidence": 88.0,
                        "description": (
                            f"API endpoint {method} {ep['path']} is marked as requiring "
                            "authentication in the spec but returns HTTP 200 without auth."
                        ),
                        "evidence": (
                            f"Without auth: HTTP {status_no_auth} | "
                            f"With auth: HTTP {status_auth} | "
                            f"Spec requires auth: True"
                        ),
                        "url": url,
                        "cwe": "CWE-285",
                        "cvss": 8.1,
                        "owasp": "A01",
                        "tags": ["api", "authorization-bypass", method.lower()],
                    })

                # BOLA/IDOR — numeric ID in path
                if re.search(r'/\d+', ep["path"]):
                    bola_urls = [
                        (lambda _p=re.search(r'/(\d+)', ep['path']): re.sub(r'/(\d+)', '/' + str(int(_p.group(1)) + 1), url) if _p else url)(),
                        re.sub(r'/(\d+)', "/0", url),
                        re.sub(r'/(\d+)', "/9999999", url),
                    ]
                    for bola_url in bola_urls[:2]:
                        try:
                            r_bola = await client.request(method, bola_url, headers=auth_headers)
                            if r_bola and r_bola.get("status") == 200:
                                body = r_bola.get("text", "")
                                if '"id"' in body or '"email"' in body:
                                    findings.append({
                                        "plugin": "rest_api_excellence",
                                        "title": f"BOLA/IDOR: {method} {ep['path']}",
                                        "severity": "HIGH",
                                        "confidence": 82.0,
                                        "description": (
                                            f"Object-level authorization bypass on {method} {ep['path']}. "
                                            "Accessing other users' objects by changing ID in URL."
                                        ),
                                        "evidence": f"URL: {bola_url} | Response: {body[:150]}",
                                        "url": bola_url,
                                        "cwe": "CWE-639",
                                        "cvss": 8.0,
                                        "tags": ["api", "bola", "idor"],
                                    })
                                    break
                        except Exception:
                            pass

            except Exception as exc:
                _logger.debug("[RESTExcellence] Auth matrix error for %s: %s", url, exc)

        return findings

    async def test_verb_tampering(self, client: Any, target: str) -> List[Dict]:
        """Test HTTP method/verb tampering vulnerabilities."""
        findings: List[Dict] = []
        parsed = urlparse(target)
        base = f"{parsed.scheme}://{parsed.netloc}"

        # Test paths likely to have method restrictions
        test_paths = ["/api/admin", "/api/users", "/api/delete", "/admin"]

        for path in test_paths:
            url = base + path
            method_results: Dict[str, int] = {}
            for method in ["GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS"]:
                try:
                    r = await client.request(method, url)
                    if r:
                        method_results[method] = r.get("status", 0)
                except Exception:
                    pass

            # Detect abnormal method acceptance
            if method_results:
                allowed_unexpectedly = [
                    m for m, s in method_results.items()
                    if s in (200, 201) and m not in ("GET", "HEAD", "OPTIONS")
                ]
                if allowed_unexpectedly:
                    findings.append({
                        "plugin": "rest_api_excellence",
                        "title": f"HTTP Verb Tampering: {path} Accepts {', '.join(allowed_unexpectedly)}",
                        "severity": "MEDIUM",
                        "confidence": 80.0,
                        "description": (
                            f"Path {path} unexpectedly accepts HTTP methods: "
                            f"{', '.join(allowed_unexpectedly)}."
                        ),
                        "evidence": f"Method responses: {method_results}",
                        "url": url,
                        "cwe": "CWE-650",
                        "cvss": 5.3,
                        "tags": ["api", "verb-tampering", "http-methods"],
                    })

                # TRACE method enabled (cross-site tracing)
                if method_results.get("TRACE", 0) == 200:
                    findings.append({
                        "plugin": "rest_api_excellence",
                        "title": f"HTTP TRACE Enabled: {url}",
                        "severity": "LOW",
                        "confidence": 90.0,
                        "description": "HTTP TRACE method enabled. May facilitate Cross-Site Tracing (XST).",
                        "evidence": f"TRACE {url} → HTTP 200",
                        "url": url,
                        "cwe": "CWE-16",
                        "cvss": 3.7,
                        "tags": ["api", "trace", "xst"],
                    })

        return findings

    async def test_rate_limit_bypass(self, client: Any, target: str) -> List[Dict]:
        """Test rate limiting bypass techniques."""
        findings: List[Dict] = []

        bypass_headers = [
            {"X-Forwarded-For": "127.0.0.1"},
            {"X-Real-IP": "127.0.0.1"},
            {"X-Originating-IP": "127.0.0.1"},
            {"X-Remote-IP": "127.0.0.1"},
            {"X-Client-IP": "127.0.0.1"},
            {"CF-Connecting-IP": "127.0.0.1"},
            {"True-Client-IP": "127.0.0.1"},
            {"X-Forwarded-For": "10.0.0.1, 192.168.1.1"},
        ]

        # First, try to hit rate limit
        limit_hit = False
        for i in range(50):
            try:
                r = await client.get(target)
                if r and r.get("status") == 429:
                    limit_hit = True
                    break
            except Exception:
                break

        if limit_hit:
            # Now test bypass techniques
            for bypass_hdr in bypass_headers:
                try:
                    r = await client.get(target, headers=bypass_hdr)
                    if r and r.get("status") not in (429, 503):
                        hdr_name = list(bypass_hdr.keys())[0]
                        hdr_val = list(bypass_hdr.values())[0]
                        findings.append({
                            "plugin": "rest_api_excellence",
                            "title": f"Rate Limit Bypass via {hdr_name}",
                            "severity": "HIGH",
                            "confidence": 85.0,
                            "description": (
                                f"Rate limit bypassed by spoofing IP via {hdr_name} header. "
                                f"Server trusts client-supplied IP headers."
                            ),
                            "evidence": (
                                f"Without header: HTTP 429 | "
                                f"With {hdr_name}: {hdr_val} → HTTP {r.get('status')}"
                            ),
                            "url": target,
                            "cwe": "CWE-770",
                            "cvss": 7.5,
                            "tags": ["api", "rate-limit-bypass", "ip-spoofing"],
                        })
                        break
                except Exception:
                    pass

        return findings

    async def scan(self, client: Any, target: str, token: str = "") -> List[Dict]:
        """Full REST API excellence scan."""
        findings: List[Dict] = []

        # Discover API spec
        spec_result = await self.discover_api_spec(client, target)
        if spec_result:
            spec_url = spec_result["url"]
            spec = spec_result["spec"]

            findings.append({
                "plugin": "rest_api_excellence",
                "title": f"API Specification Exposed: {spec_url}",
                "severity": "MEDIUM",
                "confidence": 99.0,
                "description": (
                    f"OpenAPI/Swagger specification found at {spec_url}. "
                    f"Exposes {len(spec.get('paths', {}))} API endpoints with full schema."
                ),
                "evidence": f"Spec version: {spec.get('openapi', spec.get('swagger', 'unknown'))} | "
                            f"Endpoints: {len(spec.get('paths', {}))}",
                "url": spec_url,
                "cwe": "CWE-200",
                "cvss": 5.3,
                "remediation": "Disable API spec endpoints in production or restrict to internal networks.",
                "tags": ["api", "swagger", "openapi", "spec-exposed"],
            })

            endpoints = await self.extract_endpoints(spec, target)
            findings.extend(
                await self.test_authorization_matrix(client, endpoints, token)
            )

        results = await asyncio.gather(
            self.test_verb_tampering(client, target),
            self.test_rate_limit_bypass(client, target),
            return_exceptions=True,
        )
        for r in results:
            if isinstance(r, list):
                findings.extend(r)

        return findings


