    async def scan(
        self,
        client: Any,
        target: str,
        extra_paths: Optional[List[str]] = None,
        concurrency: int = 30,
    ) -> List[Dict]:
        """Full artifact discovery with smart analysis."""
        findings: List[Dict] = []
        parsed = urlparse(target)
        base = f"{parsed.scheme}://{parsed.netloc}"

        all_paths = self.CRITICAL_PATHS + (extra_paths or [])
        _logger.info("[ArtifactExcellence] Scanning %d paths on %s", len(all_paths), base)

        sem = asyncio.Semaphore(concurrency)
        discovered: List[Dict] = []

        async def _probe(path: str) -> Optional[Dict]:
            async with sem:
                url = base + path
                try:
                    r = await client.get(url)
                    if not r:
                        return None
                    status = r.get("status", 0)
                    if status not in (200, 401, 403):
                        return None
                    text = r.get("text", "")
                    # Verify it's not a generic error page
                    if len(text) < 50 and status != 200:
                        return None
                    return {
                        "path": path,
                        "url": url,
                        "status": status,
                        "size": len(text),
                        "text_sample": text[:300],
                        "content_type": r.get("headers", {}).get("content-type", ""),
                    }
                except Exception:
                    return None

        results = await asyncio.gather(
            *[_probe(p) for p in all_paths],
            return_exceptions=True,
        )

        for result in results:
            if isinstance(result, dict):
                discovered.append(result)

        if discovered:
            _logger.info(
                "[ArtifactExcellence] Found %d accessible paths", len(discovered)
            )

        # Analyze each discovered path
        for item in discovered:
            path = item["path"]
            url = item["url"]
            status = item["status"]
            text = item["text_sample"]
            ctype = item["content_type"]

            # Classify severity based on path type
            severity, cwe, cvss, desc = self._classify_path(path, text, status)

            findings.append({
                "plugin": "artifact_discovery",
                "title": f"Sensitive Path Accessible: {path}",
                "severity": severity,
                "confidence": 95.0 if status == 200 else 80.0,
                "description": desc,
                "evidence": (
                    f"URL: {url} | Status: {status} | "
                    f"Size: {item['size']}B | Type: {ctype[:50]}"
                ),
                "url": url,
                "cwe": cwe,
                "cvss": cvss,
                "remediation": f"Restrict access to {path}. Remove if not needed.",
                "tags": ["artifact-discovery", self._path_category(path)],
            })

        # Summary
        findings.append({
            "plugin": "artifact_discovery",
            "title": f"Artifact Discovery Complete: {len(discovered)} Paths Found",
            "severity": "INFO",
            "confidence": 99.0,
            "description": f"Scanned {len(all_paths)} paths, found {len(discovered)} accessible.",
            "evidence": f"Paths: {[d['path'] for d in discovered[:10]]}",
            "url": base,
            "tags": ["artifact-discovery", "summary"],
        })

        return findings

    def _classify_path(
        self, path: str, text: str, status: int
    ) -> Tuple[str, str, float, str]:
        """Classify discovered path by severity."""
        p = path.lower()

        # Critical: confirmed secret exposure
        if any(k in text.lower() for k in ["password=", "secret=", "api_key=", "db_password"]):
            return ("CRITICAL", "CWE-312", 9.8,
                    f"Sensitive credentials found in accessible file {path}.")

        # Critical: Git/VCS exposure
        if ".git" in p or ".svn" in p or ".hg" in p:
            return ("HIGH", "CWE-538", 7.5,
                    f"Version control repository ({path}) is publicly accessible.")

        # Critical: config files
        if any(k in p for k in [".env", "config", "database", "settings", "credentials"]):
            return ("HIGH", "CWE-312", 8.1,
                    f"Configuration file {path} is publicly accessible.")

        # Critical: backup/archive files
        if any(k in p for k in [".sql", ".zip", ".tar", ".gz", "backup", "dump"]):
            return ("HIGH", "CWE-530", 7.5,
                    f"Backup/archive file {path} is accessible — may contain sensitive data.")

        # High: admin panels
        if any(k in p for k in ["admin", "phpmyadmin", "cpanel", "management"]):
            return ("HIGH", "CWE-200", 7.5,
                    f"Administrative interface {path} is publicly accessible.")

        # Medium: debug info
        if any(k in p for k in ["debug", "phpinfo", "actuator", "swagger"]):
            return ("MEDIUM", "CWE-200", 5.3,
                    f"Debug/documentation endpoint {path} exposes internal information.")

        # Low: info files
        if any(k in p for k in ["readme", "changelog", "install", "version"]):
            return ("LOW", "CWE-200", 3.1,
                    f"Informational file {path} may disclose version or infrastructure details.")

        return ("LOW", "CWE-200", 3.1,
                f"Path {path} accessible with HTTP {status}.")

    def _path_category(self, path: str) -> str:
        p = path.lower()
        if ".git" in p or ".svn" in p:
            return "vcs-exposure"
        if ".env" in p or "config" in p or "secret" in p:
            return "config-exposure"
        if ".sql" in p or "backup" in p or ".zip" in p:
            return "backup-exposure"
        if "admin" in p:
            return "admin-panel"
        if "swagger" in p or "api-doc" in p or "openapi" in p:
            return "api-spec"
        return "misc"


