    def calculate_risk_score(self, findings: List[Any]) -> Dict[str, Any]:
        """Calculate overall risk score and metrics."""
        sev_counts = Counter()
        for f in findings:
            sev = getattr(f, "severity", None) or (
                f.get("severity") if isinstance(f, dict) else "INFO"
            )
            sev_counts[sev] += 1

        risk_score = (
            sev_counts.get("CRITICAL", 0) * 15 +
            sev_counts.get("HIGH", 0) * 8 +
            sev_counts.get("MEDIUM", 0) * 4 +
            sev_counts.get("LOW", 0) * 1
        )

        # Normalize to 0-100
        max_theoretical = 1000
        normalized = min(100, (risk_score / max_theoretical) * 100)

        if normalized >= 75:
            risk_level = "CRITICAL"
        elif normalized >= 50:
            risk_level = "HIGH"
        elif normalized >= 25:
            risk_level = "MEDIUM"
        elif normalized > 0:
            risk_level = "LOW"
        else:
            risk_level = "NONE"

        return {
            "raw_score": risk_score,
            "normalized_score": round(normalized, 1),
            "risk_level": risk_level,
            "by_severity": dict(sev_counts),
            "total_findings": len(findings),
        }

    def to_sarif(self, findings: List[Any], target: str, tool_version: str = "34") -> Dict:
        """Generate SARIF 2.1.0 report."""
        rules = []
        results = []
        seen_rules: Set[str] = set()

        for f in findings:
            plugin = getattr(f, "plugin", None) or (f.get("plugin", "webscout") if isinstance(f, dict) else "webscout")
            title = getattr(f, "title", None) or (f.get("title", "") if isinstance(f, dict) else "")
            severity = getattr(f, "severity", "INFO") or (f.get("severity", "INFO") if isinstance(f, dict) else "INFO")
            description = getattr(f, "description", "") or (f.get("description", "") if isinstance(f, dict) else "")
            url = getattr(f, "url", "") or (f.get("url", "") if isinstance(f, dict) else "")
            cwe = getattr(f, "cwe", "") or (f.get("cwe", "") if isinstance(f, dict) else "")

            rule_id = hashlib.md5(f"{plugin}:{title}".encode()).hexdigest()[:12]

            if rule_id not in seen_rules:
                seen_rules.add(rule_id)
                sarif_level = {
                    "CRITICAL": "error", "HIGH": "error",
                    "MEDIUM": "warning", "LOW": "note", "INFO": "none",
                }.get(severity, "none")
                rules.append({
                    "id": rule_id,
                    "name": title[:100],
                    "shortDescription": {"text": title[:100]},
                    "fullDescription": {"text": description[:500]},
                    "defaultConfiguration": {"level": sarif_level},
                    "properties": {
                        "tags": [plugin, severity.lower()],
                        "precision": "medium",
                        "security-severity": str({
                            "CRITICAL": "9.5", "HIGH": "8.0",
                            "MEDIUM": "5.5", "LOW": "3.0", "INFO": "0.0",
                        }.get(severity, "0.0")),
                    },
                })

            sarif_level = {
                "CRITICAL": "error", "HIGH": "error",
                "MEDIUM": "warning", "LOW": "note", "INFO": "none",
            }.get(severity, "none")

            result = {
                "ruleId": rule_id,
                "level": sarif_level,
                "message": {"text": description[:1000]},
                "locations": [{
                    "physicalLocation": {
                        "artifactLocation": {
                            "uri": url or target,
                            "uriBaseId": "%SRCROOT%",
                        },
                    },
                }],
            }
            results.append(result)

        return {
            "version": "2.1.0",
            "$schema": "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/master/Schemata/sarif-schema-2.1.0.json",
            "runs": [{
                "tool": {
                    "driver": {
                        "name": "WebScout Ultimate",
                        "version": tool_version,
                        "informationUri": "https://github.com/webscout",
                        "rules": rules,
                    }
                },
                "results": results,
                "originalUriBaseIds": {
                    "%SRCROOT%": {"uri": target},
                },
            }],
        }

    def to_junit_xml(self, findings: List[Any], target: str) -> str:
        """Generate JUnit XML for CI/CD integration."""
        critical = [f for f in findings if
                    (getattr(f, "severity", None) or
                     (f.get("severity", "") if isinstance(f, dict) else "")) == "CRITICAL"]
        high = [f for f in findings if
                (getattr(f, "severity", None) or
                 (f.get("severity", "") if isinstance(f, dict) else "")) == "HIGH"]

        failures = len(critical) + len(high)
        total = len(findings)

        lines = [
            '<?xml version="1.0" encoding="UTF-8"?>',
            f'<testsuite name="WebScout Security Scan" tests="{total}" failures="{failures}" '
            f'timestamp="{datetime.utcnow().isoformat()}Z" hostname="{target[:100]}">',
        ]

        for f in findings:
            title = (getattr(f, "title", None) or
                     (f.get("title", "") if isinstance(f, dict) else ""))
            severity = (getattr(f, "severity", "INFO") or
                        (f.get("severity", "INFO") if isinstance(f, dict) else "INFO"))
            url = (getattr(f, "url", "") or
                   (f.get("url", "") if isinstance(f, dict) else ""))
            desc = (getattr(f, "description", "") or
                    (f.get("description", "") if isinstance(f, dict) else ""))

            name = title.replace('"', "'").replace("<", "&lt;").replace(">", "&gt;")[:200]
            url_safe = url.replace('"', "'")
            desc_safe = desc.replace("<", "&lt;").replace(">", "&gt;")[:500]

            lines.append(f'  <testcase name="{name}" classname="{severity}">',)
            if severity in ("CRITICAL", "HIGH"):
                lines.append(
                    f'    <failure message="{name}" type="{severity}">'
                    f'{desc_safe}</failure>'
                )
            lines.append("  </testcase>")

        lines.append("</testsuite>")
        return "\n".join(lines)

