class WebScoutV34MasterScanner:
    """
    WebScout Ultimate v34 Master Scanner
    Orchestrates all 19 excellence modules for comprehensive security analysis.
    Drop-in replacement for the original scan flow with full backward compatibility.
    """

    VERSION = "34.0.0"

    def __init__(
        self,
        client: Any,
        target: str,
        token: str = "",
        oob_domain: str = "",
        output_dir: str = ".",
        concurrency: int = 12,
        enable_port_scan: bool = True,
        enable_browser_intel: bool = True,
        enable_oob: bool = True,
        resume_file: Optional[str] = None,
    ):
        self.client = client
        self.target = target
        self.token = token
        self.output_dir = output_dir
        self.concurrency = concurrency
        self.enable_port_scan = enable_port_scan
        self.enable_browser_intel = enable_browser_intel
        self.enable_oob = enable_oob
        self.start_time = time.monotonic()

        # Initialize all excellence engines
        self.osint = OSINTExcellence()
        self.ws_engine = WebSocketExcellenceEngine()
        self.gql_engine = GraphQLExcellenceEngine()
        self.tls_engine = CryptoTLSExcellenceEngine()
        self.port_engine = PortDiscoveryExcellence()
        self.oob_engine = OOBExcellenceEngine(oob_domain=oob_domain)
        self.post_exploit = PostExploitationExcellence()
        self.rest_engine = RESTAPIExcellenceEngine()
        self.artifact_engine = ArtifactDiscoveryExcellence()
        self.reporter = ReportingExcellenceEngine()
        self.rel_mapper = RelationshipMappingExcellence()
        self.red_team = RedTeamOrchestrationExcellence()
        self.orchestrator = OrchestrationExcellence(
            max_concurrency=concurrency,
            resume_file=resume_file,
        )

    def _register_all_modules(self) -> None:
        """Register all v34 excellence modules with the orchestrator."""
        parsed = urlparse(self.target)
        host = parsed.netloc.split(":")[0]

        # Priority 10 — OSINT (first — informs all other modules)
        self.orchestrator.register_module(
            "V34-OSINT",
            lambda: self.osint.run_full_osint(self.client, self.target),
            priority=10,
            timeout_s=180,
            tags=["osint", "recon"],
        )

        # Priority 15 — TLS/Crypto
        self.orchestrator.register_module(
            "V34-TLS",
            lambda: self.tls_engine.scan(self.client, self.target),
            priority=15,
            timeout_s=120,
            tags=["tls", "crypto"],
        )

        # Priority 20 — Port Discovery
        if self.enable_port_scan:
            self.orchestrator.register_module(
                "V34-Ports",
                lambda: self.port_engine.scan(host, concurrency=200),
                priority=20,
                depends_on=["V34-OSINT"],
                timeout_s=300,
                tags=["ports", "network"],
            )

        # Priority 25 — Artifact Discovery
        self.orchestrator.register_module(
            "V34-Artifacts",
            lambda: self.artifact_engine.scan(self.client, self.target),
            priority=25,
            timeout_s=600,
            tags=["artifacts", "discovery"],
        )

        # Priority 30 — REST API
        self.orchestrator.register_module(
            "V34-REST-API",
            lambda: self.rest_engine.scan(self.client, self.target, self.token),
            priority=30,
            timeout_s=300,
            tags=["api", "rest"],
        )

        # Priority 35 — GraphQL
        self.orchestrator.register_module(
            "V34-GraphQL",
            lambda: self.gql_engine.scan(self.client, self.target, self.token),
            priority=35,
            timeout_s=300,
            tags=["graphql"],
        )

        # Priority 40 — WebSocket
        self.orchestrator.register_module(
            "V34-WebSocket",
            lambda: self.ws_engine.scan(self.client, self.target, self.token),
            priority=40,
            timeout_s=300,
            tags=["websocket"],
        )

        # Priority 45 — OOB Workflows
        if self.enable_oob:
            self.orchestrator.register_module(
                "V34-OOB",
                lambda: self.oob_engine.run_oob_scan(self.client, self.target),
                priority=45,
                timeout_s=180,
                tags=["oob", "blind"],
            )

        # Priority 50 — Post-Exploitation
        self.orchestrator.register_module(
            "V34-PostExploit",
            lambda: self.post_exploit.assess_lateral_movement(self.client, self.target),
            priority=50,
            depends_on=["V34-REST-API"],
            timeout_s=180,
            tags=["post-exploit"],
        )

    async def run_excellence_scan(self) -> Tuple[List, Dict]:
        """Run the complete v34 excellence scan."""
        _logger.info(
            "[V34] Starting WebScout Ultimate v34 scan of %s", self.target
        )

        self._register_all_modules()

        # Progress reporting
        def _on_progress(module: str, status: str, findings: int):
            icon = "✓" if status == "done" else ("!" if status == "error" else "⚡")
            _logger.info("[V34] %s %s [%s] — %d findings", icon, module, status, findings)

        self.orchestrator.on_progress(_on_progress)

        # Execute all modules
        all_findings = await self.orchestrator.run()

        # Red Team overlay
        try:
            rt_findings = await self.red_team.scan(self.client, self.target, all_findings)
            all_findings.extend(rt_findings)
        except Exception as exc:
            _logger.warning("[V34] Red team overlay error: %s", exc)

        # Build relationship graph
        try:
            osint_findings = self.orchestrator._results.get("V34-OSINT", [])
            await self.rel_mapper.build_from_osint(osint_findings, self.target)
        except Exception as exc:
            _logger.warning("[V34] Relationship mapping error: %s", exc)

        scan_time_s = time.monotonic() - self.start_time

        # Generate all reports
        report_paths = self.reporter.save_all_reports(
            all_findings, self.target, scan_time_s, self.output_dir
        )

        # Summary
        risk = self.reporter.calculate_risk_score(all_findings)
        summary = {
            **self.orchestrator.summary,
            "risk": risk,
            "scan_time_s": round(scan_time_s, 1),
            "report_paths": report_paths,
            "relationship_graph": self.rel_mapper.to_json(),
            "version": self.VERSION,
        }

        _logger.info(
            "[V34] Scan complete — %d findings | Risk: %s (%s/100) | %.0fs",
            len(all_findings),
            risk["risk_level"],
            risk["normalized_score"],
            scan_time_s,
        )

        return all_findings, summary


