#  v35 EXCELLENCE ENGINE — Aggregates all fixes into a version descriptor
# ══════════════════════════════════════════════════════════════════════════════

class WebScoutV35FixEngine:
    """
    WebScout Ultimate v35 — Fix Engine
    Exposes all v35 improvements as a coherent API.
    """

    VERSION = "35.0.0"
    FIX_COUNT = 12

    FIXES = {
        "FIX-V35-01": "Playwright guaranteed context/page cleanup (memory leak)",
        "FIX-V35-02": "Queue exhaustion watchdog + adaptive throttle",
        "FIX-V35-03": "Output sanitization — server-controlled data injection prevention",
        "FIX-V35-04": "Redirect SSRF guard — block private IP redirect chains",
        "FIX-V35-05": "Report sensitive-data masking (cleartext credential risk)",
        "FIX-V35-06": "Time-based detection: network-stability gate + MAD filter",
        "FIX-V35-07": "Polymorphic WAF-bypass payload engine (50+ techniques)",
        "FIX-V35-08": "WebSocket subprotocol negotiation fallback engine",
        "FIX-V35-09": "Adaptive rate-limiting with jitter + proxy health scoring",
        "FIX-V35-10": "Module-level resilience wrapper (single-file crash guard)",
        "FIX-V35-11": "MemoryWatchdog: per-context browser memory enforcement",
        "FIX-V35-12": "SSTI timing: triple-confirm + control differential gate",
    }

    @classmethod
    def summary(cls) -> str:
        lines = [
            f"WebScout Ultimate v{cls.VERSION} — {cls.FIX_COUNT} Active Fixes",
            "=" * 60,
        ]
        for fix_id, desc in cls.FIXES.items():
            lines.append(f"  {fix_id}: {desc}")
        return "\n".join(lines)

    @classmethod
    def create_browser_engine(
        cls,
        headless: bool = True,
        timeout_ms: int = 30_000,
        max_contexts: int = 4,
    ) -> PlaywrightBrowserEngine:
        """Create a v35-fixed Playwright browser engine."""
        return PlaywrightBrowserEngine(
            headless=headless,
            timeout_ms=timeout_ms,
            max_contexts=max_contexts,
        )

    @classmethod
    def create_memory_watchdog(cls, memory_limit_mb: int = 2048) -> MemoryWatchdog:
        return MemoryWatchdog(memory_limit_mb=memory_limit_mb)

    @classmethod
    def create_worker_pool(
        cls,
        max_workers: int = 20,
        task_timeout: float = 60.0,
    ) -> BoundedWorkerPool:
        return BoundedWorkerPool(max_workers=max_workers, task_timeout=task_timeout)

    @classmethod
    def create_rate_limiter(cls, base_delay: float = 0.0) -> AdaptiveRateLimiter:
        return AdaptiveRateLimiter(base_delay=base_delay)

    @classmethod
    def create_proxy_scorer(cls, proxy_urls: List[str]) -> ProxyHealthScorer:
        return ProxyHealthScorer(proxy_urls)

    @classmethod
    def create_ws_negotiator(cls) -> WebSocketProtocolNegotiator:
        return WebSocketProtocolNegotiator()

    @classmethod
    def get_timing_analyzer(cls) -> type:
        return TimingAnalyzer

    @classmethod
    def get_payload_engine(cls) -> type:
        return PolymorphicPayloadEngine

    @classmethod
    def get_output_sanitizer(cls) -> type:
        return OutputSanitizer

    @classmethod
    def get_redirect_guard(cls) -> type:
        return RedirectSSRFGuard

    @classmethod
    def get_report_masker(cls) -> type:
        return ReportDataMasker

    @classmethod
    def get_module_wrapper(cls) -> type:
        return ModuleResilienceWrapper


# ── Backward-compatible aliases ──────────────────────────────────────────────

# These allow the original code that instantiates old classes to automatically
# get the v35-fixed versions via Python's last-definition-wins semantics.
# (Both the original class definitions and these are in the same file;
#  the v35 patch is appended at the bottom, so these override the originals.)

# Already redefined above (same class name) — the following are explicit shims
# for any code that references the old names:
_V35PlaywrightBrowserEngine = PlaywrightBrowserEngine
_V35MemoryWatchdog = MemoryWatchdog
_V35BoundedWorkerPool = BoundedWorkerPool


def get_v35_fix_modules() -> Dict[str, Any]:
    """
    Return all v35 fix classes for use by WebScoutV34MasterScanner or any
    orchestration layer that needs to instantiate the fixed components.
    """
    return {
        "browser_engine_class": PlaywrightBrowserEngine,
        "memory_watchdog_class": MemoryWatchdog,
        "worker_pool_class": BoundedWorkerPool,
        "rate_limiter_class": AdaptiveRateLimiter,
        "proxy_scorer_class": ProxyHealthScorer,
        "ws_negotiator_class": WebSocketProtocolNegotiator,
        "timing_analyzer_class": TimingAnalyzer,
        "ssti_timing_class": SSTITimingAnalyzer,
        "payload_engine_class": PolymorphicPayloadEngine,
        "output_sanitizer_class": OutputSanitizer,
        "redirect_guard_class": RedirectSSRFGuard,
        "report_masker_class": ReportDataMasker,
        "module_wrapper_class": ModuleResilienceWrapper,
        "fix_engine_class": WebScoutV35FixEngine,
        "version": "35.0.0",
        "fix_count": 12,
    }


